/**
 * bandd_playtest 二合一模组的**版本无关 core**（18 个 Java 类）—— 2026-11-03 回填。
 *
 * 来源：`F:\B AND D MOD\mod\shared\core\com\bandd\playtest\core\`（四档真机验证过的同一份）。
 * 架构：`HttpApi`（HTTP 线程**只入队**，绝不碰 MC）→ `ActionQueue` → `PlaytestCore.onTick()`（客户端 tick 线程）
 * → `GameBridge`（**唯一**与平台相关的接口）→ 各档适配层。外加 `EvidenceWriter`（state.json/exit-code.txt/qa.log/rounds.jsonl）
 * 与 `Arbitration`（AUTO/HOTKEY/DUAL）。
 *
 * ⚠ **真机教训（勿重踩）**：
 *   - `GameBridge.unavailableActions()` 的 default 返回**空**会让 `/status` 谎报能力 ⇒ 各档必须**按实际做得到的列白名单**；
 *   - **reobf 不改反射字符串** ⇒ core/适配层**禁止**反射访问 MC（生成器已有 `assertNoReflectiveMcAccess` 守）；
 *   - HTTP 端口是**动态**的（`HttpApi.start()` 从首选端口往后试 20 个）⇒ 消费方必须实时解析（读 qa.log 的
 *     `[QA] http listening on 127.0.0.1:<port>` 或探活）。
 *
 * 用法：`PLAYTEST_MOD_CORE_SOURCES` 是「相对路径 → 源码」的表，生成器按需落到 `playtest/core/`。
 */
export const PLAYTEST_MOD_CORE_SOURCES: Readonly<Record<string, string>> = {
  "playtest/core/com/bandd/playtest/core/ActionQueue.java": "package com.bandd.playtest.core;\n\nimport java.util.Map;\nimport java.util.Queue;\nimport java.util.concurrent.CompletableFuture;\nimport java.util.concurrent.ConcurrentLinkedQueue;\nimport java.util.concurrent.TimeUnit;\n\n/**\n * 动作队列。**线程纪律（照抄仓库口径，playtest-bridge-mod.ts:38）**：\n * HTTP 处理线程**只入队**，一切 MC 调用都在客户端 tick 线程执行（HTTP 线程碰 MC 会崩）。\n */\npublic final class ActionQueue {\n    private final Queue<Job> q = new ConcurrentLinkedQueue<>();\n\n    public Job submit(String action, Map<String, Object> params) {\n        Job j = new Job(action, params);\n        q.add(j);\n        return j;\n    }\n\n    /** 客户端 tick 里调用：在本线程（= MC 线程）执行所有排队动作。 */\n    public void drain(PlaytestCore core) {\n        Job j;\n        while ((j = q.poll()) != null) {\n            j.run(core);\n        }\n    }\n\n    public static final class Job {\n        private final String action;\n        private final Map<String, Object> params;\n        private final CompletableFuture<Map<String, Object>> fut = new CompletableFuture<>();\n\n        Job(String action, Map<String, Object> params) {\n            this.action = action;\n            this.params = params;\n        }\n\n        public String action() { return action; }\n\n        public Map<String, Object> params() { return params; }\n\n        void run(PlaytestCore core) {\n            try {\n                fut.complete(core.dispatch(action, params));\n            } catch (Throwable t) {\n                fut.complete(PlaytestCore.error(\"EXEC_FAILED\", String.valueOf(t)));\n            }\n        }\n\n        /** HTTP 线程在这里等 tick 线程的结果；超时返回 null（= 不静默，报 TIMEOUT）。 */\n        public Map<String, Object> await(long ms) {\n            try {\n                return fut.get(ms, TimeUnit.MILLISECONDS);\n            } catch (Exception e) {\n                return null;\n            }\n        }\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/Arbitration.java": "package com.bandd.playtest.core;\n\nimport java.util.LinkedHashSet;\nimport java.util.Set;\n\n/**\n * 输入仲裁。**用户裁定：做成模组选项，由玩家运行时选**，所以三种模式全部实现。\n *\n *  AUTO   真人一按「AI 没按过的键」→ AI 让位（暂停 + 释放自己按过的键）\n *  HOTKEY 显式切换持权方（HTTP take_over / 游戏内热键）\n *  DUAL   AI 不碰按键（只用桥面命令）⇒ 不抢方向盘\n *\n * **记账式释放**：只释放「AI 自己按下过的键」，绝不无差别清空\n * （仓库 driver 的 releaseAll 会连带清掉真人的键 —— 见 reference/generators/playtest-driver.ts:4582-4589，\n *  那是\"一起玩\"下的真 bug，本模组不照抄）。\n */\npublic final class Arbitration {\n    public enum Mode { AUTO, HOTKEY, DUAL }\n\n    private Mode mode = Mode.AUTO;\n    private boolean aiOwns = true;\n    private final Set<String> owned = new LinkedHashSet<>();\n    private int yields = 0;\n    private String lastReason = \"init\";\n\n    public synchronized Mode mode() { return mode; }\n\n    public synchronized void setMode(Mode m) {\n        mode = m;\n        lastReason = \"mode=\" + m;\n        if (m == Mode.DUAL) { aiOwns = false; }\n        if (m == Mode.AUTO) { aiOwns = true; }\n    }\n\n    public synchronized boolean aiOwns() { return aiOwns; }\n\n    public synchronized int yields() { return yields; }\n\n    public synchronized String lastReason() { return lastReason; }\n\n    public synchronized boolean isOwned(String key) { return owned.contains(key); }\n\n    /** 真人是否在按一个「AI 没按过」的键（AUTO 让位判据）。 */\n    public synchronized boolean humanHasControl(GameBridge bridge) {\n        for (String k : bridge.supportedKeys()) {\n            if (!owned.contains(k) && bridge.isPressed(k)) return true;\n        }\n        return false;\n    }\n\n    public synchronized void yieldToHuman(GameBridge bridge, String reason) {\n        aiOwns = false;\n        yields++;\n        lastReason = reason;\n        releaseOwned(bridge);\n    }\n\n    public synchronized void takeOver() {\n        aiOwns = true;\n        lastReason = \"ai takeover\";\n    }\n\n    /** 只释放 AI 自己按下的键。 */\n    public synchronized void releaseOwned(GameBridge bridge) {\n        for (String k : new LinkedHashSet<>(owned)) {\n            bridge.setPressed(k, false);\n        }\n        owned.clear();\n    }\n\n    public synchronized void noteOwned(String key, boolean down) {\n        if (down) owned.add(key); else owned.remove(key);\n    }\n\n    public synchronized int ownedCount() { return owned.size(); }\n}\n",
  "playtest/core/com/bandd/playtest/core/Capabilities.java": "package com.bandd.playtest.core;\n\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.List;\n\n/** 能力自报：/status 里如实报「本档这一份 JAR 到底能做什么」，缺的面明确报 unavailable，不静默。 */\npublic final class Capabilities {\n    /** 桥面 = 命令级。 */\n    public static final List<String> BRIDGE = Arrays.asList(\n            \"ping\", \"query_player_state\", \"query_screen\", \"screenshot\", \"chat_command\",\n            \"set_arbitration\", \"status\",\n            \"query_chat\", \"chat_say\",   // 聊天桥：读玩家打的字 / 以 [AI] 身份回话\n            \"query_log\",                // 日志游标增量读 + 有界等待（sinceOffset/waitForPattern/waitMs）\n            \"query_state\", \"query_map\",   // 状态器：**（半）实时**游戏状态快照 + 文本地图（读缓存，不现场全扫）\n            \"query_column\", \"query_blocks\", // [T13] 单列纵剖面 / 按条件搜方块（只回命中坐标；分帧扫）\n            \"query_inventory\", \"query_inventory_slot\", // 背包面：读背包内容 / 读某一格（形状与桥路线对齐）\n            \"settings_set\", \"settings_save\"); // 设置面：改内存中的旋钮（白名单）/ 落盘那一个文件（读-改-写）\n    /**\n     * 「状态器」两条（BRIDGE 的子集，**不是**第 3 张表 —— all() 仍是 BRIDGE ∪ DRIVER）。\n     * 它们额外要求适配层实现 {@link GameBridge#blockAt}/{@link GameBridge#topSolidY}\n     * 并自报 {@link GameBridge#stateMapCapable()}；没实现的档 /status 如实报不可用。\n     */\n    public static final List<String> STATE_MAP = Arrays.asList(\"query_state\", \"query_map\");\n    /**\n     * 「纵剖面 + 按条件搜方块」两条（[T13]；**BRIDGE 的子集**，同 STATE_MAP 先例 ——\n     * all() 仍是 BRIDGE ∪ DRIVER，**不是第 3 张表**）。\n     *\n     * <p>为什么进 BRIDGE 而不是 DRIVER：这两条**不依赖屏幕、也不依赖按键** —— 它们只是**读数**，\n     * 走适配层**已有**的 {@link GameBridge#blockAt} 取值面（一列里就能取到任意 Y，用户原话\n     * 「正好区块就是有整个 Z 轴的」），与 {@code query_state} / {@code query_map} **同一面**。\n     * 与 DRIVER 的「玩家级真按键（press / look / mine / open_settings）」不是一回事。\n     *\n     * <p>能力缺口由适配层自报 {@link GameBridge#stateMapCapable()}（**同一个**取值面）——\n     * 没实现的档 {@code /status} 里**如实**把它俩列进 {@code actionsUnavailable}，\n     * {@code /execute} 回 {@code STATE_MAP_UNSUPPORTED}，绝不假装会读方块。\n     */\n    public static final List<String> STATE_QUERY = Arrays.asList(\"query_column\", \"query_blocks\");\n    /**\n     * 设置面两条（**BRIDGE 的子集**，同 STATE_MAP 先例 —— all() 仍是 BRIDGE ∪ DRIVER）。\n     *\n     * <p>为什么进 BRIDGE 而不是 DRIVER：这两条**不依赖屏幕**。settings_set 只改内存里的\n     * {@link StateConfig}（白名单，见 {@link SettingsEdit}），settings_save 只做「读-改-写那一个文件」。\n     * 它们在任何「接管了配置文件」的档上都能用，哪怕这一档压根没有图形设置页 ——\n     * 与 DRIVER「玩家级（真按键）」的定义（按 O 开屏那种）不是一回事。\n     *\n     * <p>反过来 open_settings 进 DRIVER：它是**客户端界面动作**（要 Cloth 屏 + 本档接线），\n     * 与 close_screen / query_widgets 同一面。\n     */\n    public static final List<String> SETTINGS = Arrays.asList(\"settings_set\", \"settings_save\");\n    /**\n     * 「背包面」两条（**BRIDGE 的子集**，同 STATE_MAP / SETTINGS 先例 —— all() 仍是 BRIDGE ∪ DRIVER）。\n     *\n     * <p>为什么进 BRIDGE 而不是 DRIVER：这两条**不依赖屏幕、也不依赖按键** —— 它们是**读数**，\n     * 走适配层的 {@link GameBridge#inventoryJson()}（本机玩家物品栏的内存快照），\n     * 与 DRIVER 的「玩家级真按键」定义（press / look / mine / open_settings）不是一回事。\n     * 与 query_player_state / query_state 同一面：任何「接管了玩家读数」的档都该给。\n     *\n     * <p>能力缺口由适配层自报 {@link GameBridge#inventoryCapable()} —— 没实现的档\n     * {@code /status} 里**如实**把它俩列进 {@code actionsUnavailable}，且 {@code /execute} 回\n     * {@code INVENTORY_UNSUPPORTED}，不假装能读。\n     */\n    public static final List<String> INVENTORY = Arrays.asList(\"query_inventory\", \"query_inventory_slot\");\n    /** driver 面 = 玩家级（真按键）。 */\n    public static final List<String> DRIVER = Arrays.asList(\n            \"press\", \"release_all\", \"take_over\", \"open_world\", \"look\", \"close_screen\", \"mine\",\n            \"spawn_bot\", \"bot_move\", \"bot_follow\", \"bot_despawn\", \"open_bot_inventory\",\n            \"bot_give\", \"bot_look\", \"bot_break\", \"bot_place\", \"join_server\", \"set_auth\",\n            \"query_widgets\",            // 当前 Screen 的控件清单（类名/坐标/文本/可用/可见）\n            \"open_settings\",            // 打开游戏内设置屏（客户端动作；与 close_screen/query_widgets 同一面）\n            // [T19] 玩家级「点屏幕 / 操作容器」一族（全部是**客户端界面动作**，与 query_widgets /\n            // close_screen / open_settings 同一面 ⇒ 进 DRIVER 而不是 BRIDGE）：\n            \"query_slots\",              // 读当前打开界面的**槽位**（合成格/熔炉料**不是控件**，query_widgets 读不到）\n            \"click_slot\",               // 走客户端交互管理器点槽位（原版点击语义：左/右/shift）\n            \"click_widget\",             // 敲控件中心（界面的鼠标点击入口，**不是** OS 级注入）\n            \"use_on\",                   // 玩家朝某方块右键（开工作台/熔炉/箱子、按按钮）\n            \"place_block\",              // 玩家在目标位置**放置手持方块**（玩家级；与 bot_place 分开，两档都真实现）\n            // [T22] 快捷栏 / 丢物品两条（同属**玩家级**：select_slot 改本档的选中槽字段，\n            //   drop_item 走与 click_slot **同一条**客户端交互管理器通路（原版 SlotActionType.THROW））：\n            \"select_slot\",              // 切选中快捷栏槽位（0..8）\n            \"drop_item\");               // 丢弃物品栏某一格（THROW）\n\n    /**\n     * 「点屏幕 / 操作容器」一族五条（**DRIVER 的子集**，同 STATE_MAP / SETTINGS 的先例 ——\n     * all() 仍是 BRIDGE ∪ DRIVER，**不是第 3 张表**）。\n     *\n     * <p>为什么进 DRIVER 而不是 BRIDGE：这五条**都是客户端界面动作** ——\n     * {@code query_slots} 读的是「当前打开界面的槽位」（合成格 / 熔炉料 / 玩家背包），\n     * 只有真开着容器的客户端才有这个面，与 {@code query_widgets} / {@code close_screen} /\n     * {@code open_settings} 完全同一面；{@code click_slot} / {@code click_widget} 更是**真点**，\n     * 走客户端的交互管理器与界面鼠标入口（玩家级），不是「读数」。\n     *\n     * <p>能力缺口由适配层自报 {@link GameBridge#guiActionCapable()}（默认 {@code false}）——\n     * 没实现的档在 {@code /status} 的 {@code actionsUnavailable} 里**如实**列着这五条，\n     * {@code /execute} 回 {@code GUI_ACTIONS_UNSUPPORTED}，**绝不假装会点屏幕**。\n     */\n    public static final List<String> GUI_ACTIONS = Arrays.asList(\n            \"query_slots\", \"click_slot\", \"click_widget\", \"use_on\", \"place_block\");\n\n    /**\n     * [T22] 「快捷栏 / 丢物品」两条（**DRIVER 的子集**，同 STATE_MAP / GUI_ACTIONS 的先例 ——\n     * all() 仍是 BRIDGE ∪ DRIVER，**不是第 3 张表**）。\n     *\n     * <p>为什么进 DRIVER 而不是 BRIDGE：{@code select_slot} 改的是**玩家自己的选中槽**（玩家级），\n     * {@code drop_item} 走的是与 {@code click_slot} **同一条**客户端交互管理器通路\n     * （原版 {@code SlotActionType.THROW}）—— 都不是「读数」，与 GUI_ACTIONS 完全同一面。\n     *\n     * <p>能力缺口**复用同一个自报位** {@link GameBridge#guiActionCapable()}（默认 false）——\n     * 理由：新增位会改到既有档的 {@code driverAvailable} 语义（GuiActionsTest F8 逐字钉着\n     * 「有界面能力的档 driverAvailable=true / 没有的=false」），而这两条与那五条同面 ——\n     * 没实现的档在 {@code /status} 的 {@code actionsUnavailable} 里**如实**列着这两条，\n     * {@code /execute} 回 {@code GUI_ACTIONS_UNSUPPORTED}，**绝不假装会切槽 / 会丢东西**。\n     */\n    public static final List<String> HOTBAR = Arrays.asList(\"select_slot\", \"drop_item\");\n\n    private Capabilities() {}\n\n    public static List<String> all() {\n        List<String> l = new ArrayList<>(BRIDGE);\n        l.addAll(DRIVER);\n        return l;\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/CommandResult.java": "package com.bandd.playtest.core;\n\n/**\n * 命令的**诚实回执**：把「解析成功没有 / 返回值 / 解析错误 / 出错位置」四件事分开报。\n *\n * 为什么需要它：{@code chat_command} 原来只回 {@code {\"sent\":\"<原命令>\"}} ⇒ **一条跑了但什么都没做的\n * 命令，和一条根本没解析的命令长得一模一样**（真机踩过：{@code gamerule doDaylightCycle false}\n * 在 1.21.11 被拒，只能靠人肉读聊天栏才发现）。\n *\n * 本类由适配层填充（core 不碰 MC），字段名即回执里的键名：\n * {@code parsed} / {@code result} / {@code error} / {@code cursor}。\n */\npublic final class CommandResult {\n    /** 命令是否被派发器**完整解析**（无异常、整串消费完、确实指向一条可执行命令）。 */\n    public final boolean parsed;\n    /** 执行返回值 / 影响；观察不到时 null（如多人下真正执行在服务端，客户端拿不到返回值）。 */\n    public final String result;\n    /** 解析或执行错误文本；无错 null。 */\n    public final String error;\n    /** 错误位置（字符游标）；无错或不知 null。 */\n    public final Integer cursor;\n\n    public CommandResult(boolean parsed, String result, String error, Integer cursor) {\n        this.parsed = parsed;\n        this.result = result;\n        this.error = error;\n        this.cursor = cursor;\n    }\n\n    @Override\n    public String toString() {\n        return \"CommandResult{parsed=\" + parsed + \", result=\" + result\n                + \", error=\" + error + \", cursor=\" + cursor + \"}\";\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/EvidenceWriter.java": "package com.bandd.playtest.core;\n\nimport java.io.IOException;\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.nio.file.StandardOpenOption;\nimport java.time.Instant;\n\n/**\n * 证据三件：state.json / exit-code.txt / qa.log。\n * 口径与仓库一致：**缺件读作 absent，不得读成\"没有失败\"**（fail-closed）。\n */\npublic final class EvidenceWriter {\n    private final Path dir;\n\n    public EvidenceWriter(Path dir) { this.dir = dir; }\n\n    public Path dir() { return dir; }\n\n    public void log(String line) {\n        append(\"qa.log\", \"[\" + Instant.now() + \"] \" + line + \"\\n\");\n    }\n\n    public void state(String json) {\n        write(\"state.json\", json);\n    }\n\n    public void exitCode(int code) {\n        write(\"exit-code.txt\", code + \"\\n\");\n    }\n\n    /** 铁律 2：qa.log 只含本轮 => 轮首截断。 */\n    public void truncateQaLog() {\n        write(\"qa.log\", \"\");\n    }\n\n    /** 每轮一行（含 ok）。 */\n    public void appendRounds(String jsonLine) {\n        append(\"rounds.jsonl\", jsonLine + \"\\n\");\n    }\n\n    private void append(String name, String text) {\n        try {\n            Files.createDirectories(dir);\n            Files.write(dir.resolve(name), text.getBytes(StandardCharsets.UTF_8),\n                    StandardOpenOption.CREATE, StandardOpenOption.APPEND);\n        } catch (IOException e) {\n            // 证据写不进去不静默：打到 stdout 让日志面看得见\n            System.err.println(\"[bandd-playtest] evidence append failed: \" + e);\n        }\n    }\n\n    private void write(String name, String text) {\n        try {\n            Files.createDirectories(dir);\n            Files.write(dir.resolve(name), text.getBytes(StandardCharsets.UTF_8),\n                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);\n        } catch (IOException e) {\n            System.err.println(\"[bandd-playtest] evidence write failed: \" + e);\n        }\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/GameBridge.java": "package com.bandd.playtest.core;\n\n/**\n * core ↔ 逐档适配层 的唯一接口。**core 里不许出现任何 net.minecraft.* / 加载器类型**\n * （这样同一份 core 源码可以喂给每个 (加载器, MC 版本) 的 adapter）。\n */\npublic interface GameBridge {\n    String platform();\n\n    String mcVersion();\n\n    /** 玩家与世界都在场（桥协议里的 ready）。 */\n    boolean ready();\n\n    /** 客户端 tick 调用一次（core 的队列在这里排空）。 */\n    void tick();\n\n    /** 玩家/世界读数（JSON 片段字符串）。 */\n    String playerStateJson();\n\n    /** 当前打开的界面名；无界面返回 null。 */\n    String screenName();\n\n    /** 截图，返回落盘路径。 */\n    String screenshotPath();\n\n    /**\n     * 召唤**可见的**化身（第二个角色）。\n     * 返回载体名（如 \"fake_player\" / \"mannequin\"）；本档或当前环境不支持则返回 null。\n     */\n    String spawnBot(String name, double distance);\n\n    /** 把化身移到绝对坐标（可见性由适配层负责，core 不碰 MC）。 */\n    void moveBotTo(double x, double y, double z);\n\n    /**\n     * 每个客户端 tick 驱动一次化身（core 调用）。\n     * 为什么需要：**FakePlayer.tick() 是 NeoForge 置空的**（字节码只有 `return`）⇒ 玩家自身的\n     * 捡拾/物理逻辑永不运行；这一钩子用来显式补上（如把附近掉落物喂给它）。\n     */\n    void tickBot();\n\n    // ---- 化身的\"玩家功能\"（服务端 ServerPlayerGameMode 面；形状复用仓库已核实的 driver 调用）----\n    /** 给化身发物品。item = \"minecraft:diamond\" 这类 id；失败返回 null。 */\n    String giveBot(String item, int count);\n\n    /** 把化身转向（yaw/pitch，MC 约定）。 */\n    boolean lookBot(double yaw, double pitch);\n\n    /** 化身挖掉一个方块（创造模式即时；对应仓库 driver 的 destroyBlock 口径）。 */\n    String breakBotBlock(double x, double y, double z);\n\n    /** 化身用手上的方块对着目标放（对应仓库 driver 的 useItemOn 口径）。 */\n    String placeBotBlock(double x, double y, double z);\n\n    /**\n     * 开关**本机服务端**的会话认证（只对单人/局域网世界有意义）。\n     * 为什么需要：集成服务器在构造里**强制** usesAuthentication(true)（字节码 iconst_1 实证），\n     * 而开发环境的第二客户端是**离线会话** ⇒ 必然 \"Invalid session\"。关掉它，离线客户端才能进。\n     */\n    boolean setServerAuth(boolean online);\n\n    /** 作为**真客户端**连到一个服务器/局域网世界（第二客户端路线的入口）。 */\n    void joinServer(String address);\n\n    /** 收回化身。 */\n    void despawnBot();\n\n    /**\n     * 把**化身的物品栏**开到**真人**的屏幕上（假玩家自己开不了 GUI —— openMenu 被 NeoForge 写成空实现）。\n     * 返回载体说明；不支持则 null。\n     */\n    String openBotInventory();\n\n    /**\n     * 取走**新收到**的聊天（自上次调用以来），并清空缓冲。\n     * 适配层负责挂聊天事件；core 只做搬运与暴露。\n     */\n    java.util.List<String> drainChat();\n\n    /** 进入/加载一个世界（driver 面：AI 或玩家都可用）。 */\n    void openWorld(String worldName);\n\n    /** 以玩家身份发一条命令（命令级动作）。 */\n    void chatCommand(String command);\n\n    /** 读**真人**是否正按着这个逻辑键（仲裁用）。 */\n    boolean isPressed(String key);\n\n    /** 写按键（玩家级动作）。 */\n    void setPressed(String key, boolean down);\n\n    /** 该档支持哪些逻辑键。 */\n    java.util.List<String> supportedKeys();\n\n    /**\n     * **本档做不了**的动作名（供 /status 如实自报）。默认空 = 全都做得了。\n     *\n     * 为什么需要它：`PlaytestCore.status()` 原本**无条件**报 `Capabilities.all()` ⇒ 一个 MC 侧\n     * 全 fail-closed 的档（如 ModLoader 三档：玩家/位置/截图/读方块/按键都没有出处）会在\n     * `/status` 里**谎报**自己会按按键、会截图 —— 而 `/execute` 实际一律失败。\n     * 「能力自报」谎报比没有自报更糟：调用方会据此排计划。\n     *\n     * Java 8 default 方法 ⇒ **现有适配层一行都不用改**（不实现 = 空 = 行为与从前完全一致）。\n     * 动作名取自 {@link Capabilities}。\n     */\n    /**\n     * **本机玩家**转视角（不是化身）—— `bot_look` 是给假玩家化身的，真客户端的「身体」就是 `mc.player` 自己。\n     *\n     * Java 8 default 方法 ⇒ **现有适配层一行都不用改**（不实现 = false = 行为与从前完全一致，\n     * 且 `/status` 会把它列进 `actionsUnavailable`）。\n     *\n     * 语义：设玩家朝向（yaw ∈ [-180,180]，pitch ∈ [-90,90]）。真客户端里设完由客户端 tick\n     * 自行把朝向发出去（多人/局域网时服务端看得到）。\n     */\n    default boolean look(double yaw, double pitch) {\n        return false;\n    }\n\n    /**\n     * **关掉当前界面**（本机客户端）。\n     *\n     * 为什么必须有：**有界面开着时 MC 不处理输入** —— 实测（forge 1.20.1 真机）\n     * 聊天框/暂停菜单开着时按住 forward，位移恒为 0.000 格，而动作仍回 ok。\n     * 尤其致命的是 pauseOnLostFocus（MC 默认 true）：**真人窗口在前台时，AI 客户端失焦\n     * 会自己弹出 PauseScreen** ⇒ 驱动面整个失能。关掉它（options.txt）能缓解，但界面\n     * 仍可能因别的原因出现 ⇒ 驱动前先 close_screen 是最稳的一步。\n     *\n     * Java 8 default ⇒ 未实现的档行为与从前一致（返回 false ⇒ CLOSE_UNSUPPORTED）。\n     */\n    /**\n     * **破坏准星所指的方块**（本机客户端），返回被破坏的坐标串或 null。\n     *\n     * 为什么不用模拟 keyAttack：实测（forge 1.20.1 真机）hitResult 确实是 BLOCK\n     * （截图里准星带选框）、attack 键 down 且 click 也发了、仲裁 ownedKeys=1，\n     * 但方块 6 秒不破 —— 模拟按键那条链在挖矿上不可靠。\n     * 改为直接调游戏自己的破坏 API（与仓库 driver 的 break 同路）。\n     */\n    default String mineLookingAt() {\n        return null;\n    }\n\n    default boolean closeScreen() {\n        return false;\n    }\n\n    default java.util.List<String> unavailableActions() {\n        return java.util.Collections.emptyList();\n    }\n\n    /**\n     * **本档有没有接到「游戏内设置页面」**（Cloth Config）。默认 {@code false} = 没有。\n     *\n     * <p>为什么默认 false、且必须由适配层自报：设置页面是**加载器相关**代码\n     * （Fabric 走 ModMenu 的 {@code ModMenuApi} / Forge 走 {@code ConfigScreenHandler}），\n     * core 判不出来。默认 false ⇒ 其余 54 档（含 11 个 Cloth 上游根本没有件的档）\n     * **一行不改**，{@code /status} 里也**如实**报「本档不支持图形设置，请手改该文件」，\n     * 而不是谎报自己会画界面。\n     *\n     * <p>只有真的把设置页面接上的档（fabric-1.21.11 / neoforge-1.20.1）才覆盖它报 true。\n     */\n    default boolean configGuiAvailable() {\n        return false;\n    }\n\n    /** 设置页面由哪个件提供（如 {@code \"cloth-config 21.11.153\"}）；没接就回 null。 */\n    default String configGuiProvider() {\n        return null;\n    }\n\n    /**\n     * **打开方式**的人话说明。\n     * 为什么必须单独一位：Fabric 上 ModMenu 只是社区惯例、**不是本模组的必需前置**\n     * ⇒ 除了 ModMenu 那条路，还另给一个不依赖第三方的打开方式（全局按键），这里如实报出来。\n     */\n    default String configGuiOpenHint() {\n        return null;\n    }\n\n    /**\n     * **打开游戏内设置页面**（客户端动作；{@code open_settings} 的落点）。\n     *\n     * <p>为什么由适配层做而不是 core：打开方式**逐档不同** —— fabric 走 ModMenu 的工厂 +\n     * 全局按键 O 的同一个 Screen 构造器，neoforge 走 Forge 自带的\n     * {@code ConfigScreenHandler.ConfigScreenFactory} + 聊天栏 {@code !settings}；\n     * core 连 {@code Screen} 这个类型都不许碰。\n     *\n     * <p>返回**屏的类名**（{@code getClass().getSimpleName()}，便于调用方用 {@code query_widgets}\n     * 交叉验证「开的是不是真的设置屏」）。**没造出来就返回 null**（未初始化 / Cloth 件缺失 /\n     * 构建抛异常）—— core 据此如实回 {@code SETTINGS_GUI_UNSUPPORTED}，**绝不假装打开**。\n     *\n     * <p>Java 8 default 方法 ⇒ 其余 54 档（含 11 个 Cloth 上游根本没有件的档）**一行不改**，\n     * 行为与从前逐字一致（{@code /status} 的 {@code actionsUnavailable} 里如实列着它）。\n     */\n    default String openSettingsScreen() {\n        return null;\n    }\n\n    /**\n     * **本机客户端当前所处的阶段**：`menu` | `singleplayer` | `connecting` | `multiplayer` 之一；\n     * 判不出来返回 null。\n     *\n     * 为什么需要：`ready()` 的字节码只是 `Minecraft.getInstance() != null && mc.player != null\n     * && mc.level != null` ⇒ **在 AI 自己的单人世界里也是 true**（本机实测）。外部脚本若\n     * 「轮询 ready 直到 true」来判「AI 是否进了人类的世界」，会在 AI 自己的单人世界里**提前判绿**。\n     * 这个字段必须能区分「自己的单人世界」与「已连上别人的服务器（含局域网）」。\n     *\n     * Java 8 default 方法 ⇒ **未实现的档行为与从前完全一致**（返回 null）。\n     */\n    default String clientPhase() {\n        return null;\n    }\n\n    /**\n     * 本机集成服务器（单人/局域网世界的服务端）**当前实际**监听的端口；没有则 0。\n     *\n     * 为什么需要：人类实例的日志会**残留旧会话**的 `Started serving on <port>` 行（本机实测：\n     * 11:57 的行留在 13:02 收尾的日志里）⇒ 外部脚本「刮日志取端口」会把**旧端口**拿去 join。\n     * 这个值必须来自**当前活着的服务器对象**，而不是日志文本。\n     *\n     * Java 8 default 方法 ⇒ **未实现的档行为与从前完全一致**（返回 0）。\n     */\n    default int lanPort() {\n        return 0;\n    }\n\n    /**\n     * 执行一条命令并返回**诚实回执**（解析结果 + 执行结果 + 错误位置）。\n     *\n     * 为什么需要它：{@code chat_command} 原来只回 {@code {\"sent\":\"<原命令>\"}} ⇒ 一条跑了但什么都没做的\n     * 命令，和一条根本没解析的命令长得一模一样。适配层走**客户端命令派发器**\n     * （{@code CommandDispatcher.parse} + {@code execute}）拿到 {@code ParseResults} 与执行结果，\n     * 塞进 {@link CommandResult}；core 只负责把它放进回执（**保留原 {@code sent} 字段**）。\n     *\n     * Java 8 default 方法 ⇒ **未实现的档行为与从前逐字一致**（返回 null ⇒ core 退回旧路：只回 sent）。\n     * 被禁列过滤的命令由 core 在调用本方法**之前**拦下（仍回 COMMAND_FORBIDDEN）。\n     */\n    default CommandResult runCommand(String command) {\n        return null;\n    }\n\n    /**\n     * 当前 Screen 的**控件清单**（JSON 数组字符串）；没有界面时返回 {@code \"[]\"}\n     * —— **空清单不是错误**。每项含控件类名 / 坐标 / 尺寸 / 渲染文本 / 可用 / 可见。\n     *\n     * Java 8 default ⇒ 未实现的档行为与从前一致（原来也没有这个动作，返回空清单）。\n     */\n    default String widgetsJson() {\n        return \"[]\";\n    }\n\n    /**\n     * **游戏实例目录**（用于推 {@code logs/latest.log}）；本档给不出返回 null。\n     * 为什么由适配层给：目录只有 MC 侧知道（如 {@code Minecraft.gameDirectory}），core 不碰 MC。\n     */\n    default String gameDirectory() {\n        return null;\n    }\n\n    // ==================================================================\n    // 状态器面（query_state / query_map）—— 取值口 + 自报位\n    // 与 look / closeScreen / widgetsJson 同套路：**全部 default**\n    // ⇒ 其余 54 档一行不改、行为与从前逐字一致（= 如实「不支持」）。\n    // ==================================================================\n\n    /**\n     * 本档是否提供状态器所需的取值面（{@link #blockAt} + {@link #topSolidY}）。\n     * 默认 {@code false} = 不支持。\n     *\n     * 为什么必须单独一个自报位：那两个方法各有 default 实现（null / Integer.MIN_VALUE），\n     * **不可能从返回值区分**「本档压根没实现」与「此刻这一格真取不到」。\n     * {@code PlaytestCore.status()} 与 {@code dispatch} 都读它 ⇒ 老档在 /status 里\n     * 如实把自己报进 {@code actionsUnavailable}，而不是谎报「会画地图」。\n     */\n    default boolean stateMapCapable() {\n        return false;\n    }\n\n    /**\n     * 坐标处方块的**注册名/id 字符串**（如 {@code \"minecraft:stone\"}；空气也照实回\n     * {@code \"minecraft:air\"}）。**越界 / 未加载 / 本档不支持一律回 null** ⇒ core 当「未知」。\n     *\n     * 为什么必须 null 而不是空串/air：未加载的区块里 MC 的 {@code getBlockState} 会回\n     * 「虚空空气」而不是报错（World/Level 的 isChunkLoaded/hasChunk 才是真判据）\n     * ⇒ 不显式判「加载没加载」，AI 会把没加载的地方读成一片空气。\n     */\n    default String blockAt(int x, int y, int z) {\n        return null;\n    }\n\n    /**\n     * 该列**最高非空气方块**的 Y（地表高度）；越界 / 未加载 / 本档不支持回\n     * {@link Integer#MIN_VALUE}。\n     *\n     * 为什么由适配层给而不是 core 逐层扫：逐层扫一列要几十次 {@code getBlockState}，\n     * 48×48 就是十几万次；适配层一行高度图查询（getTopY / getHeight）就够。\n     */\n    default int topSolidY(int x, int z) {\n        return Integer.MIN_VALUE;\n    }\n\n    /**\n     * 世界环境（时间/天气）JSON 片段；本档取不到回 {@code null}（core 留 null **并如实说明**，\n     * 不编 0=白天）。\n     *\n     * 形状（缺字段留 null，不编）：\n     * {@code {\"timeOfDay\":<0..23999|null>,\"dayTime\":<long|null>,\"raining\":<bool|null>,\"thundering\":<bool|null>}}\n     */\n    default String worldEnvJson() {\n        return null;\n    }\n\n    // ==================================================================\n    // 实体扫描面（query_map / query_state 的 entities 叠加层）\n    // 与 stateMapCapable 同套路：**全部 default** ⇒ 其余 54 档一行不改、\n    // 行为与从前逐字一致（= 如实「不支持」，核心回 entitiesNote，不假装有）。\n    // ==================================================================\n\n    /**\n     * 本档是否提供**实体扫描面**（{@link #nearbyEntitiesJson}）。默认 {@code false} = 不支持。\n     *\n     * <p>为什么必须单独一个自报位（与 {@link #stateMapCapable()} 完全同一个理由）：\n     * {@code nearbyEntitiesJson} 的 default 是 {@code null}，**不可能从返回值区分**\n     * 「本档压根没实现」与「此刻真的一只实体也没有」—— 前者要如实写\n     * {@code entitiesNote} 说「本档不支持」，后者要如实给**空层**。两者都长成 null。\n     *\n     * <p>另外它还给 {@code /status} 一个**不碰 MC 的**取值口：{@code /status} 跑在 HTTP 线程上\n     * （见 {@link HttpApi}），不能在那里调 {@code nearbyEntitiesJson} 去「探测」能力\n     * （那是跨线程读游戏状态）。自报位是常量 ⇒ 随便读。\n     */\n    default boolean entityScanCapable() {\n        return false;\n    }\n\n    /**\n     * 玩家周围 {@code radius}（**格**，三维直线距离）内**已加载**的实体明细（JSON 片段）；\n     * 本档不支持 / 当前不在世界里一律回 {@code null}（core 如实说明，不假装有）。\n     *\n     * <p>形状（**只报取到的**，取不到就不报，不许编）：\n     * <pre>\n     * {\"count\":2,\"entities\":[\n     *    {\"type\":\"minecraft:zombie\",\"cls\":\"Zombie\",\"x\":8.5,\"y\":65.0,\"z\":-6.5},\n     *    {\"type\":\"minecraft:item\",\"cls\":\"ItemEntity\",\"x\":9.1,\"y\":65.0,\"z\":-7.2}]}\n     * </pre>\n     * <ul>\n     *   <li>{@code type} = 该档的**实体注册名**（现代档 {@code minecraft:zombie}；老档可能是别的口径，\n     *       逐档如实报，core 原样透出）；{@code cls} = 实体类简单名（诊断用）；</li>\n     *   <li>坐标 = 世界绝对坐标（不是相对玩家的）；</li>\n     *   <li>**默认应排除玩家自己**（与桥路线 {@code query_nearby_entities} 一致：{@code o == mc.player} 跳过）；</li>\n     *   <li>本档只能看到**已加载**的实体 —— 取到啥报啥，**不承诺**「半径内全都看得到」。</li>\n     * </ul>\n     *\n     * <p>Java 8 default ⇒ 未实现的档行为与从前逐字一致（返回 null）。\n     */\n    default String nearbyEntitiesJson(double radius) {\n        return null;\n    }\n\n    // ==================================================================\n    // 背包面（query_inventory / query_inventory_slot）\n    // 形状**与桥路线对齐**（forge 1.7.10–1.12.2 的 query_inventory/query_inventory_slot）。\n    // 同样全部 default ⇒ 其余 54 档一行不改。\n    // ==================================================================\n\n    /**\n     * 本档是否提供**读背包面**（{@link #inventoryJson}）。默认 {@code false} = 不支持。\n     *\n     * <p>理由同 {@link #entityScanCapable()}：{@code null} 无法区分「没实现」与「取不到」，\n     * 且 {@code /status}（HTTP 线程）不能现场调 {@code inventoryJson} 去探测。\n     */\n    default boolean inventoryCapable() {\n        return false;\n    }\n\n    /**\n     * 玩家背包内容（JSON 片段）。本档不支持 / 当前没有玩家一律回 {@code null}。\n     *\n     * <p>形状（**与桥路线 {@code query_inventory} 同形**，额外三个玩家真用得上的字段）：\n     * <pre>\n     * {\"size\":41,\n     *  \"slots\":[{\"slot\":0,\"itemId\":\"minecraft:stone\",\"idKind\":\"registryName\",\"count\":64}, ...],  // **只列非空格**\n     *  \"selectedSlot\":3,\n     *  \"mainHand\":{\"slot\":3,\"itemId\":\"minecraft:diamond_sword\",\"idKind\":\"registryName\",\"count\":1},\n     *  \"hotbar\":[{\"slot\":0,\"empty\":true}, {\"slot\":1,\"itemId\":\"minecraft:stone\",\"idKind\":\"registryName\",\"count\":64}, ...]}\n     * </pre>\n     * <ul>\n     *   <li>{@code slots} **跳过空格子**（与桥一致）；每项含 {@code slot/itemId/idKind/count}；</li>\n     *   <li>{@code idKind} = {@code itemId} 是哪个口径的名字。现代档给 {@code \"registryName\"}\n     *       （如 {@code minecraft:stone}）；**桥路线给的是 {@code \"unlocalizedName\"}**（如 {@code item.stone}）\n     *       —— 两个口径**逐字不同源**，调用方按 idKind 分派，别当同一个串比；</li>\n     *   <li>{@code mainHand} = 主手那格（空格 / 没有玩家 ⇒ null）；{@code selectedSlot} = 选中的快捷栏下标；\n     *       {@code hotbar} = 前 9 格（含空格，每项带 {@code empty}）；</li>\n     *   <li>本档取不到的字段**留空 / 不报**，不许编 0。</li>\n     * </ul>\n     *\n     * <p>Java 8 default ⇒ 未实现的档行为与从前逐字一致（返回 null ⇒ core 回\n     * {@code INVENTORY_UNSUPPORTED}，并在 {@code /status} 的 {@code actionsUnavailable} 里如实列着）。\n     */\n    default String inventoryJson() {\n        return null;\n    }\n\n    // ==================================================================\n    // [T19] 「点屏幕 / 操作容器」一族（query_slots / click_slot / click_widget / use_on / place_block）\n    // 与 look / closeScreen / widgetsJson 同套路：**全部 default** ⇒ 其余 54 档一行不改、\n    // 行为与从前逐字一致（= 如实「不支持」，/status 里列进 actionsUnavailable）。\n    // ==================================================================\n\n    /**\n     * 本档是否实现「点屏幕 / 操作容器」一族（见 {@link Capabilities#GUI_ACTIONS}）。\n     * 默认 {@code false} = 不支持。\n     *\n     * <p>为什么必须单独一个自报位（与 {@link #stateMapCapable()} / {@link #inventoryCapable()}\n     * 完全同一个理由）：这些方法的 default 各回 null / fail，**不可能从返回值区分**\n     * 「本档压根没实现」与「此刻真没有界面 / 真点不动」—— 两者都长成失败。\n     * 另外 {@code /status} 跑在 HTTP 线程上（见 {@link HttpApi}），不能在那里现场调\n     * {@code slotsJson()} 去「探测」能力（那是跨线程读游戏状态）。自报位是常量 ⇒ 随便读。\n     */\n    default boolean guiActionCapable() {\n        return false;\n    }\n\n    /**\n     * **当前打开界面的槽位**（JSON 对象字符串）；**没有界面 / 界面上没有槽位菜单** 回 {@code null}。\n     *\n     * <p>为什么必须有它：合成格、熔炉的料与燃料、箱子里的东西**不是控件** ——\n     * {@link #widgetsJson()} 一个都读不到。所以「能读状态」并不等于「看得见容器里的东西」。\n     *\n     * <p>形状（**适配层只给原始事实**；{@code role} / {@code playerRange} 由 core 的\n     * {@link SlotRoles} 按 menuType+下标补，保证两档逐字同表）：\n     * <pre>\n     * {\"screen\":\"CraftingScreen\",\"menuType\":\"minecraft:crafting\",\"containerId\":0,\n     *  \"slots\":[{\"index\":0,\"x\":124,\"y\":35,\"empty\":true},\n     *           {\"index\":1,\"x\":30,\"y\":17,\"empty\":false,\"itemId\":\"minecraft:oak_planks\",\"count\":3},\n     *           ...]}\n     * </pre>\n     * <ul>\n     *   <li>{@code screen} = 界面类简单名；{@code menuType} = 菜单注册名（{@code Registries.SCREEN_HANDLER}\n     *       / {@code BuiltInRegistries.MENU} 的 id）；{@code containerId} = 菜单的 syncId / containerId；</li>\n     *   <li>每项：{@code index}（下标）、{@code x}/{@code y}（**Slot 自己的坐标**，\n     *       相对容器界面左上角 —— 不减去界面 leftPos/topPos）、{@code empty}、\n     *       非空时 {@code itemId}（现代注册名）+ {@code count}；</li>\n     *   <li>取不到的字段**不报**（core 会如实留 null / 0），**不许编**。</li>\n     * </ul>\n     *\n     * <p>Java 8 default ⇒ 未实现的档行为与从前逐字一致（返回 null ⇒ core 回\n     * {@code GUI_ACTIONS_UNSUPPORTED}，不假装空列表）。\n     */\n    default String slotsJson() {\n        return null;\n    }\n\n    /**\n     * **点槽位**（{@code click_slot}）—— 走**客户端交互管理器**这条现成通路\n     * （fabric = {@code ClientPlayerInteractionManager#clickSlot}；neoforge =\n     * {@code MultiPlayerGameMode#handleInventoryMouseClick}）。\n     *\n     * <p>语义**照原版**：{@code button=0} + shift=false ⇒ PICKUP（左键，拿起/放下整叠）；\n     * {@code button=1} ⇒ PICKUP（右键，拿一半 / 放一个）；{@code shift=true} ⇒ QUICK_MOVE\n     * （用原版的点击类型枚举，**不**另造一套）。\n     *\n     * <p>**fail-loud**（{@link GuiResult}）：没开界面 ⇒ {@code NO_SCREEN_OPEN}；\n     * 下标越界 ⇒ {@code SLOT_OUT_OF_RANGE}（core 已先拦一道，这里是**第二道** ——\n     * 适配层知道本档 slotCount）。**不许静默当成功**。\n     */\n    default GuiResult clickSlot(int slot, int button, boolean shift) {\n        return GuiResult.fail(GuiResult.UNSUPPORTED, \"本档未实现 click_slot（GameBridge#clickSlot）\");\n    }\n\n    /**\n     * **点控件**（{@code click_widget}）：{@code index} = {@link #widgetsJson()} 列表里的下标。\n     *\n     * <p>做法**照真实点击的代码路径**：算出该控件中心，调**界面的鼠标点击入口**\n     * （fabric {@code Screen.mouseClicked(Click,boolean)} / neoforge\n     * {@code Screen.mouseClicked(double,double,int)}）—— 这样按钮、页签、滑块都能按；\n     * **不是** OS 级按键 / 鼠标注入。\n     *\n     * <p>fail-loud：没界面 ⇒ {@code NO_SCREEN_OPEN}；下标越界 ⇒ {@code WIDGET_OUT_OF_RANGE}；\n     * 该控件不可点（不可见 / 被禁用 / 这一项不是可点控件）⇒ {@code WIDGET_NOT_CLICKABLE}；\n     * 界面入口回 false ⇒ {@code WIDGET_CLICK_REJECTED}。\n     */\n    default GuiResult clickWidget(int index) {\n        return GuiResult.fail(GuiResult.UNSUPPORTED, \"本档未实现 click_widget（GameBridge#clickWidget）\");\n    }\n\n    /**\n     * **玩家朝某个方块右键**（{@code use_on}；用于开工作台 / 熔炉 / 箱子，以及按按钮）。\n     *\n     * <p>语义 = 原版「使用物品于方块」：先在客户端把朝向对准目标方块，再走交互通路\n     * （fabric {@code ClientPlayerInteractionManager#interactBlock}；neoforge\n     * {@code MultiPlayerGameMode#useItemOn}）。**不**模拟 OS 输入。\n     *\n     * <p>fail-loud：不在世界里 ⇒ {@code NOT_IN_WORLD}；超出触及距离 ⇒ {@code TARGET_TOO_FAR}；\n     * 游戏没受理 ⇒ {@code USE_FAILED}。\n     */\n    default GuiResult useOn(double x, double y, double z) {\n        return GuiResult.fail(GuiResult.UNSUPPORTED, \"本档未实现 use_on（GameBridge#useOn）\");\n    }\n\n    /**\n     * **玩家在目标位置放置手持方块**（{@code place_block}；玩家级 —— 与化身级的\n     * {@link #placeBotBlock} **语义分开、互不影响**）。\n     *\n     * <p>做法：查目标格是否可替换（不可 ⇒ {@code TARGET_NOT_PLACEABLE}）、手上有没有东西\n     * （没有 ⇒ {@code NO_ITEM_IN_HAND}）、够不够得着（不够 ⇒ {@code TARGET_TOO_FAR}）；\n     * 然后在目标格周围找一个**支撑面**，构造该面的 {@code BlockHitResult}、把朝向对准它，\n     * 再走与 {@code use_on} 同一个交互通路（原版就是这么把方块放到「点中面的外一格」）。\n     * 游戏没受理 ⇒ {@code PLACE_FAILED}。\n     */\n    default GuiResult placeBlock(double x, double y, double z) {\n        return GuiResult.fail(GuiResult.UNSUPPORTED, \"本档未实现 place_block（GameBridge#placeBlock）\");\n    }\n\n    // ==================================================================\n    // [T20-③] 窗口聚焦自报面（press 的诚实回执）\n    // 全部 default ⇒ 其余 54 档一行不改（返回 null = 本档不报，core 如实写「未知」，不假装已聚焦）。\n    // ==================================================================\n\n    /**\n     * 本机客户端窗口**当前是否聚焦**；本档不报 ⇒ {@code null}（**不假装已聚焦**）。\n     *\n     * <p>为什么必须由适配层给：真机实测（2026-11-11）窗口失焦时 {@code attack} / {@code use}\n     * **不生效**，但旧回执照样写 {@code down}（假回执）。核心拿不到聚焦位（那是 GLFW /\n     * {@code Minecraft} 的对象），只有适配层知道名字（neoforge 1.20.1 =\n     * {@code Minecraft#isWindowActive()}；fabric 1.21.11 = {@code MinecraftClient#isWindowFocused()}）。\n     *\n     * <p>语义：{@code Boolean.TRUE} = 聚焦（按键**可能**生效）；{@code Boolean.FALSE} = 失焦\n     * （单人世界 {@code pauseOnLostFocus=true} 还会弹暂停屏 ⇒ 按键**不会**生效）；\n     * {@code null} = 本档不报 ⇒ core 回执里 {@code windowFocused:null} + {@code mayTakeEffect:null}\n     * （**未知**，不假装）。\n     *\n     * <p>Java 8 default ⇒ 未实现的档行为与从前逐字一致。\n     */\n    default Boolean windowFocused() {\n        return null;\n    }\n\n    // ==================================================================\n    // [T20-①] mine 的破坏进度自报面（跨 tick 会话状态）\n    // default ⇒ 未实现的档不报（core 的 mine 回执里 progress 留 null 并如实说明）。\n    // ==================================================================\n\n    /**\n     * 上一次 {@code mine} 的**破坏进度自报**（只读内存字段；本档不报 ⇒ {@code null}）。\n     *\n     * <p>为什么需要：{@code mine} 是**跨 tick** 的（第一发只 START，实际破坏在后续 tick 由\n     * {@code continueDestroyBlock} / {@code updateBlockBreakingProgress} 累计）。\n     * 旧回执只回一个坐标 ⇒ 调用方看到 {@code ok} 以为已经挖穿，实际是黑盒\n     * （真机实测：生存模式 40 次 mine / 22 秒，方块纹丝不动却一路 ok）。\n     *\n     * <p>形状（**取不到的字段留 null / 不报，不许编**；由\n     * {@link MiningTracker#status()} 生成）：\n     * <pre>\n     * {\"target\":\"x,y,z\"|null,\"hasTarget\":bool,\"targetBlock\":\"minecraft:stone\"|null,\n     *  \"targetStillThere\":bool,\"miningTicks\":int,\"maxTicks\":int,\"elapsedMs\":long|null,\n     *  \"minedCount\":int,\"lastMined\":\"x,y,z\"|null,\"lastStopReason\":\"MINE_BROKEN\"|\"MINE_TIMEOUT\"|null,\n     *  \"lastStopTarget\":\"x,y,z\"|null,\"stops\":int,\"continueReturnedTrueCount\":int,\n     *  \"continueReturnedTrueNote\":\"…\",\"note\":\"…\"}\n     * </pre>\n     *\n     * <p>Java 8 default ⇒ 其余档一行不改。\n     */\n    default java.util.Map<String, Object> mineStatus() {\n        return null;\n    }\n\n    // ==================================================================\n    // [T22] 快捷栏 / 丢物品（select_slot / drop_item）—— 与 [T19] 的 GUI 一族**同一面**\n    //   （都是「玩家级、走客户端交互管理器」的动作；自报位仍复用 guiActionCapable() 这一个\n    //    先例，见 {@link #guiActionCapable()}。默认实现 fail-loud ⇒ 其余 54 档一行不改、\n    //    /status 里如实列进 actionsUnavailable）。\n    // 名字**各自 javap 取证**（两档字段名/方法名不同源，不许互相套用）：\n    //   fabric 1.21.11（yarn 1.21.11+build.6 映射件）\n    //     public int  PlayerInventory.getSelectedSlot();\n    //     public void PlayerInventory.setSelectedSlot(int);\n    //     public ItemStack PlayerInventory.getSelectedStack();\n    //     public final Inventory Slot.inventory;   public int Slot.getIndex();\n    //     public void ClientPlayerInteractionManager.clickSlot(int,int,int,SlotActionType,PlayerEntity);\n    //     public final PlayerScreenHandler PlayerEntity.playerScreenHandler;\n    //     public GameMode ClientPlayerInteractionManager.getCurrentGameMode();\n    //     public boolean PlayerAbilities.flying;  public boolean PlayerAbilities.allowFlying;\n    //     public boolean PlayerManager.areCheatsAllowed();\n    //   neoforge 1.20.1（forge-1.20.1-47.4.10 mapped_parchment 件）\n    //     public int Inventory.selected;   public ItemStack Inventory.getSelected();\n    //     public final Container Slot.container;  public int Slot.getContainerSlot();\n    //     public void MultiPlayerGameMode.handleInventoryMouseClick(int,int,int,ClickType,Player);\n    //     public final InventoryMenu Player.inventoryMenu;\n    //     public GameType MultiPlayerGameMode.getPlayerMode();\n    //     public boolean Abilities.flying;  public boolean Abilities.mayfly;\n    //     public boolean WorldData.getAllowCommands();\n    // ==================================================================\n\n    /**\n     * **切换玩家选中的快捷栏槽位**（{@code select_slot}）—— 玩家级，走本档的选中槽字段/方法。\n     *\n     * <p>为什么必须有它：真机实测（fabric 1.21.11，T18）快捷栏永远锁在 slot0（{@code press} 也不支持\n     * 数字键）⇒ 拿到镐子也切不过去。语义：把选中槽切到 {@code slot}（0..8）。\n     *\n     * <p>回执（{@code GuiResult.data}，**逐档读真实的选中槽字段**，不编）：\n     * {@code previousSlot}（切换前）、{@code selectedSlot}（**切换后复读**）、\n     * {@code mainHand}（切换后主手那格，形状同 {@code query_inventory} 的 {@code mainHand}；\n     * 空格 ⇒ null）—— 调用方拿它与 {@code query_inventory.selectedSlot/mainHand} 交叉验证。\n     *\n     * <p>fail-loud：不在世界 / 没有玩家 ⇒ {@code NOT_IN_WORLD}；{@code slot} 不在 0..8 ⇒\n     * {@code SLOT_OUT_OF_RANGE}（core 已先拦一道，这里是**第二道**）。\n     */\n    default GuiResult selectSlot(int slot) {\n        return GuiResult.fail(GuiResult.UNSUPPORTED,\n                \"本档未实现 select_slot（GameBridge#selectSlot）\");\n    }\n\n    /**\n     * **丢弃物品栏某一格**（{@code drop_item}）—— 走与 {@code click_slot} **同一条**客户端交互管理器\n     * 通路，用原版 {@code SlotActionType.THROW}（{@code button=0} 丢一个、{@code button=1} 丢整叠）。\n     *\n     * <p>为什么必须有它：真机实测（T18）{@code press drop} 回 {@code KEY_NOT_SUPPORTED} ⇒ 脏背包\n     * 清不掉、诚实从零做不了。\n     *\n     * <p><b>slot 口径（与 {@code query_inventory} 的 {@code slots[].slot} 同一个空间）</b>：\n     * 玩家物品栏下标（{@code 0..size-1}）。{@link #inventoryJson()} 的 {@code size} 就是上界；\n     * {@code slot < 0} ⇒ 用**当前选中槽**（{@code selectedSlot}）。适配层把该下标映射到目标菜单\n     * （没开容器 ⇒ 玩家自己的物品栏菜单；开着容器 ⇒ 当前容器菜单）里**同一个物品栏对象的那一格**\n     * （按 {@code Slot} 的容器同一性与 {@code getIndex()/getContainerSlot()} 找，不靠版式硬编码）。\n     *\n     * <p><b>count / all</b>：原版 THROW 只有「丢一个 / 丢整叠」两种。{@code all=true}（或缺省 count）\n     * ⇒ 整叠；{@code count=1} ⇒ 丢一个；{@code 1<count<叠数} ⇒ 连点 {@code count} 次丢一个。\n     *\n     * <p>回执（{@code GuiResult.data}）：{@code slot}、{@code count}（**实际丢掉的个数**）、\n     * {@code requested}（请求的 count / all）、{@code empty}（丢后该格是否空）、\n     * {@code remaining}（丢后该格剩余个数）、{@code id}（丢后该格物品 id；空 ⇒ null）。\n     *\n     * <p>fail-loud：不在世界 ⇒ {@code NOT_IN_WORLD}；下标越界 / 开容器时 armour/offhand 不在该菜单\n     * ⇒ {@code SLOT_OUT_OF_RANGE}；没受理 ⇒ 如实失败。\n     */\n    default GuiResult dropItem(int slot, int count, boolean all) {\n        return GuiResult.fail(GuiResult.UNSUPPORTED,\n                \"本档未实现 drop_item（GameBridge#dropItem）\");\n    }\n\n    /**\n     * **玩家模式 / 能力自报**（{@code query_player_state} 的 {@code gameMode/flying/canFly/cheats}）。\n     * 默认 {@code null} = 本档不报（core 把四者一律留 null 并加人话，**不编**）。\n     *\n     * <p>为什么单独一个方法而不是塞进 {@link #playerStateJson()}：{@code playerStateJson} 被\n     * {@code query_state}/{@code query_map} 也吃 ⇒ 往里加键会改动那两条的既有回执形状；本方法\n     * **只喂 {@code query_player_state}**，其余动作逐字不变。\n     *\n     * <p>形状（**取不到的键留 null，不编**；适配层按本档实况给）：\n     * <pre>\n     * {\"gameMode\":\"survival\"|\"creative\"|\"adventure\"|\"spectator\"|null,\n     *  \"flying\":bool|null,\"canFly\":bool|null,\"cheats\":bool|null,\n     *  \"note\":\"…（这一档从哪取的、哪个拿不到）\"}\n     * </pre>\n     * {@code gameMode} 用**原版枚举名**（小写）；{@code cheats} 只对**本机集成服务器**有意义\n     * （多人服拿不到 ⇒ 留 null）。\n     */\n    default String playerMetaJson() {\n        return null;\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/GameStateService.java": "package com.bandd.playtest.core;\n\nimport java.util.ArrayList;\nimport java.util.HashSet;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\nimport java.util.TreeSet;\n\n/**\n * **（半）实时游戏状态器**：在 mod 内**持续刷新并缓存**一张「网格 + 高度」的文本地图 + 状态快照，\n * 查询**只读缓存**（不是每次查询现场全扫）。\n *\n * <h3>线程与分帧纪律（硬约束）</h3>\n * <ul>\n *   <li>{@link #tick()} 由客户端 tick 线程调（{@link PlaytestCore#onTick()} 里挂钩）。</li>\n *   <li>扫描**每 tick 只推进 {@link StateConfig#columnsPerTick} 格**（分帧）——\n *       **绝不允许一次全扫**（48×48 = 2304 格一次扫会卡 tick 线程）。</li>\n *   <li>**扫完一整张才启用**：{@link #tick()} 里扫满一整张才会把 pending 提为 active；\n *       查询只读 active。扫描中途查询 ⇒ 回上一张已完成的图 + {@code scan} 进度。</li>\n *   <li>查询（{@link #query(Map)}）在 tick 线程（ActionQueue）跑，只读数组、不做 MC 调用。</li>\n * </ul>\n *\n * <h3>版本语义</h3>\n * {@code stateVersion} 只在**一张完整的图与上一张内容不同**时自增（维度/原点/步长/格内容任一不同）。\n * 扫描进行中或「重采后内容一模一样」都**不动**版本 ⇒ 客户端拿 {@code sinceVersion} 轮询时\n * 未变的那次只回 {@code {unchanged:true, stateVersion, tick}}，**不回整张图**。\n *\n * <h3>地图口径（用户拍板）</h3>\n * 每格 = **方块码 1 字符 + 高度数字定宽字段**（固定宽度 ⇒ 不靠空格对齐、不粘连）；\n * 玩家所在格把方块码换成 {@link StateConfig#playerMark}（高度字段保留）；\n * 未知格（{@code blockAt} 回 null）用 {@link StateConfig#unknownCode} + 高度全 '?'，**不崩**。\n *\n * <h3>图例口径（legend / legendUnused —— 只广告图里真有的码）</h3>\n * {@code legend} **只列本张渲染出来的 {@code grid} 里真实出现的码**（方块码按 id 升序）：\n * 未知码只在图里真有未知格时出现、方块码只在图里真采到时出现、溢出码只在实际画了溢出码时出现。\n * 玩家格的 {@link StateConfig#playerMark} **不是方块码**，永不进 {@code legend}（它由\n * {@code playerMark} + {@code playerCell}/{@code playerCellOutside} 自报）；\n * 因此若某方块**只出现在玩家那一格**，它的码不会进 {@code legend}，而是进 {@code legendUnused}。\n * 本张快照**已分配码、但没画进本图**的方块码（降采样/截断漏掉，或只被玩家标记盖住）如实列进\n * {@code legendUnused}（形如 {@code [{\"code\":\"P\",\"id\":\"minecraft:oak_fence\"}]}，空数组 = 全用上）。\n * {@code legendOverflow} 语义不变：码位用尽时列出的额外 id 列表（本张快照里落在 overflowCode 的 id，按 id 升序）。\n *\n * <h3>会话码表（paletteEpoch / paletteSize）—— 修 bug：方块码跨扫描不稳定</h3>\n * 真机实证（fabric-1.21.11，{@code stateVersion} 6 → 7）：挖掉脚下一格 ⇒ 高度只降 1，但 2304 格里有\n * 2248 格的**方块码整体位移**（新暴露的 id 按字典序插到前面 ⇒ 后面全体 +1）⇒ AI 无法跨快照追踪\n * 同一块地、{@code sinceVersion} 省 token 的设计被架空。\n *\n * <p>新口径：码表**按会话持久、只追加**（{@code idToCode} / {@code nextSlot} / {@code usedCodes}）——\n * <ul>\n *   <li>同一 {@code paletteEpoch} 内，**同一方块 id 的码恒定不变**；</li>\n *   <li>新出现的 id 拿**未用过的**码；**永不回收、永不重排**已有码；</li>\n *   <li>码位（{@code cfg.palette}，默认 52 个：A-Z a-z）用尽后，新 id 一律画\n *       {@code cfg.overflowCode}（{@code '#'}）并进 {@code legendOverflow}；</li>\n *   <li>{@code paletteSize} = 本世代**已分配过码**的 id 总数（**含本图未出现的**；本张快照里已分配码\n *       但没画进 grid 的仍如实进 {@code legendUnused}）。码表**单调增**，只有换世代才会缩小。</li>\n * </ul>\n *\n * <p>**重置边界（只此三处，别处不许清空码表）**：\n * <ol>\n *   <li>换维度：{@code completeScan} 检测到 {@code sDim != dim}；</li>\n *   <li>换世界：{@code open_world} / {@code join_server} 由 {@link PlaytestCore} **显式**调\n *       {@link #resetPalette(String)}（同一维度名下的两个存档是**不同世界**，维度判据抓不到 ⇒ 必须显式重置）；</li>\n *   <li>渲染码表配置变了（{@code cfg.palette} 指纹变化 ⇒ 旧码可能已不在码表里）。</li>\n * </ol>\n * 重置时**丢弃当前快照**（{@code mapReady=false}）：旧世界的图不能拿新码表渲染（否则整张变 overflowCode）。\n * 同一会话内**正常重扫（refresh / 主动刷新）绝不重置** ⇒ 码稳定。\n *\n * <h3>step 参数口径（fail-loud，不许静默）</h3>\n * <ul>\n *   <li>省略 {@code step} ⇒ 自动降采样（按 maxChars 决定，最粗不超过 maxAutoStep）。</li>\n *   <li>{@code step < 1}（含 0 / 负数）⇒ 视为**未指定**、走自动规则；回执必带\n *       {@code stepClampedTo} + {@code stepNote}（不再静默变成 1）。</li>\n *   <li>{@code step >= 1} ⇒ 先抬到不小于扫描步长、再夹到不超过 {@code maxAutoStep}、最后对齐到扫描步长倍数；\n *       只要最终值与请求值不同，回执必带 {@code stepRequested}/{@code stepClampedTo}/{@code stepNote}。</li>\n * </ul>\n *\n * <h3>实体层（{@code entityGrid} / {@code entityLegend} / {@code entities[]}）—— 叠加，不是另起一张图</h3>\n * {@link StateConfig#includeEntities}（或本次调用的 {@code entities=true|false}）打开后，地图头里**多一层**\n * 与 {@code grid} **同几何**的定宽字符网格 {@code entityGrid}：\n * <ul>\n *   <li>同 {@code cols}/{@code rows}/{@code step}/{@code origin}/{@code cellWidth}（每格也是 {@code cellWidth} 个字符）；</li>\n *   <li>空格子 = 填充符 {@link #ENTITY_FILL}（{@code \".\"}）；玩家格画 {@code playerMark}；\n *       **该格内有实体时实体标记优先**（实体明细 {@code entities[]} 永远完整，不会因被标记盖住就丢）；</li>\n *   <li>**绝不许覆盖方块层**：方块码只出现在 {@code grid} 里；{@code entityGrid} 的标记是**另一个命名空间**\n *       （类别字母 {@code i/x/v/r/m/a/e}），有**独立**的 {@code entityLegend}，也**不进** {@code legend}/{@code legendUnused}；</li>\n *   <li>{@code entities[]} = 半径内实体的明细（type / cls / 类别 / 世界坐标 / 与玩家距离 / 是否落在图内 + 格坐标），\n *       **按距离由近到远排序**；</li>\n *   <li>半径内没实体 ⇒ 如实给**空层**（全填充符 + {@code entityCount:0} + {@code entityNote}），不是错误、更不是「编一个」；</li>\n *   <li>本档没有实体扫描面（{@code GameBridge#nearbyEntitiesJson} 回 null / 没自报\n *       {@code entityScanCapable()}）⇒ 头里如实写 {@code entitiesIncluded:false} + {@code entitiesNote}，**不假装有**。</li>\n * </ul>\n * 实体缓存由 {@link #tick()}（客户端 tick 线程）每 tick 刷新一次，查询只读缓存 —— 与方块层同一个纪律：\n * **HTTP / 查询侧一次 MC 调用都不做**。\n *\n * <p>Java 8 兼容（与 54 个老档共用同一份 core 源码）。\n */\npublic final class GameStateService {\n\n    /** 状态快照 schema（动作回执顶层带它）。 */\n    public static final String STATE_SCHEMA = \"bandd-state/1\";\n    /** 地图 schema（地图头里带它）。 */\n    public static final String MAP_SCHEMA = \"bandd-state-map/1\";\n    /** 轴向说明（**写死**，不许靠读者猜）。 */\n    public static final String AXIS_NOTE =\n            \"列 0..cols-1 向右 = +x（东）；行 0..rows-1 向下 = +z（南）；原点(左上角) = 最西北那格\";\n    /** 高度口径（写进地图头，别让读者猜 h 是什么）。 */\n    public static final String HEIGHT_MODE =\n            \"每列最高非空气方块的 Y（WORLD_SURFACE 高度图：getTopY/getHeight(type,x,z) - 1）\";\n    /**\n     * [T16] 本档（1.18+ 主世界口径）的**建高下限**：{@code topSolidY < 此值} ⇒ 该列**没有任何方块**\n     * ⇒ 判未知（问号），不当地表画。\n     *\n     * <p>为什么必须有这条：真机两档都复现 —— 客户端在**未加载区块**上回的不是 null，而是\n     * {@code minecraft:void_air} 且 {@code topSolidY=-65}（适配层那条加载判据实际没拦住）。\n     * core 用两条判据兜底：① 该格地表方块 id 是 void_air；② topSolidY 低于本下限。\n     * **不改**各档适配层的加载 API（跨版本四声部、风险大）。\n     */\n    public static final int SURFACE_MIN_BUILD_Y = -64;\n    /** 未知格的图例名。 */\n    public static final String UNKNOWN_ID = \"<unknown:未加载/越界/本档不支持>\";\n    /** [T16] 地图把 void_air / 低于建高下限的格判未知时的人话（只在真有这种格时进地图头）。 */\n    public static final String VOID_AIR_UNKNOWN_NOTE =\n            \"有格读到 minecraft:void_air（客户端在**未加载**区块回它而不是 null；真机两档 topSolidY=-65）\"\n            + \" 或 topSolidY 低于本档建高下限 \" + SURFACE_MIN_BUILD_Y\n            + \" ⇒ 这些格一律判**未知**（画 unknownCode、不进 legend），**不当地表方块画**；\"\n            + \"已加载区域不受影响。要看清哪一列未加载请用 query_column（它的 unloadedSuspect 是同一件事的列级自证）\";\n    /**\n     * 会话码表的自证说明（原样写进地图头 {@code paletteNote}）——\n     * 别让调用方猜 {@code paletteEpoch}/{@code paletteSize} 是什么，也别让它以为「码会随扫描重排」。\n     */\n    public static final String PALETTE_NOTE =\n            \"同一 paletteEpoch 内，同一方块 id 的码恒定不变（码表只追加：新 id 拿未用过的码，\"\n                    + \"已有码永不回收、永不重排）；码位用尽后新 id 一律画 overflowCode 并进 legendOverflow。\"\n                    + \"paletteEpoch 只在换世界（open_world/join_server）/换维度/换码表配置时自增；\"\n                    + \"paletteSize = 本世代已分配过码的 id 总数（含本图未出现的）\";\n\n    // ---- 实体层（叠加层）----\n    /** 实体层空格子的填充符（写进地图头 {@code entityGridFill}，别让读者猜）。 */\n    public static final String ENTITY_FILL = \".\";\n    /** 实体层的几何 / 填充口径（原样写进地图头 {@code entityGridNote}）。 */\n    public static final String ENTITY_GRID_NOTE =\n            \"entityGrid 与 grid 同几何（同 cols/rows/step/origin/cellWidth），是**另一层**行宽相同的字符网格；\"\n                    + \"每格 cellWidth 个字符：空格子 = entityGridFill 重复 cellWidth 次，\"\n                    + \"有标记的格 = 标记字符 + entityGridFill 重复 (cellWidth-1) 次；\"\n                    + \"玩家格画 playerMark，但**该格内有实体时实体标记优先**；\"\n                    + \"方块码只出现在 grid 里，本层的标记（类别字母）是独立命名空间，见 entityLegend\";\n    /** 实体层标记的命名空间说明（写进地图头，避免与方块码混淆）。 */\n    public static final String ENTITY_LEGEND_NOTE =\n            \"entityLegend 是**实体类别 → 标记字符**，与方块 legend 完全独立（不是方块码）；\"\n                    + \"标记按实体注册名/类简单名的子串**启发式**归类（i=掉落物 x=经验球 v=载具 r=投射物 \"\n                    + \"m=敌对 a=被动 e=其它），可能把模组实体归到 e；原始 type/cls 逐条写在 entities[] 里，不藏\";\n    /** 半径内没有实体时的话（如实给空层，不是错误）。 */\n    public static final String ENTITY_EMPTY_NOTE =\n            \"本张地图的实体半径内当前**没有**实体 ⇒ entityGrid 全为填充符、entities 为空数组（如实给空层，不是编的）\";\n\n    private final GameBridge bridge;\n    private final StateConfig cfg;\n\n    // ---- 进行中的扫描（pending）----\n    private boolean scanning;\n    private int sStep, sOriginX, sOriginZ, sCols, sRows, sCursor;\n    private String[] sCodes;\n    private int[] sHeights;\n    private String sDim;\n    private int sStartedTick;\n    private int sErrors;\n    private String sLastError;\n    /** [T16] 本次扫描里被判为 void_air 未知的格数（未加载区自证；写进地图头）。 */\n    private int sVoidAir;\n\n    // ---- 已完成的快照（active；查询只读这一份）----\n    private boolean ready;\n    private int version;\n    private int cols, rows, step, originX, originZ;\n    private String[] codes;\n    private int[] heights;\n    private String dim;\n    private int builtTick;\n    private int yMin = Integer.MAX_VALUE;\n    private int yMax = Integer.MIN_VALUE;\n    private int heightWidth = 1;\n    /** [T16] 当前快照里因 void_air / 低于建高下限被判未知的格数（>0 才进地图头）。 */\n    private int voidAirUnknown;\n    // ---- 会话码表（**只追加**：同一 paletteEpoch 内同一 id 的码不变；见类注释）----\n    /** id → 码。**只增不改**；只有 {@link #resetPalette(String)} 会清空（= 换世代）。 */\n    private final Map<String, Character> idToCode = new LinkedHashMap<String, Character>();\n    /** 本世代**已经发出去过**的码（不回收 ⇒ 新 id 拿到的码一定是本世代没出现过的字符）。 */\n    private final Set<Character> usedCodes = new HashSet<Character>();\n    /** palette 里下一个待分配的槽位（单调递增；配 {@link #usedCodes} 双保险）。 */\n    private int nextSlot;\n    /** 码表世代号：同一世代内同一 id 的码不变；重置时 +1（写进地图头 {@code paletteEpoch}）。 */\n    private int paletteEpoch = 1;\n    /** 本世代建立时对应的维度（诊断用）。 */\n    private String paletteDim;\n    /** 本世代建立时的 palette 指纹（配置改了 ⇒ 旧码可能非法 ⇒ 必须换世代）。 */\n    private String paletteFingerprint;\n    /** 重置次数 / 最近一次重置原因（{@code /status} 自报）。 */\n    private int paletteResets;\n    private String paletteResetReason;\n    // ---- 本张快照的码记账（legend / legendUnused / legendOverflow 都是**按张**的）----\n    /** 本张快照里**已分配到码**的 id（按 id 升序；= legend ∪ legendUnused 的签名域）。 */\n    private final List<String> snapshotAllocatedIds = new ArrayList<String>();\n    /** 本张快照里**没有码可用**（码位用尽）的 id（按 id 升序，最多留 64 个样本）。 */\n    private final List<String> overflowIds = new ArrayList<String>();\n    /** 本张快照落在 overflowCode 的 id **总数**（overflowIds 只留前 64 个样本）。 */\n    private int overflowTotal;\n    private boolean legendOverflow;\n\n    // ---- 实体层缓存（由 tick() 每 tick 刷新；查询只读）----\n    /** 半径内实体明细（**上一 tick** 的读数）。 */\n    // 这些字段在 **tick 线程写、HTTP 线程（/status）读** ⇒ 全部 volatile（否则读到的是撕裂的旧值）。\n    private volatile List<EntityRec> entities = new ArrayList<EntityRec>();\n    /** 桥有没有真的给过实体数据（区分「不支持」与「这一刻真没有」）。 */\n    private volatile boolean entitySupported;\n    /** 有没有探测过（不支持的档只调一次，之后不再每 tick 空调）。 */\n    private volatile boolean entityProbed;\n    /** 上次刷新的 tick / 解析失败原因（自报用）。 */\n    private volatile int entityRefreshedTick = -1;\n    private volatile String entityLastError;\n    /** 上次实体扫描用的半径（格）；-1 = 还没扫过。 */\n    private volatile double entityRadiusUsed = -1.0;\n    /** 上一 tick 桥报的实体总数（可能 > entities.size()，如实留档）。 */\n    private volatile int entityReportedTotal = -1;\n\n    // ---- [T14] 纵层 yMode：会话**纵层专用**码表（同一张 palette，**从末尾倒着发**）----\n    /**\n     * 地表图上**天然不出现**的 id（最典型的是 {@code minecraft:air}）用的纵层专用码。\n     *\n     * <p>为什么不并进 {@link #idToCode}：既有契约里 {@code paletteSize} = 「地表图发出过的码数」\n     * （单测 StateTest K6/L1/L5 逐字钉着它）。纵层新出现的 id 若也写进 {@code idToCode}，\n     * 会把那个口径改掉。这里改成**同一张 palette、同一个 {@link #usedCodes}、但从末尾倒着发的\n     * 第二只只追加游标** ⇒ 同一 id 仍只有一个码、码仍全局唯一、仍只追加不回收，\n     * 而 {@code paletteSize} 的口径一字不动（另给 {@code layerPaletteSize} 自报）。\n     */\n    private final Map<String, Character> layerIdToCode = new LinkedHashMap<String, Character>();\n    /** 纵层专用游标：从 palette **末尾**往前找第一个没被 {@link #usedCodes} 占掉的字符。 */\n    // ---- [T14] 纵层 yMode：分帧采样 job（进行中）与已发布快照（查询只读） ----\n    private volatile YLJob ylJob;\n    private volatile YLJob ylDone;\n    private volatile boolean ylEverRan;\n    private volatile int ylRuns;\n    private String ylLastCancelReason;\n\n    // ---- 计数 ----\n    private int ticks;\n    private int lastScanStart = -1000000;\n    private int scansCompleted;\n    private int refreshes;\n\n    public GameStateService(GameBridge bridge, StateConfig cfg) {\n        this.bridge = bridge;\n        this.cfg = cfg == null ? new StateConfig() : cfg;\n        this.cfg.sanitize();\n    }\n\n    /** 给 T3（设置页面）用的唯一入口：读就 {@code core.state().config()}。 */\n    public StateConfig config() {\n        return cfg;\n    }\n\n    // ==================================================================\n    // 1. 每个客户端 tick：分帧推进扫描 + 到期主动重采\n    // ==================================================================\n\n    /**\n     * 客户端 tick 线程每 tick 一次。**这里**是唯一调用 {@code blockAt}/{@code topSolidY}\n     * 与 {@code nearbyEntitiesJson} 的地方（查询侧一次 MC 调用都不做）。\n     */\n    public void tick() {\n        ticks++;\n        refreshEntities();                          // 实体层：每 tick 刷一遍（不支持的档只调一次，之后不再空调）\n        if (!bridge.stateMapCapable()) return;      // 本档没有取值面 ⇒ 一格都不扫（老档零开销）\n        if (!bridge.ready()) {                       // 没有玩家/世界（菜单、加载中）\n            scanning = false;                        // 中止进行中的扫描；已完成的快照留着\n            sqActive = false;                        // [T13] 方框搜索同理中止（不假装还在扫）\n            if (ylJob != null) {                     // [T14] 纵层采样同理中止（不假装还在扫）\n                ylLastCancelReason = \"玩家 / 世界不在场 ⇒ 本次纵层采样中止（已采的丢弃）\";\n                ylJob = null;\n            }\n            refreshPlayerDepth();                    // [T13] ⑦ 没有玩家 ⇒ 深度一律 null + 如实说明\n            return;\n        }\n        refreshPlayerDepth();                        // [T13] ⑦ 每 tick 刷一次地表深度（1 次 topSolidY）\n        advanceSearch();                             // [T13] ⑥b 分帧推进方框搜索（每 tick ≤ 256 格）\n        advanceLayerScan();                          // [T14] ⑧ 分帧推进纵层采样（每 tick ≤ columnsPerTick 格）\n        if (!scanning) {\n            if (ticks - lastScanStart < cfg.refreshIntervalTicks) return;\n            startScan(cfg.step, cfg.chunkRadius, false);\n            if (!scanning) return;\n        }\n        scanSlice(cfg.columnsPerTick);\n    }\n\n    /** 立刻重采一张（分帧照旧；{@code refresh:true} 与主动刷新都走这里）。 */\n    public boolean requestRefresh() {\n        if (!bridge.stateMapCapable() || !bridge.ready()) return false;\n        refreshes++;\n        startScan(cfg.step, cfg.chunkRadius, true);\n        return true;\n    }\n\n    private void startScan(int reqStep, int reqRadius, boolean force) {\n        double[] pxz = playerXZ();\n        if (pxz == null) return;\n        int bx = (int) Math.floor(pxz[0]);\n        int bz = (int) Math.floor(pxz[1]);\n        int cx = floorDiv(bx, 16);\n        int cz = floorDiv(bz, 16);\n        int r = Math.max(0, reqRadius);\n        int st = Math.max(1, reqStep);\n        int side = (2 * r + 1) * 16;\n        int c = ceilDiv(side, st);\n        int rw = c;\n        sStep = st;\n        sOriginX = (cx - r) * 16;\n        sOriginZ = (cz - r) * 16;\n        sCols = c;\n        sRows = rw;\n        sCursor = 0;\n        sErrors = 0;\n        sLastError = null;\n        sVoidAir = 0;\n        sCodes = new String[c * rw];\n        sHeights = new int[c * rw];\n        sDim = dimOf();\n        sStartedTick = ticks;\n        scanning = true;\n        lastScanStart = ticks;\n        if (force) { /* 主动刷新：上一次未完成的扫描直接丢弃 */ }\n    }\n\n    private void scanSlice(int budget) {\n        int total = sCols * sRows;\n        int done = 0;\n        while (done < budget && sCursor < total) {\n            int idx = sCursor;\n            int i = idx % sCols;\n            int j = idx / sCols;\n            int bx = sOriginX + i * sStep;\n            int bz = sOriginZ + j * sStep;\n            try {\n                int top = bridge.topSolidY(bx, bz);\n                // [T16] 未加载区块：客户端回的是 minecraft:void_air（不是 null）且 topSolidY 低到 -65。\n                // 两条判据（id 是 void_air / 低于本档建高下限）都判**未知** —— 画问号、不进 legend。\n                // 只在 core 判；**不动**各档适配层的加载 API（见 SURFACE_MIN_BUILD_Y 的类注释）。\n                if (top == Integer.MIN_VALUE) {\n                    sHeights[idx] = Integer.MIN_VALUE;      // 适配层如实回「取不到」\n                    sCodes[idx] = null;\n                } else if (top < SURFACE_MIN_BUILD_Y) {\n                    sHeights[idx] = Integer.MIN_VALUE;      // 低于建高下限 = 这一列什么都没有（未加载形状）\n                    sCodes[idx] = null;\n                    sVoidAir++;\n                } else {\n                    String id = bridge.blockAt(bx, top, bz);\n                    if (isVoidAirId(id)) {\n                        sHeights[idx] = Integer.MIN_VALUE;  // 客户端在未加载区块回 void_air（不是 null）\n                        sCodes[idx] = null;\n                        sVoidAir++;\n                    } else {\n                        sHeights[idx] = top;\n                        sCodes[idx] = id;\n                    }\n                }\n            } catch (Throwable t) {\n                // 适配层炸了也不许把游戏 tick 带崩：这一格记「未知」并如实计数\n                sHeights[idx] = Integer.MIN_VALUE;\n                sCodes[idx] = null;\n                sErrors++;\n                sLastError = String.valueOf(t);\n            }\n            sCursor++;\n            done++;\n        }\n        if (sCursor >= total) completeScan();\n    }\n\n    private void completeScan() {\n        scanning = false;\n        // ---- 会话码表的**重置边界**（只此三处；别处不许清空码表）----\n        // ① 换维度：新旧世界的 id 集合语义不同，旧码带过去就是张冠李戴。\n        // ② 换码表配置：旧码可能已不在 cfg.palette 里 ⇒ 不能再用。\n        // ③ 换世界（open_world / join_server）：不在维度判据里（同一维度名下的另一个存档是同名不同世界）\n        //    ⇒ 由 PlaytestCore 显式调 resetPalette()。见类注释。\n        boolean dimChanged = ready && (dim == null ? sDim != null : !dim.equals(sDim));\n        if (dimChanged) resetPalette(\"dimension:\" + (sDim == null ? \"?\" : sDim));\n        if (paletteFingerprint != null && !paletteFingerprint.equals(cfg.palette)) {\n            resetPalette(\"palette-config-changed\");\n        }\n        boolean same = ready\n                && step == sStep && originX == sOriginX && originZ == sOriginZ\n                && cols == sCols && rows == sRows\n                && (dim == null ? sDim == null : dim.equals(sDim));\n        if (same) {\n            for (int i = 0; i < codes.length; i++) {\n                if (heights[i] != sHeights[i]) { same = false; break; }\n                String a = codes[i];\n                String b = sCodes[i];\n                if (a == null ? b != null : !a.equals(b)) { same = false; break; }\n            }\n        }\n        scansCompleted++;\n        if (same) return;                 // 内容没变：stateVersion 不动（sinceVersion 才可能回 unchanged）\n        codes = sCodes;\n        heights = sHeights;\n        voidAirUnknown = sVoidAir;\n        step = sStep;\n        originX = sOriginX;\n        originZ = sOriginZ;\n        cols = sCols;\n        rows = sRows;\n        dim = sDim;\n        builtTick = ticks;\n        rebuildLegend();\n        version++;\n        ready = true;\n    }\n\n    /**\n     * 重建 yMin/yMax、高度字段宽度，并给本张快照的 id **分配/复用**会话码（只追加）。\n     * 只在内容变化时做。\n     */\n    private void rebuildLegend() {\n        yMin = Integer.MAX_VALUE;\n        yMax = Integer.MIN_VALUE;\n        TreeSet<String> ids = new TreeSet<String>();\n        for (int i = 0; i < codes.length; i++) {\n            int h = heights[i];\n            if (h != Integer.MIN_VALUE) {\n                if (h < yMin) yMin = h;\n                if (h > yMax) yMax = h;\n            }\n            if (codes[i] != null) ids.add(codes[i]);\n        }\n        int w = 1;\n        if (yMin != Integer.MAX_VALUE) {\n            w = Math.max(Integer.toString(yMin).length(), Integer.toString(yMax).length());\n        }\n        heightWidth = Math.max(cfg.minHeightWidth, w);\n\n        // ---- 会话码表：**只追加** --------------------------------------------------\n        // 这里**绝不 clear()**：旧 bug 就是每张都从零重建、按 id 升序重排 ⇒ 插入一个字典序靠前的\n        // 新 id 会把后面所有码整体 +1（真机 2248/2304 格变化）。只有 resetPalette() 才允许清空。\n        if (paletteFingerprint == null) paletteFingerprint = cfg.palette;\n        if (paletteDim == null) paletteDim = dim;\n        snapshotAllocatedIds.clear();\n        overflowIds.clear();\n        overflowTotal = 0;\n        for (String id : ids) {          // ids 是 TreeSet ⇒ 按 id 升序，输出顺序确定、可复现\n            Character c = assignCode(id);\n            if (c != null) {\n                snapshotAllocatedIds.add(id);\n            } else {\n                overflowTotal++;\n                if (overflowIds.size() < 64) overflowIds.add(id);\n            }\n        }\n        legendOverflow = overflowTotal > 0;\n    }\n\n    /**\n     * 取（必要时**新发**）一个 id 的方块码 —— 本类的核心不变量。\n     *\n     * <p>规则：本世代已分配过的 id ⇒ 直接回原码（**永不改码**）；新 id ⇒ 拿 palette 里下一个\n     * **没用过**的槽位；槽位用尽 ⇒ 回 {@code null}（调用方按 {@code overflowCode} 画、\n     * 并记进 {@code legendOverflow}）。**永不回收、永不重排**。\n     */\n    private Character assignCode(String id) {\n        Character known = idToCode.get(id);\n        if (known != null) return known;\n        String pal = cfg.palette;\n        while (nextSlot < pal.length() && usedCodes.contains(Character.valueOf(pal.charAt(nextSlot)))) {\n            nextSlot++;                  // 防御：换过码表却没能换世代时，跳过本世代已用过的字符\n        }\n        if (nextSlot >= pal.length()) return null;   // 码位用尽：新 id 一律 overflowCode\n        Character fresh = Character.valueOf(pal.charAt(nextSlot));\n        nextSlot++;\n        idToCode.put(id, fresh);\n        usedCodes.add(fresh);\n        return fresh;\n    }\n\n    /**\n     * **换世代**：清空会话码表，并丢弃当前快照（旧世界的图不能拿新码表渲染 ⇒ 否则整张变 overflowCode）。\n     *\n     * <p>只许在类注释列出的三个边界调用：换世界（{@code open_world} / {@code join_server}，\n     * 由 {@link PlaytestCore} 显式调）、换维度、换码表配置。**正常重扫（refresh）绝不调用。**\n     *\n     * <p>注意：这里**不动** {@code stateVersion}（版本只由「完整图内容变化」推进）；\n     * 而 {@code ready=false} ⇒ 快照回执如实报 {@code mapReady=false} + {@code mapNote}，不拿旧图充数。\n     */\n    public void resetPalette(String reason) {\n        paletteEpoch++;\n        paletteResets++;\n        paletteResetReason = reason;\n        idToCode.clear();\n        usedCodes.clear();\n        nextSlot = 0;\n        snapshotAllocatedIds.clear();\n        overflowIds.clear();\n        overflowTotal = 0;\n        legendOverflow = false;\n        paletteFingerprint = null;\n        paletteDim = null;\n        // [T14] 纵层专用码表 / 已发布快照与纵层采样**同属本世代** ⇒ 一起清（同一张 palette，同一套只追加规则）\n        layerIdToCode.clear();\n        ylDone = null;\n        ylJob = null;\n        ylLastCancelReason = \"换世代（resetPalette）⇒ 纵层采样与已发布快照一并作废\";\n        ready = false;                 // 旧图作废：新世界的第一张图扫完一整张才会 mapReady=true\n        scanning = false;\n        lastScanStart = -1000000;      // 别等 refreshIntervalTicks：下一 tick 立刻重新开扫\n    }\n\n    // ==================================================================\n    // 2. 查询（只读缓存）\n    // ==================================================================\n\n    /**\n     * 取状态快照（可选地图）。参数面：\n     * <ul>\n     *   <li>{@code sinceVersion}（long，省略/负数 = 一定要整张）：与 {@code stateVersion} 相同 ⇒\n     *       只回 {@code {unchanged:true, stateVersion, tick}}，**不回整张图**。</li>\n     *   <li>{@code refresh}（bool）：要求**立刻重采**；仍分帧（本次回的是上一张已完成的图 +\n     *       {@code scan} 进度），不是同步扫完。</li>\n     *   <li>{@code step}（int，可选）：只对**渲染**降采样。{@code <1} 视为未指定（走自动规则）；\n     *       合法的显式步长会被抬到不小于扫描步长、夹到不超过 {@code maxAutoStep}、并对齐到扫描步长倍数。\n     *       只要没能逐字采纳，回执（顶层与地图头两处同值）必带\n     *       {@code stepRequested}/{@code stepClampedTo}/{@code stepNote} —— 绝不静默。</li>\n     *   <li>{@code maxChars}（int，可选）：只覆盖**本次**的地图正文上限。</li>\n     *   <li>{@code entities}（bool，可选）：**只覆盖本次**要不要实体叠加层。省略 ⇒ 沿用\n     *       {@link StateConfig#includeEntities}（配置口径）。本档没有实体扫描面 ⇒ 头里如实写\n     *       {@code entitiesIncluded:false} + {@code entitiesNote}，不假装有。</li>\n     * </ul>\n     */\n    public Map<String, Object> query(Map<String, Object> p) {\n        return query(p, planY(p));\n    }\n\n    /**\n     * 与 {@link #query(Map)} 同一个实现，只是**纵层请求（{@link YPlan}）已由调用方解析好**\n     * （{@link PlaytestCore#dispatch} 先用 {@link #planY(Map)} 校验，参数不合法就回 BAD_REQUEST ——\n     * 与 query_column / query_blocks 的参数校验同一个落点，不把错误混进 ok 回执里）。\n     */\n    public Map<String, Object> query(Map<String, Object> p, YPlan plan) {\n        long since = -1L;\n        try {\n            since = (long) Double.parseDouble(Json.num(p, \"sinceVersion\", \"-1\").trim());\n        } catch (RuntimeException ignored) {\n        }\n        boolean refresh = Json.bool(p, \"refresh\", false);\n        // entities：调用方给了就以它为准，没给就沿用配置（默认 false）。与 step 一样「给了什么就按什么」。\n        boolean entitiesOn = cfg.includeEntities;\n        if (p != null && p.containsKey(\"entities\") && p.get(\"entities\") != null) {\n            entitiesOn = Json.bool(p, \"entities\", entitiesOn);\n        }\n        // step 必须区分「没给」与「给了 0 / 负数」：后者以前会被静默当成「没给」⇒ 现在如实回 stepNote。\n        boolean stepGiven = p != null && p.containsKey(\"step\") && p.get(\"step\") != null;\n        int reqStep = intParam(p, \"step\", 0);\n        int reqMax = intParam(p, \"maxChars\", 0);\n\n        if (refresh) requestRefresh();\n        else if (!ready && !scanning && bridge.ready()) startScan(cfg.step, cfg.chunkRadius, false);\n        // [T14] 纵层：有效模式不是 surface 就 arm 一次分帧采样（同一件事不重复 arm；\n        // 几何不同（换区块 / 改 step）⇒ 旧采样作废、按新几何重采）。arm 只排程，**不做 MC 调用**。\n        if (plan != null && plan.layersOn && ready && bridge.ready()) armLayerScan(plan);\n\n        Map<String, Object> out = new LinkedHashMap<String, Object>();\n        out.put(\"schema\", STATE_SCHEMA);\n        boolean unchanged = ready && since >= 0L && since == (long) version;\n        out.put(\"stateVersion\", ready ? (Object) Integer.valueOf(version) : null);\n        out.put(\"tick\", ticks);\n        out.put(\"unchanged\", unchanged);\n        if (unchanged) return out;      // 半实时：未变 ⇒ 只回这三样，不回整张图\n\n        Map<String, Object> st = Json.parseObject(bridge.playerStateJson());\n        Object dimNow = st.get(\"dimension\");\n        out.put(\"dimension\", dimNow != null ? dimNow : (ready ? dim : null));\n        out.put(\"player\", playerJson(st));\n        out.put(\"screen\", bridge.screenName());\n        Map<String, Object> env = envJson();\n        out.put(\"time\", env == null ? null : env.get(\"time\"));\n        out.put(\"weather\", env == null ? null : env.get(\"weather\"));\n        if (env != null && env.get(\"note\") != null) out.put(\"envNote\", env.get(\"note\"));\n        // [T13] ⑦ 玩家地表深度（每 tick 在 tick 线程刷新，这里只读缓存；取不到 ⇒ null + note）\n        out.putAll(depthJson());\n        out.put(\"mapReady\", ready);\n        out.put(\"scan\", scanJson());\n        if (ready) {\n            Map<String, Object> map = render(reqStep, reqMax, stepGiven, entitiesOn, plan);\n            out.put(\"map\", map);\n            // step 诊断同时挂在回执顶层（旧契约里 stepClampedTo 就在这一层）与地图头里，两处同值、不漂移。\n            mirrorStep(out, map);\n        } else {\n            out.put(\"map\", null);\n            out.put(\"mapNote\", \"首张地图还没扫完（分帧扫描中，每 tick \" + cfg.columnsPerTick\n                    + \" 格）；扫完一整张才会启用。用 scan.done/scan.total 看进度。\");\n        }\n        return out;\n    }\n\n    /** 只读缓存的自报段（给 /status）。 */\n    public Map<String, Object> status() {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"capable\", bridge.stateMapCapable());\n        m.put(\"ready\", ready);\n        m.put(\"stateVersion\", ready ? (Object) Integer.valueOf(version) : null);\n        m.put(\"scanInProgress\", scanning);\n        m.put(\"scansCompleted\", scansCompleted);\n        m.put(\"refreshRequests\", refreshes);\n        m.put(\"builtTick\", ready ? (Object) Integer.valueOf(builtTick) : null);\n        m.put(\"ticks\", ticks);\n        m.put(\"snapshotStep\", step);\n        m.put(\"snapshotOrigin\", xy(originX, originZ));\n        m.put(\"snapshotCols\", cols);\n        m.put(\"snapshotRows\", rows);\n        // 会话码表的自报（换世代后 paletteSize 会掉回 0，直到新世界的第一张图扫完）\n        m.put(\"paletteEpoch\", Integer.valueOf(paletteEpoch));\n        m.put(\"paletteSize\", Integer.valueOf(idToCode.size()));\n        m.put(\"paletteCapacity\", Integer.valueOf(cfg.palette.length()));\n        m.put(\"paletteResets\", Integer.valueOf(paletteResets));\n        m.put(\"paletteResetReason\", paletteResetReason);\n        // 实体叠加层的自报（**只读缓存，不碰 MC** ⇒ /status 在 HTTP 线程上也安全）\n        m.put(\"entityScan\", entityStatus());\n        // [T13] 方框搜索 job 与地表深度的自报（同样只读缓存 ⇒ /status 安全）\n        m.put(\"blockSearch\", blockSearchStatus());\n        // [T14] 纵层只读自报（同样**不碰 MC** ⇒ HTTP 线程上安全）\n        Map<String, Object> yl = new LinkedHashMap<String, Object>();\n        yl.put(\"layerScan\", layerScanJson());\n        yl.put(\"layerPaletteSize\", Integer.valueOf(layerIdToCode.size()));\n        // [T16] 四个旋钮现在是**配置默认**（设置页可改）；这里如实报当前生效值。\n        yl.put(\"yLayerMaxDefault\", Integer.valueOf(cfg.yLayerMax));\n        yl.put(\"yLayerHardMax\", Integer.valueOf(Y_LAYER_HARD_MAX));\n        yl.put(\"yAutoDepth\", Integer.valueOf(cfg.yModeAutoDepth));\n        yl.put(\"yAutoRange\", Integer.valueOf(cfg.yAutoRange));\n        yl.put(\"yModeAuto\", Boolean.valueOf(cfg.yModeAuto));\n        yl.put(\"cellsPerTick\", Integer.valueOf(Math.max(1, cfg.columnsPerTick)));\n        yl.put(\"note\", Y_LAYER_SCAN_NOTE);\n        m.put(\"yLayer\", yl);\n        m.put(\"playerDepth\", depthJson());\n        m.put(\"config\", cfg.toJson());\n        return m;\n    }\n\n    // ==================================================================\n    // 3. 渲染（只读 active）\n    // ==================================================================\n\n    private Map<String, Object> render(int reqStep, int maxCharsIn, boolean stepGiven, boolean entitiesOn,\n                                      YPlan plan) {\n        int maxChars = maxCharsIn > 0 ? maxCharsIn : cfg.maxChars;\n        // 渲染步长的硬上限 = maxAutoStep（对齐到扫描步长倍数）⇒ 显式 step 与自动降采样受**同一个**上限约束。\n        int stepCap = quantize(Math.max(cfg.maxAutoStep, step), step);\n        int rs;\n        if (stepGiven && reqStep >= 1) {\n            int want = Math.max(reqStep, step);\n            if (want > stepCap) want = stepCap;\n            rs = quantize(want, step);\n        } else {\n            // 未指定，或 step<1（明确按「未指定」处理）：自动降采样。\n            rs = step;\n            while (rs < stepCap && gridChars(rs) > maxChars) {\n                int next = quantize(rs * 2, step);\n                if (next <= rs) break;\n                rs = next;\n            }\n        }\n        int rc = colsAt(rs);\n        int rr = rowsAt(rs);\n        int cellW = cellWidth();\n        int rowLen = rc * cellW;\n        int total = gridChars(rs);\n        int shownRows = rr;\n        if (rowLen > 0) {\n            long fit = (maxChars + 1L) / (rowLen + 1L);\n            if (fit < rr) shownRows = (int) Math.max(0L, fit);\n        } else {\n            shownRows = 0;\n        }\n        boolean truncated = shownRows < rr;\n        int shownChars = shownRows <= 0 ? 0 : shownRows * rowLen + (shownRows - 1);\n        RenderedGrid rg = buildGrid(rs, shownRows);\n        String grid = rg.text;\n\n        int[] pc = playerCell(rs, rc, rr);\n        boolean outside = pc[0] < 0 || pc[1] < 0;\n        if (pc[0] < 0) pc[0] = 0;\n        if (pc[1] < 0) pc[1] = 0;\n\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"schema\", MAP_SCHEMA);\n        m.put(\"stateVersion\", version);\n        m.put(\"tick\", ticks);\n        m.put(\"builtTick\", builtTick);\n        m.put(\"dimension\", dim);\n        m.put(\"origin\", xy(originX, originZ));\n        m.put(\"axis\", axisJson());\n        m.put(\"step\", rs);\n        m.put(\"cols\", rc);\n        m.put(\"rows\", rr);\n        m.put(\"cellWidth\", cellW);\n        m.put(\"heightWidth\", cfg.includeHeight ? (Object) Integer.valueOf(heightWidth) : null);\n        m.put(\"includeHeight\", cfg.includeHeight);\n        m.put(\"heightMode\", cfg.includeHeight ? HEIGHT_MODE : null);\n        m.put(\"yMin\", yMin == Integer.MAX_VALUE ? null : (Object) Integer.valueOf(yMin));\n        m.put(\"yMax\", yMax == Integer.MIN_VALUE ? null : (Object) Integer.valueOf(yMax));\n        m.put(\"player\", playerJson(Json.parseObject(bridge.playerStateJson())));\n        m.put(\"playerMark\", String.valueOf(cfg.playerMark));\n        m.put(\"playerCell\", cellJson(pc[0], pc[1]));\n        m.put(\"playerCellOutside\", outside);\n        m.put(\"unknownCode\", String.valueOf(cfg.unknownCode));\n        m.put(\"overflowCode\", String.valueOf(cfg.overflowCode));\n        // 会话码表的**自证字段**：同一 paletteEpoch 内同一 id 的码不变（见 PALETTE_NOTE / 类注释）。\n        m.put(\"paletteEpoch\", Integer.valueOf(paletteEpoch));\n        m.put(\"paletteSize\", Integer.valueOf(idToCode.size()));\n        m.put(\"paletteCapacity\", Integer.valueOf(cfg.palette.length()));\n        m.put(\"paletteNote\", PALETTE_NOTE);\n        m.put(\"legend\", legendJson(rg));\n        m.put(\"legendUnused\", legendUnusedJson(rg));\n        if (legendOverflow) {\n            m.put(\"legendOverflow\", new ArrayList<String>(overflowIds));\n            m.put(\"legendOverflowTotal\", Integer.valueOf(overflowTotal));\n            m.put(\"legendOverflowNote\", \"码位（\" + cfg.palette.length() + \" 个）用尽：这 \" + overflowTotal\n                    + \" 个 id 与其它同类共用 overflowCode（已有码不回收、不重排）\");\n        }\n        // ================= 实体叠加层（**另一层平行网格**，绝不覆盖方块层）=================\n        // 头里**无条件**自报能力位：调用方不看内容也能知道「本档会不会给实体层」。\n        m.put(\"entityScanSupported\", Boolean.valueOf(bridge.entityScanCapable()));\n        if (entitiesOn) {\n            if (entitySupported) {\n                putEntityLayer(m, rs, rc, rr, shownRows);\n            } else {\n                m.put(\"entitiesIncluded\", Boolean.FALSE);\n                m.put(\"entitiesNote\", \"本次要求实体层（entities=true / StateConfig.includeEntities=true），\"\n                        + \"但本档给不出实体读数：\"\n                        + (bridge.entityScanCapable()\n                                ? \"适配层自报 entityScanCapable()=true，而 nearbyEntitiesJson 回 null\"\n                                        + \"（此刻取不到，或玩家/世界不在场）\"\n                                : \"GameBridge#nearbyEntitiesJson 回 null 且未自报 entityScanCapable()\")\n                        + \" ⇒ 如实不含实体层，**不假装有**\");\n                if (entityLastError != null) m.put(\"entityLastError\", entityLastError);\n            }\n        } else {\n            m.put(\"entitiesIncluded\", Boolean.FALSE);\n            m.put(\"entitiesNote\", \"本次未请求实体层（entities=false / StateConfig.includeEntities=false）\"\n                    + \" ⇒ 如实不含；要叠加请传 entities=true 或把 includeEntities 打开\");\n        }\n        m.put(\"truncated\", truncated);\n        m.put(\"shownRows\", shownRows);\n        m.put(\"shownChars\", shownChars);\n        m.put(\"totalChars\", total);\n        m.put(\"maxChars\", maxChars);\n        m.put(\"maxAutoStep\", cfg.maxAutoStep);\n        // [T16] 未加载区自证：真有 void_air / 低于建高下限的格才加这两个键（全加载的默认图**逐字不变**）。\n        if (voidAirUnknown > 0) {\n            m.put(\"voidAirUnknownBlocks\", Integer.valueOf(voidAirUnknown));\n            m.put(\"voidAirUnknownNote\", VOID_AIR_UNKNOWN_NOTE);\n        }\n        m.put(\"charsNote\", \"totalChars/shownChars 只数**网格正文**（含行间换行，不含头/图例）；maxChars 也只约束它\");\n        if (truncated) {\n            m.put(\"truncatedNote\", \"即使降到 step=\" + rs + \"（maxAutoStep=\" + cfg.maxAutoStep\n                    + \"）仍超 maxChars=\" + maxChars + \" ⇒ 按整行截断，只回前 \" + shownRows + \"/\" + rr + \" 行\");\n        }\n        // step 诊断（写进**地图头**；调用方给的 step 没被逐字采纳就必须说明，绝不静默）。\n        if (stepGiven) {\n            m.put(\"stepRequested\", Integer.valueOf(reqStep));\n            if (reqStep < 1) {\n                m.put(\"stepClampedTo\", Integer.valueOf(rs));\n                m.put(\"stepNote\", \"step=\" + reqStep + \" < 1 ⇒ 按「未指定」处理，走自动降采样；实际 step=\" + rs);\n            } else if (rs != reqStep) {\n                m.put(\"stepClampedTo\", Integer.valueOf(rs));\n                m.put(\"stepNote\", stepExplain(reqStep, rs, stepCap));\n            }\n        }\n        // [T13] ⑦ 玩家地表深度（**地图头**里也给一份，与 query_state 顶层同源同值）\n        m.putAll(depthJson());\n        m.put(\"grid\", grid);\n        // [T14] 纵层（**只追加**：surface 且调用方没给任何纵层参数时，plan.present=false ⇒ 一个新键都不加，\n        // 既有回执逐字不变；grid 本身在上面，位置与内容都没动）。\n        if (plan != null && plan.present) putYMode(m, plan, rs, rc, rr, shownRows, maxChars);\n        return m;\n    }\n\n    /** 把地图头里的 step 诊断镜像到回执顶层（旧契约 {@code stepClampedTo} 的落点），两处同值。 */\n    private static void mirrorStep(Map<String, Object> out, Map<String, Object> map) {\n        Object v = map.get(\"stepRequested\");\n        if (v != null) out.put(\"stepRequested\", v);\n        v = map.get(\"stepClampedTo\");\n        if (v != null) out.put(\"stepClampedTo\", v);\n        v = map.get(\"stepNote\");\n        if (v != null) out.put(\"stepNote\", v);\n    }\n\n    private RenderedGrid buildGrid(int rs, int shownRows) {\n        int k = rs / step;\n        int rc = colsAt(rs);\n        int[] pc = playerCell(rs, rc, rowsAt(rs));\n        StringBuilder b = new StringBuilder();\n        RenderedGrid out = new RenderedGrid();\n        for (int j = 0; j < shownRows; j++) {\n            if (j > 0) b.append('\\n');\n            int sj = j * k;\n            for (int i = 0; i < rc; i++) {\n                int idx = sj * cols + i * k;\n                char ch;\n                if (i == pc[0] && j == pc[1]) {\n                    // 玩家标记**按角色**记账（不是按字符）：它永远不是方块码，所以永不进 legend。\n                    ch = cfg.playerMark;\n                    out.usedPlayerMark = true;\n                } else {\n                    String id = codes[idx];\n                    if (id == null) {\n                        ch = cfg.unknownCode;\n                        out.usedUnknown = true;\n                    } else {\n                        Character c = idToCode.get(id);\n                        if (c == null) {\n                            ch = cfg.overflowCode;\n                            out.usedOverflow = true;\n                        } else {\n                            ch = c.charValue();\n                            out.usedBlockCodes.add(c);\n                        }\n                    }\n                }\n                b.append(ch);\n                if (cfg.includeHeight) b.append(fmtHeight(heights[idx], heightWidth));\n            }\n        }\n        out.text = b.toString();\n        return out;\n    }\n\n    /** 渲染结果 + **本图真实用到的码**（按角色记账 ⇒ 玩家标记不会混进方块码）。 */\n    private static final class RenderedGrid {\n        String text = \"\";\n        final Set<Character> usedBlockCodes = new HashSet<Character>();\n        boolean usedPlayerMark;\n        boolean usedUnknown;\n        boolean usedOverflow;\n    }\n\n    /** 定宽高度字段：正数补前导 0、负数留符号位 ⇒ **宽度恒定**（不靠空格对齐、不粘连）。 */\n    static String fmtHeight(int h, int w) {\n        if (h == Integer.MIN_VALUE) {\n            StringBuilder q = new StringBuilder();\n            for (int i = 0; i < w; i++) q.append('?');\n            return q.toString();\n        }\n        String s = Integer.toString(h);\n        if (s.length() >= w) return s;\n        StringBuilder b = new StringBuilder();\n        int pad = w - s.length();\n        if (h < 0) {\n            b.append('-');\n            for (int i = 1; i < pad; i++) b.append('0');\n            b.append(s.substring(1));\n        } else {\n            for (int i = 0; i < pad; i++) b.append('0');\n            b.append(s);\n        }\n        return b.toString();\n    }\n\n    private int cellWidth() {\n        return 1 + (cfg.includeHeight ? heightWidth : 0);\n    }\n\n    private int colsAt(int rs) {\n        return ceilDiv(cols * step, rs);\n    }\n\n    private int rowsAt(int rs) {\n        return ceilDiv(rows * step, rs);\n    }\n\n    private int gridChars(int rs) {\n        int rc = colsAt(rs);\n        int rr = rowsAt(rs);\n        int rowLen = rc * cellWidth();\n        return (rc <= 0 || rr <= 0) ? 0 : (rr * rowLen + rr - 1);\n    }\n\n    /** 玩家格（列/行）；不在图内返回 {-1,-1}（调用方如实写 playerCellOutside）。 */\n    private int[] playerCell(int rs, int rc, int rr) {\n        double[] pxz = playerXZ();\n        if (pxz == null) return new int[] { -1, -1 };\n        int c = (int) Math.floor((pxz[0] - originX) / (double) rs);\n        int r = (int) Math.floor((pxz[1] - originZ) / (double) rs);\n        if (c < 0 || r < 0 || c >= rc || r >= rr) return new int[] { -1, -1 };\n        return new int[] { c, r };\n    }\n\n    // ==================================================================\n    // 4. 小工具\n    // ==================================================================\n\n    /**\n     * 图例 = **本张 {@code grid} 里真实出现的码**（方块码按 id 升序）。玩家标记按角色排除；\n     * 未知码 / 方块码 / 溢出码都只有真的画进图里才列。\n     */\n    private Map<String, Object> legendJson(RenderedGrid rg) {\n        // 既有 legend 的语义**一字未动**：只列本张 grid 里真出现的码。\n        return legendFor(rg.usedBlockCodes, rg.usedUnknown, rg.usedOverflow);\n    }\n\n    /**\n     * 图例的公共实现（既有 {@code legend} 与新增 {@code layerLegend} 共用它 ⇒ 输出形状 / 排序 /\n     * 未知码 / 溢出码的口径**完全一致**；只是喂进来的「用到的码」集合不同）。\n     */\n    private Map<String, Object> legendFor(Set<Character> usedCodesIn, boolean usedUnknown, boolean usedOverflow) {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        if (usedUnknown) m.put(String.valueOf(cfg.unknownCode), UNKNOWN_ID);\n        // 只遍历**本张快照**的 id（会话码表里更早快照留下的 id 不该被本图广告）；\n        // 列表已按 id 升序 ⇒ 输出顺序确定、可复现。\n        for (String id : snapshotAllocatedIds) {\n            Character c = idToCode.get(id);\n            if (c != null && usedCodesIn.contains(c)) {\n                m.put(String.valueOf(c.charValue()), id);\n            }\n        }\n        if (legendOverflow && usedOverflow) {\n            m.put(String.valueOf(cfg.overflowCode), \"<\" + overflowTotal + \" 种，见 legendOverflow>\");\n        }\n        return m;\n    }\n\n    /** 本张快照**已分配码、但没画进本图**的方块码（按 id 升序；空数组 = 全部用上）。 */\n    private List<Object> legendUnusedJson(RenderedGrid rg) {\n        List<Object> out = new ArrayList<Object>();\n        // 同 legend：只列**本张快照**里已分配码、却没画进本图的 id（按 id 升序）。\n        for (String id : snapshotAllocatedIds) {\n            Character c = idToCode.get(id);\n            if (c != null && !rg.usedBlockCodes.contains(c)) {\n                Map<String, Object> one = new LinkedHashMap<String, Object>();\n                one.put(\"code\", String.valueOf(c.charValue()));\n                one.put(\"id\", id);\n                out.add(one);\n            }\n        }\n        return out;\n    }\n\n    /** 显式 step 没被逐字采纳时的**人话**原因（fail-loud）。 */\n    private String stepExplain(int req, int rs, int cap) {\n        StringBuilder n = new StringBuilder(\"step=\").append(req);\n        if (req < step) n.append(\" 细于扫描步长 \").append(step);\n        if (req > cap) n.append(\" 超过 maxAutoStep=\").append(cfg.maxAutoStep).append(\" 上限\");\n        if (req >= step && req <= cap) n.append(\" 不是扫描步长 \").append(step).append(\" 的整数倍\");\n        n.append(\" ⇒ 实际 step=\").append(rs).append(\"（如实回 stepClampedTo，不静默）\");\n        return n.toString();\n    }\n\n    private Map<String, Object> axisJson() {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"right\", \"+x（东）\");\n        m.put(\"down\", \"+z（南）\");\n        m.put(\"left\", \"-x（西）\");\n        m.put(\"up\", \"-z（北）\");\n        m.put(\"note\", AXIS_NOTE);\n        return m;\n    }\n\n    private Map<String, Object> scanJson() {\n        int total = sCols * sRows;\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"active\", scanning);\n        m.put(\"done\", scanning || total == 0 ? sCursor : total);\n        m.put(\"total\", total);\n        m.put(\"step\", sStep);\n        m.put(\"origin\", xy(sOriginX, sOriginZ));\n        m.put(\"cols\", sCols);\n        m.put(\"rows\", sRows);\n        m.put(\"startedTick\", sStartedTick);\n        m.put(\"errors\", sErrors);\n        if (sLastError != null) m.put(\"lastError\", sLastError);\n        return m;\n    }\n\n    private Map<String, Object> playerJson(Map<String, Object> st) {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"x\", intCell(st.get(\"x\")));\n        m.put(\"y\", intCell(st.get(\"y\")));\n        m.put(\"z\", intCell(st.get(\"z\")));\n        m.put(\"yaw\", dbl(st.get(\"yaw\")));\n        m.put(\"pitch\", dbl(st.get(\"pitch\")));\n        return m;\n    }\n\n    private Map<String, Object> envJson() {\n        String s = bridge.worldEnvJson();\n        if (s == null || s.isEmpty()) {\n            Map<String, Object> m = new LinkedHashMap<String, Object>();\n            m.put(\"note\", \"本档未提供 worldEnvJson() ⇒ 时间/天气取不到，如实留 null（不是 0/白天）\");\n            return m;\n        }\n        Map<String, Object> src = Json.parseObject(s);\n        Map<String, Object> time = new LinkedHashMap<String, Object>();\n        // 时间字段按**长整数**回（Json.parse 会把 JSON 数字读成 Double ⇒ 直接透出会变 \"6000.0\"，\n        // 时间戳是整数语义，别让它看起来像小数）。\n        time.put(\"timeOfDay\", longOrNull(src.get(\"timeOfDay\")));\n        time.put(\"dayTime\", longOrNull(src.get(\"dayTime\")));\n        Map<String, Object> weather = new LinkedHashMap<String, Object>();\n        weather.put(\"raining\", src.get(\"raining\"));\n        weather.put(\"thundering\", src.get(\"thundering\"));\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"time\", time);\n        m.put(\"weather\", weather);\n        return m;\n    }\n\n    private double[] playerXZ() {\n        Map<String, Object> st;\n        try {\n            st = Json.parseObject(bridge.playerStateJson());\n        } catch (RuntimeException e) {\n            return null;\n        }\n        Double x = dbl(st.get(\"x\"));\n        Double z = dbl(st.get(\"z\"));\n        if (x == null || z == null) return null;\n        return new double[] { x.doubleValue(), z.doubleValue() };\n    }\n\n    private String dimOf() {\n        try {\n            Object d = Json.parseObject(bridge.playerStateJson()).get(\"dimension\");\n            return d == null ? null : String.valueOf(d);\n        } catch (RuntimeException e) {\n            return null;\n        }\n    }\n\n    private static int intParam(Map<String, Object> p, String k, int dflt) {\n        try {\n            return (int) Double.parseDouble(Json.num(p, k, Integer.toString(dflt)).trim());\n        } catch (RuntimeException e) {\n            return dflt;\n        }\n    }\n\n    private static Integer intCell(Object v) {\n        Double d = dbl(v);\n        return d == null ? null : Integer.valueOf((int) Math.floor(d.doubleValue()));\n    }\n\n    /** 数值（整数或整值小数）⇒ Long；取不到 ⇒ null（**不编 0**）。 */\n    private static Object longOrNull(Object v) {\n        Double d = dbl(v);\n        return d == null ? null : (Object) Long.valueOf(d.longValue());\n    }\n\n    private static Double dbl(Object v) {\n        if (v instanceof Number) return Double.valueOf(((Number) v).doubleValue());\n        if (v instanceof String) {\n            try {\n                return Double.valueOf(Double.parseDouble(((String) v).trim()));\n            } catch (NumberFormatException e) {\n                return null;\n            }\n        }\n        return null;\n    }\n\n    private static Map<String, Object> xy(int x, int z) {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"x\", Integer.valueOf(x));\n        m.put(\"z\", Integer.valueOf(z));\n        return m;\n    }\n\n    private static Map<String, Object> cellJson(int col, int row) {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"col\", Integer.valueOf(col));\n        m.put(\"row\", Integer.valueOf(row));\n        return m;\n    }\n\n    private static int quantize(int v, int base) {\n        int b = Math.max(1, base);\n        int q = ((v + b - 1) / b) * b;\n        return Math.max(b, q);\n    }\n\n    private static int ceilDiv(int a, int b) {\n        return b <= 0 ? 0 : (a + b - 1) / b;\n    }\n\n    private static int floorDiv(int a, int b) {\n        int q = a / b;\n        if ((a ^ b) < 0 && q * b != a) q--;\n        return q;\n    }\n\n    // ==================================================================\n    // 5. 实体层（叠加层）—— 缓存刷新 / 归类 / 渲染\n    // ==================================================================\n\n    /** 实体扫描半径（格）：足够覆盖整张图的对角（地图是正方形 ⇒ 半对角 = 边长×√2/2），再 +1 保险。 */\n    private double entityRadiusBlocks() {\n        int side = cfg.mapSideBlocks();\n        return Math.max(4.0, Math.ceil(side * 0.7072) + 1.0);\n    }\n\n    /** 只读自报（给 /status；**不碰 MC**，HTTP 线程也能读）。 */\n    public Map<String, Object> entityStatus() {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"capable\", Boolean.valueOf(bridge.entityScanCapable()));\n        m.put(\"probed\", Boolean.valueOf(entityProbed));\n        m.put(\"supported\", Boolean.valueOf(entitySupported));\n        m.put(\"refreshedTick\", entityRefreshedTick < 0 ? null : Integer.valueOf(entityRefreshedTick));\n        m.put(\"radiusBlocks\", entityRadiusUsed < 0 ? null : Integer.valueOf((int) Math.round(entityRadiusUsed)));\n        m.put(\"cached\", Integer.valueOf(entities.size()));\n        m.put(\"reportedTotal\", entityReportedTotal < 0 ? null : Integer.valueOf(entityReportedTotal));\n        m.put(\"lastError\", entityLastError);\n        m.put(\"configIncludeEntities\", Boolean.valueOf(cfg.includeEntities));\n        m.put(\"fill\", ENTITY_FILL);\n        m.put(\"note\", \"实体层是**叠加**层：与 grid 同几何的平行网格，绝不动方块层；查询只读 tick() 刷新的缓存\");\n        return m;\n    }\n\n    /** 客户端 tick 线程每 tick 刷新实体缓存（不支持的档只调一次，之后直接返回）。 */\n    private void refreshEntities() {\n        if (!bridge.ready()) {\n            entities = new ArrayList<EntityRec>();\n            entitySupported = false;\n            entityProbed = false;\n            entityReportedTotal = -1;\n            return;\n        }\n        if (entityProbed && !entitySupported) return;   // 已知不支持：不再每 tick 空调\n        double r = entityRadiusBlocks();\n        entityRadiusUsed = r;\n        String json;\n        try {\n            json = bridge.nearbyEntitiesJson(r);\n        } catch (Throwable t) {\n            // 适配层炸了也不许把游戏 tick 带崩：如实记账，不当成「没有实体」\n            entities = new ArrayList<EntityRec>();\n            entitySupported = false;\n            entityProbed = true;\n            entityLastError = String.valueOf(t);\n            entityReportedTotal = -1;\n            return;\n        }\n        entityProbed = true;\n        entityRefreshedTick = ticks;\n        if (json == null) {\n            entities = new ArrayList<EntityRec>();\n            entitySupported = false;\n            entityReportedTotal = -1;\n            return;\n        }\n        entitySupported = true;\n        entityLastError = null;\n        entities = parseEntities(json);\n    }\n\n    /** 解析适配层给的实体 JSON；形状不对的**不编**，跳过并如实记 lastError。 */\n    private List<EntityRec> parseEntities(String json) {\n        List<EntityRec> out = new ArrayList<EntityRec>();\n        Map<String, Object> src;\n        try {\n            src = Json.parseObject(json);\n        } catch (RuntimeException e) {\n            entityLastError = \"解析实体 JSON 失败：\" + e;\n            entityReportedTotal = -1;\n            return out;\n        }\n        Object cnt = src.get(\"count\");\n        entityReportedTotal = (cnt instanceof Number) ? ((Number) cnt).intValue() : -1;\n        Object arr = src.get(\"entities\");\n        if (!(arr instanceof List)) {\n            entityLastError = \"实体 JSON 里没有 entities 数组\";\n            return out;\n        }\n        int bad = 0;\n        for (Object o : (List<?>) arr) {\n            if (!(o instanceof Map)) { bad++; continue; }\n            Map<?, ?> e = (Map<?, ?>) o;\n            Double x = dbl(e.get(\"x\")), y = dbl(e.get(\"y\")), z = dbl(e.get(\"z\"));\n            if (x == null || y == null || z == null) { bad++; continue; }   // 坐标取不到 ⇒ 不编\n            String type = e.get(\"type\") == null ? null : String.valueOf(e.get(\"type\"));\n            String cls = e.get(\"cls\") == null ? null : String.valueOf(e.get(\"cls\"));\n            out.add(new EntityRec(type, cls, x.doubleValue(), y.doubleValue(), z.doubleValue()));\n        }\n        if (bad > 0) entityLastError = \"有 \" + bad + \" 条实体项缺坐标/形状不对 ⇒ 未计入（不编坐标）\";\n        return out;\n    }\n\n    /**\n     * **实体类别**（决定 entityGrid 的标记字母）—— 纯 core 侧启发式，按<b>实体注册名/类简单名</b>的\n     * 子串归类（顺序即优先级）。**可能把模组实体归到 other** ⇒ 原始 {@code type}/{@code cls}\n     * 逐条写在 {@code entities[]} 里，绝不藏。\n     */\n    static String categoryOf(String type, String cls) {\n        String t = type == null ? \"\" : type.toLowerCase(java.util.Locale.ROOT);\n        String c = cls == null ? \"\" : cls.toLowerCase(java.util.Locale.ROOT);\n        if (\"minecraft:item\".equals(t) || \"itementity\".equals(c)) return \"item\";\n        if (t.contains(\"experience_orb\") || c.contains(\"experienceorb\")) return \"xp_orb\";\n        if (t.contains(\"boat\") || t.contains(\"minecart\") || c.contains(\"boat\") || c.contains(\"minecart\")) return \"vehicle\";\n        if (t.contains(\"arrow\") || t.contains(\"fireball\") || t.contains(\"snowball\") || t.contains(\"trident\")\n                || t.contains(\"wind_charge\") || c.contains(\"arrow\") || c.contains(\"fireball\")\n                || c.contains(\"snowball\") || c.contains(\"trident\") || c.contains(\"projectile\")\n                || c.contains(\"throwable\")) return \"projectile\";\n        for (int i = 0; i < HOSTILE_HINTS.length; i++) {\n            if (t.contains(HOSTILE_HINTS[i]) || c.contains(HOSTILE_HINTS[i])) return \"hostile\";\n        }\n        for (int i = 0; i < PASSIVE_HINTS.length; i++) {\n            if (t.contains(PASSIVE_HINTS[i]) || c.contains(PASSIVE_HINTS[i])) return \"passive\";\n        }\n        return \"other\";\n    }\n\n    /** 敌对生物提示词（按**注册名/类简单名**子串匹配；顺序无关，命中即 hostile）。 */\n    private static final String[] HOSTILE_HINTS = {\n            \"zombie\", \"skeleton\", \"creeper\", \"spider\", \"enderman\", \"witch\", \"slime\", \"magma_cube\",\n            \"blaze\", \"ghast\", \"guardian\", \"shulker\", \"phantom\", \"piglin\", \"hoglin\", \"zoglin\",\n            \"wither\", \"drowned\", \"husk\", \"stray\", \"pillager\", \"vindicator\", \"evoker\", \"ravager\",\n            \"silverfish\", \"endermite\", \"vex\", \"illusioner\", \"breeze\", \"bogged\", \"warden\", \"giant\",\n            \"cave_spider\", \"elder_guardian\", \"zombified\" };\n\n    /** 被动 / 友好生物提示词（同上；**在 hostile 之后判**，所以 piglin 不会被 pig 抢走）。 */\n    private static final String[] PASSIVE_HINTS = {\n            \"cow\", \"pig\", \"sheep\", \"chicken\", \"rabbit\", \"horse\", \"donkey\", \"mule\", \"llama\", \"wolf\",\n            \"cat\", \"ocelot\", \"fox\", \"bee\", \"turtle\", \"panda\", \"polar_bear\", \"goat\", \"axolotl\",\n            \"frog\", \"camel\", \"sniffer\", \"armadillo\", \"allay\", \"villager\", \"golem\", \"squid\",\n            \"dolphin\", \"bat\", \"parrot\", \"strider\", \"animal\", \"mooshroom\", \"tadpole\", \"nautilus\" };\n\n    /** 类别 → 实体层标记字符（与方块码**不是**同一命名空间，见 ENTITY_LEGEND_NOTE）。 */\n    static char markFor(String cat) {\n        if (\"item\".equals(cat)) return 'i';\n        if (\"xp_orb\".equals(cat)) return 'x';\n        if (\"vehicle\".equals(cat)) return 'v';\n        if (\"projectile\".equals(cat)) return 'r';\n        if (\"hostile\".equals(cat)) return 'm';\n        if (\"passive\".equals(cat)) return 'a';\n        return 'e';\n    }\n\n    /** 类别 → 人话（写进 entityLegend）。 */\n    static String labelFor(String cat) {\n        if (\"item\".equals(cat)) return \"掉落物\";\n        if (\"xp_orb\".equals(cat)) return \"经验球\";\n        if (\"vehicle\".equals(cat)) return \"载具（船/矿车）\";\n        if (\"projectile\".equals(cat)) return \"投射物\";\n        if (\"hostile\".equals(cat)) return \"敌对生物\";\n        if (\"passive\".equals(cat)) return \"被动/友好生物\";\n        return \"其它（未归类）\";\n    }\n\n    /**\n     * 渲染实体叠加层：**平行网格**（同 cols/rows/step/origin/cellWidth）+ 独立图例 + 明细列表。\n     * **绝不写 {@code grid}**、绝不碰方块码表。\n     */\n    private void putEntityLayer(Map<String, Object> m, int rs, int rc, int rr, int shownRows) {\n        int cellW = cellWidth();\n        m.put(\"entitiesIncluded\", Boolean.TRUE);\n        m.put(\"entityCount\", Integer.valueOf(entities.size()));\n        m.put(\"entityRadiusBlocks\", Integer.valueOf((int) Math.round(entityRadiusUsed)));\n        m.put(\"entityGridFill\", ENTITY_FILL);\n        m.put(\"entityGridCols\", Integer.valueOf(rc));\n        m.put(\"entityGridRows\", Integer.valueOf(shownRows));\n        m.put(\"entityGridTotalRows\", Integer.valueOf(rr));\n        m.put(\"entityGridCellWidth\", Integer.valueOf(cellW));\n        m.put(\"entityGridNote\", ENTITY_GRID_NOTE);\n        m.put(\"entityLegendNote\", ENTITY_LEGEND_NOTE);\n        m.put(\"entityGridTruncated\", Boolean.valueOf(shownRows < rr));\n        if (shownRows < rr) {\n            m.put(\"entityGridTruncatedNote\", \"方块层按整行截断到 \" + shownRows + \"/\" + rr\n                    + \" 行 ⇒ 实体层同几何一并截断（落在截断行里的实体仍在 entities[] 里，inGrid=false）\");\n        }\n\n        double px = 0.0, py = 0.0, pz = 0.0;\n        boolean havePlayer = false;\n        double[] xyz = playerXYZ();\n        if (xyz != null) { px = xyz[0]; py = xyz[1]; pz = xyz[2]; havePlayer = true; }\n        if (!havePlayer) m.put(\"entityDistNote\", \"读不到玩家坐标 ⇒ dist 以世界原点(0,0,0)为基准（如实说明，不假装）\");\n\n        final double fpx = px, fpy = py, fpz = pz;\n        List<EntityRec> sorted = new ArrayList<EntityRec>(entities);\n        java.util.Collections.sort(sorted, new java.util.Comparator<EntityRec>() {\n            public int compare(EntityRec a, EntityRec b) {\n                double da = a.dist2(fpx, fpy, fpz);\n                double db = b.dist2(fpx, fpy, fpz);\n                if (da < db) return -1;\n                if (da > db) return 1;\n                return a.sortKey().compareTo(b.sortKey());\n            }\n        });\n\n        char[][] marks = new char[shownRows][rc];\n        int[] pc = playerCell(rs, rc, rr);\n        if (pc[0] >= 0 && pc[1] >= 0 && pc[1] < shownRows) marks[pc[1]][pc[0]] = cfg.playerMark;\n\n        Map<String, Object> legend = new LinkedHashMap<String, Object>();\n        List<Object> detail = new ArrayList<Object>();\n        int onGrid = 0;\n        for (EntityRec e : sorted) {\n            String cat = categoryOf(e.type, e.cls);\n            char mark = markFor(cat);\n            int col = (int) Math.floor((e.x - originX) / (double) rs);\n            int row = (int) Math.floor((e.z - originZ) / (double) rs);\n            boolean inGrid = col >= 0 && col < rc && row >= 0 && row < shownRows;\n            if (inGrid) {\n                marks[row][col] = mark;                     // 实体标记优先于玩家标记（玩家仍在 entities[] 之外）\n                legend.put(String.valueOf(mark), labelFor(cat));\n                onGrid++;\n            }\n            Map<String, Object> one = new LinkedHashMap<String, Object>();\n            one.put(\"type\", e.type);\n            one.put(\"cls\", e.cls);\n            one.put(\"category\", cat);\n            one.put(\"mark\", String.valueOf(mark));\n            one.put(\"x\", Double.valueOf(e.x));\n            one.put(\"y\", Double.valueOf(e.y));\n            one.put(\"z\", Double.valueOf(e.z));\n            one.put(\"dist\", Double.valueOf(round3(Math.sqrt(e.dist2(px, py, pz)))));\n            one.put(\"inGrid\", Boolean.valueOf(inGrid));\n            one.put(\"cell\", inGrid ? cellJson(col, row) : null);\n            detail.add(one);\n        }\n\n        StringBuilder b = new StringBuilder();\n        String fillRun = repeat(ENTITY_FILL, cellW);\n        String markPad = repeat(ENTITY_FILL, cellW - 1);\n        for (int j = 0; j < shownRows; j++) {\n            if (j > 0) b.append('\\n');\n            for (int i = 0; i < rc; i++) {\n                char c = marks[j][i];\n                if (c == 0) b.append(fillRun);\n                else b.append(c).append(markPad);\n            }\n        }\n        m.put(\"entityGrid\", b.toString());\n        m.put(\"entityLegend\", legend);\n        m.put(\"entitiesOnGridCount\", Integer.valueOf(onGrid));\n        m.put(\"entities\", detail);\n        if (detail.isEmpty()) {\n            m.put(\"entityNote\", ENTITY_EMPTY_NOTE);\n        } else if (onGrid == 0) {\n            m.put(\"entityNote\", \"半径内有 \" + detail.size() + \" 个实体，但**没有一个落在本图范围内**\"\n                    + \"（或都落在被截断的行里）⇒ entityGrid 全为填充符；明细见 entities[]\");\n        }\n        if (entityReportedTotal >= 0 && entityReportedTotal != detail.size()) {\n            m.put(\"entityCountNote\", \"适配层报 count=\" + entityReportedTotal + \"，其中 \" + detail.size()\n                    + \" 条带完整坐标可入图；差 \" + (entityReportedTotal - detail.size()) + \" 条未计入（不编坐标）\");\n        }\n    }\n\n    private static String repeat(String s, int n) {\n        StringBuilder b = new StringBuilder();\n        for (int i = 0; i < n; i++) b.append(s);\n        return b.toString();\n    }\n\n    private static double round3(double d) {\n        return Math.round(d * 1000.0) / 1000.0;\n    }\n\n    /** 玩家 (x,y,z)；取不到 y 时 y 记 0（并在头里如实说明）。 */\n    private double[] playerXYZ() {\n        Map<String, Object> st;\n        try {\n            st = Json.parseObject(bridge.playerStateJson());\n        } catch (RuntimeException e) {\n            return null;\n        }\n        Double x = dbl(st.get(\"x\"));\n        Double z = dbl(st.get(\"z\"));\n        if (x == null || z == null) return null;\n        Double y = dbl(st.get(\"y\"));\n        return new double[] { x.doubleValue(), y == null ? 0.0 : y.doubleValue(), z.doubleValue() };\n    }\n\n    /** 一条实体读数（世界里的一条：type/cls + 绝对坐标）。 */\n    private static final class EntityRec {\n        final String type;\n        final String cls;\n        final double x, y, z;\n\n        EntityRec(String type, String cls, double x, double y, double z) {\n            this.type = type;\n            this.cls = cls;\n            this.x = x;\n            this.y = y;\n            this.z = z;\n        }\n\n        double dist2(double px, double py, double pz) {\n            double dx = x - px, dy = y - py, dz = z - pz;\n            return dx * dx + dy * dy + dz * dz;\n        }\n\n        String sortKey() {\n            return (type == null ? \"\" : type) + \"|\" + (cls == null ? \"\" : cls);\n        }\n    }\n\n    // ==================================================================\n    // [T13] 单列纵剖面 query_column / 按条件搜方块 query_blocks\n    //       + playerDepthBelowSurface（地表深度）\n    //\n    // 口径（都是**新增面**，与既有 query_state / query_map 的缓存、版本、码表语义**互不相干**）：\n    //   · 取值口**复用** GameBridge#blockAt(x,y,z)（本来就吃任意 Y；用户原话「正好区块就是有整个\n    //     Z 轴的」）⇒ **不碰** Chunk / LevelChunkSection / PalettedContainer 这类跨版本容器 API\n    //     （四代分叉、收益不成比例）。成本靠**分帧预算**控，不靠换 API。\n    //   · query_column：单列（≤ COLUMN_MAX_BLOCKS 次 blockAt）同步读，天然有界。\n    //   · query_blocks：**独立的分帧 job**（每 tick ≤ SEARCH_BLOCKS_PER_TICK 次 blockAt）；\n    //     与地图扫描共用 tick 线程，但**字段完全分开** ⇒ 绝不动地图的分帧 / 版本 / 码表语义。\n    //   · 两者都**只读**，不写任何地图状态。\n    // ==================================================================\n\n    /** query_column 回执 schema。 */\n    public static final String COLUMN_SCHEMA = \"bandd-state-column/1\";\n    /** query_blocks 回执 schema。 */\n    public static final String SEARCH_SCHEMA = \"bandd-state-search/1\";\n    /** 纵剖面逐行顺序（写死，别让读者猜）。 */\n    public static final String COLUMN_ORDER = \"desc\";\n    /** 顺序的人话说明。 */\n    public static final String COLUMN_ORDER_NOTE =\n            \"blocks[] 从**高 Y 到低 Y**（降序）逐行给：第 0 项 = y2，末尾 = 本次真正读到的最后一层；\"\n            + \"空气**如实出现**（id=minecraft:air），这是判「洞 / 头顶有没有遮挡」的关键\";\n    /** id=null 的口径（与 air 必须分清）。 */\n    public static final String UNKNOWN_ROW_NOTE =\n            \"id=null = 那一格**取不到**（越界 / 未加载 / 本档不支持）—— 与空气语义不同，不许当空气读；\"\n            + \"判据在适配层（GameBridge#blockAt 回 null）\";\n    /** 空气口径。 */\n    public static final String AIR_ID_NOTE =\n            \"isAir 口径：id 以 :air / :cave_air / :void_air 结尾，或整串等于 air / cave_air / void_air\"\n            + \"（与 WORLD_SURFACE 高度图的空气口径对齐）\";\n\n    /** query_column 的 maxBlocks 默认值（省略或 ≤0 时用它；有界）。 */\n    public static final int COLUMN_DEFAULT_MAX_BLOCKS = 96;\n    /** query_column 的 maxBlocks 硬上限（超了如实回 maxBlocksClampedTo）。 */\n    public static final int COLUMN_MAX_BLOCKS = 512;\n    /** 默认窗口：玩家脚下 32 层。 */\n    public static final int COLUMN_WINDOW_DOWN = 32;\n    /** 默认窗口：玩家头上 16 层。 */\n    public static final int COLUMN_WINDOW_UP = 16;\n    /** 默认窗口的人话。 */\n    public static final String COLUMN_DEFAULT_WINDOW_NOTE =\n            \"省略 y1/y2 ⇒ 用**有界**默认窗口 [floor(玩家Y) - \" + COLUMN_WINDOW_DOWN + \", floor(玩家Y) + \"\n            + COLUMN_WINDOW_UP + \"]（共 \" + (COLUMN_WINDOW_UP + COLUMN_WINDOW_DOWN + 1) + \" 层）\";\n    /** 只给了一个 y 时的补法说明。 */\n    public static final String COLUMN_PARTIAL_Y_NOTE =\n            \"只给了 y1 / y2 中的一个 ⇒ 另一个按**默认窗口**补（**不**编一个中点出来）\";\n\n    // ---- query_blocks 的旋钮（**故意不放进 StateConfig**：本轮是新增面，不动既有设置键 / 文件 / 单测）----\n    /** 每个客户端 tick 最多读多少格（分帧预算；绝不一次全扫）。 */\n    public static final int SEARCH_BLOCKS_PER_TICK = 256;\n    public static final int SEARCH_DEFAULT_RADIUS = 8;\n    public static final int SEARCH_MAX_RADIUS = 32;\n    public static final int SEARCH_DEFAULT_MAX_MATCHES = 64;\n    public static final int SEARCH_MAX_MATCHES = 512;\n    /** 默认 y 窗口：玩家上下各 16 层。 */\n    public static final int SEARCH_WINDOW_UP = 16;\n    public static final int SEARCH_WINDOW_DOWN = 16;\n    /** y 跨度硬上限（层）：超了从上面裁，并如实回 yClampedTo。 */\n    public static final int SEARCH_MAX_Y_SPAN = 128;\n    /** filter 列表最多几条。 */\n    public static final int SEARCH_MAX_FILTERS = 64;\n    /** filter 的口径（**原样进回执头**，别让调用方猜通配与命名空间规则）。 */\n    public static final String FILTER_NOTE =\n            \"filter 是**id 通配列表**，命中任一即算命中（OR）：\"\n            + \"① 匹配对**大小写不敏感**；\"\n            + \"② * 通配任意长度（可为空）的子串，可多个；其它字符（含 . 与 ?）都是**字面**匹配，不是正则；\"\n            + \"③ pattern **不含冒号**时，既比完整 id，也比 id 里冒号之后那一段（例：air 命中 minecraft:air）；\"\n            + \"④ id=null（未加载 / 越界）**永不参与匹配**，只记进 scan.unknownBlocks\";\n    /** matches 排序口径。 */\n    public static final String SEARCH_SORT_NOTE =\n            \"matches 按与**本次扫描起点**（= 扫描开始那一刻的玩家位置，见 origin）的三维欧氏距离\"\n            + \"**由近到远**排序；距离相同的按 (x,y,z) 升序定序（可复现）\";\n    /** 分帧说明。 */\n    public static final String SEARCH_SCAN_NOTE =\n            \"搜索是**分帧**的：每客户端 tick 最多读 \" + SEARCH_BLOCKS_PER_TICK\n            + \" 格（scan.blocksPerTick）；scan.active=true ⇒ **还没扫完**，matched 只是**已扫范围内**的命中数，\"\n            + \"不是最终值。换条件（filter / radius / y1 / y2 / maxMatches 任一不同）⇒ **自动重扫**\"\n            + \"（restarted=true + restartedReason=condition_changed，绝不拿上一次条件的结果配本次条件）；\"\n            + \"refresh=true 强制重扫。\";\n\n    /**\n     * [T20-②] 条件变了 ⇒ **自动重扫**的人话（原样进回执）。\n     *\n     * <p>为什么改口径（旧行为是真机实测出的静默错误）：换 filter / radius / y1 / y2 却不带 refresh 时，\n     * 旧的顶层 {@code filter} 回显**新条件**，而 {@code matched} / {@code matches} 仍是**上一次**扫描的\n     * 结果（唯一诚实字段是 {@code scan.filterApplied}）—— 实测者点名要 {@code minecraft:iron_ore}\n     * 却拿回 11 条 {@code minecraft:air}，差点当成矿物结论。\n     *\n     * <p>新口径（**选项 a：条件变即自动重扫**；不选「拒绝并要求 refresh」是因为分帧 job 天然支持重启，\n     * 拒绝只会逼调用方多发一次往返，且旧结果的诱惑仍在）：条件与上一次不同 ⇒ 立即用**本次条件**起新一轮，\n     * {@code restarted=true} + {@code restartedReason=condition_changed} + {@code previousCondition}\n     * （上一次用的条件原样回出去）⇒ 回执里**永远不会**出现「新条件配旧结果」。\n     */\n    public static final String SEARCH_RESTARTED_NOTE =\n            \"本次请求的条件（filter / radius / y1..y2 / maxMatches）与上一次扫描**不同** ⇒ 已**自动重扫**\"\n            + \"（restarted=true / restartedReason=condition_changed）：matches / matched / truncated / scan \"\n            + \"**全部来自本次条件的新一轮**，绝不用上一次条件的结果配本次条件的回显；\"\n            + \"上一次用的条件在 previousCondition 里原样给出。新扫描照旧分帧 ⇒ scan.active=true 时 \"\n            + \"matched 只是**已扫范围内**的命中数。\";\n\n    /** [T20-②] 条件与上一次**逐字相同** ⇒ 复用同一轮扫描（不重启）的人话。 */\n    public static final String SEARCH_REUSED_NOTE =\n            \"本次条件与上一次扫描**逐字相同**（filter / radius / y1..y2 / maxMatches 全等）\"\n            + \" ⇒ 复用同一轮扫描（restarted=false / reused=true），进度接着走，**不重置**。\";\n\n    /** [T20-②] 显式 refresh=true 时的人话。 */\n    public static final String SEARCH_REFRESH_NOTE =\n            \"调用方显式传了 refresh=true ⇒ 无条件重扫（restarted=true / restartedReason=refresh_requested）。\";\n    /** 扫描没起来时的原因说明（如实自报，不假装扫过）。 */\n    public static final String SEARCH_NOT_STARTED_NOTE =\n            \"扫描**没有起**（本档没有 blockAt 取值面 / 玩家与世界不在场 / 读不到玩家坐标）\"\n            + \" ⇒ scan.active=false、doneBlocks=0、matches=[]；这是**如实读数**，不是「扫完了没有命中」\";\n    /** 空结果的说明（空结果是合法读数）。 */\n    public static final String SEARCH_EMPTY_NOTE =\n            \"本次筛条件在**已扫范围内**零命中 ⇒ matched:0 + matches:[]（空结果是**合法读数**，不是错误）\";\n    /** 命中数到 maxMatches 时的说明（fail-loud：剩余区域**没扫**）。 */\n    public static final String SEARCH_TRUNCATED_NOTE =\n            \"命中数已达 maxMatches ⇒ 搜索**提前停止**：truncated=true，且 scan.doneBlocks < scan.totalBlocks\"\n            + \" ⇒ **剩余区域没有扫**（不是「只有这些」）。要看完请调大 maxMatches 再 refresh=true\";\n\n    /**\n     * [T22] {@code query_blocks} 顶层 {@code complete} / {@code stoppedBy} / {@code remainingBlocks}\n     * 的口径（**原样进回执头**，别让调用方把「提前停」读成「扫完了」）。\n     *\n     * <p>为什么必须有它：真机实测（T18 fabric 1.21.11，{@code maxMatches=128}）撞上限时回了\n     * {@code active=false + truncated=true}，而 {@code doneBlocks=32783 < totalBlocks=266175}\n     * ⇒ 调用方只看到 {@code active=false} 就把「提前停」读成「扫完了」。\n     *\n     * <p>语义：{@code complete=true} 仅当**整盒扫完且没提前停**；{@code complete=false} 时\n     * {@code remainingBlocks} 是**还没扫**的格子数（不是命中数）；{@code stoppedBy} 取值：\n     * {@code \"maxMatches\"}（撞命中上限提前停）/ {@code \"scanning\"}（还在分帧扫，还没停）/\n     * {@code \"aborted\"}（玩家 / 世界离场导致中止）/ {@code \"notStarted\"}（本轮扫描没起）/\n     * {@code null}（自然扫完）。\n     */\n    public static final String SEARCH_COMPLETE_NOTE =\n            \"complete=true 仅当**整个扫描盒都扫完且没提前停**；complete=false 时 remainingBlocks 是\"\n            + \"**还没扫**的格子数（不是「只有这些命中」）。stoppedBy：maxMatches=命中数撞 maxMatches\"\n            + \"提前停；scanning=还在分帧扫（尚未停）；aborted=玩家/世界离场导致中止；notStarted=扫描没起；\"\n            + \"null=自然扫完。truncated 语义不变（= 命中被 maxMatches 截断）。\";\n\n    // ---- ⑦ 地表深度：每 tick 在 tick 线程刷新一次，查询只读缓存 ----\n    /** playerDepthBelowSurface 的公式与人话（**原样进地图头与 query_state 顶层**）。 */\n    public static final String DEPTH_NOTE =\n            \"playerDepthBelowSurface = **地表平面 Y** 减 玩家 Y，其中地表平面 Y = 该列最高非空气方块的 Y + 1\"\n            + \"（也就是玩家站在地表方块顶上时脚所在的 Y）⇒ **正值 = 玩家在地表以下**（地下 / 洞 / 矿道），\"\n            + \"0 = 正站在地表上，负值 = 高于地表（树上 / 水里 / 跳起 / 飞）。\"\n            + \"playerSurfaceBlockY = 该列最高非空气方块的 Y（与 query_map 高度字段的 h **同义**）；\"\n            + \"playerStandY = playerSurfaceBlockY + 1。\"\n            + \"取不到（无玩家 / 该列未加载 / 本档不支持）⇒ 三个字段一律 null 并如实标注，**绝不填 0 冒充**\";\n    private volatile Double depthPlayerY;\n    private volatile Integer depthSurfaceBlockY;\n    private volatile Integer depthStandY;\n    private volatile Double depthValue;\n    private volatile String depthNote = \"还没刷新过（玩家 / 世界不在场）\";\n    private volatile int depthRefreshedTick = -1;\n\n    private void clearDepth(String why) {\n        depthPlayerY = null;\n        depthSurfaceBlockY = null;\n        depthStandY = null;\n        depthValue = null;\n        depthNote = why == null ? DEPTH_NOTE : why;\n    }\n\n    /** 客户端 tick 线程每 tick 刷一次（1 次 topSolidY + 1 次 playerStateJson；查询侧一次 MC 调用都不做）。 */\n    private void refreshPlayerDepth() {\n        if (!bridge.stateMapCapable() || !bridge.ready()) {\n            clearDepth(\"本档没有 blockAt/topSolidY 取值面，或玩家 / 世界不在场 ⇒ 如实留 null（不填 0 冒充）\");\n            return;\n        }\n        Map<String, Object> st;\n        try {\n            st = Json.parseObject(bridge.playerStateJson());\n        } catch (RuntimeException e) {\n            clearDepth(\"playerStateJson 解析失败：\" + e);\n            return;\n        }\n        Double x = dbl(st.get(\"x\")), y = dbl(st.get(\"y\")), z = dbl(st.get(\"z\"));\n        if (x == null || y == null || z == null) {\n            clearDepth(\"玩家 x/y/z 取不全 ⇒ 如实留 null（不填 0 冒充）\");\n            return;\n        }\n        int bx = (int) Math.floor(x.doubleValue());\n        int bz = (int) Math.floor(z.doubleValue());\n        int top;\n        try {\n            top = bridge.topSolidY(bx, bz);\n        } catch (Throwable t) {\n            clearDepth(\"topSolidY 抛异常：\" + t);\n            return;\n        }\n        depthPlayerY = y;\n        depthRefreshedTick = ticks;\n        if (top == Integer.MIN_VALUE) {\n            depthSurfaceBlockY = null;\n            depthStandY = null;\n            depthValue = null;\n            depthNote = \"玩家所在列 (x=\" + bx + \", z=\" + bz + \") 的地表取不到（未加载 / 越界 / 本档不支持）\"\n                    + \" ⇒ playerDepthBelowSurface 如实回 null，**不填 0 冒充**\";\n            return;\n        }\n        // **未加载**的列，客户端回的是 void_air（不是 null），topSolidY 会低到 -65（真机实证 2026-11-11）。\n        // 这里**不额外调 blockAt**（tick 上的读格预算要保持原样，见 StateTest C2），改用**建高下限**判：\n        // 正常世界的最低建高是 -64（1.18+），topSolidY < 该下限只可能是「这一列什么都没有」= 未加载/虚空。\n        if (top < SURFACE_MIN_BUILD_Y) {\n            depthSurfaceBlockY = null;\n            depthStandY = null;\n            depthValue = null;\n            depthNote = \"玩家所在列 (x=\" + bx + \", z=\" + bz + \") 的地表取不到：topSolidY=\" + top\n                    + \" < 本档建高下限 \" + SURFACE_MIN_BUILD_Y\n                    + \" ⇒ 该列**疑似未加载**（客户端在未加载区块回 void_air 而不是 null）\"\n                    + \" ⇒ playerDepthBelowSurface 如实回 null，**不填 0 冒充**\";\n            return;\n        }\n        depthSurfaceBlockY = Integer.valueOf(top);\n        depthStandY = Integer.valueOf(top + 1);\n        depthValue = Double.valueOf(round3((top + 1) - y.doubleValue()));\n        depthNote = DEPTH_NOTE;\n    }\n\n    /** ⑦ 的四个字段（query_state 顶层与地图头**同源同值**；取不到就是 null + 人话）。 */\n    public Map<String, Object> depthJson() {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"playerDepthBelowSurface\", depthValue);\n        m.put(\"playerSurfaceBlockY\", depthSurfaceBlockY);\n        m.put(\"playerStandY\", depthStandY);\n        m.put(\"playerY\", depthPlayerY);\n        m.put(\"playerDepthNote\", depthNote);\n        m.put(\"playerDepthRefreshedTick\", depthRefreshedTick < 0 ? null : Integer.valueOf(depthRefreshedTick));\n        return m;\n    }\n\n    // ==================================================================\n    // ⑧ 纵层 yMode（地图的纵层视图 + 地下自动切层）\n    //\n    // 设计口径（**只追加**，不动任何既有字段）：\n    //   · 取值口**复用** GameBridge#blockAt(x,y,z)（本来就吃任意 Y；用户原话「正好区块就是有整个\n    //     Z 轴的」）⇒ **不为纵层**去碰 Chunk / LevelChunkSection / PalettedContainer（跨版本四代、\n    //     收益不成比例）。成本靠**分帧预算**控：纵层采样是**独立的分帧 job**（每 tick ≤\n    //     StateConfig#columnsPerTick **格**，列×层一起算），与地图扫描 / 方框搜索共用 tick 线程但\n    //     **字段完全分开** ⇒ 绝不动地图的分帧 / 版本 / 码表语义。\n    //   · 几何**必须与地图一致**：层网格的 cols/rows/step/origin/cellWidth 逐字取本地图快照\n    //     ⇒ 每行长度仍等于 cols × cellWidth（与 grid 同一个等式）。\n    //   · 码表**共用**（同一 id 在 grid 与层网格里码相同）但**不动既有 legend 语义**：\n    //     既有 legend 仍只列 grid 里真出现的码；纵层另给一张**并集**图例 layerLegend。\n    //   · fail-loud：减层（层数上限 / 渲染字符预算 / 地图按行截断）**逐条写进头**，绝不静默丢层。\n    //   · 向后兼容：**不给任何纵层参数、且没触发自动切层**时，回执与改动前**逐字一致**（零新键）。\n    // ==================================================================\n\n    /** 纵层模式名：既有行为（**默认**）。 */\n    public static final String Y_MODE_SURFACE = \"surface\";\n    /** 纵层模式名：以**玩家脚下方块 Y** 为基准。 */\n    public static final String Y_MODE_PLAYER = \"player\";\n    /** 纵层模式名：yRange 直接给**绝对 Y**。 */\n    public static final String Y_MODE_ABSOLUTE = \"absolute\";\n    /** 一次请求采样的层数上限（默认；每次可用 yLayerMax 覆盖）。 */\n    public static final int Y_LAYER_MAX_DEFAULT = 8;\n    /** 层数**硬上限**（yLayerMax 超了夹到这里，并如实回 yLayerMaxNote）。 */\n    public static final int Y_LAYER_HARD_MAX = 16;\n    /** 一次回执最多渲染多少层（就算字符预算够也不超过它）。 */\n    public static final int Y_LAYER_RENDER_HARD = 16;\n    /** 请求的层区间跨度硬上限（层）；超了以请求区间中点为中心夹窄，并如实说明。 */\n    public static final int Y_RANGE_HARD_SPAN = 256;\n    /** 自动切层的地下判据：playerDepthBelowSurface ≥ 此值 ⇒ 默认改用 player 纵层。 */\n    public static final int Y_AUTO_DEPTH = 3;\n    /** 自动切层 / player 模式省略 yRange 时的 dy 半径（±N ⇒ 2N+1 层）。 */\n    public static final int Y_AUTO_RANGE = 2;\n\n    /** yMode 的口径（原样进地图头，别让调用方猜）。 */\n    public static final String Y_MODE_NOTE =\n            \"yMode = 地图的**纵层**口径：\"\n            + \"surface（默认）= **既有行为**（每格 = 该列最高非空气方块的码 + 定宽高度），逐字不变；\"\n            + \"player = 以玩家脚下方块 Y（= yLayerBaseY）为基准，按 yRange 的 **dy** 逐层取方块；\"\n            + \"absolute = yRange / y1+y2 直接给**绝对 Y**。\"\n            + \"层网格与 grid **同几何**（同 cols/rows/step/origin/cellWidth ⇒ 每行长度仍等于 cols×cellWidth）；\"\n            + \"层网格**不画玩家标记**（那会盖住玩家脚下那一格的读数），玩家位置看 playerCell。\"\n            + \"**只追加**：surface 且调用方没给任何纵层参数时，回执一个新键都不加。\";\n\n    /** 层网格的口径（原样进地图头）。 */\n    public static final String Y_LAYER_GRID_NOTE =\n            \"layers[] 每项 = **一层**的定宽字符网格：与 grid **同几何**（同 cols/rows/step/origin/cellWidth），\"\n            + \"每格 cellWidth 个字符 = 方块码 + **与 grid 同一列的定宽高度字段**（高度是列属性、与层无关）；\"\n            + \"layer.playerCellId = 该层里**玩家所在那格**的方块 id 原串（玩家格在层网格外 ⇒ null）；\"\n            + \"码表**共用**（同一 id 在 grid 与层网格里码相同），层里第一次出现的新 id 只追加、不回收、不重排；\"\n            + \"图例见 layerLegend / layerLegendUnused —— 既有 legend 的语义**一字未动**。\";\n\n    /** 纵层分帧采样的人话（原样进地图头）。 */\n    public static final String Y_LAYER_SCAN_NOTE =\n            \"纵层采样是**独立的分帧 job**：与地图扫描共用 tick 线程，但每 tick 最多读 StateConfig.columnsPerTick \"\n            + \"**格**（列×层一起算）⇒ 层数越多、采满越慢，**不会**把 tick 线程卡住。\"\n            + \"查询只读**已完成**的那一份（layerSnapshot）；还没采完 ⇒ layers 为空数组 + layerScan.active=true，\"\n            + \"**不假装有层**。\";\n\n    /** yMode 回执块（一次查询的解析结果 + 自动切层自证）。 */\n    static final class YPlan {\n        /** 回执里要不要出现 yMode 块（调用方给过任一纵层参数，或有效模式不是 surface）。 */\n        boolean present;\n        /** 要不要渲染纵层。 */\n        boolean layersOn;\n        /** 有效模式：surface / player / absolute。 */\n        String mode = Y_MODE_SURFACE;\n        /** 调用方**显式**给的 yMode（null = 没给）。 */\n        String requested;\n        /** 这次是不是自动切层切过来的（**必须自证**，不许悄悄换）。 */\n        boolean autoSwitched;\n        /** 人话原因。 */\n        String reason;\n        /** 请求的层区间（player: dy；absolute: 绝对 Y）。 */\n        int low, high;\n        /** player: floor(玩家Y)；absolute: 0。 */\n        int baseY;\n        /** 请求的层数（夹之前）。 */\n        int requestedLayers;\n        /** 实际要采样的层绝对 Y（升序；已按 yLayerMax 减层）。 */\n        int[] ys;\n        /** 减层的人话（null = 没减）。 */\n        String reduceNote;\n        /** 夹过的本次层数上限 + 原始请求值 + 人话。 */\n        int layerMax = Y_LAYER_MAX_DEFAULT;\n        Integer layerMaxRequested;\n        String layerMaxNote;\n        /** 层网格正文的总字符预算（null = 用本次 maxChars）。 */\n        Integer layersMaxChars;\n        /** yRange 形状 / 默认 / 夹取的人话（null = 没有要说的）。 */\n        String rangeNote;\n        String rangeClampNote;\n        /** 非 null ⇒ 调用方回 BAD_REQUEST。 */\n        String error;\n    }\n\n    /** 一层纵层采样的分帧 job（也用来当**已发布快照**：采完后只读、不再改）。 */\n    private static final class YLJob {\n        String mode;\n        int baseY;\n        int[] ys;\n        int requested;\n        String reduceNote;\n        int cols, rows, step, originX, originZ;\n        String dim;\n        String[] ids;\n        int cursor;\n        int totalCells;\n        int errors;\n        String lastError;\n        int startedTick = -1;\n        int finishedTick = -1;\n        int mapVersion = -1;\n        String key;\n    }\n\n    private static boolean yHas(Map<String, Object> p, String k) {\n        return p != null && p.containsKey(k) && p.get(k) != null;\n    }\n\n    /**\n     * 解析这一次查询的纵层请求（**纯函数**，不 arm、不采样；排程副作用只在 query 里的 armLayerScan）。\n     *\n     * <p>错误一律走 {@link YPlan#error}（调用方回 BAD_REQUEST）—— 与 query_column / query_blocks\n     * 的参数校验同一个落点，不把错误混进 ok 回执里。\n     */\n    public YPlan planY(Map<String, Object> p) {\n        YPlan y = new YPlan();\n        Object mv = p == null ? null : p.get(\"yMode\");\n        String m = mv == null ? null : String.valueOf(mv).trim();\n        boolean modeGiven = m != null && !m.isEmpty();\n        if (modeGiven && !Y_MODE_SURFACE.equals(m) && !Y_MODE_PLAYER.equals(m) && !Y_MODE_ABSOLUTE.equals(m)) {\n            y.error = \"yMode 只能是 surface | player | absolute，收到 \" + Json.of(mv);\n            return y;\n        }\n        y.requested = modeGiven ? m : null;\n        boolean autoGiven = yHas(p, \"yModeAuto\");\n        // [T16] 自动切层的**配置默认**：调用方给了 yModeAuto 就以它为准（只覆盖本次）；\n        // 没给就用 cfg.yModeAuto（设置页 / 配置文件；默认 true）。\n        boolean auto = autoGiven ? Json.bool(p, \"yModeAuto\", cfg.yModeAuto) : cfg.yModeAuto;\n        // 配置把自动切层关掉了（且调用方本次没给 yModeAuto）⇒ 回执要**自证**这件事（见 present）。\n        boolean autoCfgOff = !autoGiven && !cfg.yModeAuto;\n        boolean rangeGiven = yHas(p, \"yRange\") || yHas(p, \"y1\") || yHas(p, \"y2\");\n        boolean maxGiven = yHas(p, \"yLayerMax\");\n        boolean charsGiven = yHas(p, \"layersMaxChars\");\n\n        // ---- 有效模式：自动切层在这里判，理由**必须**写进 reason（不许悄悄换）----\n        Double dep = depthValue;\n        if (modeGiven) {\n            y.mode = m;\n            y.autoSwitched = false;\n            y.reason = \"调用方**显式**给了 yMode=\" + m + \" ⇒ 按它走（自动切层不参与）\";\n        } else if (!auto) {\n            y.mode = Y_MODE_SURFACE;\n            y.reason = (autoGiven ? \"参数 yModeAuto=false\" : \"配置 StateConfig.yModeAuto=false（设置页 / 配置文件）\")\n                    + \" ⇒ 自动切层被**显式关掉** ⇒ 沿用 surface（既有行为）；\"\n                    + \"要纵层请显式给 yMode=player|absolute\";\n        } else if (dep != null && dep.doubleValue() >= (double) cfg.yModeAutoDepth) {\n            y.mode = Y_MODE_PLAYER;\n            y.autoSwitched = true;\n            y.reason = \"playerDepthBelowSurface=\" + dep + \" ≥ \" + cfg.yModeAutoDepth\n                    + \"（配置 yModeAutoDepth）⇒ 玩家明显在地下 ⇒ **自动**改用 player 纵层\"\n                    + \"（配置 yAutoRange=±\" + cfg.yAutoRange + \" 层）；\"\n                    + \"显式给 yMode，或把 yModeAuto 关掉，都能关掉它\";\n        } else {\n            y.mode = Y_MODE_SURFACE;\n            y.reason = dep == null\n                    ? \"playerDepthBelowSurface=null（地表深度取不到）⇒ **不**自动切层，沿用 surface\"\n                    : \"playerDepthBelowSurface=\" + dep + \" < \" + cfg.yModeAutoDepth\n                            + \"（配置 yModeAutoDepth）⇒ 不在明显地下，沿用 surface\";\n        }\n        // autoCfgOff：配置关了自动切层、本次又没给任何参数 ⇒ 仍给一小块自证（yMode=surface +\n        // yModeAutoSwitched=false + 人话），否则调用方看不出「是配置关的」。\n        // 默认配置（yModeAuto=true）下 autoCfgOff=false ⇒ 既有「零新键」契约**逐字不变**。\n        y.present = modeGiven || autoGiven || rangeGiven || maxGiven || charsGiven\n                || !Y_MODE_SURFACE.equals(y.mode) || autoCfgOff;\n        if (!y.present) return y;                       // ★ 零新键：回执与改动前逐字一致\n        if (Y_MODE_SURFACE.equals(y.mode)) return y;    // 调用方给了参数但结果是 surface：只自证「没切层」\n\n        // ---- 层区间 ----\n        y.layersOn = true;\n        if (Y_MODE_ABSOLUTE.equals(y.mode)) {\n            y.baseY = 0;\n            if (yHas(p, \"yRange\")) {\n                int[] r = yRangeOf(p.get(\"yRange\"));\n                if (r == null) {\n                    y.error = \"yMode=absolute 的 yRange 形状不对：要 数字 / [a,b] / \\\"a..b\\\"（**整数绝对 Y**），收到 \"\n                            + Json.of(p.get(\"yRange\"));\n                    return y;\n                }\n                y.low = r[0];\n                y.high = r[1];\n            } else if (yHas(p, \"y1\") || yHas(p, \"y2\")) {\n                Object a = yHas(p, \"y1\") ? longOrNull(p.get(\"y1\")) : null;\n                Object b = yHas(p, \"y2\") ? longOrNull(p.get(\"y2\")) : null;\n                if (!(a instanceof Long) || !(b instanceof Long)) {\n                    y.error = \"yMode=absolute 的 y1/y2 必须**都给整数**（收到 y1=\" + Json.of(p.get(\"y1\"))\n                            + \" y2=\" + Json.of(p.get(\"y2\")) + \"）\";\n                    return y;\n                }\n                y.low = (int) Math.min(((Long) a).longValue(), ((Long) b).longValue());\n                y.high = (int) Math.max(((Long) a).longValue(), ((Long) b).longValue());\n            } else {\n                y.error = \"yMode=absolute 必须给 yRange（绝对 Y 区间，如 [64,70] / \\\"64..70\\\"）或 y1+y2；\"\n                        + \"本动作**不猜**世界高度\";\n                return y;\n            }\n        } else {\n            double[] xyz = playerXYZ();\n            if (xyz == null) {\n                y.error = \"yMode=player 要玩家的 x/y/z 来定基准，但取不到（playerStateJson 里没有）\";\n                return y;\n            }\n            y.baseY = (int) Math.floor(xyz[1]);\n            if (yHas(p, \"yRange\")) {\n                int[] r = yRangeOf(p.get(\"yRange\"));\n                if (r == null) {\n                    y.error = \"yMode=player 的 yRange 形状不对：要 数字（±n） / [a,b] / \\\"a..b\\\"（**整数 dy**），收到 \"\n                            + Json.of(p.get(\"yRange\"));\n                    return y;\n                }\n                y.low = r[0];\n                y.high = r[1];\n                if (p.get(\"yRange\") instanceof Number) {\n                    y.rangeNote = \"yRange 给了单个数字 ⇒ 按**对称区间** [−n, +n] = [\" + y.low + \"..\" + y.high + \"] 读（dy）\";\n                }\n            } else {\n                y.low = -cfg.yAutoRange;\n                y.high = cfg.yAutoRange;\n                y.rangeNote = \"没给 yRange ⇒ 用**有界**默认 ±\" + cfg.yAutoRange\n                        + \"（配置 yAutoRange；共 \" + (2 * cfg.yAutoRange + 1) + \" 层，dy）\";\n            }\n        }\n        if (y.low > y.high) {\n            int t = y.low; y.low = y.high; y.high = t;\n        }\n        int span = y.high - y.low + 1;\n        if (span > Y_RANGE_HARD_SPAN) {\n            int mid = y.low + span / 2;\n            int lo = mid - Y_RANGE_HARD_SPAN / 2;\n            int hi = lo + Y_RANGE_HARD_SPAN - 1;\n            y.rangeClampNote = \"请求的层跨度 \" + span + \" 层 > 硬上限 \" + Y_RANGE_HARD_SPAN\n                    + \" ⇒ 以请求区间中点为心夹到 [\" + lo + \"..\" + hi + \"]（如实回 yLayerRange，不静默）\";\n            y.low = lo;\n            y.high = hi;\n            span = Y_RANGE_HARD_SPAN;\n        }\n        y.requestedLayers = span;\n\n        // ---- 层数上限（每次可覆盖；夹了必须说）----\n        // [T16] 默认取配置 yLayerMax（默认 8）；调用方给 yLayerMax 只覆盖本次。硬上限仍是常量 16。\n        int lm = yHas(p, \"yLayerMax\") ? intParam(p, \"yLayerMax\", cfg.yLayerMax) : cfg.yLayerMax;\n        y.layerMaxRequested = Integer.valueOf(lm);\n        if (lm < 1) {\n            y.layerMax = 1;\n            y.layerMaxNote = \"yLayerMax=\" + lm + \" < 1 ⇒ 夹到 1（至少采一层；不静默）\";\n        } else if (lm > Y_LAYER_HARD_MAX) {\n            y.layerMax = Y_LAYER_HARD_MAX;\n            y.layerMaxNote = \"yLayerMax=\" + lm + \" 超过硬上限 \" + Y_LAYER_HARD_MAX + \" ⇒ 夹到 \"\n                    + Y_LAYER_HARD_MAX + \"（如实回 yLayerMaxRequested，不静默）\";\n        } else {\n            y.layerMax = lm;\n        }\n\n        // ---- 渲染字符预算（每次可覆盖；默认与本次 maxChars 同值）----\n        if (yHas(p, \"layersMaxChars\")) {\n            int v = intParam(p, \"layersMaxChars\", 0);\n            if (v > 0) y.layersMaxChars = Integer.valueOf(v);\n            else y.rangeNote = yAppend(y.rangeNote, \"layersMaxChars=\" + v + \" ≤ 0 ⇒ 视为未给，用本次 maxChars 当层预算\");\n        }\n\n        // ---- 实际采样的层（按 yLayerMax 减层；减了必须说）----\n        int mm = Math.min(span, y.layerMax);\n        if (mm < 1) mm = 1;\n        int[] a;\n        if (mm >= span) {\n            a = new int[span];\n            for (int i = 0; i < span; i++) a[i] = y.low + i;\n        } else {\n            a = new int[mm];\n            int last = Integer.MIN_VALUE;\n            for (int k = 0; k < mm; k++) {\n                int v = y.low + (int) (((long) k * span) / mm);\n                if (v <= last) v = last + 1;\n                a[k] = v;\n                last = v;\n            }\n            // 「玩家那一层」(dy=0) 必须在采样列表里（只在它落在请求区间内时）——\n            // 否则调用方拿不到 dy=0 那一层，B② 的交叉验证就无从谈起。\n            if (Y_MODE_PLAYER.equals(y.mode) && y.low <= 0 && y.high >= 0) {\n                boolean hasZero = false;\n                for (int i = 0; i < a.length; i++) if (a[i] == 0) { hasZero = true; break; }\n                if (!hasZero) {\n                    a[mm / 2] = 0;\n                    java.util.Arrays.sort(a);\n                    for (int i = 1; i < a.length; i++) if (a[i] <= a[i - 1]) a[i] = a[i - 1] + 1;\n                }\n            }\n            StringBuilder kept = new StringBuilder();\n            for (int i = 0; i < a.length; i++) {\n                if (i > 0) kept.append(',');\n                kept.append(a[i] + y.baseY);\n            }\n            y.reduceNote = \"请求 \" + span + \" 层 > 本次上限 yLayerMax=\" + y.layerMax\n                    + \" ⇒ **只采样 \" + a.length + \" 层**（跨整个请求区间均匀挑，并保证玩家那一层 dy=0 在内），\"\n                    + \"实际层的绝对 Y = [\" + kept + \"] —— 这是**没采**，不是那里没有方块；\"\n                    + \"要全采请调大 yLayerMax（硬上限 \" + Y_LAYER_HARD_MAX + \"）或缩小 yRange\";\n        }\n        y.ys = new int[a.length];\n        for (int i = 0; i < a.length; i++) y.ys[i] = a[i] + y.baseY;\n        return y;\n    }\n\n    private static String yAppend(String a, String b) {\n        if (a == null) return b;\n        return a + \"；\" + b;\n    }\n\n    /** 层的绝对 Y 区间回执。 */\n    private static Map<String, Object> yRangeJson(int low, int high) {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"from\", Integer.valueOf(low));\n        m.put(\"to\", Integer.valueOf(high));\n        m.put(\"count\", Integer.valueOf(high - low + 1));\n        return m;\n    }\n\n    /**\n     * yRange 的形状：数字 n ⇒ [−n, +n]（对称）；{@code [a,b]} / {@code \"a..b\"} ⇒ [min,max]。\n     * **非整值一律拒**（回 null ⇒ 调用方 BAD_REQUEST），不静默取整。\n     */\n    private static int[] yRangeOf(Object v) {\n        if (v instanceof Number) {\n            Integer n = yIntOf(dbl(v));\n            if (n == null) return null;\n            int a = Math.abs(n.intValue());\n            return new int[] { -a, a };\n        }\n        if (v instanceof String) {\n            String s = ((String) v).trim();\n            int p = s.indexOf(\"..\");\n            if (p < 0) {\n                Integer n = yIntOf(dbl(s));\n                if (n == null) return null;\n                int a = Math.abs(n.intValue());\n                return new int[] { -a, a };\n            }\n            Integer a = yIntOf(dbl(s.substring(0, p)));\n            Integer b = yIntOf(dbl(s.substring(p + 2)));\n            if (a == null || b == null) return null;\n            return new int[] { Math.min(a.intValue(), b.intValue()), Math.max(a.intValue(), b.intValue()) };\n        }\n        if (v instanceof List) {\n            List<?> l = (List<?>) v;\n            if (l.size() != 2) return null;\n            Integer a = yIntOf(dbl(l.get(0)));\n            Integer b = yIntOf(dbl(l.get(1)));\n            if (a == null || b == null) return null;\n            return new int[] { Math.min(a.intValue(), b.intValue()), Math.max(a.intValue(), b.intValue()) };\n        }\n        return null;\n    }\n\n    /** 必须是**整值**（8 / 8.0 行；8.7 拒）。 */\n    private static Integer yIntOf(Double d) {\n        if (d == null) return null;\n        double x = d.doubleValue();\n        if (Double.isNaN(x) || Double.isInfinite(x)) return null;\n        if (x != Math.rint(x)) return null;\n        return Integer.valueOf((int) x);\n    }\n\n    /** 取（必要时**发**）一个层里出现的 id 的码 —— 先查会话码表，再查纵层专用尾段。 */\n    private Character layerCodeOf(String id) {\n        Character c = idToCode.get(id);\n        if (c != null) return c;\n        Character k = layerIdToCode.get(id);\n        if (k != null) return k;\n        String pal = cfg.palette;\n        for (int i = pal.length() - 1; i >= 0; i--) {\n            Character cand = Character.valueOf(pal.charAt(i));\n            if (usedCodes.contains(cand)) continue;    // 全局唯一：地表图用过的码不许再发\n            usedCodes.add(cand);\n            layerIdToCode.put(id, cand);\n            return cand;\n        }\n        return null;                                   // 码位用尽 ⇒ overflowCode，并如实进 layerLegendOverflowNote\n    }\n\n    /** arm / 复用一次纵层分帧采样（**只排程，不做 MC 调用**）。 */\n    private void armLayerScan(YPlan plan) {\n        if (!ready || !bridge.ready()) return;\n        int n = cols * rows;\n        if (n <= 0 || plan.ys == null || plan.ys.length == 0) return;\n        String key = ylKey(plan.mode, plan.baseY, plan.ys, originX, originZ, step, cols, rows, dim);\n        if (ylJob != null && key.equals(ylJob.key)) return;                    // 同一件事正在采\n        if (ylJob == null && ylDone != null && key.equals(ylDone.key)) return; // 同一件事已经采好\n        YLJob j = new YLJob();\n        j.mode = plan.mode;\n        j.baseY = plan.baseY;\n        j.ys = plan.ys.clone();\n        j.requested = plan.requestedLayers;\n        j.reduceNote = plan.reduceNote;\n        j.cols = cols;\n        j.rows = rows;\n        j.step = step;\n        j.originX = originX;\n        j.originZ = originZ;\n        j.dim = dim;\n        j.totalCells = j.ys.length * n;\n        j.ids = new String[j.totalCells];\n        j.cursor = 0;\n        j.startedTick = ticks;\n        j.mapVersion = version;\n        j.key = key;\n        ylJob = j;\n        ylRuns++;\n    }\n\n    private static String ylKey(String mode, int baseY, int[] ys, int ox, int oz, int step, int cols, int rows, String dim) {\n        StringBuilder b = new StringBuilder();\n        b.append(mode).append('|').append(baseY).append('|');\n        for (int i = 0; i < ys.length; i++) {\n            if (i > 0) b.append(',');\n            b.append(ys[i]);\n        }\n        b.append('|').append(ox).append(',').append(oz).append(',').append(step)\n                .append(',').append(cols).append(',').append(rows).append('|').append(dim);\n        return b.toString();\n    }\n\n    /**\n     * 每个客户端 tick 推进一帧纵层采样（**独立字段，绝不碰地图扫描 / 方框搜索**）。\n     * 预算 = {@link StateConfig#columnsPerTick} **格**（列×层一起算）。\n     */\n    private void advanceLayerScan() {\n        YLJob j = ylJob;\n        if (j == null) return;\n        if (!ready) {\n            ylLastCancelReason = \"地图快照不在场（换世界 / 换世代）⇒ 本次纵层采样作废\";\n            ylJob = null;\n            return;\n        }\n        if (j.cols != cols || j.rows != rows || j.step != step\n                || j.originX != originX || j.originZ != originZ) {\n            ylLastCancelReason = \"地图几何变了（origin/step/cols/rows）⇒ 本次纵层采样作废，等下一次查询按新几何重采\";\n            ylJob = null;\n            return;\n        }\n        int budget = Math.max(1, cfg.columnsPerTick);\n        int n = Math.max(1, cols * rows);\n        while (budget > 0 && j.cursor < j.totalCells) {\n            int idx = j.cursor % n;\n            int k = j.cursor / n;\n            int i = idx % cols;\n            int jj = idx / cols;\n            int bx = j.originX + i * j.step;\n            int bz = j.originZ + jj * j.step;\n            try {\n                String id = bridge.blockAt(bx, j.ys[k], bz);\n                // [T16] 层里同样：void_air = 未加载（客户端不回 null）⇒ 判未知，不当地表/空气画。\n                j.ids[j.cursor] = isVoidAirId(id) ? null : id;\n            } catch (Throwable t) {\n                j.ids[j.cursor] = null;                // 适配层炸了不许把 tick 线程带崩\n                j.errors++;\n                j.lastError = String.valueOf(t);\n            }\n            j.cursor++;\n            budget--;\n        }\n        if (j.cursor >= j.totalCells) {\n            j.finishedTick = ticks;\n            ylDone = j;                                // 发布（此后只读）\n            ylJob = null;\n            ylEverRan = true;\n        }\n    }\n\n    /** 纵层采样的自报（给地图头与 /status；只读缓存，不碰 MC）。 */\n    public Map<String, Object> layerScanJson() {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        YLJob j = ylJob;\n        m.put(\"active\", Boolean.valueOf(j != null));\n        m.put(\"doneCells\", Integer.valueOf(j == null ? 0 : j.cursor));\n        m.put(\"totalCells\", Integer.valueOf(j == null ? 0 : j.totalCells));\n        m.put(\"layers\", Integer.valueOf(j == null ? 0 : j.ys.length));\n        m.put(\"startedTick\", j == null ? null : Integer.valueOf(j.startedTick));\n        m.put(\"finishedTick\", ylDone == null ? null : Integer.valueOf(ylDone.finishedTick));\n        m.put(\"runs\", Integer.valueOf(ylRuns));\n        m.put(\"errors\", Integer.valueOf(j == null ? 0 : j.errors));\n        if (j != null && j.lastError != null) m.put(\"lastError\", j.lastError);\n        if (j != null && j.reduceNote != null) m.put(\"reduceNote\", j.reduceNote);\n        if (j == null && ylLastCancelReason != null) m.put(\"lastCancelReason\", ylLastCancelReason);\n        m.put(\"note\", j != null\n                ? \"纵层采样进行中（分帧）：doneCells/totalCells 是**列×层**的进度；采完一整份才发布，查询不读半成品\"\n                : (ylEverRan ? \"纵层采样**没在跑**（上一份已完成或已作废）\" : \"还没有纵层采样请求\"));\n        return m;\n    }\n\n    private Map<String, Object> layerSnapshotJson(YLJob d) {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"mode\", d.mode);\n        m.put(\"baseY\", Integer.valueOf(d.baseY));\n        m.put(\"requested\", Integer.valueOf(d.requested));\n        m.put(\"scanned\", Integer.valueOf(d.ys.length));\n        List<Object> ys = new ArrayList<Object>();\n        for (int i = 0; i < d.ys.length; i++) ys.add(Integer.valueOf(d.ys[i]));\n        m.put(\"ys\", ys);\n        m.put(\"finishedTick\", Integer.valueOf(d.finishedTick));\n        m.put(\"mapVersionAtScan\", Integer.valueOf(d.mapVersion));\n        m.put(\"geometry\", ylGeomJson(d.cols, d.rows, d.step, d.originX, d.originZ));\n        if (d.reduceNote != null) m.put(\"reduceNote\", d.reduceNote);\n        if (d.errors > 0) m.put(\"errors\", Integer.valueOf(d.errors));\n        if (d.lastError != null) m.put(\"lastError\", d.lastError);\n        return m;\n    }\n\n    private static Map<String, Object> ylGeomJson(int cols, int rows, int step, int ox, int oz) {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"origin\", xy(ox, oz));\n        m.put(\"step\", Integer.valueOf(step));\n        m.put(\"cols\", Integer.valueOf(cols));\n        m.put(\"rows\", Integer.valueOf(rows));\n        return m;\n    }\n\n    /**\n     * 把纵层块写进地图头。**只在 {@code plan.present} 时调用** ⇒ 默认（surface + 没给任何参数）\n     * 路径一个新键都不加，既有回执逐字不变。\n     */\n    private void putYMode(Map<String, Object> m, YPlan plan, int rs, int rc, int rr, int shownRows, int maxChars) {\n        m.put(\"yMode\", plan.mode);\n        m.put(\"yModeRequested\", plan.requested);\n        m.put(\"yModeAutoSwitched\", Boolean.valueOf(plan.autoSwitched));\n        m.put(\"yModeReason\", plan.reason);\n        m.put(\"yModeNote\", Y_MODE_NOTE);\n        if (!plan.layersOn) {\n            m.put(\"layersIncluded\", Boolean.FALSE);\n            m.put(\"layersNote\", \"有效 yMode=surface ⇒ **就是既有行为**（grid 逐字不变），本次不含纵层；\"\n                    + \"要纵层请给 yMode=player|absolute（或别关掉自动切层）\");\n            return;\n        }\n\n        m.put(\"layersIncluded\", Boolean.TRUE);\n        m.put(\"yLayerBaseY\", Integer.valueOf(plan.baseY));\n        m.put(\"yLayerRange\", yRangeJson(plan.low, plan.high));\n        if (plan.rangeNote != null) m.put(\"yRangeNote\", plan.rangeNote);\n        if (plan.rangeClampNote != null) m.put(\"yRangeClampNote\", plan.rangeClampNote);\n        m.put(\"yLayerMax\", Integer.valueOf(plan.layerMax));\n        if (plan.layerMaxNote != null) {\n            m.put(\"yLayerMaxRequested\", plan.layerMaxRequested);\n            m.put(\"yLayerMaxNote\", plan.layerMaxNote);\n        }\n        m.put(\"yLayerCellsPerTick\", Integer.valueOf(Math.max(1, cfg.columnsPerTick)));\n        m.put(\"yLayerScanNote\", Y_LAYER_SCAN_NOTE);\n        m.put(\"layerScan\", layerScanJson());\n        m.put(\"layersRequested\", Integer.valueOf(plan.requestedLayers));\n\n        // ---- 有没有可渲染的成品快照（几何 + 请求指纹都要对得上）----\n        YLJob d = ylDone;\n        boolean geomOk = d != null\n                && d.cols == cols && d.rows == rows && d.step == step\n                && d.originX == originX && d.originZ == originZ\n                && (d.dim == null ? dim == null : d.dim.equals(dim));\n        boolean reqOk = geomOk && ylKey(d.mode, d.baseY, d.ys, originX, originZ, step, cols, rows, dim)\n                .equals(ylKey(plan.mode, plan.baseY, plan.ys, originX, originZ, step, cols, rows, dim));\n        m.put(\"layerSnapshot\", geomOk ? layerSnapshotJson(d) : null);\n        m.put(\"layerSnapshotMatchesRequest\", Boolean.valueOf(reqOk));\n        if (!geomOk) {\n            m.put(\"layersScanned\", Integer.valueOf(0));\n            m.put(\"layersShown\", Integer.valueOf(0));\n            m.put(\"layersDropped\", Integer.valueOf(plan.requestedLayers));\n            m.put(\"layersOmitted\", Integer.valueOf(0));\n            m.put(\"layerTruncated\", Boolean.TRUE);\n            m.put(\"layers\", new ArrayList<Object>());\n            m.put(\"layersDroppedNote\", \"要的 \" + plan.requestedLayers + \" 层**还没采完 / 上一份几何对不上**\"\n                    + \"（layerScan.active=\" + (ylJob != null) + \"）⇒ 本次 layers=[] —— 这是**还没有**，\"\n                    + \"不是「那里没有方块」；等 layerScan.doneCells == totalCells 再取一次\");\n            m.put(\"layerLegend\", new LinkedHashMap<String, Object>());\n            m.put(\"layerLegendUnused\", new ArrayList<Object>());\n            m.put(\"layerLegendNote\", Y_LAYER_GRID_NOTE);\n            m.put(\"layerNote\", \"**本次没有任何一层可渲染** ⇒ 如实给空数组 + 原因，不编、不静默\");\n            return;\n        }\n\n        // ---- 渲染预算：层数 × 每层字符 ≤ layersMaxChars（默认 = 本次 maxChars）----\n        int cellW = cellWidth();\n        int rowLen = rc * cellW;\n        int budget = plan.layersMaxChars != null ? plan.layersMaxChars.intValue() : maxChars;\n        int perLayer = shownRows <= 0 ? 0 : shownRows * rowLen + (shownRows - 1);\n        int byBudget = perLayer <= 0 ? 0 : budget / perLayer;\n        int scanned = d.ys.length;\n        int shown = Math.min(scanned, Math.min(byBudget, Y_LAYER_RENDER_HARD));\n        if (shown < 0) shown = 0;\n\n        // 丢掉的是**边缘**层：以「玩家那一层（player）/ 请求区间中点（absolute）」为心取连续窗口 ——\n        // 这样「这一层是空气、上一层是石头」的相邻两层一定在一起。\n        int targetDy = Y_MODE_PLAYER.equals(d.mode) ? 0 : (plan.low + plan.high) / 2;\n        int idxBase = 0;\n        int best = Integer.MAX_VALUE;\n        for (int k = 0; k < scanned; k++) {\n            int dist = Math.abs((d.ys[k] - d.baseY) - targetDy);\n            if (dist < best) { best = dist; idxBase = k; }\n        }\n        int start = idxBase - (shown - 1) / 2;\n        if (start < 0) start = 0;\n        if (start + shown > scanned) start = Math.max(0, scanned - shown);\n\n        // ---- 逐层渲染（几何与 grid 一模一样；**不画玩家标记**）----\n        int[] pc = playerCell(rs, rc, rr);\n        boolean pcIn = pc[0] >= 0 && pc[1] >= 0;\n        int kk = rs / step;\n        int n = cols * rows;\n        Set<Character> layerUsed = new HashSet<Character>();\n        Set<String> layerOverflowIds = new HashSet<String>();\n        boolean usedUnknown = false, usedOverflow = false;\n        List<Object> layers = new ArrayList<Object>();\n        for (int li = 0; li < shown; li++) {\n            int k = start + li;\n            StringBuilder b = new StringBuilder();\n            for (int j = 0; j < shownRows; j++) {\n                if (j > 0) b.append('\\n');\n                int sj = j * kk;\n                for (int i = 0; i < rc; i++) {\n                    int idx = sj * cols + i * kk;\n                    String id = d.ids[k * n + idx];\n                    char ch;\n                    if (id == null) {\n                        ch = cfg.unknownCode;\n                        usedUnknown = true;\n                    } else {\n                        Character c = layerCodeOf(id);\n                        if (c == null) {\n                            ch = cfg.overflowCode;\n                            usedOverflow = true;\n                            layerOverflowIds.add(id);\n                        } else {\n                            ch = c.charValue();\n                            layerUsed.add(c);\n                        }\n                    }\n                    b.append(ch);\n                    if (cfg.includeHeight) b.append(fmtHeight(heights[idx], heightWidth));\n                }\n            }\n            int chars = shownRows <= 0 ? 0 : shownRows * rowLen + (shownRows - 1);\n            Map<String, Object> L = new LinkedHashMap<String, Object>();\n            L.put(\"y\", Integer.valueOf(d.ys[k]));\n            L.put(\"dy\", Integer.valueOf(d.ys[k] - d.baseY));\n            L.put(\"yIsAbsolute\", Boolean.TRUE);\n            L.put(\"cols\", Integer.valueOf(rc));\n            L.put(\"rows\", Integer.valueOf(rr));\n            L.put(\"shownRows\", Integer.valueOf(shownRows));\n            L.put(\"cellWidth\", Integer.valueOf(cellW));\n            L.put(\"rowLength\", Integer.valueOf(rowLen));\n            L.put(\"shownChars\", Integer.valueOf(chars));\n            L.put(\"truncated\", Boolean.valueOf(shownRows < rr));\n            if (pcIn) {\n                String pid = d.ids[k * n + (pc[1] * kk) * cols + pc[0] * kk];\n                L.put(\"playerCellId\", pid);\n                L.put(\"playerCell\", cellJson(pc[0], pc[1]));\n            } else {\n                L.put(\"playerCellId\", null);\n                L.put(\"playerCell\", null);\n            }\n            L.put(\"grid\", b.toString());\n            layers.add(L);\n        }\n\n        int dropped = Math.max(0, plan.requestedLayers - scanned);\n        int omitted = Math.max(0, scanned - shown);\n        m.put(\"layersScanned\", Integer.valueOf(scanned));\n        m.put(\"layersShown\", Integer.valueOf(shown));\n        m.put(\"layersDropped\", Integer.valueOf(dropped));\n        m.put(\"layersOmitted\", Integer.valueOf(omitted));\n        m.put(\"layerTruncated\", Boolean.valueOf(dropped > 0 || omitted > 0 || shownRows < rr));\n        if (dropped > 0) {\n            String why;\n            if (reqOk) {\n                why = \"本次上限 yLayerMax=\" + plan.layerMax + \" ⇒ **只采了 \" + scanned + \" 层**（差 \" + dropped\n                        + \" 层**根本没采**）\" + (plan.reduceNote != null ? \"；\" + plan.reduceNote : \"\");\n            } else {\n                why = \"本次渲染的是**上一次请求**的 \" + scanned + \" 层快照（与本次请求不是同一份，\"\n                        + \"见 layerSnapshotMismatchNote）⇒ 相对本次请求的 \" + plan.requestedLayers + \" 层，还有 \"\n                        + dropped + \" 层没到；本次请求那一份正在 layerScan 里采（active=\" + (ylJob != null) + \"）\";\n            }\n            m.put(\"layersDroppedNote\", \"请求 \" + plan.requestedLayers + \" 层，\" + why\n                    + \" —— 这是**没采 / 还没到**，不是「那里没有方块」；不许静默读成「只有这些层」\");\n        }\n        if (omitted > 0) {\n            m.put(\"layersOmittedNote\", \"已采 \" + scanned + \" 层，但层网格正文预算 layersMaxChars=\" + budget\n                    + \"（每层 \" + perLayer + \" 字符）只放得下 \" + shown + \" 层 ⇒ **只回了 \" + shown + \" 层**\"\n                    + \"（丢掉 \" + omitted + \" 层，取的是**以基准层为中心的连续窗口** y=[\"\n                    + d.ys[start] + \"..\" + d.ys[start + shown - 1] + \"]）—— 要全要请调大 layersMaxChars / maxChars，\"\n                    + \"或缩小 yRange / 调大 step\");\n        }\n        if (shownRows < rr) {\n            m.put(\"layersRowsNote\", \"地图本身按行截断成 \" + shownRows + \"/\" + rr + \" 行（见 truncatedNote）\"\n                    + \" ⇒ 层网格**同步**只回这几行（几何必须与 grid 一致，不许偷偷换几何）\");\n        }\n        m.put(\"layers\", layers);\n        m.put(\"layerLegend\", layerLegendJson(layerUsed, usedUnknown, usedOverflow, layerOverflowIds));\n        m.put(\"layerLegendUnused\", layerLegendUnusedJson(layerUsed));\n        if (usedOverflow) {\n            m.put(\"layerLegendOverflowNote\", \"层里有 id 拿不到码（palette \" + cfg.palette.length()\n                    + \" 位已被地表图 / 纵层发完）⇒ 画 \" + cfg.overflowCode\n                    + \"；真实 id 见 layerLegendUnused 与 layerPaletteSize 的自报\");\n        }\n        m.put(\"layerLegendNote\", Y_LAYER_GRID_NOTE);\n        m.put(\"layerNote\", \"layers 是**只读快照**（layerSnapshot.finishedTick 那一 tick 采的，分帧、每 tick ≤ \"\n                + Math.max(1, cfg.columnsPerTick) + \" 格）；层网格**不画玩家标记** ⇒ 玩家格的方块 id 看每层的 playerCellId\");\n        if (!reqOk) {\n            m.put(\"layerSnapshotMismatchNote\", \"这份层快照是**上一次请求**采的（模式 / 基准 Y / 层集合 / 几何与本次不同）\"\n                    + \" ⇒ layerSnapshotMatchesRequest=false，请以 layerSnapshot 里的 mode/baseY/ys 为准；\"\n                    + \"新的那一份正在 layerScan 里采\");\n        }\n    }\n\n    /**\n     * **纵层并集图例**：列各层真用到的码（按 id 升序；形状与既有 {@code legend} 完全一致）。\n     *\n     * <p>为什么不能直接复用 {@code legendJson}：它的签名域是 {@code snapshotAllocatedIds}\n     * （**地表图**发过码的 id）；纵层会出现地表图天然没有的 id（最典型 {@code minecraft:air}），\n     * 那些码在 {@link #layerIdToCode} 里 ⇒ 这里取**两者并集**。既有 {@code legend} 一字未动。\n     */\n    private Map<String, Object> layerLegendJson(Set<Character> used, boolean usedUnknown, boolean usedOverflow,\n                                                Set<String> overflowIdsInLayers) {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        if (usedUnknown) m.put(String.valueOf(cfg.unknownCode), UNKNOWN_ID);\n        TreeSet<String> ids = new TreeSet<String>();\n        ids.addAll(snapshotAllocatedIds);\n        ids.addAll(layerIdToCode.keySet());\n        for (String id : ids) {\n            Character c = idToCode.get(id);\n            if (c == null) c = layerIdToCode.get(id);\n            if (c != null && used.contains(c)) m.put(String.valueOf(c.charValue()), id);\n        }\n        if (usedOverflow) {\n            m.put(String.valueOf(cfg.overflowCode), \"<\" + overflowIdsInLayers.size() + \" 种，见 layerLegendOverflowNote>\");\n        }\n        return m;\n    }\n\n    /** 纵层并集图例的「已发码但没画进任何层」清单（按 id 升序）。 */\n    private List<Object> layerLegendUnusedJson(Set<Character> used) {\n        List<Object> out = new ArrayList<Object>();\n        TreeSet<String> ids = new TreeSet<String>();\n        ids.addAll(snapshotAllocatedIds);\n        ids.addAll(layerIdToCode.keySet());\n        for (String id : ids) {\n            Character c = idToCode.get(id);\n            if (c == null) c = layerIdToCode.get(id);\n            if (c != null && !used.contains(c)) {\n                Map<String, Object> one = new LinkedHashMap<String, Object>();\n                one.put(\"code\", String.valueOf(c.charValue()));\n                one.put(\"id\", id);\n                out.add(one);\n            }\n        }\n        return out;\n    }\n\n    // ==================================================================\n    // ⑥a query_column（单列纵剖面）\n    // ==================================================================\n\n    /**\n     * 单列纵剖面：从 yHigh 到 yLow **降序**逐层给 {@code {y, id}}（空气也如实出现）。\n     *\n     * <p>调用方（{@link PlaytestCore#dispatch}）已校验 x/z 必填且为整数，并把 y1/y2 的缺省补好。\n     * 本方法只做「读 + 有界 + 账目」：**最多读 maxBlocks 层**，超了 fail-loud（truncated + 丢掉哪一段）。\n     */\n    public Map<String, Object> queryColumn(int x, int z, int y1In, int y2In, int maxBlocksIn) {\n        Map<String, Object> out = new LinkedHashMap<String, Object>();\n        out.put(\"schema\", COLUMN_SCHEMA);\n        out.put(\"x\", Integer.valueOf(x));\n        out.put(\"z\", Integer.valueOf(z));\n        out.put(\"order\", COLUMN_ORDER);\n        out.put(\"orderNote\", COLUMN_ORDER_NOTE);\n\n        int maxBlocks = maxBlocksIn <= 0 ? COLUMN_DEFAULT_MAX_BLOCKS : Math.min(maxBlocksIn, COLUMN_MAX_BLOCKS);\n        out.put(\"maxBlocks\", Integer.valueOf(maxBlocks));\n        out.put(\"maxBlocksDefault\", Integer.valueOf(COLUMN_DEFAULT_MAX_BLOCKS));\n        out.put(\"maxBlocksMax\", Integer.valueOf(COLUMN_MAX_BLOCKS));\n        if (maxBlocksIn <= 0) {\n            out.put(\"maxBlocksNote\", \"未给 maxBlocks（或给了 ≤0）⇒ 用默认 \" + COLUMN_DEFAULT_MAX_BLOCKS\n                    + \"（**有界**，绝不整列无界返回）\");\n        } else if (maxBlocksIn > COLUMN_MAX_BLOCKS) {\n            out.put(\"maxBlocksClampedTo\", Integer.valueOf(COLUMN_MAX_BLOCKS));\n            out.put(\"maxBlocksNote\", \"maxBlocks=\" + maxBlocksIn + \" 超过硬上限 \" + COLUMN_MAX_BLOCKS\n                    + \" ⇒ 夹到 \" + COLUMN_MAX_BLOCKS + \"（如实回 maxBlocksClampedTo，不静默）\");\n        }\n\n        int yHigh = Math.max(y1In, y2In);\n        int yLow = Math.min(y1In, y2In);\n        out.put(\"y1\", Integer.valueOf(yLow));\n        out.put(\"y2\", Integer.valueOf(yHigh));\n        out.put(\"y1Requested\", Integer.valueOf(y1In));\n        out.put(\"y2Requested\", Integer.valueOf(y2In));\n        if (y1In > y2In) {\n            out.put(\"ySwapNote\", \"调用方给的 y1=\" + y1In + \" > y2=\" + y2In\n                    + \" ⇒ 按 [yLow..yHigh] 读；回执里的 y1/y2 已按升序规范化（y1=\" + yLow + \", y2=\" + yHigh + \"）\");\n        }\n\n        List<Object> rows = new ArrayList<Object>();\n        int unknown = 0, air = 0, nonAir = 0, voidAir = 0;\n        Integer firstNonAirY = null;\n        String firstNonAirId = null;\n        String colError = null;\n        boolean truncated = false;\n        int droppedFromY = 0, droppedToY = 0;\n        int y = yHigh;\n        while (true) {\n            if (rows.size() >= maxBlocks) {\n                if (y >= yLow) {\n                    truncated = true;\n                    droppedFromY = y;\n                    droppedToY = yLow;\n                }\n                break;\n            }\n            if (y < yLow) break;\n            String id;\n            try {\n                id = bridge.blockAt(x, y, z);\n            } catch (Throwable t) {\n                id = null;                                  // 适配层炸了也不许把回执编成空气\n                if (colError == null) colError = String.valueOf(t);\n            }\n            Map<String, Object> row = new LinkedHashMap<String, Object>();\n            row.put(\"y\", Integer.valueOf(y));\n            row.put(\"id\", id);\n            rows.add(row);\n            if (id == null) {\n                unknown++;\n            } else if (isAirId(id)) {\n                air++;\n                if (isVoidAirId(id)) voidAir++;\n            } else {\n                nonAir++;\n                if (firstNonAirY == null) {\n                    firstNonAirY = Integer.valueOf(y);\n                    firstNonAirId = id;\n                }\n            }\n            y--;\n        }\n\n        out.put(\"count\", Integer.valueOf(rows.size()));\n        out.put(\"blocks\", rows);\n        out.put(\"truncated\", Boolean.valueOf(truncated));\n        if (truncated) {\n            out.put(\"droppedFromY\", Integer.valueOf(droppedFromY));\n            out.put(\"droppedToY\", Integer.valueOf(droppedToY));\n            out.put(\"truncatedNote\", \"只读了 \" + rows.size() + \" 层（maxBlocks=\" + maxBlocks\n                    + \"）⇒ **没读**的那一段 = y \" + droppedFromY + \" .. \" + droppedToY + \"（共 \"\n                    + (droppedFromY - droppedToY + 1) + \" 层被丢下）—— 是**没读**，不是那里没有方块\");\n        } else {\n            out.put(\"droppedFromY\", null);\n            out.put(\"droppedToY\", null);\n        }\n        out.put(\"readFromY\", Integer.valueOf(yHigh));\n        out.put(\"readToY\", rows.isEmpty() ? null : ((Map<?, ?>) rows.get(rows.size() - 1)).get(\"y\"));\n        out.put(\"airCount\", Integer.valueOf(air));\n        out.put(\"unknownCount\", Integer.valueOf(unknown));\n        out.put(\"nonAirCount\", Integer.valueOf(nonAir));\n        out.put(\"firstNonAirY\", firstNonAirY);\n        out.put(\"firstNonAirId\", firstNonAirId);\n        out.put(\"voidAirCount\", Integer.valueOf(voidAir));\n        out.put(\"unknownNote\", UNKNOWN_ROW_NOTE);\n        out.put(\"airIdNote\", AIR_ID_NOTE);\n        if (unknown > 0) {\n            out.put(\"unknownRowsNote\", \"本次读的 \" + rows.size() + \" 层里有 \" + unknown\n                    + \" 层取不到（id=null）—— 多半是未加载区块 / 越界 Y；这些层**不参与** firstNonAirY 判定\");\n        }\n        if (colError != null) out.put(\"lastError\", colError);\n\n        // ---- 与地图高度语义的**自检口**（B① 判据用得上）----\n        int top = Integer.MIN_VALUE;\n        try {\n            top = bridge.topSolidY(x, z);\n        } catch (Throwable ignored) {\n            top = Integer.MIN_VALUE;\n        }\n        out.put(\"topSolidY\", top == Integer.MIN_VALUE ? null : (Object) Integer.valueOf(top));\n        // **疑似未加载**的自证（真机实证 2026-11-11：距玩家 600 格的列，fabric 1.21.11 与 neoforge 1.20.1\n        // **都**回 minecraft:void_air（不是 null）且 topSolidY=-65 ⇒ 适配层的区块加载判据在客户端没生效）。\n        // 这里**如实点名**，别让调用方把未加载区读成「一片空气」。\n        boolean allVoidAir = rows.size() > 0 && voidAir == rows.size();\n        out.put(\"unloadedSuspect\", Boolean.valueOf(allVoidAir));\n        if (allVoidAir) {\n            out.put(\"unloadedSuspectNote\", \"本列读到的 \" + rows.size() + \" 层**全部**是 minecraft:void_air\"\n                    + \"（且 topSolidY=\" + (top == Integer.MIN_VALUE ? \"null\" : String.valueOf(top)) + \"）\"\n                    + \" ⇒ 极可能**该区块未加载**：适配层的加载判据没生效，GameBridge#blockAt **没有**回 null\"\n                    + \"（真机实证：距玩家 600 格的列就是这个形状）⇒ **别把这里当空气读**；\"\n                    + \"要确认请换个近处的坐标再读一次\");\n        }\n        Integer mapH = mapHeightAt(x, z);\n        out.put(\"mapHeightAtColumn\", mapH);\n        out.put(\"heightCrossCheckNote\",\n                \"topSolidY = 该列最高非空气方块的 Y（= query_map 高度字段的 h）；\"\n                + \"mapHeightAtColumn = **本地图快照**里 (x,z) 那一格的高度（该列没被采到 / 没有图 ⇒ null）；\"\n                + \"firstNonAirY = 本次读的窗口里最高的非空气层 ⇒ 窗口盖住地表时三者应当相等\");\n        return out;\n    }\n\n    /** 地图快照里 (x,z) 那一格的高度；该列没被采到 / 还没有图 ⇒ null（不编）。只读。 */\n    public Integer mapHeightAt(int x, int z) {\n        if (!ready) return null;\n        int i = x - originX, j = z - originZ;\n        if (i < 0 || j < 0) return null;\n        if (step <= 0 || i % step != 0 || j % step != 0) return null;\n        int col = i / step, row = j / step;\n        if (col >= cols || row >= rows) return null;\n        int h = heights[row * cols + col];\n        return h == Integer.MIN_VALUE ? null : Integer.valueOf(h);\n    }\n\n    // ==================================================================\n    // ⑥b query_blocks（按条件搜方块；**独立的分帧 job**）\n    // ==================================================================\n    private volatile boolean sqActive;\n    private volatile boolean sqEverRan;\n    /**\n     * [T20-②] 本次扫描是否真有原点（读到了玩家坐标）。\n     * 没有 ⇒ origin / scan.origin / scan.center / scan.y1 / scan.y2 **一律 null**，\n     * 绝不回上一次扫描的原点或编一个 0,0,0（那正是「旧数据配新条件」的另一种形态）。\n     */\n    private volatile boolean sqHasOrigin;\n    private volatile boolean sqTruncated;\n    private volatile int sqCursor, sqTotalBlocks, sqBlocksDone, sqTotalCols, sqYCount;\n    private volatile int sqCols, sqRadius, sqOriginX, sqOriginZ, sqCenterX, sqCenterZ, sqY1, sqY2, sqMaxMatches;\n    private volatile int sqErrors, sqUnknown, sqHitCount, sqRuns, sqVoidAir;\n    private volatile long sqStartedTick = -1, sqFinishedTick = -1;\n    private volatile String sqLastError, sqStopReason, sqStartBlocked;\n    private volatile List<String> sqFilter = new ArrayList<String>();\n    private volatile boolean sqFilterDirty;\n    private final List<BlockHit> sqHits = new ArrayList<BlockHit>();\n    private List<String> sqFilterApplied = new ArrayList<String>();\n    private double sqPx, sqPy, sqPz;\n\n    /**\n     * 起一次搜索（丢弃上一次的命中 / 进度 / **原点**）。\n     *\n     * <p>[T20-②] **先清后判**：任何一条早退路径（本档没有取值面 / 玩家或世界不在场 / 读不到玩家坐标）\n     * 都必须先把状态落成「**本次条件 + 空命中**」再返回 —— 否则旧命中会配着新条件回出去\n     * （旧实现就有这个洞：起不动时 sqHits / sqFilterApplied 仍是上一次的）。\n     */\n    private boolean startSearch(int radius, int yLow, int yHigh, List<String> filter, int maxMatches) {\n        // ---- ① 先把「本次条件 + 空账」落到位（不依赖能不能起得来）----\n        sqActive = false;\n        sqEverRan = false;\n        sqHasOrigin = false;\n        sqStartBlocked = null;\n        sqTruncated = false;\n        sqStopReason = null;\n        sqLastError = null;\n        sqErrors = 0;\n        sqUnknown = 0;\n        sqHitCount = 0;\n        sqVoidAir = 0;\n        sqRadius = radius;\n        sqY1 = yLow;\n        sqY2 = yHigh;\n        sqYCount = Math.max(0, yHigh - yLow + 1);\n        sqCols = 2 * radius + 1;\n        sqTotalCols = sqCols * sqCols;\n        sqTotalBlocks = sqTotalCols * sqYCount;\n        sqCursor = 0;\n        sqBlocksDone = 0;\n        sqMaxMatches = maxMatches;\n        sqHits.clear();\n        sqFilter = new ArrayList<String>(filter);\n        sqFilterApplied = new ArrayList<String>(filter);\n        sqFilterDirty = false;\n        sqStartedTick = ticks;\n        sqFinishedTick = -1;\n\n        // ---- ② 起不动就如实记原因（命中已清空 ⇒ 不会拿旧结果冒充新条件）----\n        if (!bridge.stateMapCapable() || !bridge.ready() || colPlayerXYZ() == null) {\n            sqStartBlocked = SEARCH_NOT_STARTED_NOTE;\n            return false;\n        }\n        double[] xyz = colPlayerXYZ();\n        sqRuns++;\n        sqActive = true;\n        // **以玩家为中心**：盒 = [floor(px)-r, floor(px)+r] × [floor(pz)-r, floor(pz)+r]\n        // （origin 存**最小角**；center 存玩家所在那格，两者都写进回执，别让调用方猜）。\n        sqCenterX = (int) Math.floor(xyz[0]);\n        sqCenterZ = (int) Math.floor(xyz[2]);\n        sqOriginX = sqCenterX - radius;\n        sqOriginZ = sqCenterZ - radius;\n        sqPx = xyz[0];\n        sqPy = xyz[1];\n        sqPz = xyz[2];\n        sqHasOrigin = true;\n        sqEverRan = true;\n        return true;\n    }\n\n    /** 客户端 tick 线程每 tick 推进一小段（**分帧**）。没有进行中的搜索 ⇒ 立即返回。 */\n    private void advanceSearch() {\n        if (!sqActive) return;\n        int budget = SEARCH_BLOCKS_PER_TICK;\n        int yCount = sqYCount;\n        while (budget > 0 && sqCursor < sqTotalBlocks) {\n            int col = sqCursor / yCount;\n            int y = sqY1 + (sqCursor % yCount);\n            int bx = sqOriginX + (col % sqCols);\n            int bz = sqOriginZ + (col / sqCols);\n            String id;\n            try {\n                id = bridge.blockAt(bx, y, bz);\n            } catch (Throwable t) {\n                id = null;\n                sqErrors++;\n                sqLastError = String.valueOf(t);\n            }\n            if (id == null) {\n                sqUnknown++;\n            } else if (isVoidAirId(id)) {\n                // 客户端在**未加载**区块上会回 void_air（不是 null）⇒ 单列**如实记账**，\n                // 且**不参与**任何 filter 匹配（避免把未加载区当成空气命中）。\n                sqVoidAir++;\n            } else if (idMatches(id, sqFilterApplied)) {\n                if (sqHitCount >= sqMaxMatches) {\n                    // 这一格已经读到了，但**不**收（超出 maxMatches）⇒ 记账照样 +1，再提前收工。\n                    // fail-loud：truncated=true 且 complete=false（剩余区域**没扫**，不是「只有这些」）。\n                    sqTruncated = true;\n                    sqStopReason = SEARCH_TRUNCATED_NOTE;\n                    sqCursor++;\n                    sqBlocksDone++;\n                    sqCursor = sqTotalBlocks;\n                    break;\n                }\n                sqHits.add(new BlockHit(bx, y, bz, id, dist2FromOrigin(bx, y, bz)));\n                sqHitCount++;\n            }\n            sqCursor++;\n            budget--;\n            sqBlocksDone++;\n        }\n        if (sqCursor >= sqTotalBlocks) {\n            sqActive = false;\n            if (sqFinishedTick < 0) sqFinishedTick = ticks;\n            if (sqStopReason == null && sqTruncated) sqStopReason = SEARCH_TRUNCATED_NOTE;\n        }\n    }\n\n    private double dist2FromOrigin(int x, int y, int z) {\n        double dx = x + 0.5 - sqPx, dy = y + 0.5 - sqPy, dz = z + 0.5 - sqPz;\n        return dx * dx + dy * dy + dz * dz;\n    }\n\n    /**\n     * query_blocks：按条件搜方块，**只回命中坐标**。\n     *\n     * <p>调用方已校验 filter 必填、把 radius / y1 / y2 / maxMatches 的缺省补好。本方法负责：\n     * 起扫描（refresh 或首次）、把当前进度与**已扫范围内**的命中如实回出去。\n     */\n    public Map<String, Object> queryBlocks(int radiusIn, int y1In, int y2In, List<String> filter,\n            int maxMatchesIn, boolean refresh) {\n        int radius = radiusIn <= 0 ? SEARCH_DEFAULT_RADIUS : Math.min(radiusIn, SEARCH_MAX_RADIUS);\n        int maxMatches = maxMatchesIn <= 0 ? SEARCH_DEFAULT_MAX_MATCHES : Math.min(maxMatchesIn, SEARCH_MAX_MATCHES);\n        int yLow = Math.min(y1In, y2In);\n        int yHigh = Math.max(y1In, y2In);\n        boolean yClamped = false;\n        if (yHigh - yLow + 1 > SEARCH_MAX_Y_SPAN) {\n            yHigh = yLow + SEARCH_MAX_Y_SPAN - 1;\n            yClamped = true;\n        }\n        // [T20-②] 条件签名 = (filter, radius, y1, y2, maxMatches) **规范化之后**的值。\n        // 任一不同 ⇒ 与「显式 refresh」同样处理：**立即用本次条件重扫**（选项 a）。\n        // 旧行为（真机实测的静默错误）：只标 filterChanged，却把上一次条件的 matches 配着新 filter 回出去。\n        boolean hadRun = sqEverRan;\n        boolean sameAsApplied = hadRun && sameCondition(radius, yLow, yHigh, maxMatches, filter);\n        boolean conditionChanged = hadRun && !sameAsApplied;\n        Map<String, Object> previousCondition = conditionChanged ? appliedConditionJson() : null;\n        boolean restarted = refresh || !hadRun || conditionChanged;\n        boolean started = false;\n        if (restarted) {\n            started = startSearch(radius, yLow, yHigh, filter, maxMatches);\n        }\n        sqFilterDirty = conditionChanged;\n\n        Map<String, Object> out = new LinkedHashMap<String, Object>();\n        out.put(\"schema\", SEARCH_SCHEMA);\n        out.put(\"filter\", new ArrayList<String>(filter));\n        out.put(\"filterNote\", FILTER_NOTE);\n        out.put(\"filterCount\", Integer.valueOf(filter.size()));\n        out.put(\"filterMax\", Integer.valueOf(SEARCH_MAX_FILTERS));\n        out.put(\"radius\", Integer.valueOf(radius));\n        out.put(\"radiusRequested\", Integer.valueOf(radiusIn));\n        out.put(\"radiusDefault\", Integer.valueOf(SEARCH_DEFAULT_RADIUS));\n        out.put(\"radiusMax\", Integer.valueOf(SEARCH_MAX_RADIUS));\n        if (radiusIn <= 0) {\n            out.put(\"radiusNote\", \"未给 radius（或给了 ≤0）⇒ 用默认水平半径 \" + SEARCH_DEFAULT_RADIUS\n                    + \" 格（正方形，共 \" + ((2 * SEARCH_DEFAULT_RADIUS + 1) * (2 * SEARCH_DEFAULT_RADIUS + 1))\n                    + \" 列）\");\n        } else if (radiusIn > SEARCH_MAX_RADIUS) {\n            out.put(\"radiusClampedTo\", Integer.valueOf(SEARCH_MAX_RADIUS));\n            out.put(\"radiusNote\", \"radius=\" + radiusIn + \" 超过硬上限 \" + SEARCH_MAX_RADIUS\n                    + \" ⇒ 夹到 \" + SEARCH_MAX_RADIUS + \"（如实回 radiusClampedTo，不静默）\");\n        }\n        out.put(\"y1\", Integer.valueOf(yLow));\n        out.put(\"y2\", Integer.valueOf(yHigh));\n        out.put(\"y1Requested\", Integer.valueOf(y1In));\n        out.put(\"y2Requested\", Integer.valueOf(y2In));\n        out.put(\"ySpanMax\", Integer.valueOf(SEARCH_MAX_Y_SPAN));\n        if (yHigh != Math.max(y1In, y2In)) {\n            out.put(\"yClampedTo\", yLow + \"..\" + yHigh);\n            out.put(\"yNote\", \"y 跨度超过硬上限 \" + SEARCH_MAX_Y_SPAN + \" 层 ⇒ 从上面裁到 [\" + yLow + \"..\" + yHigh\n                    + \"]（如实回 yClampedTo，不静默）\");\n        } else if (y1In > y2In) {\n            out.put(\"ySwapNote\", \"调用方给的 y1=\" + y1In + \" > y2=\" + y2In + \" ⇒ 按 [yLow..yHigh] 读\");\n        }\n        out.put(\"maxMatches\", Integer.valueOf(maxMatches));\n        out.put(\"maxMatchesRequested\", Integer.valueOf(maxMatchesIn));\n        out.put(\"maxMatchesDefault\", Integer.valueOf(SEARCH_DEFAULT_MAX_MATCHES));\n        out.put(\"maxMatchesMax\", Integer.valueOf(SEARCH_MAX_MATCHES));\n        if (maxMatchesIn <= 0) {\n            out.put(\"maxMatchesNote\", \"未给 maxMatches（或给了 ≤0）⇒ 用默认 \" + SEARCH_DEFAULT_MAX_MATCHES);\n        } else if (maxMatchesIn > SEARCH_MAX_MATCHES) {\n            out.put(\"maxMatchesClampedTo\", Integer.valueOf(SEARCH_MAX_MATCHES));\n            out.put(\"maxMatchesNote\", \"maxMatches=\" + maxMatchesIn + \" 超过硬上限 \" + SEARCH_MAX_MATCHES\n                    + \" ⇒ 夹到 \" + SEARCH_MAX_MATCHES + \"（如实回 maxMatchesClampedTo，不静默）\");\n        }\n        out.put(\"refreshRequested\", Boolean.valueOf(refresh));\n        out.put(\"restarted\", Boolean.valueOf(restarted));\n        out.put(\"reused\", Boolean.valueOf(!restarted));\n        out.put(\"scanStarted\", Boolean.valueOf(started));\n        if (conditionChanged) {\n            out.put(\"restartedReason\", \"condition_changed\");\n            out.put(\"conditionChanged\", Boolean.TRUE);\n            out.put(\"previousCondition\", previousCondition);\n        } else if (refresh) {\n            out.put(\"restartedReason\", \"refresh_requested\");\n            out.put(\"restartedNote\", SEARCH_REFRESH_NOTE);\n        } else if (!hadRun) {\n            out.put(\"restartedReason\", \"first_run\");\n            out.put(\"restartedNote\", \"本会话还没有过扫描 ⇒ 直接起一轮（restartedReason=first_run）。\");\n        } else {\n            out.put(\"restartedReason\", null);\n            out.put(\"reusedNote\", SEARCH_REUSED_NOTE);\n        }\n\n        Map<String, Object> origin = new LinkedHashMap<String, Object>();\n        // [T20-②] 没有本次原点（扫描没起得来）⇒ 一律 null：**绝不**回上一次扫描的原点或编 0,0,0。\n        origin.put(\"x\", sqHasOrigin ? Double.valueOf(round3(sqPx)) : null);\n        origin.put(\"y\", sqHasOrigin ? Double.valueOf(round3(sqPy)) : null);\n        origin.put(\"z\", sqHasOrigin ? Double.valueOf(round3(sqPz)) : null);\n        origin.put(\"block\", sqHasOrigin ? xy(sqCenterX, sqCenterZ) : null);\n        origin.put(\"boxMin\", sqHasOrigin ? xy(sqOriginX, sqOriginZ) : null);\n        origin.put(\"boxMax\", sqHasOrigin ? xy(sqOriginX + 2 * sqRadius, sqOriginZ + 2 * sqRadius) : null);\n        origin.put(\"available\", Boolean.valueOf(sqHasOrigin));\n        origin.put(\"note\", sqHasOrigin\n                ? \"x/y/z = **本次扫描开始那一刻**的玩家位置（dist 的基准）；\"\n                + \"block = 玩家所在那格；boxMin/boxMax = 扫描盒的两个角（水平面，闭区间，以玩家那格为中心）\"\n                : \"本次扫描**没有起点**（起不动：见 scanNote）⇒ 各字段一律 null（不编 0,0,0）\");\n        out.put(\"origin\", origin);\n        out.put(\"orderNote\", SEARCH_SORT_NOTE);\n\n        List<Object> matches = sortedMatches();\n        out.put(\"matches\", matches);\n        out.put(\"matched\", Integer.valueOf(matches.size()));\n        out.put(\"truncated\", Boolean.valueOf(sqTruncated));\n        if (sqTruncated) out.put(\"truncatedNote\", SEARCH_TRUNCATED_NOTE);\n        // [T22] 截断契约：把「扫完了没有」与「为什么停」提到**顶层**（scan.complete 仍在，语义一致），\n        //   complete=false 时**明说还剩多少格没扫**（绝不把提前停读成扫完了）。\n        boolean complete = searchComplete();\n        int remaining = Math.max(0, sqTotalBlocks - sqBlocksDone);\n        out.put(\"complete\", Boolean.valueOf(complete));\n        out.put(\"stoppedBy\", searchStoppedBy());\n        out.put(\"remainingBlocks\", Integer.valueOf(remaining));\n        out.put(\"completeNote\", SEARCH_COMPLETE_NOTE);\n        if (!complete) out.put(\"completeReasonNote\", searchCompleteNote(remaining));\n        out.put(\"scan\", searchScanJson());\n        if (!sqEverRan) {\n            out.put(\"scanNote\", sqStartBlocked == null ? SEARCH_NOT_STARTED_NOTE : sqStartBlocked);\n        }\n        if (conditionChanged) {\n            // 旧行为下这里配的是**旧条件的 matches**（真机实测的静默错误）；现在 matches 已来自新条件的新一轮。\n            out.put(\"filterChanged\", Boolean.TRUE);\n            out.put(\"filterChangedNote\", SEARCH_RESTARTED_NOTE);\n        }\n        if (matches.isEmpty() && !conditionChanged) {\n            out.put(\"matchNote\", sqActive ? SEARCH_EMPTY_NOTE + \"（注意：扫描**还在进行中**，后面可能还有命中）\"\n                    : SEARCH_EMPTY_NOTE);\n        }\n        return out;\n    }\n\n    /**\n     * [T20-②] **完整的条件签名**比较（不是只看 filter）：filter + radius + y1 + y2 + maxMatches。\n     *\n     * <p>为什么必须全比：真机实测过「只换 radius / y1 / y2 而不带 refresh」也会把旧结果配着新条件的\n     * 回显回出去（旧实现只比 filter，其它旋钮根本没进判据）。\n     */\n    private boolean sameCondition(int radius, int yLow, int yHigh, int maxMatches, List<String> filter) {\n        return radius == sqRadius && yLow == sqY1 && yHigh == sqY2\n                && maxMatches == sqMaxMatches && sameFilter(filter, sqFilterApplied);\n    }\n\n    /** [T20-②] 上一次扫描**实际用的**条件（原样回给调用方供核对，**不猜**）。 */\n    private Map<String, Object> appliedConditionJson() {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"filter\", new ArrayList<String>(sqFilterApplied));\n        m.put(\"radius\", Integer.valueOf(sqRadius));\n        m.put(\"y1\", Integer.valueOf(sqY1));\n        m.put(\"y2\", Integer.valueOf(sqY2));\n        m.put(\"maxMatches\", Integer.valueOf(sqMaxMatches));\n        m.put(\"scannedBlocks\", Integer.valueOf(sqBlocksDone));\n        m.put(\"hits\", Integer.valueOf(sqHitCount));\n        return m;\n    }\n\n    /** 两个 filter 列表是否逐字相同（trim + 小写后比；顺序无关）。 */\n    static boolean sameFilter(List<String> a, List<String> b) {\n        java.util.List<String> na = normFilter(a), nb = normFilter(b);\n        if (na.size() != nb.size()) return false;\n        for (String s : na) if (!nb.contains(s)) return false;\n        return true;\n    }\n\n    private static java.util.List<String> normFilter(List<String> in) {\n        java.util.List<String> out = new ArrayList<String>();\n        if (in == null) return out;\n        for (String s : in) {\n            if (s == null) continue;\n            String t = s.trim().toLowerCase(java.util.Locale.ROOT);\n            if (!t.isEmpty() && !out.contains(t)) out.add(t);\n        }\n        return out;\n    }\n\n    /** 命中按与扫描原点的距离由近到远排序（并列按 (x,y,z) 升序 ⇒ 可复现）。 */\n    private List<Object> sortedMatches() {\n        List<BlockHit> copy = new ArrayList<BlockHit>(sqHits);\n        java.util.Collections.sort(copy, new java.util.Comparator<BlockHit>() {\n            public int compare(BlockHit a, BlockHit b) {\n                if (a.dist2 < b.dist2) return -1;\n                if (a.dist2 > b.dist2) return 1;\n                if (a.y != b.y) return a.y - b.y;\n                if (a.x != b.x) return a.x - b.x;\n                return a.z - b.z;\n            }\n        });\n        List<Object> out = new ArrayList<Object>();\n        for (BlockHit h : copy) {\n            Map<String, Object> one = new LinkedHashMap<String, Object>();\n            one.put(\"x\", Integer.valueOf(h.x));\n            one.put(\"y\", Integer.valueOf(h.y));\n            one.put(\"z\", Integer.valueOf(h.z));\n            one.put(\"id\", h.id);\n            one.put(\"dist\", Double.valueOf(round3(Math.sqrt(h.dist2))));\n            out.add(one);\n        }\n        return out;\n    }\n\n    private Map<String, Object> searchScanJson() {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"active\", Boolean.valueOf(sqActive));\n        m.put(\"complete\", Boolean.valueOf(!sqActive && !sqTruncated && sqTotalBlocks > 0\n                && sqBlocksDone >= sqTotalBlocks));\n        m.put(\"doneBlocks\", Integer.valueOf(sqBlocksDone));\n        m.put(\"totalBlocks\", Integer.valueOf(sqTotalBlocks));\n        m.put(\"doneCols\", Integer.valueOf(sqYCount <= 0 ? 0 : sqBlocksDone / sqYCount));\n        m.put(\"totalCols\", Integer.valueOf(sqTotalCols));\n        m.put(\"radius\", Integer.valueOf(sqRadius));\n        m.put(\"cols\", Integer.valueOf(sqCols));\n        // [T20-②] 没有本次原点 ⇒ 一律 null（绝不回上一次的原点 / 编 0,0,0）。\n        m.put(\"origin\", sqHasOrigin ? xy(sqOriginX, sqOriginZ) : null);\n        m.put(\"originNote\", \"origin = 扫描盒的**最小角**（min corner，含）；盒 = [origin.x, origin.x+cols-1] × [origin.z, origin.z+cols-1]\");\n        m.put(\"center\", sqHasOrigin ? xy(sqCenterX, sqCenterZ) : null);\n        m.put(\"y1\", sqHasOrigin ? Integer.valueOf(sqY1) : null);\n        m.put(\"y2\", sqHasOrigin ? Integer.valueOf(sqY2) : null);\n        m.put(\"blocksPerTick\", Integer.valueOf(SEARCH_BLOCKS_PER_TICK));\n        m.put(\"startedTick\", sqStartedTick < 0 ? null : Long.valueOf(sqStartedTick));\n        m.put(\"finishedTick\", sqFinishedTick < 0 ? null : Long.valueOf(sqFinishedTick));\n        m.put(\"runs\", Integer.valueOf(sqRuns));\n        m.put(\"hits\", Integer.valueOf(sqHitCount));\n        m.put(\"errors\", Integer.valueOf(sqErrors));\n        m.put(\"unknownBlocks\", Integer.valueOf(sqUnknown));\n        m.put(\"voidAirBlocks\", Integer.valueOf(sqVoidAir));\n        if (sqVoidAir > 0) {\n            m.put(\"voidAirNote\", \"有 \" + sqVoidAir + \" 格读到 minecraft:void_air ⇒ 这些格**疑似未加载**\"\n                    + \"（适配层没回 null），已**不参与**任何 filter 匹配、只记进本计数\");\n        }\n        m.put(\"stopReason\", sqStopReason);\n        m.put(\"filterApplied\", new ArrayList<String>(sqFilterApplied));\n        if (sqLastError != null) m.put(\"lastError\", sqLastError);\n        m.put(\"note\", SEARCH_SCAN_NOTE);\n        return m;\n    }\n\n    /**\n     * [T22] {@code complete}：仅当**本轮扫描真的起了、已停、没被 maxMatches 截断、且整盒都扫完**。\n     * 与 {@code scan.complete} 同一个判据（这里提到顶层给调用方，免得钻进 scan 段读错）。\n     * 扫描没起（{@code sqEverRan=false}）⇒ 恒 false（**不假装扫完了**）。\n     */\n    private boolean searchComplete() {\n        return sqEverRan && !sqActive && !sqTruncated\n                && sqTotalBlocks > 0 && sqBlocksDone >= sqTotalBlocks;\n    }\n\n    /**\n     * [T22] {@code stoppedBy}：为什么这一轮没扫完（或没起）。取值见 {@link #SEARCH_COMPLETE_NOTE}。\n     * 自然扫完 ⇒ {@code null}。\n     */\n    private String searchStoppedBy() {\n        if (!sqEverRan) return \"notStarted\";\n        if (sqTruncated) return \"maxMatches\";\n        if (sqActive) return \"scanning\";\n        if (sqBlocksDone < sqTotalBlocks) return \"aborted\";\n        return null;\n    }\n\n    /** [T22] {@code complete=false} 时的人话（明说还剩多少格没扫 + 这一轮为什么停）。 */\n    private String searchCompleteNote(int remaining) {\n        if (!sqEverRan) {\n            return \"扫描**没有起**（见 scanNote）⇒ 无从谈 complete；remainingBlocks=\" + remaining\n                    + \" 是整盒格数（**一格都没扫**）\";\n        }\n        if (sqTruncated) {\n            return SEARCH_TRUNCATED_NOTE + \"（remainingBlocks=\" + remaining + \" = **没扫**的格数，\"\n                    + \"不是命中数；调大 maxMatches 并 refresh=true 可继续）\";\n        }\n        if (sqActive) {\n            return \"扫描**还在进行中**（scan.active=true，stoppedBy=scanning）⇒ 剩余 \" + remaining\n                    + \" 格还没扫；条件不变继续轮询即可（续扫，不重置进度）\";\n        }\n        return \"扫描被**中止**（玩家 / 世界离场导致 scan.active=false，stoppedBy=aborted）⇒ 剩余 \"\n                + remaining + \" 格没扫；回到世界后条件不变会继续（或 refresh=true 重扫）\";\n    }\n\n    /** 只读自报（给 /status；**不碰 MC、不碰命中列表**，HTTP 线程也能读）。 */\n    public Map<String, Object> blockSearchStatus() {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"capable\", Boolean.valueOf(bridge.stateMapCapable()));\n        m.put(\"everRan\", Boolean.valueOf(sqEverRan));\n        m.put(\"active\", Boolean.valueOf(sqActive));\n        m.put(\"doneBlocks\", Integer.valueOf(sqBlocksDone));\n        m.put(\"totalBlocks\", Integer.valueOf(sqTotalBlocks));\n        m.put(\"hits\", Integer.valueOf(sqHitCount));\n        m.put(\"truncated\", Boolean.valueOf(sqTruncated));\n        m.put(\"runs\", Integer.valueOf(sqRuns));\n        m.put(\"radius\", Integer.valueOf(sqRadius));\n        m.put(\"y1\", Integer.valueOf(sqY1));\n        m.put(\"y2\", Integer.valueOf(sqY2));\n        m.put(\"blocksPerTick\", Integer.valueOf(SEARCH_BLOCKS_PER_TICK));\n        m.put(\"filterApplied\", new ArrayList<String>(sqFilterApplied));\n        m.put(\"startedTick\", sqStartedTick < 0 ? null : Long.valueOf(sqStartedTick));\n        m.put(\"finishedTick\", sqFinishedTick < 0 ? null : Long.valueOf(sqFinishedTick));\n        m.put(\"startBlocked\", sqStartBlocked);\n        m.put(\"note\", \"query_blocks 是**独立的分帧 job**：与地图扫描共用 tick 线程但字段完全分开，\"\n                + \"绝不动地图的分帧 / 版本 / 码表语义；本段只读缓存（不碰 MC）\");\n        return m;\n    }\n\n    // ---- query_column / query_blocks 的小工具 ----\n\n    /** 玩家 (x,y,z)；缺任一 ⇒ null（**不编 0**）。 */\n    private double[] colPlayerXYZ() {\n        Map<String, Object> st;\n        try {\n            st = Json.parseObject(bridge.playerStateJson());\n        } catch (RuntimeException e) {\n            return null;\n        }\n        Double x = dbl(st.get(\"x\")), y = dbl(st.get(\"y\")), z = dbl(st.get(\"z\"));\n        if (x == null || y == null || z == null) return null;\n        return new double[] { x.doubleValue(), y.doubleValue(), z.doubleValue() };\n    }\n\n    /** 该 id 算不算「空气」（口径写进回执头的 airIdNote）。 */\n    static boolean isAirId(String id) {\n        if (id == null) return false;\n        if (id.endsWith(\":air\") || id.endsWith(\":cave_air\") || id.endsWith(\":void_air\")) return true;\n        return \"air\".equals(id) || \"cave_air\".equals(id) || \"void_air\".equals(id);\n    }\n\n    /** 该 id 是不是「虚空空气」（客户端在**未加载**区块上会回它，而不是 null）。 */\n    static boolean isVoidAirId(String id) {\n        if (id == null) return false;\n        return id.endsWith(\":void_air\") || \"void_air\".equals(id);\n    }\n\n    /** 命中判定：filter 里任一 pattern 命中即算命中（口径见 {@link #FILTER_NOTE}）。 */\n    static boolean idMatches(String id, List<String> patterns) {\n        if (id == null || patterns == null) return false;\n        String full = id.toLowerCase(java.util.Locale.ROOT);\n        String path = full;\n        int c = full.indexOf(':');\n        if (c >= 0 && c + 1 < full.length()) path = full.substring(c + 1);\n        for (String raw : patterns) {\n            if (raw == null) continue;\n            String p = raw.trim().toLowerCase(java.util.Locale.ROOT);\n            if (p.isEmpty()) continue;\n            if (globMatch(p, full)) return true;\n            if (p.indexOf(':') < 0 && globMatch(p, path)) return true;\n        }\n        return false;\n    }\n\n    /** 极简 glob：* 通配任意（可空）子串；其余字符字面比较（**不是**正则）。两个串都应当已小写化。 */\n    static boolean globMatch(String pat, String text) {\n        int p = 0, t = 0, star = -1, mark = 0;\n        while (t < text.length()) {\n            if (p < pat.length() && pat.charAt(p) == '*') {\n                star = p++;\n                mark = t;\n            } else if (p < pat.length() && pat.charAt(p) == text.charAt(t)) {\n                p++;\n                t++;\n            } else if (star >= 0) {\n                p = star + 1;\n                t = ++mark;\n            } else {\n                return false;\n            }\n        }\n        while (p < pat.length() && pat.charAt(p) == '*') p++;\n        return p == pat.length();\n    }\n\n    /** 一条命中（坐标 + id + 与扫描原点的距离平方）。 */\n    private static final class BlockHit {\n        final int x, y, z;\n        final String id;\n        final double dist2;\n\n        BlockHit(int x, int y, int z, String id, double dist2) {\n            this.x = x;\n            this.y = y;\n            this.z = z;\n            this.id = id;\n            this.dist2 = dist2;\n        }\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/GuiResult.java": "package com.bandd.playtest.core;\n\nimport java.util.LinkedHashMap;\nimport java.util.Map;\n\n/**\n * **界面动作的诚实回执**（fail-loud，绝不静默）：成功 = {@code ok:true} + {@code data}；\n * 失败 = {@code ok:false} + 一个**明确错误码** + 人话 message。\n *\n * <p>为什么要单独一个类（而不是像 {@code mineLookingAt} 那样回 null）：本族五条动作的失败原因\n * **互不相同**且调用方要据此决策 —— 「没开界面」要先去开界面，「索引越界」是调用方的错，\n * 「手上没东西」要先给物品。全挤进一个 null 里，调用方只能猜。\n * 形状照 {@link CommandResult} 的先例：**适配层填，core 只负责透出**。\n *\n * <p>为什么错误码是常量而不是自由字符串：单测与外部脚本要按码分支（见 tests 的 GuiActionsTest），\n * 自由字符串一改就静默漂移。\n *\n * <p>Java 8 可用（本类无任何 MC / 加载器类型）。\n */\npublic final class GuiResult {\n    /** 本档压根没实现这条动作（{@link GameBridge} 的 default 落点）。 */\n    public static final String UNSUPPORTED = \"GUI_ACTIONS_UNSUPPORTED\";\n    /** 当前**没有打开任何容器界面**（连隐藏的玩家背包都没开）⇒ 读不到槽位。 */\n    public static final String NO_SCREEN_OPEN = \"NO_SCREEN_OPEN\";\n    /** 槽位下标越界（{@code slot < 0 || slot >= slotCount}）。 */\n    public static final String SLOT_OUT_OF_RANGE = \"SLOT_OUT_OF_RANGE\";\n    /** 控件下标越界（对应 {@code query_widgets} 列表）。 */\n    public static final String WIDGET_OUT_OF_RANGE = \"WIDGET_OUT_OF_RANGE\";\n    /** 该控件不可点（不可见 / 被禁用 / 这一项不是可点控件）。 */\n    public static final String WIDGET_NOT_CLICKABLE = \"WIDGET_NOT_CLICKABLE\";\n    /** 点击发出去了但控件没收（界面鼠标入口回 false）。 */\n    public static final String WIDGET_CLICK_REJECTED = \"WIDGET_CLICK_REJECTED\";\n    /** 没有玩家 / 不在世界里。 */\n    public static final String NOT_IN_WORLD = \"NOT_IN_WORLD\";\n    /** 目标方块超出触及距离（创造 5.0 / 生存 4.5）。 */\n    public static final String TARGET_TOO_FAR = \"TARGET_TOO_FAR\";\n    /** 手上没有东西（{@code place_block} 需要手持方块）。 */\n    public static final String NO_ITEM_IN_HAND = \"NO_ITEM_IN_HAND\";\n    /** 目标位置**不可放置**（已被占用 / 不是可替换方块）。 */\n    public static final String TARGET_NOT_PLACEABLE = \"TARGET_NOT_PLACEABLE\";\n    /** 右键没被游戏受理（{@code ActionResult} 不是 accepted）。 */\n    public static final String USE_FAILED = \"USE_FAILED\";\n    /** 放置没被游戏受理。 */\n    public static final String PLACE_FAILED = \"PLACE_FAILED\";\n\n    /** 动作是否成功。 */\n    public final boolean ok;\n    /** 失败码（成功时为 null）；取值见上面的常量。 */\n    public final String code;\n    /** 人话说明（成功时可为 null）。 */\n    public final String message;\n    /** 成功时的附加读数（失败时可为空表，**不为 null**）。 */\n    public final Map<String, Object> data;\n\n    private GuiResult(boolean ok, String code, String message, Map<String, Object> data) {\n        this.ok = ok;\n        this.code = code;\n        this.message = message;\n        this.data = data == null ? new LinkedHashMap<String, Object>() : data;\n    }\n\n    public static GuiResult ok() {\n        return new GuiResult(true, null, null, new LinkedHashMap<String, Object>());\n    }\n\n    public static GuiResult ok(Map<String, Object> data) {\n        return new GuiResult(true, null, null, data);\n    }\n\n    public static GuiResult fail(String code, String message) {\n        return new GuiResult(false, code, message, new LinkedHashMap<String, Object>());\n    }\n\n    /** 失败时也带上读数（诊断用）—— 仍回同一错误码。 */\n    public static GuiResult fail(String code, String message, Map<String, Object> data) {\n        return new GuiResult(false, code, message, data);\n    }\n\n    @Override\n    public String toString() {\n        return \"GuiResult{ok=\" + ok + \", code=\" + code + \", message=\" + message + \", data=\" + data + \"}\";\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/HttpApi.java": "package com.bandd.playtest.core;\n\nimport com.sun.net.httpserver.HttpExchange;\nimport com.sun.net.httpserver.HttpServer;\n\nimport java.io.IOException;\nimport java.io.OutputStream;\nimport java.net.InetSocketAddress;\nimport java.nio.charset.StandardCharsets;\nimport java.util.LinkedHashMap;\nimport java.util.Map;\nimport java.util.concurrent.Executors;\n\n/**\n * HTTP 面（loopback + token）。协议与仓库的 playtest_bridge 对齐：\n *   GET  /status          → 状态 + 能力自报\n *   POST /execute         → {id, action, params} → {id, status, message?, data?}；HTTP 恒 200\n *\n * **安全默认**：只绑 127.0.0.1；端口被占则自增（最多 +20）；除 /status 外一律要 token。\n * **线程纪律**：本类只在 HTTP 线程跑，**绝不碰 MC**；动作全部入队，由客户端 tick 执行。\n */\npublic final class HttpApi {\n    private final PlaytestCore core;\n    private HttpServer server;\n    private int port;\n\n    public HttpApi(PlaytestCore core) { this.core = core; }\n\n    public int start(int preferredPort) throws IOException {\n        IOException last = null;\n        for (int p = preferredPort; p < preferredPort + 20; p++) {\n            try {\n                server = HttpServer.create(new InetSocketAddress(\"127.0.0.1\", p), 0);\n                port = p;\n                break;\n            } catch (IOException e) {\n                last = e;\n            }\n        }\n        if (server == null) throw last == null ? new IOException(\"no port\") : last;\n        server.createContext(\"/status\", this::handleStatus);\n        server.createContext(\"/execute\", this::handleExecute);\n        server.setExecutor(Executors.newSingleThreadExecutor(r -> {\n            Thread t = new Thread(r, \"bandd-playtest-http\");\n            t.setDaemon(true);\n            return t;\n        }));\n        server.start();\n        core.setPort(port);\n        core.evidence().log(\"[QA] http listening on 127.0.0.1:\" + port);\n        return port;\n    }\n\n    public int port() { return port; }\n\n    public void stop() {\n        if (server != null) server.stop(0);\n    }\n\n    private void handleStatus(HttpExchange ex) throws IOException {\n        try {\n            respond(ex, 200, Json.of(core.status()));\n        } catch (Throwable t) {\n            respond(ex, 200, Json.of(PlaytestCore.error(\"STATUS_FAILED\", String.valueOf(t))));\n        }\n    }\n\n    private void handleExecute(HttpExchange ex) throws IOException {\n        Map<String, Object> out;\n        try {\n            String body = new String(readAll(ex), StandardCharsets.UTF_8);\n            Map<String, Object> req = Json.parseObject(body);\n            String id = Json.str(req, \"id\", \"\");\n            String token = Json.str(req, \"token\", header(ex, \"X-Bandd-Token\"));\n            if (core.token() != null && !core.token().isEmpty() && !core.token().equals(token)) {\n                out = PlaytestCore.error(\"UNAUTHORIZED\", \"token 不对或缺失（见 <gameDir>/config/bandd_playtest.json）\");\n            } else {\n                String action = Json.str(req, \"action\", \"\");\n                Map<String, Object> params = new LinkedHashMap<>();\n                Object pv = req.get(\"params\");\n                if (pv instanceof Map) {\n                    @SuppressWarnings(\"unchecked\")\n                    Map<String, Object> pm = (Map<String, Object>) pv;\n                    params = pm;\n                }\n                if (core.isOffThreadAction(action)) {\n                    // 只读文件 / 有界等待的动作（query_log）在 HTTP 线程直接跑：\n                    // 它不碰 MC 状态，且 waitMs 最长 60s —— 放 tick 线程会把游戏冻住。\n                    Map<String, Object> res = core.dispatch(action, params);\n                    res.put(\"id\", id);\n                    res.put(\"action\", action);\n                    out = res;\n                } else {\n                    // 入队 → 等 tick 线程执行（HTTP 线程不碰 MC）\n                    ActionQueue.Job job = core.queue().submit(action, params);\n                    long budget = core.timeoutMsFor(action);\n                    Map<String, Object> res = job.await(budget);\n                    if (res == null) {\n                        out = PlaytestCore.error(\"PLAYTEST_TIMEOUT\",\n                                (budget / 1000) + \"s 内未完成（长动作如 open_world 需更久；游戏卡住也会这样）\");\n                    } else {\n                        res.put(\"id\", id);\n                        res.put(\"action\", action);\n                        out = res;\n                    }\n                }\n            }\n        } catch (Throwable t) {\n            out = PlaytestCore.error(\"BAD_REQUEST\", String.valueOf(t));\n        }\n        respond(ex, 200, Json.of(out));\n    }\n\n    private static byte[] readAll(HttpExchange ex) throws IOException {\n        java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();\n        byte[] buf = new byte[4096];\n        int n;\n        while ((n = ex.getRequestBody().read(buf)) > 0) bos.write(buf, 0, n);\n        return bos.toByteArray();\n    }\n\n    private static String header(HttpExchange ex, String name) {\n        String v = ex.getRequestHeaders().getFirst(name);\n        return v == null ? \"\" : v;\n    }\n\n    private static void respond(HttpExchange ex, int code, String body) throws IOException {\n        byte[] b = body.getBytes(StandardCharsets.UTF_8);\n        ex.getResponseHeaders().add(\"Content-Type\", \"application/json; charset=utf-8\");\n        ex.sendResponseHeaders(code, b.length);\n        try (OutputStream os = ex.getResponseBody()) {\n            os.write(b);\n        }\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/Json.java": "package com.bandd.playtest.core;\n\nimport java.util.ArrayList;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/**\n * 极小 JSON：只做本模组需要的形状。手写、零第三方依赖\n * （仓库里的 driver 也是手写 JSON，不引 Gson —— 见 reference/generators/playtest-driver.ts）。\n */\npublic final class Json {\n    private Json() {}\n\n    public static String esc(String s) {\n        StringBuilder b = new StringBuilder();\n        for (int i = 0; i < s.length(); i++) {\n            char c = s.charAt(i);\n            switch (c) {\n                case '\"':  b.append(\"\\\\\\\"\"); break;\n                case '\\\\': b.append(\"\\\\\\\\\"); break;\n                case '\\n': b.append(\"\\\\n\"); break;\n                case '\\r': b.append(\"\\\\r\"); break;\n                case '\\t': b.append(\"\\\\t\"); break;\n                default:\n                    if (c < 0x20) b.append(String.format(\"\\\\u%04x\", (int) c));\n                    else b.append(c);\n            }\n        }\n        return b.toString();\n    }\n\n    public static String of(Object o) {\n        StringBuilder b = new StringBuilder();\n        write(b, o);\n        return b.toString();\n    }\n\n    @SuppressWarnings(\"unchecked\")\n    private static void write(StringBuilder b, Object o) {\n        if (o == null) { b.append(\"null\"); return; }\n        if (o instanceof String) { b.append('\"').append(esc((String) o)).append('\"'); return; }\n        if (o instanceof Boolean || o instanceof Number) { b.append(o.toString()); return; }\n        if (o instanceof Map) {\n            b.append('{');\n            boolean first = true;\n            for (Map.Entry<String, Object> e : ((Map<String, Object>) o).entrySet()) {\n                if (!first) b.append(',');\n                first = false;\n                b.append('\"').append(esc(e.getKey())).append(\"\\\":\");\n                write(b, e.getValue());\n            }\n            b.append('}');\n            return;\n        }\n        if (o instanceof Iterable) {\n            b.append('[');\n            boolean first = true;\n            for (Object v : (Iterable<Object>) o) {\n                if (!first) b.append(',');\n                first = false;\n                write(b, v);\n            }\n            b.append(']');\n            return;\n        }\n        b.append('\"').append(esc(String.valueOf(o))).append('\"');\n    }\n\n    public static Map<String, Object> parseObject(String s) {\n        Object v = parse(s);\n        if (v instanceof Map) {\n            @SuppressWarnings(\"unchecked\")\n            Map<String, Object> m = (Map<String, Object>) v;\n            return m;\n        }\n        return new LinkedHashMap<>();\n    }\n\n    public static Object parse(String s) {\n        P p = new P(s);\n        Object v = p.value();\n        return v;\n    }\n\n    public static String str(Map<String, Object> m, String k, String dflt) {\n        Object v = m.get(k);\n        return v == null ? dflt : String.valueOf(v);\n    }\n\n    /**\n     * **数值参数**取值：同时吃 JSON 数字与 JSON 字符串。\n     *\n     * <p>为什么必须有它（真机实证的静默缺陷）：{@code P.num()} 把裸数字解析成 {@code Double}，\n     * 而 {@link #str} 对 Double 走 {@code String.valueOf} ⇒ JSON 里的 {@code 1500} 变成\n     * {@code \"1500.0\"}；调用方 {@code Long.parseLong}/{@code Integer.parseInt} 当场\n     * NumberFormatException，被 catch 吞掉 ⇒ **静默落回默认值**。真机读数：数值 waitMs 被当成 0，\n     * 等待请求 70ms 就回 timedOut=true；写字符串 {@code \"1500\"} 才真等 ~1506ms。\n     *\n     * <p>本方法把数字规范成**无科学计数法、无多余 .0** 的十进制串\n     * （{@code 1500.0→\"1500\"}、{@code 1.5→\"1.5\"}），字符串原样返回。\n     * {@link #str} 的语义**不动**（action/command/key/world 这类字符串参数继续用 str）。\n     */\n    public static String num(Map<String, Object> m, String k, String dflt) {\n        Object v = m.get(k);\n        if (v == null) return dflt;\n        if (v instanceof Float || v instanceof Double) {\n            double d = ((Number) v).doubleValue();\n            if (Double.isNaN(d) || Double.isInfinite(d)) return String.valueOf(d);\n            return java.math.BigDecimal.valueOf(d).stripTrailingZeros().toPlainString();\n        }\n        if (v instanceof Number) return v.toString();\n        return String.valueOf(v);\n    }\n\n    public static boolean bool(Map<String, Object> m, String k, boolean dflt) {\n        Object v = m.get(k);\n        if (v instanceof Boolean) return (Boolean) v;\n        if (v instanceof String) return Boolean.parseBoolean((String) v);\n        return dflt;\n    }\n\n    private static final class P {\n        private final String s;\n        private int i;\n\n        P(String s) { this.s = s; }\n\n        void ws() { while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++; }\n\n        Object value() {\n            ws();\n            if (i >= s.length()) return null;\n            char c = s.charAt(i);\n            if (c == '{') return obj();\n            if (c == '[') return arr();\n            if (c == '\"') return str();\n            if (s.startsWith(\"true\", i)) { i += 4; return Boolean.TRUE; }\n            if (s.startsWith(\"false\", i)) { i += 5; return Boolean.FALSE; }\n            if (s.startsWith(\"null\", i)) { i += 4; return null; }\n            return num();\n        }\n\n        Map<String, Object> obj() {\n            Map<String, Object> m = new LinkedHashMap<>();\n            i++;\n            ws();\n            if (i < s.length() && s.charAt(i) == '}') { i++; return m; }\n            while (i < s.length()) {\n                ws();\n                String k = str();\n                ws();\n                i++; // ':'\n                m.put(k, value());\n                ws();\n                char c = s.charAt(i++);\n                if (c == '}') return m;\n            }\n            return m;\n        }\n\n        List<Object> arr() {\n            List<Object> l = new ArrayList<>();\n            i++;\n            ws();\n            if (i < s.length() && s.charAt(i) == ']') { i++; return l; }\n            while (i < s.length()) {\n                l.add(value());\n                ws();\n                char c = s.charAt(i++);\n                if (c == ']') return l;\n            }\n            return l;\n        }\n\n        String str() {\n            StringBuilder b = new StringBuilder();\n            i++;\n            while (i < s.length()) {\n                char c = s.charAt(i++);\n                if (c == '\"') return b.toString();\n                if (c == '\\\\') {\n                    char e = s.charAt(i++);\n                    switch (e) {\n                        case 'n': b.append('\\n'); break;\n                        case 't': b.append('\\t'); break;\n                        case 'r': b.append('\\r'); break;\n                        case 'b': b.append('\\b'); break;\n                        case 'f': b.append('\\f'); break;\n                        case 'u':\n                            b.append((char) Integer.parseInt(s.substring(i, i + 4), 16));\n                            i += 4;\n                            break;\n                        default: b.append(e);\n                    }\n                } else {\n                    b.append(c);\n                }\n            }\n            return b.toString();\n        }\n\n        Double num() {\n            int st = i;\n            while (i < s.length() && \"-+.eE0123456789\".indexOf(s.charAt(i)) >= 0) i++;\n            try { return Double.valueOf(s.substring(st, i)); } catch (NumberFormatException e) { return Double.valueOf(0); }\n        }\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/LogTail.java": "package com.bandd.playtest.core;\n\nimport java.io.IOException;\nimport java.io.RandomAccessFile;\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.util.ArrayList;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.regex.Pattern;\n\n/**\n * 日志文件的**游标增量读 + 有界等待**。\n *\n * 设计照仓库 MCP 工具 {@code inspect_runtime}：{@code sinceOffset} → {@code nextOffset}\n * ＋ 可选 {@code waitForPattern} ＋ {@code waitMs}（**封顶 60 秒**）。\n *\n * 三条纪律：\n * <ol>\n *   <li>**缺口明说**：文件被截断/轮换（{@code size < sinceOffset}）⇒ {@code rotated:true}\n *       ＋ {@code missed:true} ＋ {@code reason}（绝不静默）；</li>\n *   <li>**超时明说**：等到 {@code waitMs} 还没命中 ⇒ {@code matched:false} ＋ {@code timedOut:true}；</li>\n *   <li>**只回完整行**：末尾半行不返回、{@code nextOffset} 也不越过它（下次续读）。</li>\n * </ol>\n *\n * 纯 Java（core 不碰 MC）：日志路径由适配层给出的游戏目录推。\n * 返回值形状：{@code {lines, nextOffset, rotated, missed, matched, timedOut, reason?}}。\n */\npublic final class LogTail {\n    /** waitMs 的硬封顶（与仓库 inspect_runtime 一致）。 */\n    public static final long MAX_WAIT_MS = 60000L;\n    /** 单次最多读多少字节（防止一次把整份日志吞进内存）。 */\n    private static final int MAX_CHUNK = 8 * 1024 * 1024;\n\n    private LogTail() {}\n\n    /**\n     * 从 {@code sinceOffset} 起读**新增的完整行**；给了 {@code waitForPattern} 就在\n     * {@code waitMs} 内轮询等待命中（封顶 {@link #MAX_WAIT_MS}）。\n     *\n     * @throws IOException 文件读失败（由 core 翻成 LOG_READ_FAILED）\n     * @throws java.util.regex.PatternSyntaxException waitForPattern 不是合法正则（core 翻成 BAD_PATTERN）\n     */\n    public static Map<String, Object> read(Path logFile, long sinceOffset, String waitForPattern, long waitMs)\n            throws IOException {\n        Pattern pat = null;\n        if (waitForPattern != null && !waitForPattern.isEmpty()) {\n            pat = Pattern.compile(waitForPattern);\n        }\n        List<String> lines = new ArrayList<>();\n        boolean rotated = false;\n        boolean missed = false;\n        String reason = null;\n        long offset = Math.max(0L, sinceOffset);\n        long waitBudget = Math.max(0L, Math.min(waitMs, MAX_WAIT_MS));\n        long deadline = System.currentTimeMillis() + waitBudget;\n        boolean matched = false;\n        boolean timedOut = false;\n\n        while (true) {\n            long size = Files.exists(logFile) ? Files.size(logFile) : 0L;\n            if (size < offset) {\n                // 截断/轮换：缺口明说，从头再读\n                rotated = true;\n                missed = true;\n                reason = \"日志被截断或轮换（size=\" + size + \" < sinceOffset=\" + offset + \"）⇒ 已从 0 重读，中间段缺失\";\n                offset = 0L;\n            }\n            offset = readCompleteLines(logFile, offset, lines);\n            if (pat != null) {\n                for (String l : lines) {\n                    if (pat.matcher(l).find()) { matched = true; break; }\n                }\n            }\n            if (pat == null || matched) break;\n            long remain = deadline - System.currentTimeMillis();\n            if (remain <= 0) { timedOut = true; break; }\n            try {\n                Thread.sleep(Math.min(200L, remain));\n            } catch (InterruptedException ie) {\n                Thread.currentThread().interrupt();\n                timedOut = true;\n                break;\n            }\n        }\n        return result(lines, offset, rotated, missed, matched, timedOut, reason);\n    }\n\n    /**\n     * 读 {@code [offset, EOF)} 里的**完整行**并追加进 {@code sink}；\n     * 返回新的游标（末尾半行之前的位置）。没有完整行时游标不动。\n     */\n    private static long readCompleteLines(Path f, long offset, List<String> sink) throws IOException {\n        if (!Files.exists(f)) return offset;\n        long size = Files.size(f);\n        if (size <= offset) return offset;\n        int want = (int) Math.min(size - offset, (long) MAX_CHUNK);\n        byte[] buf = new byte[want];\n        int n;\n        try (RandomAccessFile raf = new RandomAccessFile(f.toFile(), \"r\")) {\n            raf.seek(offset);\n            n = raf.read(buf);\n        }\n        if (n <= 0) return offset;\n        int lastNl = -1;\n        for (int i = n - 1; i >= 0; i--) {\n            if (buf[i] == '\\n') { lastNl = i; break; }\n        }\n        if (lastNl < 0) return offset;   // 没有完整行：半行留给下次\n        String text = new String(buf, 0, lastNl + 1, StandardCharsets.UTF_8);\n        String[] parts = text.split(\"\\n\", -1);\n        for (int i = 0; i < parts.length - 1; i++) {   // 末尾那个空串是最后一个 '\\n' 造成的\n            String line = parts[i];\n            if (line.endsWith(\"\\r\")) line = line.substring(0, line.length() - 1);\n            sink.add(line);\n        }\n        return offset + lastNl + 1;\n    }\n\n    private static Map<String, Object> result(List<String> lines, long nextOffset, boolean rotated, boolean missed,\n                                              boolean matched, boolean timedOut, String reason) {\n        Map<String, Object> m = new LinkedHashMap<>();\n        m.put(\"lines\", lines);\n        m.put(\"nextOffset\", nextOffset);\n        m.put(\"rotated\", rotated);\n        m.put(\"missed\", missed);\n        m.put(\"matched\", matched);\n        m.put(\"timedOut\", timedOut);\n        if (reason != null) m.put(\"reason\", reason);\n        return m;\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/MiningTracker.java": "package com.bandd.playtest.core;\n\nimport java.util.LinkedHashMap;\nimport java.util.Map;\n\n/**\n * 挖矿会话的**跨 tick 状态机**（core 面，可离线单测；适配层只喂「目标格现在是不是空气」）。\n *\n * <p><b>为什么必须有它</b>（2026-11-11 真机挖出的致命缺陷）：vanilla 的\n * {@code MultiPlayerGameMode.continueDestroyBlock}（mojmap）/ Yarn\n * {@code ClientPlayerInteractionManager.updateBlockBreakingProgress}（1.14.4 档里叫\n * {@code method_2902}）/ MCP {@code PlayerControllerMP.onPlayerDamageBlock} 在\n * <b>「延迟 / 冷却未到」的分支里也 return true</b>：\n * <pre>\n *   // javap -c net.minecraft.client.multiplayer.MultiPlayerGameMode#continueDestroyBlock\n *   //   （jar = forge-1.20.1-47.4.10_mapped_parchment_2023.09.03-1.20.1）\n *    4: getfield destroyDelay:I ; ifle 23\n *   11: ... destroyDelay-- ; 21: iconst_1 ; 22: ireturn      &lt;-- 方块还在也返回 true\n *   // fabric 1.21.11 yarn 件同形：blockBreakingCooldown &gt; 0 分支 iconst_1 / ireturn\n * </pre>\n * ⇒ 把返回值当「已挖穿」会在**第一 tick** 就把目标清空，破坏进度永远攒不满\n * （真机铁证：生存模式 {@code mine} 40 次 / 22 秒、{@code press attack} 按住 12 秒，\n * 方块纹丝不动；而 {@code bot_break} 能挖穿 ⇒ 世界与服务端正常）。\n *\n * <p><b>唯一完成判据 = 目标格变空气</b>（适配层用 {@code getBlockState(pos).isAir()} 喂进来）；\n * 另有**超时兜底**（fail-loud，回 {@link #STOP_TIMEOUT}，不无限空转）。\n * {@code continueReturnedTrue} 参数**只作诊断记账**（它出现的次数本身说明「延迟分支」走了几 tick），\n * <b>绝不据此收工</b> —— 这就是与旧写法（{@code if (continueDestroyBlock(...)) mining = null;}）的唯一区别。\n *\n * <p>Java 8 可用（不碰任何 net.minecraft.* / 加载器类型）。\n */\npublic final class MiningTracker {\n\n    /** 收工原因：目标格变空气（挖穿 / 被别人换掉）。 */\n    public static final String STOP_BROKEN = \"MINE_BROKEN\";\n    /** 收工原因：超过 maxTicks 仍未挖穿（fail-loud，不假装成功、不无限挂着）。 */\n    public static final String STOP_TIMEOUT = \"MINE_TIMEOUT\";\n\n    /** 默认超时：600 tick = 30s @20tps（徒手挖黑曜石都够；超了明确收工）。 */\n    public static final int DEFAULT_MAX_TICKS = 600;\n\n    /** 进度自报的人话（原样进 mine 回执的 progressNote）。 */\n    public static final String NOTE =\n            \"mine 是**跨 tick** 的：本回执只代表「目标已锁定并开始破坏」，不代表已经挖穿。\"\n            + \"progress.miningTicks = 该目标已推进的 tick 数；progress.targetStillThere=false / \"\n            + \"progress.lastStopReason=\" + STOP_BROKEN + \" 才表示真挖穿；\" + STOP_TIMEOUT\n            + \" = 超时收工（fail-loud，没挖穿）。真值判据请用 query_column / query_blocks 读该格。\";\n\n    private final int maxTicks;\n    private boolean hasTarget;\n    private int tx, ty, tz;\n    private int ticks;\n    private long startedAtMs = -1L;\n    private long lastTickAtMs = -1L;\n    private int minedCount;\n    private String lastMined;\n    private String lastStopReason;\n    private String lastStopTarget;\n    private int stops;\n    private String targetBlockId;\n    private int continueTrueCount;\n\n    public MiningTracker() {\n        this(DEFAULT_MAX_TICKS);\n    }\n\n    public MiningTracker(int maxTicks) {\n        this.maxTicks = maxTicks <= 0 ? DEFAULT_MAX_TICKS : maxTicks;\n    }\n\n    /**\n     * 锁定 / 更换目标。\n     *\n     * @return {@code true} = 这是**新目标**（调用方应发一次 startDestroyBlock / attackBlock）；\n     *         {@code false} = 同一目标（**绝不能**重发 START —— MC 的 START 会把破坏进度清零，\n     *         调用方按周期反复调 mine 时就会变成「非常快速的单次点击」，永远挖不动）。\n     */\n    public boolean aim(int x, int y, int z, String blockId, long nowMs) {\n        if (hasTarget && x == tx && y == ty && z == tz) return false;\n        hasTarget = true;\n        tx = x; ty = y; tz = z;\n        ticks = 0;\n        startedAtMs = nowMs;\n        lastTickAtMs = nowMs;\n        targetBlockId = blockId;\n        return true;\n    }\n\n    public boolean hasTarget() { return hasTarget; }\n    public int targetX() { return tx; }\n    public int targetY() { return ty; }\n    public int targetZ() { return tz; }\n    public int ticks() { return ticks; }\n    public int maxTicks() { return maxTicks; }\n    public int minedCount() { return minedCount; }\n    public String lastMined() { return lastMined; }\n    public String lastStopReason() { return lastStopReason; }\n    public String targetBlockId() { return targetBlockId; }\n\n    /** 收工 / 主动放弃（不记 minedCount）。 */\n    public void clear() {\n        hasTarget = false;\n        ticks = 0;\n        startedAtMs = -1L;\n    }\n\n    /**\n     * **本 tick 是否继续挖**（在调用宿主的 continue 之前调）。\n     *\n     * <p>判据**只有两条**：目标格变空气 ⇒ {@link #STOP_BROKEN}；超过 maxTicks ⇒ {@link #STOP_TIMEOUT}。\n     * 宿主的 continue 返回值**不参与**这个决定（见 {@link #noteContinueReturned}）。\n     *\n     * @param targetIsAir 宿主读到的「目标格现在是不是空气」（**唯一完成判据**）\n     * @param nowMs       宿主时钟（毫秒，只用于 elapsedMs 自报）\n     * @return {@code null} = 继续挖；否则 = 收工原因码\n     */\n    public String beginTick(boolean targetIsAir, long nowMs) {\n        if (!hasTarget) return null;\n        lastTickAtMs = nowMs;\n        if (targetIsAir) {\n            stop(STOP_BROKEN);\n            return STOP_BROKEN;\n        }\n        if (ticks >= maxTicks) {\n            stop(STOP_TIMEOUT);\n            return STOP_TIMEOUT;\n        }\n        ticks++;\n        return null;\n    }\n\n    /**\n     * 记录宿主 {@code continueDestroyBlock} / {@code updateBlockBreakingProgress} /\n     * {@code onPlayerDamageBlock} 的返回值 —— **只作诊断记账，绝不据此收工**\n     * （vanilla 在 destroyDelay / blockBreakingCooldown 未到的分支里也回 true，javap -c 实证）。\n     */\n    public void noteContinueReturned(boolean returnedTrue) {\n        if (returnedTrue) continueTrueCount++;\n    }\n\n    private void stop(String reason) {\n        if (STOP_BROKEN.equals(reason)) minedCount++;\n        lastMined = xy(tx, ty, tz);\n        lastStopReason = reason;\n        lastStopTarget = xy(tx, ty, tz);\n        stops++;\n        hasTarget = false;\n        ticks = 0;\n    }\n\n    /** 进度自报（只读内存字段，**不碰 MC** ⇒ HTTP 线程 / 任意线程都安全）。 */\n    public Map<String, Object> status() {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"target\", hasTarget ? xy(tx, ty, tz) : null);\n        m.put(\"hasTarget\", Boolean.valueOf(hasTarget));\n        m.put(\"targetBlock\", targetBlockId);\n        m.put(\"targetStillThere\", Boolean.valueOf(hasTarget));\n        m.put(\"miningTicks\", Integer.valueOf(ticks));\n        m.put(\"maxTicks\", Integer.valueOf(maxTicks));\n        m.put(\"elapsedMs\", (hasTarget && startedAtMs >= 0)\n                ? Long.valueOf(Math.max(0L, lastTickAtMs - startedAtMs)) : null);\n        m.put(\"minedCount\", Integer.valueOf(minedCount));\n        m.put(\"lastMined\", lastMined);\n        m.put(\"lastStopReason\", lastStopReason);\n        m.put(\"lastStopTarget\", lastStopTarget);\n        m.put(\"stops\", Integer.valueOf(stops));\n        m.put(\"continueReturnedTrueCount\", Integer.valueOf(continueTrueCount));\n        m.put(\"continueReturnedTrueNote\",\n                \"continueDestroyBlock / updateBlockBreakingProgress / onPlayerDamageBlock 返回 true 的 tick 数。\"\n                + \"**这个数 > 0 且 targetStillThere 仍为 true 是正常的**：vanilla 在 destroyDelay / \"\n                + \"blockBreakingCooldown 未到的分支里也回 true（javap -c 实证）⇒ 绝不能拿它当「已挖穿」。\");\n        m.put(\"note\", NOTE);\n        return m;\n    }\n\n    private static String xy(int x, int y, int z) {\n        return x + \",\" + y + \",\" + z;\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/PlanInterpreter.java": "package com.bandd.playtest.core;\n\nimport java.io.IOException;\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.util.ArrayList;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/**\n * plan.txt 热载解释器（仓库「游玩自测作业规则」六条铁律的 1/2 条）。\n *\n * 铁律 1（常驻会话）：本解释器是长驻的，守候 evidenceDir/plan.txt；\n *   文件一变就在同一进程内开新一轮，不重启游戏。动作/断言/坐标/等待时长一律改 plan（热载）。\n * 铁律 2（fail-closed + 证据三件）：每轮必落\n *   - state.json（轮末快照）\n *   - exit-code.txt（0 绿 / 1 红）\n *   - qa.log（只含本轮 的 [QA] 段 —— 轮首截断）\n *   外加 rounds.jsonl（每轮一行，含 ok）。\n *\n * DSL（行式；井号起注释；空行忽略）：\n *   wait &lt;ticks&gt;                 等 N 个客户端 tick\n *   press &lt;key&gt; &lt;down|up&gt;      按/松一个逻辑键（受仲裁与「只释放自己按过的键」约束）\n *   hold &lt;key&gt; &lt;ticks&gt;         按住 N tick 后自动松开（记账式）\n *   release                      释放 AI 自己按过的全部键\n *   cmd &lt;rest&gt;                 以玩家身份发命令（禁列 kill/tnt/fill 会被拒 =&gt; 本轮判红）\n *   shot                         截图\n *   mark &lt;name&gt;                记一个标记进 state\n *   assert &lt;field&gt; &lt;op&gt; &lt;value&gt; 类型化后置条件；不成立 =&gt; 本轮判红并停止\n *   stop                         正常结束本轮（绿）\n *\n * field：player.present | player.onGround（布尔）、player.health | pos.x | pos.y | pos.z（数值）、\n *        player.name | screen（字符串，字面 null 表示无界面）\n * op：== != &gt; &lt; &gt;= &lt;=\n */\npublic final class PlanInterpreter {\n    public enum Kind { WAIT, PRESS, HOLD, RELEASE, CMD, SHOT, MARK, ASSERT, STOP,\n                        BOT_SPAWN, BOT_MOVE, BOT_FOLLOW, BOT_DESPAWN }\n\n    public static final class Step {\n        public final Kind kind;\n        public final List<String> args;\n        public final int line;\n        Step(Kind kind, List<String> args, int line) { this.kind = kind; this.args = args; this.line = line; }\n    }\n\n    private final GameBridge bridge;\n    private final EvidenceWriter evidence;\n    private final Path planFile;\n    private final List<Step> steps = new ArrayList<>();\n    private int index = 0;\n    private int waitTicks = 0;\n    private final Map<String, String> holds = new LinkedHashMap<>();\n    private final List<String> marks = new ArrayList<>();\n    private int round = 0;\n    private boolean running = false;\n    private String loadedHash = \"\";\n    private String lastResult = \"none\";\n    private int lastSteps = 0;\n    private int planCheckCounter = 0;\n\n    public PlanInterpreter(GameBridge bridge, EvidenceWriter evidence, Path planFile) {\n        this.bridge = bridge;\n        this.evidence = evidence;\n        this.planFile = planFile;\n    }\n\n    public int round() { return round; }\n    public boolean running() { return running; }\n    public String lastResult() { return lastResult; }\n\n    public Map<String, Object> status() {\n        Map<String, Object> m = new LinkedHashMap<>();\n        m.put(\"round\", round);\n        m.put(\"running\", running);\n        m.put(\"stepIndex\", index);\n        m.put(\"stepCount\", steps.size());\n        m.put(\"lastResult\", lastResult);\n        m.put(\"lastSteps\", lastSteps);\n        m.put(\"planFile\", planFile.toString());\n        m.put(\"marks\", new ArrayList<>(marks));\n        return m;\n    }\n\n    /** 客户端 tick 调用（MC 线程）。 */\n    public void tick(PlaytestCore core) {\n        // 每 5 个 tick 看一次 plan.txt（按 tick 计，不依赖墙钟 ⇒ 可确定性测试）\n        if (planCheckCounter++ % 5 == 0) maybeReload(core);\n        if (!running) return;\n        if (waitTicks > 0) {\n            waitTicks--;\n            if (waitTicks == 0 && !holds.isEmpty()) releaseHeld(core, \"hold 到期\");\n            return;\n        }\n        if (index >= steps.size()) { endRound(core, true, \"plan exhausted\"); return; }\n        Step s = steps.get(index);\n        try {\n            if (!exec(core, s)) { endRound(core, false, \"step \" + s.line + \" failed: \" + s.kind); return; }\n        } catch (Throwable t) {\n            evidence.log(\"[QA] step \" + s.line + \" threw: \" + t);\n            endRound(core, false, \"exception at line \" + s.line);\n            return;\n        }\n        index++;\n    }\n\n    /** 文件变了就开新一轮（同一进程内）。 */\n    private void maybeReload(PlaytestCore core) {\n        String text;\n        try {\n            if (!Files.exists(planFile)) return;\n            text = new String(Files.readAllBytes(planFile), StandardCharsets.UTF_8);\n        } catch (IOException e) {\n            return;\n        }\n        String hash = Integer.toHexString(text.hashCode()) + \":\" + text.length();\n        if (hash.equals(loadedHash)) return;\n        loadedHash = hash;\n        steps.clear();\n        String[] lines = text.split(\"\\n\");\n        for (int i = 0; i < lines.length; i++) {\n            Step s = parse(lines[i], i + 1);\n            if (s != null) steps.add(s);\n        }\n        if (running) {\n            evidence.log(\"[QA] plan.txt 变更 => 中断上一轮并开新一轮（同一进程，未重启游戏）\");\n            releaseHeld(core, \"plan reload\");\n        }\n        startRound(core);\n    }\n\n    private Step parse(String raw, int lineNo) {\n        String line = raw;\n        int h = line.indexOf('#');\n        if (h >= 0) line = line.substring(0, h);\n        line = line.trim();\n        if (line.isEmpty()) return null;\n        String[] tok = line.split(\"\\\\s+\", 2);\n        String head = tok[0].toLowerCase();\n        String rest = tok.length > 1 ? tok[1].trim() : \"\";\n        List<String> args = new ArrayList<>();\n        if (!rest.isEmpty()) for (String a : rest.split(\"\\\\s+\")) args.add(a);\n        switch (head) {\n            case \"wait\":    return new Step(Kind.WAIT, args, lineNo);\n            case \"press\":   return new Step(Kind.PRESS, args, lineNo);\n            case \"hold\":    return new Step(Kind.HOLD, args, lineNo);\n            case \"release\": return new Step(Kind.RELEASE, args, lineNo);\n            case \"cmd\":     return new Step(Kind.CMD, java.util.Collections.singletonList(rest), lineNo);\n            case \"shot\":    return new Step(Kind.SHOT, args, lineNo);\n            case \"mark\":    return new Step(Kind.MARK, args, lineNo);\n            case \"assert\":  return new Step(Kind.ASSERT, args, lineNo);\n            case \"stop\":    return new Step(Kind.STOP, args, lineNo);\n            case \"bot_spawn\":   return new Step(Kind.BOT_SPAWN, args, lineNo);\n            case \"bot_move\":    return new Step(Kind.BOT_MOVE, args, lineNo);\n            case \"bot_follow\":  return new Step(Kind.BOT_FOLLOW, args, lineNo);\n            case \"bot_despawn\": return new Step(Kind.BOT_DESPAWN, args, lineNo);\n            default:\n                evidence.log(\"[QA] plan.txt:\" + lineNo + \" 未知指令「\" + head + \"」=> 本轮判红（不静默跳过）\");\n                return new Step(Kind.ASSERT, java.util.Arrays.asList(\"__unknown__\", \"==\", head), lineNo);\n        }\n    }\n\n    private void startRound(PlaytestCore core) {\n        round++;\n        index = 0;\n        waitTicks = 0;\n        holds.clear();\n        marks.clear();\n        running = true;\n        evidence.truncateQaLog();\n        evidence.log(\"[QA] ROUND \" + round + \" START steps=\" + steps.size() + \" plan=\" + planFile);\n        evidence.state(Json.of(core.status()));\n    }\n\n    private void endRound(PlaytestCore core, boolean ok, String reason) {\n        running = false;\n        lastResult = ok ? \"ok\" : \"failed\";\n        lastSteps = index;\n        releaseHeld(core, \"round end\");\n        evidence.exitCode(ok ? 0 : 1);\n        evidence.log(\"[QA] ROUND \" + round + \" DONE ok=\" + ok + \" steps=\" + index + \"/\" + steps.size() + \" reason=\" + reason);\n        Map<String, Object> line = new LinkedHashMap<>();\n        line.put(\"round\", round);\n        line.put(\"ok\", ok);\n        line.put(\"steps\", index);\n        line.put(\"total\", steps.size());\n        line.put(\"reason\", reason);\n        line.put(\"at\", java.time.Instant.now().toString());\n        evidence.appendRounds(Json.of(line));\n        evidence.state(Json.of(core.status()));\n    }\n\n    private void releaseHeld(PlaytestCore core, String why) {\n        for (String k : new ArrayList<>(holds.keySet())) {\n            core.dispatch(\"press\", params(\"key\", k, \"down\", Boolean.FALSE));\n        }\n        holds.clear();\n        core.dispatch(\"release_all\", new LinkedHashMap<>());\n        evidence.log(\"[QA] 释放 AI 按过的键（\" + why + \"）\");\n    }\n\n    private boolean exec(PlaytestCore core, Step s) {\n        switch (s.kind) {\n            case WAIT: {\n                if (s.args.isEmpty()) return false;\n                waitTicks = Integer.parseInt(s.args.get(0));\n                return true;\n            }\n            case PRESS: {\n                if (s.args.size() < 2) return false;\n                boolean down = !\"up\".equalsIgnoreCase(s.args.get(1));\n                Map<String, Object> r = core.dispatch(\"press\", params(\"key\", s.args.get(0), \"down\", down));\n                boolean ok = \"ok\".equals(r.get(\"status\"));\n                if (!ok) evidence.log(\"[QA] press 被拒: \" + r.get(\"code\") + \" \" + r.get(\"message\"));\n                return ok;\n            }\n            case HOLD: {\n                if (s.args.size() < 2) return false;\n                String key = s.args.get(0);\n                Map<String, Object> r = core.dispatch(\"press\", params(\"key\", key, \"down\", Boolean.TRUE));\n                if (!\"ok\".equals(r.get(\"status\"))) { evidence.log(\"[QA] hold 被拒: \" + r.get(\"code\")); return false; }\n                holds.put(key, s.args.get(1));\n                waitTicks = Integer.parseInt(s.args.get(1));\n                return true;\n            }\n            case RELEASE:\n                releaseHeld(core, \"plan 显式 release\");\n                return true;\n            case CMD: {\n                Map<String, Object> r = core.dispatch(\"chat_command\", params(\"command\", s.args.get(0)));\n                boolean ok = \"ok\".equals(r.get(\"status\"));\n                if (!ok) evidence.log(\"[QA] cmd 被拒: \" + r.get(\"code\") + \" \" + r.get(\"message\"));\n                return ok;\n            }\n            case SHOT: {\n                Map<String, Object> r = core.dispatch(\"screenshot\", new LinkedHashMap<>());\n                return \"ok\".equals(r.get(\"status\"));\n            }\n            case MARK: {\n                if (s.args.isEmpty()) return false;\n                marks.add(s.args.get(0));\n                evidence.log(\"[QA] mark \" + s.args.get(0));\n                return true;\n            }\n            case ASSERT: {\n                // 两种写法都收：三段式 <field> <op> <value>，以及两段式 <field> <value>（隐含 ==）\n                if (s.args.size() < 2) return false;\n                String field = s.args.get(0);\n                String op;\n                String want;\n                if (s.args.size() >= 3) {\n                    op = s.args.get(1);\n                    want = s.args.get(2);\n                } else {\n                    op = \"==\";\n                    want = s.args.get(1);\n                }\n                boolean ok = evalAssert(field, op, want);\n                evidence.log(\"[QA] assert \" + field + \" \" + op + \" \" + want + \" -> \" + ok);\n                return ok;\n            }\n            case BOT_SPAWN: {\n                Map<String, Object> q = params(\"name\", s.args.isEmpty() ? \"AI\" : s.args.get(0));\n                if (s.args.size() > 1) q.put(\"distance\", s.args.get(1));\n                return \"ok\".equals(core.dispatch(\"spawn_bot\", q).get(\"status\"));\n            }\n            case BOT_MOVE: {\n                Map<String, Object> q = new LinkedHashMap<>();\n                if (s.args.size() >= 3) {\n                    q.put(\"x\", s.args.get(0));\n                    q.put(\"y\", s.args.get(1));\n                    q.put(\"z\", s.args.get(2));\n                } else {\n                    q.put(\"mode\", \"front\");\n                    if (!s.args.isEmpty()) q.put(\"distance\", s.args.get(0));\n                }\n                return \"ok\".equals(core.dispatch(\"bot_move\", q).get(\"status\"));\n            }\n            case BOT_FOLLOW:\n                return \"ok\".equals(core.dispatch(\"bot_follow\",\n                        params(\"on\", s.args.isEmpty() || !\"off\".equalsIgnoreCase(s.args.get(0)))).get(\"status\"));\n            case BOT_DESPAWN:\n                return \"ok\".equals(core.dispatch(\"bot_despawn\", new LinkedHashMap<>()).get(\"status\"));\n            case STOP:\n                endRound(core, true, \"stop\");\n                return true;\n            default:\n                return false;\n        }\n    }\n\n    /** 类型化后置条件求值（唯一一处读状态的地方）。 */\n    private boolean evalAssert(String field, String op, String want) {\n        if (\"__unknown__\".equals(field)) return false;\n        Map<String, Object> st = Json.parseObject(bridge.playerStateJson());\n        Object have;\n        switch (field) {\n            case \"player.present\":  have = st.get(\"present\"); break;\n            case \"player.onGround\": have = st.get(\"onGround\"); break;\n            case \"player.health\":   have = st.get(\"health\"); break;\n            case \"player.name\":     have = st.get(\"name\"); break;\n            case \"screen\":          have = bridge.screenName(); break;\n            case \"pos.x\":           have = st.get(\"x\"); break;\n            case \"pos.y\":           have = st.get(\"y\"); break;\n            case \"pos.z\":           have = st.get(\"z\"); break;\n            default:\n                evidence.log(\"[QA] assert 未知字段「\" + field + \"」=> 判红（不静默通过）\");\n                return false;\n        }\n        if (have == null) return \"null\".equals(want);\n        if (have instanceof Boolean || have instanceof Number) {\n            double h = (have instanceof Boolean) ? (((Boolean) have) ? 1 : 0) : ((Number) have).doubleValue();\n            double w;\n            if (\"true\".equalsIgnoreCase(want)) w = 1;\n            else if (\"false\".equalsIgnoreCase(want)) w = 0;\n            else {\n                try { w = Double.parseDouble(want); } catch (NumberFormatException e) { return false; }\n            }\n            switch (op) {\n                case \"==\": return h == w;\n                case \"!=\": return h != w;\n                case \">\":  return h > w;\n                case \"<\":  return h < w;\n                case \">=\": return h >= w;\n                case \"<=\": return h <= w;\n                default:   return false;\n            }\n        }\n        String h = String.valueOf(have);\n        switch (op) {\n            case \"==\": return h.equals(want);\n            case \"!=\": return !h.equals(want);\n            default:   return false;\n        }\n    }\n\n    private static Map<String, Object> params(Object... kv) {\n        Map<String, Object> m = new LinkedHashMap<>();\n        for (int i = 0; i < kv.length; i += 2) m.put(String.valueOf(kv[i]), kv[i + 1]);\n        return m;\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/PlaytestCore.java": "package com.bandd.playtest.core;\n\nimport java.nio.file.Path;\nimport java.nio.file.Paths;\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/**\n * 版本无关的核心：协议 / 动作派发 / 仲裁 / 证据。\n * **不许出现任何 net.minecraft.* 或加载器类型** —— 逐档差异全在 adapter（GameBridge 的实现）。\n */\npublic final class PlaytestCore {\n    /** 仓库口径的禁列（意图菜单禁 kill/tnt/fill）—— 这里对命令级动作也拦一道。 */\n    private static final List<String> FORBIDDEN_PREFIX = Arrays.asList(\"kill\", \"tnt\", \"fill\");\n\n    /** 本档没实现读背包面时的错误码（{@code GameBridge#inventoryJson} 回 null）。 */\n    public static final String INVENTORY_UNSUPPORTED = \"INVENTORY_UNSUPPORTED\";\n    /**\n     * {@code idKind} 的口径说明（**原样进回执**）。为什么必须写死这一句：\n     * 桥路线（forge 1.7.10–1.12.2）的 {@code query_inventory} 给的是 **unlocalizedName**（{@code item.stone}），\n     * 而驱动路线给的是**现代注册名**（{@code minecraft:stone}）—— 形状对齐、**口径不同源**，\n     * 调用方拿这两串直接比会永远不等 ⇒ 必须在回执里当面说清。\n     */\n    private static final String ID_KIND_NOTE =\n            \"idKind = itemId 的口径。本档走现代注册名 registryName（如 minecraft:stone）；\"\n                    + \"桥路线（forge 1.7.10–1.12.2）同类字段给的是 unlocalizedName（如 item.stone）\"\n                    + \" —— 两个口径**逐字不同源**，别拿同一个串直接比\";\n\n    /** [T22] gameMode 的口径说明（原样进 query_player_state 的 player 段）。 */\n    private static final String GAMEMODE_NOTE =\n            \"gameMode = 原版游戏模式枚举名（survival / creative / adventure / spectator）；\"\n            + \"只报**本档当场读到**的值，读不到一律 null（不编）。\";\n\n    /** 化身（第二个角色）= 玩家形状的 mannequin 实体（1.21.9+ 起存在；本仓 primer 一手证实）。 */\n    public static final String BOT_TAG = \"bandd_bot\";\n    /** 收回化身的**逐字**命令（禁列 kill 的唯一例外，不接受任何其它形态）。 */\n    public static final String BOT_KILL = \"kill @e[tag=\" + BOT_TAG + \",limit=1]\";\n    private static final String BOT_SELECTOR = \"@e[tag=\" + BOT_TAG + \",limit=1]\";\n\n    private final GameBridge bridge;\n    private final Arbitration arb = new Arbitration();\n    private final ActionQueue queue = new ActionQueue();\n    private final EvidenceWriter evidence;\n    private final PlanInterpreter plan;\n    private final String token;\n    /**\n     * **（半）实时游戏状态器**：地图 + 状态快照，持续刷新并缓存（查询只读缓存）。\n     * 全部旋钮在 {@link StateConfig}（T3 的设置页面接这一个类）。\n     */\n    private final GameStateService state;\n    /**\n     * **那一个可手改的配置文件**（fabric-1.21.11 / neoforge-1.20.1 两档接；其余 54 档为 {@code null}）。\n     * 接了 ⇒ 状态器的旋钮从文件读、设置页面写回同一个文件；没接 ⇒ 仍用内存默认值，\n     * 但 {@code /status} 的 {@code settings} 段**照样**给出文件绝对路径 + 全部键名与默认值 + 手改提示。\n     */\n    private final Settings settings;\n    // ---- 化身（第二个角色）状态 ----\n    private boolean botSpawned = false;\n    private boolean botFollow = false;\n    private String botName = \"AI\";\n    private String botKind = \"none\";\n    private final List<String> chatHistory = new ArrayList<>();\n    private int botFollowTick = 0;\n    private final long started = System.currentTimeMillis();\n    private volatile int port = 0;\n    private int requests = 0;\n\n    /** 老入口：**不接管配置文件**。54 个老档一行不改，行为与从前逐字一致。 */\n    public PlaytestCore(GameBridge bridge, Path evidenceDir, String token) {\n        this(bridge, evidenceDir, token, null);\n    }\n\n    /**\n     * 新入口：接管那一个配置文件 —— 状态器的旋钮从文件读（缺键回默认），设置页面写回**同一个文件**。\n     *\n     * <p>为什么是**加**一个构造器而不是改老的：core 与 54 个老档共用同一份源码，\n     * 改老签名会让那 54 档当场编译不过。\n     */\n    public PlaytestCore(GameBridge bridge, Path evidenceDir, String token, Settings settings) {\n        this.bridge = bridge;\n        this.evidence = new EvidenceWriter(evidenceDir);\n        this.plan = new PlanInterpreter(bridge, this.evidence, evidenceDir.resolve(\"plan.txt\"));\n        this.token = token;\n        this.settings = settings;\n        // 状态器与设置页面**共用同一个 StateConfig 实例** ⇒ 页面上改一个值，\n        // 状态器下一轮 startScan 就用新值（不需要任何「同步」代码）。见 GameStateService#config()。\n        this.state = new GameStateService(bridge, settings == null ? new StateConfig() : settings.config());\n        if (settings != null) settings.config().sanitize();\n        logSettings();\n    }\n\n    public GameBridge bridge() { return bridge; }\n\n    public Arbitration arbitration() { return arb; }\n\n    public ActionQueue queue() { return queue; }\n\n    public EvidenceWriter evidence() { return evidence; }\n\n    public PlanInterpreter plan() { return plan; }\n\n    /** 状态器（T3 设置页面走 {@code core.state().config()} 读写旋钮）。 */\n    public GameStateService state() { return state; }\n\n    /**\n     * 那一个可手改的配置文件；本档没接就是 {@code null}（老档）。\n     * 设置页面：{@code core.settings().config()} 读写旋钮，{@code core.settings().save()} 落盘。\n     */\n    public Settings settings() { return settings; }\n\n    /**\n     * **服务端线程**每 tick 调用（由入口挂 ServerTickEvent.Post）。\n     * 为什么单独一个入口：化身是服务端对象，服务端实体的操作必须在**服务端线程**做；\n     * 从客户端 tick 线程去碰它属于跨线程访问（捡拾曾因此静默失效）。\n     */\n    public void onServerTick() {\n        bridge.tickBot();\n    }\n\n    /**\n     * 化身的\"跟随\"：每 20 tick 把 mannequin 放到玩家侧后方 1.5 格。\n     * 说明：化身是 **mannequin**（玩家形状、无连接玩家），移动靠服务端 /tp —— 不是真玩家物理。\n     */\n    private void botFollowStep() {\n        if (!botSpawned || !botFollow) return;\n        if (++botFollowTick % 20 != 0) return;\n        Map<String, Object> st = Json.parseObject(bridge.playerStateJson());\n        Object x = st.get(\"x\"), y = st.get(\"y\"), z = st.get(\"z\");\n        if (!(x instanceof Number) || !(y instanceof Number) || !(z instanceof Number)) return;\n        double bx = ((Number) x).doubleValue() + 1.5;\n        double by = ((Number) y).doubleValue();\n        double bz = ((Number) z).doubleValue() + 1.5;\n        bridge.moveBotTo(bx, by, bz);\n    }\n\n    /** 取 x/y/z 三个数字参数；缺任一返回 null。 */\n    private static double[] xyz(Map<String, Object> p) {\n        String x = Json.num(p, \"x\", \"\"), y = Json.num(p, \"y\", \"\"), z = Json.num(p, \"z\", \"\");\n        if (x.isEmpty() || y.isEmpty() || z.isEmpty()) return null;\n        try {\n            return new double[] { Double.parseDouble(x), Double.parseDouble(y), Double.parseDouble(z) };\n        } catch (NumberFormatException e) {\n            return null;\n        }\n    }\n\n    /** tellraw 的 JSON 文本转义（反斜杠与双引号）。 */\n    private static String escJson(String s) {\n        return s.replace(\"\\\\\", \"\\\\\\\\\").replace(\"\\\"\", \"\\\\\\\"\");\n    }\n\n    /** 最近聊天（供 /status 的 chat 段）。 */\n    public List<String> chatHistory() {\n        return new ArrayList<>(chatHistory);\n    }\n\n    private static String round3(double d) {\n        return String.valueOf(Math.round(d * 1000.0) / 1000.0);\n    }\n\n    /** 化身自报（供 /status）。 */\n    public Map<String, Object> botStatus() {\n        Map<String, Object> m = new LinkedHashMap<>();\n        m.put(\"spawned\", botSpawned);\n        m.put(\"name\", botName);\n        m.put(\"kind\", botKind);\n        m.put(\"follow\", botFollow);\n        m.put(\"note2\", \"FakePlayer.tick() 被 NeoForge 置空 ⇒ 捡拾由本模组每 5 tick 显式驱动\");\n        m.put(\"note\", \"fake_player = 服务端假玩家（有物品栏/能破坏放置，但不在 PlayerList、无真实连接）；\"\n                + \"mannequin = 玩家形状化身（无物品栏）\");\n        return m;\n    }\n\n    /**\n     * 每个动作的等待预算（ms）。**真机教训（2026-11-01）**：open_world 读档会阻塞客户端线程\n     * 十余秒 ⇒ 原先一刀切 5s 会把它误报成 PLAYTEST_TIMEOUT（动作其实成功了）。\n     */\n    public long timeoutMsFor(String action) {\n        switch (action) {\n            case \"open_world\": return 90000;\n            case \"screenshot\": return 15000;\n            case \"chat_command\": return 10000;\n            default: return 5000;\n        }\n    }\n\n    /**\n     * 该动作是否允许在 **HTTP 线程**直接执行（不入 tick 队列）。\n     * 为什么：`query_log` 的 waitMs 有界等待最长 60s，若放到客户端 tick 线程会把游戏冻住；\n     * 它只读文件（不碰 MC 状态），所以放 HTTP 线程跑。默认 false = 一切照旧入队。\n     */\n    public boolean isOffThreadAction(String action) {\n        return \"query_log\".equals(action);\n    }\n\n    public String token() { return token; }\n\n    public void setPort(int p) { this.port = p; }\n\n    /** 客户端 tick 调用（MC 线程）。 */\n    public void onTick() {\n        bridge.tick();   // 让适配层有机会做「跨 tick 的持续动作」（如挖矿进度）\n        state.tick();    // 状态器：**分帧**推进地图扫描（每 tick 只扫几格，绝不全扫）\n        queue.drain(this);\n        plan.tick(this);\n        botFollowStep();\n        if (arb.mode() == Arbitration.Mode.AUTO && arb.aiOwns() && arb.humanHasControl(bridge)) {\n            arb.yieldToHuman(bridge, \"auto-yield: human input detected\");\n            evidence.log(\"[QA] arbitration AUTO → yield to human（已释放 AI 按下的键）\");\n        }\n    }\n\n    public void onShutdown() {\n        arb.releaseOwned(bridge);\n        evidence.log(\"[QA] shutdown：已释放 AI 按下的全部键\");\n        evidence.exitCode(0);\n    }\n\n    public Map<String, Object> status() {\n        Map<String, Object> m = new LinkedHashMap<>();\n        m.put(\"ok\", true);\n        m.put(\"mod\", \"bandd_playtest\");\n        m.put(\"platform\", bridge.platform());\n        m.put(\"mcVersion\", bridge.mcVersion());\n        m.put(\"httpPort\", port);\n        m.put(\"ready\", bridge.ready());\n        // 「判据不可靠」两个坑的修复口（两者都由适配层取证后透出）：\n        // ① ready 在 AI 自己的单人世界里也是 true ⇒ 另给 clientPhase 区分 单机/多人（见 GameBridge#clientPhase）；\n        // ② 人类日志里的 LAN 端口会残留旧会话 ⇒ lanPort 取自当前活着的集成服务器对象（见 GameBridge#lanPort）。\n        m.put(\"clientPhase\", bridge.clientPhase());\n        m.put(\"lanPort\", bridge.lanPort());\n        m.put(\"tokenRequired\", true);\n        // 能力自报**按适配层自报的缺口过滤**（见 GameBridge#unavailableActions）。\n        // 默认实现返回空 ⇒ 未实现的适配层行为与从前逐字一致。\n        List<String> unavailable = new ArrayList<>(bridge.unavailableActions());\n        // 状态器面（query_state / query_map）额外要求适配层实现 blockAt + topSolidY：\n        // 那两个方法各有 default 实现（null / MIN_VALUE），**不可能从返回值区分**\n        // 「本档压根没实现」与「此刻这一格真取不到」⇒ 由适配层用 stateMapCapable() 自报。\n        // 默认 false ⇒ 54 个老档不用改一行，/status 里也会**如实**把它们列进 actionsUnavailable。\n        if (!bridge.stateMapCapable()) {\n            for (String a : Capabilities.STATE_MAP) {\n                if (!unavailable.contains(a)) unavailable.add(a);\n            }\n            // [T13] query_column / query_blocks 依赖**同一个**取值面（blockAt）⇒ 同一条判据。\n            // 不并进 STATE_MAP：那会改到既有常量（既有单测 STATE_MAP 的断言一条不动）。\n            for (String a : Capabilities.STATE_QUERY) {\n                if (!unavailable.contains(a)) unavailable.add(a);\n            }\n        }\n        // 设置面同样**如实过滤**：\n        //   open_settings 要「本档接了图形设置页」（Cloth 件 + 接线）—— 默认 false 的 54 档 + 11 个\n        //     上游没有 Cloth 件的档都列进 actionsUnavailable，而不是谎报会开屏。\n        //   settings_set / settings_save 要「本档接管了那一个配置文件」（settings != null）——\n        //     没接管的档这两个动作会 fail-loud（SETTINGS_UNSUPPORTED），/status 里也如实列着。\n        if (!bridge.configGuiAvailable() && !unavailable.contains(\"open_settings\")) {\n            unavailable.add(\"open_settings\");\n        }\n        if (settings == null) {\n            if (!unavailable.contains(\"settings_set\")) unavailable.add(\"settings_set\");\n            if (!unavailable.contains(\"settings_save\")) unavailable.add(\"settings_save\");\n        }\n        // 背包面（query_inventory / query_inventory_slot）同样**如实过滤**：要适配层自报\n        // inventoryCapable()（默认 false）⇒ 54 个老档一行不改，/status 里也如实列进 actionsUnavailable，\n        // 而不是谎报「会读背包」。为什么不现场调 inventoryJson 探测：/status 跑在 HTTP 线程上（见 HttpApi）。\n        if (!bridge.inventoryCapable()) {\n            for (String a : Capabilities.INVENTORY) {\n                if (!unavailable.contains(a)) unavailable.add(a);\n            }\n        }\n        // [T19] 「点屏幕 / 操作容器」一族同样**如实过滤**：要适配层自报 guiActionCapable()（默认 false）\n        // ⇒ 其余 54 档一行不改，/status 里也如实列进 actionsUnavailable，\n        // 而不是谎报「会点屏幕 / 会读容器槽位」。为什么不现场调 slotsJson() 探测：\n        // /status 跑在 HTTP 线程上（见 HttpApi），那是跨线程读游戏状态。\n        if (!bridge.guiActionCapable()) {\n            for (String a : Capabilities.GUI_ACTIONS) {\n                if (!unavailable.contains(a)) unavailable.add(a);\n            }\n            // [T22] select_slot / drop_item 与那五条**同一面**（同一个自报位）⇒ 同一条判据。\n            // 不并进 GUI_ACTIONS：那会改到既有常量与既有单测（GuiActionsTest F5/F7 逐字钉着\n            // GUI_ACTIONS 的 5 条）；这里按 STATE_QUERY 的先例另立子表。\n            for (String a : Capabilities.HOTBAR) {\n                if (!unavailable.contains(a)) unavailable.add(a);\n            }\n        }\n        List<String> available = new ArrayList<>();\n        for (String a : Capabilities.all()) {\n            if (!unavailable.contains(a)) available.add(a);\n        }\n        m.put(\"actions\", available);\n        m.put(\"actionsUnavailable\", unavailable);\n        Map<String, Object> caps = new LinkedHashMap<>();\n        caps.put(\"bridge\", Capabilities.BRIDGE);\n        caps.put(\"driver\", Capabilities.DRIVER);\n        // 设置面两条是 BRIDGE 的**子集**（同 STATE_MAP 先例），这里另给一份便于调用方直接读。\n        caps.put(\"settings\", Capabilities.SETTINGS);\n        // 背包面两条同样是 BRIDGE 的子集（不依赖屏幕/按键，见 Capabilities.INVENTORY 的注释）\n        caps.put(\"inventory\", Capabilities.INVENTORY);\n        // [T13] 纵剖面 / 方框搜索两条同样是 BRIDGE 的子集（不依赖屏幕/按键，见 Capabilities.STATE_QUERY）\n        caps.put(\"stateQuery\", Capabilities.STATE_QUERY);\n        // [T19] 「点屏幕 / 操作容器」五条是 **DRIVER 的子集**（客户端界面动作，见 Capabilities.GUI_ACTIONS）\n        caps.put(\"guiActions\", Capabilities.GUI_ACTIONS);\n        // [T22] select_slot / drop_item 同为 DRIVER 的子集（与 GUI_ACTIONS 同一面，见 Capabilities.HOTBAR）\n        caps.put(\"hotbarActions\", Capabilities.HOTBAR);\n        // driver 面「可用」= 仲裁没禁它 **且** 15 个 driver 动作一个不缺（保守：缺一个就报 false）\n        boolean driverAvailable = arb.mode() != Arbitration.Mode.DUAL;\n        for (String a : Capabilities.DRIVER) {\n            if (unavailable.contains(a)) { driverAvailable = false; break; }\n        }\n        caps.put(\"driverAvailable\", driverAvailable);\n        caps.put(\"supportedKeys\", bridge.supportedKeys());\n        m.put(\"capabilities\", caps);\n        Map<String, Object> a = new LinkedHashMap<>();\n        a.put(\"mode\", arb.mode().name());\n        a.put(\"aiOwns\", arb.aiOwns());\n        a.put(\"yields\", arb.yields());\n        a.put(\"ownedKeys\", arb.ownedCount());\n        a.put(\"lastReason\", arb.lastReason());\n        m.put(\"arbitration\", a);\n        m.put(\"plan\", plan.status());\n        m.put(\"stateMap\", state.status());\n        m.put(\"settings\", settingsStatus());\n        m.put(\"bot\", botStatus());\n        m.put(\"chatCount\", chatHistory.size());\n        m.put(\"evidenceDir\", evidence.dir().toString());\n        m.put(\"uptimeMs\", System.currentTimeMillis() - started);\n        m.put(\"requests\", requests);\n        return m;\n    }\n\n    /**\n     * {@code /status} 的 {@code settings} 段 —— **56 档全有**，且一个字段都不谎报。\n     *\n     * <p>内容按用户要求给全：**文件绝对路径** + **全部键名与默认值**（{@code keys}）+\n     * 能不能图形化（{@code guiAvailable}，只由适配层自报，默认 false）+ 一句\n     * 「本档不支持图形设置，请手改该文件」。\n     *\n     * <p>11 个 Cloth **上游根本没有件**的档（liteloader / rift / modloader 三族 + forge 1.12.2 /\n     * 1.13.2）额外拿到 {@code clothUpstreamMissing=true} 与点名原因 —— 这条判定用的是\n     * {@link Settings#clothUpstreamMissing(String, String)} 里那张**有出处的静态表**\n     * （出处 artifacts/cloth-config-调研.md），不是猜的。\n     */\n    public Map<String, Object> settingsStatus() {\n        Map<String, Object> s = new LinkedHashMap<>();\n        s.put(\"file\", settingsFilePath());\n        boolean gui = bridge.configGuiAvailable();\n        boolean upstreamMissing = Settings.clothUpstreamMissing(bridge.platform(), bridge.mcVersion());\n        s.put(\"guiAvailable\", gui);\n        s.put(\"guiProvider\", gui ? bridge.configGuiProvider() : null);\n        s.put(\"guiOpen\", gui ? bridge.configGuiOpenHint() : null);\n        s.put(\"clothUpstreamMissing\", upstreamMissing);\n        s.put(\"guiUnavailableReason\", gui ? null\n                : (upstreamMissing\n                        ? \"Cloth Config 上游没有 \" + bridge.platform() + \" \" + bridge.mcVersion() + \" 的件\"\n                        : \"本档未接入图形设置页（Cloth 件存在但本档没接线）\"));\n        s.put(\"writable\", settings == null ? null : Boolean.valueOf(settings.writable()));\n        s.put(\"exists\", settings == null ? null : Boolean.valueOf(settings.exists()));\n        if (settings != null && settings.lastError() != null) s.put(\"lastError\", settings.lastError());\n        s.put(\"keys\", Settings.defaultsDoc());\n        s.put(\"hint\", gui\n                ? \"游戏内改：\" + bridge.configGuiOpenHint() + \"；不想用界面也行 —— 直接编辑 \" + settingsFilePath()\n                        + \"（键名与默认值见 keys）\"\n                : \"本档不支持图形设置，请手改该文件：\" + settingsFilePath()\n                        + \"（键名与默认值见 keys；改完重启游戏生效；越界值会被自动夹回；删掉本文件 = 回默认）\");\n        s.put(\"clothUpstreamNote\", Settings.clothUpstreamNote());\n        return s;\n    }\n\n    /** 配置文件绝对路径：接了就用传入的；没接就按 {@code <gameDir>/config/bandd_playtest.json} 推。 */\n    private String settingsFilePath() {\n        if (settings != null && settings.file() != null) return settings.file().toString();\n        String dir = bridge.gameDirectory();\n        if (dir == null || dir.isEmpty()) return null;\n        return Paths.get(dir, \"config\", Settings.FILE_NAME).toString();\n    }\n\n    /** 启动时把「设置在哪、能不能图形化」写一行进 qa.log（56 档共用这一条路，老档不改一行也有）。 */\n    private void logSettings() {\n        Map<String, Object> s = settingsStatus();\n        boolean gui = Boolean.TRUE.equals(s.get(\"guiAvailable\"));\n        evidence.log(\"[QA] settings: gui=\" + (gui ? \"available(\" + s.get(\"guiProvider\") + \")\" : \"unavailable\")\n                + \" file=\" + s.get(\"file\")\n                + \" -- \" + s.get(\"hint\"));\n    }\n\n    /** 在 MC 线程上执行一个动作（由 ActionQueue 调用）。 */\n    public Map<String, Object> dispatch(String action, Map<String, Object> p) {\n        requests++;\n        switch (action == null ? \"\" : action) {\n            case \"ping\":\n                return ok(single(\"pong\", Boolean.TRUE));\n            case \"status\":\n                return status();\n            case \"query_player_state\": {\n                Map<String, Object> m = new LinkedHashMap<>();\n                Map<String, Object> player = Json.parseObject(bridge.playerStateJson());\n                // [T22] 模式 / 能力自报：**只喂这一条**（不并进 playerStateJson —— 否则会改到\n                // query_state / query_map 的既有回执形状）。取不到就留 null + 人话，**不编**。\n                String metaJson = bridge.playerMetaJson();\n                Map<String, Object> meta = null;\n                if (metaJson != null) {\n                    try { meta = Json.parseObject(metaJson); } catch (RuntimeException ignored) { meta = null; }\n                }\n                player.put(\"gameMode\", meta == null ? null : meta.get(\"gameMode\"));\n                player.put(\"flying\", meta == null ? null : meta.get(\"flying\"));\n                player.put(\"canFly\", meta == null ? null : meta.get(\"canFly\"));\n                player.put(\"cheats\", meta == null ? null : meta.get(\"cheats\"));\n                player.put(\"gameModeNote\", GAMEMODE_NOTE);\n                player.put(\"playerMetaNote\", meta == null\n                        ? \"本档不报玩家模式 / 能力（GameBridge#playerMetaJson 回 null）⇒ \"\n                                + \"gameMode/flying/canFly/cheats 一律 null（**不编**）\"\n                        : (meta.get(\"note\") == null\n                                ? \"本档自报玩家模式 / 能力（GameBridge#playerMetaJson）\"\n                                : String.valueOf(meta.get(\"note\"))));\n                m.put(\"player\", player);\n                m.put(\"screen\", bridge.screenName());\n                evidence.log(\"[QA] query_player_state: present=\" + player.get(\"present\")\n                        + \" screen=\" + m.get(\"screen\") + \" gameMode=\" + player.get(\"gameMode\")\n                        + \" flying=\" + player.get(\"flying\") + \" cheats=\" + player.get(\"cheats\"));\n                return ok(m);\n            }\n            case \"query_screen\":\n                return ok(single(\"screen\", bridge.screenName()));\n            case \"query_widgets\": {\n                // 当前 Screen 的控件清单；**没有界面时返回空清单（不是错误）**。\n                String json = bridge.widgetsJson();\n                Object list = Json.parse(json == null ? \"[]\" : json);\n                if (!(list instanceof List)) list = new ArrayList<>();\n                Map<String, Object> m = new LinkedHashMap<>();\n                m.put(\"screen\", bridge.screenName());\n                m.put(\"count\", ((List<?>) list).size());\n                m.put(\"widgets\", list);\n                return ok(m);\n            }\n            case \"query_log\": {\n                // 日志游标增量读 + 有界等待（waitMs 封顶 60s）。路径 = <gameDir>/logs/latest.log。\n                String dir = bridge.gameDirectory();\n                if (dir == null || dir.isEmpty()) {\n                    return error(\"LOG_UNSUPPORTED\", \"本档未提供游戏目录 ⇒ 无法定位 logs/latest.log\");\n                }\n                // 数值参数必须走 Json.num：裸数字经 Json.str 会变成 \"1500.0\"，Long.parseLong 当场抛错\n                // 再被 catch 吞掉 ⇒ 静默落回 0（真机实证：数值 waitMs 被当成 0，70ms 就回 timedOut）。\n                long since = 0L;\n                try { since = Long.parseLong(Json.num(p, \"sinceOffset\", \"0\").trim()); } catch (NumberFormatException ignored) { }\n                long waitMs = 0L;\n                try { waitMs = Long.parseLong(Json.num(p, \"waitMs\", \"0\").trim()); } catch (NumberFormatException ignored) { }\n                if (waitMs < 0) waitMs = 0;\n                if (waitMs > LogTail.MAX_WAIT_MS) waitMs = LogTail.MAX_WAIT_MS;\n                String pattern = Json.str(p, \"waitForPattern\", \"\");\n                Path log = Paths.get(dir, \"logs\", \"latest.log\");\n                try {\n                    Map<String, Object> data = LogTail.read(log, since, pattern, waitMs);\n                    data.put(\"logFile\", log.toString());\n                    evidence.log(\"[QA] query_log: since=\" + since + \" next=\" + data.get(\"nextOffset\")\n                            + \" matched=\" + data.get(\"matched\") + \" timedOut=\" + data.get(\"timedOut\")\n                            + \" rotated=\" + data.get(\"rotated\"));\n                    return ok(data);\n                } catch (java.util.regex.PatternSyntaxException e) {\n                    return error(\"BAD_PATTERN\", \"waitForPattern 不是合法正则：\" + e.getMessage());\n                } catch (java.io.IOException e) {\n                    return error(\"LOG_READ_FAILED\", \"读日志失败：\" + e);\n                }\n            }\n            case \"query_state\": {\n                // **（半）实时状态器**：状态在 mod 内持续刷新并缓存，这里只**读缓存**\n                // （绝不现场全扫 —— 现场全扫会卡死 tick 线程）。\n                if (!bridge.stateMapCapable()) {\n                    return error(\"STATE_MAP_UNSUPPORTED\",\n                            \"本档未实现状态器取值面（blockAt/topSolidY；见 GameBridge#stateMapCapable）\"\n                                    + \" ⇒ 不假装会画地图（/status 的 actionsUnavailable 里也如实列着它）\");\n                }\n                // [T14] 纵层参数面（yMode / yRange / yLayerMax / yModeAuto / layersMaxChars）在这里校验：\n                // 参数不合法回 BAD_REQUEST（与 query_column / query_blocks 同一个落点），不混进 ok 回执。\n                GameStateService.YPlan yp = state.planY(p);\n                if (yp.error != null) return error(\"BAD_REQUEST\", yp.error);\n                return ok(state.query(p, yp));\n            }\n            case \"query_map\": {\n                // query_map = query_state 的一个**切片**：只要地图（+ 版本/扫描进度）。\n                if (!bridge.stateMapCapable()) {\n                    return error(\"STATE_MAP_UNSUPPORTED\",\n                            \"本档未实现状态器取值面（blockAt/topSolidY）—— query_map 同 query_state\");\n                }\n                GameStateService.YPlan yp = state.planY(p);\n                if (yp.error != null) return error(\"BAD_REQUEST\", yp.error);\n                Map<String, Object> full = state.query(p, yp);\n                Map<String, Object> slice = new LinkedHashMap<>();\n                // **契约统一（2026-11-10）**：query_map 与 query_state 的回执顶层都带 schema，\n                // 未变（unchanged）时也一样 —— 否则调用方拿到的 {unchanged,stateVersion,tick}\n                // 不知道自己读的是哪个契约的哪一版。query_map 是 query_state 的切片，故同用 STATE_SCHEMA。\n                slice.put(\"schema\", GameStateService.STATE_SCHEMA);\n                slice.put(\"unchanged\", full.get(\"unchanged\"));\n                slice.put(\"stateVersion\", full.get(\"stateVersion\"));\n                slice.put(\"tick\", full.get(\"tick\"));\n                if (!Boolean.TRUE.equals(full.get(\"unchanged\"))) {\n                    slice.put(\"mapReady\", full.get(\"mapReady\"));\n                    slice.put(\"scan\", full.get(\"scan\"));\n                    slice.put(\"map\", full.get(\"map\"));\n                    if (full.get(\"mapNote\") != null) slice.put(\"mapNote\", full.get(\"mapNote\"));\n                    // step 诊断与 query_state 顶层同形（step<1 / 被夹 / 非整数倍都如实转达，不静默）\n                    if (full.get(\"stepRequested\") != null) slice.put(\"stepRequested\", full.get(\"stepRequested\"));\n                    if (full.get(\"stepClampedTo\") != null) slice.put(\"stepClampedTo\", full.get(\"stepClampedTo\"));\n                    if (full.get(\"stepNote\") != null) slice.put(\"stepNote\", full.get(\"stepNote\"));\n                }\n                return ok(slice);\n            }\n            // ================= 纵剖面 / 按条件搜方块（[T13] 新增面）=================\n            // 为什么进 BRIDGE 而不是 DRIVER：这两条**不依赖屏幕、也不依赖按键** —— 它们只是**读数**\n            // （走适配层**已有**的 blockAt(x,y,z) 取值面，任意 Y 都能取；用户原话「正好区块就是有整个\n            // Z 轴的」）⇒ 与 query_state / query_map 同一面。缺口由适配层自报 stateMapCapable()，\n            // 没实现的档在 /status 的 actionsUnavailable 里**如实**列着，/execute 回 STATE_MAP_UNSUPPORTED。\n            case \"query_column\": {\n                if (!bridge.stateMapCapable()) {\n                    return error(\"STATE_MAP_UNSUPPORTED\",\n                            \"本档未实现状态器取值面（blockAt/topSolidY；见 GameBridge#stateMapCapable）\"\n                                    + \" ⇒ query_column 同 query_state，不假装会读方块\");\n                }\n                if (!has(p, \"x\") || !has(p, \"z\")) {\n                    return error(\"MISSING_REQUIRED_PARAM\", \"需要 x 与 z（整数世界坐标）\");\n                }\n                Long xv = longOrNull(p, \"x\"), zv = longOrNull(p, \"z\");\n                if (xv == null || zv == null) {\n                    return error(\"BAD_REQUEST\", \"x/z 必须是**整值**（8 / 8.0 / \\\"8\\\" 都行；8.7 一律拒，\"\n                            + \"不静默 floor）收到 x=\" + Json.of(p.get(\"x\")) + \" z=\" + Json.of(p.get(\"z\")));\n                }\n                if (has(p, \"y1\") && longOrNull(p, \"y1\") == null) {\n                    return error(\"BAD_REQUEST\", \"y1 必须是整值，收到 \" + Json.of(p.get(\"y1\")));\n                }\n                if (has(p, \"y2\") && longOrNull(p, \"y2\") == null) {\n                    return error(\"BAD_REQUEST\", \"y2 必须是整值，收到 \" + Json.of(p.get(\"y2\")));\n                }\n                if (has(p, \"maxBlocks\") && longOrNull(p, \"maxBlocks\") == null) {\n                    return error(\"BAD_REQUEST\", \"maxBlocks 必须是整值，收到 \" + Json.of(p.get(\"maxBlocks\")));\n                }\n                YRange yr = resolveY(p, GameStateService.COLUMN_WINDOW_UP, GameStateService.COLUMN_WINDOW_DOWN);\n                if (yr == null) {\n                    return error(\"NO_PLAYER\", \"y1/y2 没给全、又读不到玩家 Y ⇒ 定不出默认窗口；\"\n                            + \"请显式给 y1 与 y2（本动作不猜世界高度）\");\n                }\n                int mb = 0;\n                if (has(p, \"maxBlocks\")) mb = longOrNull(p, \"maxBlocks\").intValue();\n                Map<String, Object> col = state.queryColumn(xv.intValue(), zv.intValue(),\n                        yr.y1, yr.y2, mb);\n                if (yr.note != null) col.put(\"yDefaultNote\", yr.note);\n                if (yr.partial) col.put(\"yPartial\", Boolean.TRUE);\n                evidence.log(\"[QA] query_column: x=\" + xv + \" z=\" + zv + \" y=\" + yr.y1 + \"..\" + yr.y2\n                        + \" count=\" + col.get(\"count\") + \" truncated=\" + col.get(\"truncated\")\n                        + \" firstNonAirY=\" + col.get(\"firstNonAirY\") + \" topSolidY=\" + col.get(\"topSolidY\"));\n                return ok(col);\n            }\n            case \"query_blocks\": {\n                if (!bridge.stateMapCapable()) {\n                    return error(\"STATE_MAP_UNSUPPORTED\",\n                            \"本档未实现状态器取值面（blockAt/topSolidY）—— query_blocks 同 query_state\");\n                }\n                List<String> raw = filterList(p);\n                if (raw == null) {\n                    return error(\"MISSING_REQUIRED_PARAM\",\n                            \"缺少 filter（字符串数组，如 [\\\"minecraft:stone\\\", \\\"*_ore\\\"]；也可给单个字符串）\");\n                }\n                List<String> filter = new ArrayList<String>();\n                for (String s : raw) {\n                    if (s != null && !s.trim().isEmpty()) filter.add(s.trim());\n                }\n                if (filter.isEmpty()) {\n                    return error(\"BAD_REQUEST\", \"filter 是**必填**且不能是空的（0 条 / 全空白 ⇒ 没有判据；\"\n                            + \"这是调用方的错，不是「空结果」）\");\n                }\n                if (filter.size() > GameStateService.SEARCH_MAX_FILTERS) {\n                    return error(\"BAD_REQUEST\", \"filter 最多 \" + GameStateService.SEARCH_MAX_FILTERS\n                            + \" 条，收到 \" + filter.size());\n                }\n                if (has(p, \"radius\") && longOrNull(p, \"radius\") == null) {\n                    return error(\"BAD_REQUEST\", \"radius 必须是整值，收到 \" + Json.of(p.get(\"radius\")));\n                }\n                if (has(p, \"maxMatches\") && longOrNull(p, \"maxMatches\") == null) {\n                    return error(\"BAD_REQUEST\", \"maxMatches 必须是整值，收到 \" + Json.of(p.get(\"maxMatches\")));\n                }\n                if (has(p, \"y1\") && longOrNull(p, \"y1\") == null) {\n                    return error(\"BAD_REQUEST\", \"y1 必须是整值，收到 \" + Json.of(p.get(\"y1\")));\n                }\n                if (has(p, \"y2\") && longOrNull(p, \"y2\") == null) {\n                    return error(\"BAD_REQUEST\", \"y2 必须是整值，收到 \" + Json.of(p.get(\"y2\")));\n                }\n                YRange yr = resolveY(p, GameStateService.SEARCH_WINDOW_UP, GameStateService.SEARCH_WINDOW_DOWN);\n                if (yr == null) {\n                    return error(\"NO_PLAYER\", \"y1/y2 没给全、又读不到玩家 Y ⇒ 定不出默认窗口；请显式给 y1 与 y2\");\n                }\n                int radius = has(p, \"radius\") ? longOrNull(p, \"radius\").intValue() : 0;\n                int maxMatches = has(p, \"maxMatches\") ? longOrNull(p, \"maxMatches\").intValue() : 0;\n                boolean refresh = Json.bool(p, \"refresh\", false);\n                Map<String, Object> sb = state.queryBlocks(radius, yr.y1, yr.y2, filter, maxMatches, refresh);\n                if (yr.note != null) sb.put(\"yDefaultNote\", yr.note);\n                if (yr.partial) sb.put(\"yPartial\", Boolean.TRUE);\n                Map<String, Object> sc = mapAtOf(sb, \"scan\");\n                evidence.log(\"[QA] query_blocks: filter=\" + filter + \" radius=\" + sb.get(\"radius\")\n                        + \" matched=\" + sb.get(\"matched\") + \" truncated=\" + sb.get(\"truncated\")\n                        + \" complete=\" + sb.get(\"complete\") + \" stoppedBy=\" + sb.get(\"stoppedBy\")\n                        + \" remaining=\" + sb.get(\"remainingBlocks\")\n                        + \" scanActive=\" + sc.get(\"active\") + \" done=\" + sc.get(\"doneBlocks\") + \"/\" + sc.get(\"totalBlocks\"));\n                return ok(sb);\n            }\n            // ================= 背包面（query_inventory / query_inventory_slot）=================\n            // 回执形状**照桥路线**（forge 1.7.10–1.12.2 的 query_inventory/query_inventory_slot）：\n            //   {size, slots:[{slot, empty, itemId, idKind, count}...]}   ← **跳过空格子**，与桥一致\n            // 额外三项（玩家真用得上）：selectedSlot / mainHand / hotbar 摘要。\n            // 形状对齐、**idKind 口径不同源**（现代 registryName vs 桥的 unlocalizedName）—— 回执里当面说清。\n            case \"query_inventory\": {\n                String json = bridge.inventoryJson();\n                if (json == null) {\n                    return error(INVENTORY_UNSUPPORTED,\n                            \"本档未实现读背包（GameBridge#inventoryJson 回 null）⇒ 不假装能读；\"\n                                    + \"/status 的 actionsUnavailable 里如实列着 query_inventory/query_inventory_slot\");\n                }\n                Map<String, Object> inv = parseInventory(json);\n                inv.put(\"idKindNote\", ID_KIND_NOTE);\n                inv.put(\"emptySkipped\", Boolean.TRUE);\n                inv.put(\"emptySkippedNote\", \"slots 只列**非空**格子（与桥路线 query_inventory 一致）；\"\n                        + \"要知道某一格空不空请用 query_inventory_slot\");\n                evidence.log(\"[QA] query_inventory: size=\" + inv.get(\"size\") + \" slotCount=\" + inv.get(\"slotCount\")\n                        + \" selectedSlot=\" + inv.get(\"selectedSlot\"));\n                return ok(inv);\n            }\n            case \"query_inventory_slot\": {\n                String json = bridge.inventoryJson();\n                if (json == null) {\n                    return error(INVENTORY_UNSUPPORTED,\n                            \"本档未实现读背包（GameBridge#inventoryJson 回 null）⇒ query_inventory_slot 同 query_inventory\");\n                }\n                if (p == null || !p.containsKey(\"slot\") || p.get(\"slot\") == null) {\n                    return error(\"MISSING_REQUIRED_PARAM\", \"缺少 slot（整数，0..size-1）\");\n                }\n                int slot;\n                try {\n                    slot = (int) Math.floor(Double.parseDouble(Json.num(p, \"slot\", \"NaN\")));\n                } catch (NumberFormatException e) {\n                    return error(\"BAD_REQUEST\", \"slot 必须是整数，收到：\" + Json.of(p.get(\"slot\")));\n                }\n                Map<String, Object> inv = parseInventory(json);\n                Object sizeV = inv.get(\"size\");\n                int size = sizeV instanceof Number ? ((Number) sizeV).intValue() : -1;\n                Map<String, Object> data = new LinkedHashMap<>();\n                data.put(\"slot\", Integer.valueOf(slot));\n                Map<String, Object> hit = findSlot(inv, slot);\n                if (hit == null) {\n                    // 空槽 / 越界都如实回 empty:true，**不许编**一个 itemId 出来（与桥路线一致）\n                    data.put(\"empty\", Boolean.TRUE);\n                    data.put(\"itemId\", null);\n                    data.put(\"idKind\", null);\n                    data.put(\"count\", Integer.valueOf(0));\n                    data.put(\"slotNote\", size >= 0 && (slot < 0 || slot >= size)\n                            ? \"slot 越界（size=\" + size + \"）⇒ 如实回 empty:true，不假装读到东西\"\n                            : \"该格是空的 ⇒ empty:true（与桥路线一致）\");\n                } else {\n                    data.putAll(hit);\n                }\n                Object sel = inv.get(\"selectedSlot\");\n                data.put(\"isSelectedSlot\",\n                        Boolean.valueOf(sel instanceof Number && ((Number) sel).intValue() == slot));\n                data.put(\"idKindNote\", ID_KIND_NOTE);\n                return ok(data);\n            }\n            // ================= 设置面（settings_set / settings_save）=================\n            // 为什么走 BRIDGE：这两条**不依赖屏幕**（core 里一个 net.minecraft.* 都没有），\n            // 只动内存里的 StateConfig 与那一个文件；见 Capabilities.SETTINGS 的注释。\n            case \"settings_set\": {\n                if (settings == null) {\n                    return error(SettingsEdit.UNSUPPORTED,\n                            \"本档没有接管配置文件（Settings=null）⇒ 不能改设置；\"\n                                    + \"/status 的 actionsUnavailable 里如实列着它\");\n                }\n                String key = Json.str(p, \"key\", \"\");\n                if (key.isEmpty()) {\n                    return error(\"MISSING_REQUIRED_PARAM\", \"缺少 key；可改的键：\" + SettingsEdit.keysLine());\n                }\n                // **白名单**（用户拍板：禁止任意 JSON 写入）。不在表里的一律 fail-loud，\n                // 且三类各有独立错误码：protected（顶层握手/装配）/ derived（派生值）/ unknown。\n                if (!SettingsEdit.known(key)) {\n                    Map<String, Object> e;\n                    if (SettingsEdit.protectedTop(key)) {\n                        e = error(SettingsEdit.PROTECTED_KEY,\n                                \"不许改该键：\" + key + \"（顶层握手/装配键，白名单外；\"\n                                        + \"port 与 token 更是外部驱动的凭据，逐字不许动）\");\n                    } else if (Settings.DERIVED_KEY.equals(key)) {\n                        e = error(SettingsEdit.DERIVED_KEY_CODE,\n                                key + \" 是派生值（(2×chunkRadius+1)×16），不是旋钮 ⇒ 改 chunkRadius 即可\");\n                    } else {\n                        e = error(SettingsEdit.UNKNOWN_KEY, \"不是可改的键：\" + key);\n                    }\n                    e.put(\"key\", key);\n                    e.put(\"allowedKeys\", SettingsEdit.KEYS);\n                    evidence.log(\"[QA] settings_set: 拒绝 key=\" + key + \" code=\" + e.get(\"code\"));\n                    return e;\n                }\n                if (!p.containsKey(\"value\")) {\n                    return error(\"MISSING_REQUIRED_PARAM\",\n                            \"缺少 value；\" + key + \" 接受：\" + SettingsEdit.specOf(key));\n                }\n                Object rawValue = p.get(\"value\");\n                SettingsEdit.Verdict verdict = SettingsEdit.coerce(key, rawValue);\n                if (!verdict.ok) {\n                    // **不许静默夹回**：越界/类型不符直接拒，把人话区间写进回执。\n                    Map<String, Object> e = error(SettingsEdit.BAD_VALUE, \"非法值：\" + verdict.message);\n                    e.put(\"key\", key);\n                    e.put(\"spec\", SettingsEdit.specOf(key));\n                    e.put(\"received\", Json.of(rawValue));\n                    evidence.log(\"[QA] settings_set: 拒绝 key=\" + key + \" value=\" + Json.of(rawValue)\n                            + \" code=\" + SettingsEdit.BAD_VALUE);\n                    return e;\n                }\n                StateConfig cfg = settings.config();\n                Map<String, Object> before = SettingsEdit.snapshot(cfg);\n                SettingsEdit.apply(cfg, key, verdict.value);\n                // 与设置页面保存按钮**同一条口径**：写完过一遍 sanitize\n                // （palette 去重 / 剔除标记码；maxAutoStep 让位于 step）。连带调整如实报。\n                cfg.sanitize();\n                Map<String, Object> after = SettingsEdit.snapshot(cfg);\n                List<String> changed = SettingsEdit.diff(before, after);\n                Object effective = after.get(key);\n                boolean adjusted = !SettingsEdit.same(verdict.value, effective);\n                // **让状态器下一轮就用新值**：请求立刻重采（下一张图就换几何）。\n                // 为什么在这里叫：状态器与设置面共用**同一个** StateConfig 实例（见构造器），\n                // 但进行中的那张扫描是按开始时读到的参数跑完的 ⇒ 要立刻生效就得重新起一张。\n                boolean refreshed = bridge.stateMapCapable() && state.requestRefresh();\n                Map<String, Object> data = new LinkedHashMap<String, Object>();\n                data.put(\"key\", key);\n                data.put(\"value\", effective);\n                data.put(\"requested\", verdict.value);\n                data.put(\"adjusted\", Boolean.valueOf(adjusted));\n                data.put(\"applied\", Boolean.TRUE);\n                data.put(\"sameInstanceAsStateService\", Boolean.valueOf(state.config() == settings.config()));\n                data.put(\"refreshRequested\", Boolean.valueOf(refreshed));\n                data.put(\"changedKeys\", changed);\n                evidence.log(\"[QA] settings_set: \" + key + \"=\" + effective + \" (requested=\"\n                        + Json.of(verdict.value) + \" adjusted=\" + adjusted + \" refresh=\" + refreshed\n                        + \" changed=\" + changed + \")\");\n                return ok(data);\n            }\n            case \"settings_save\": {\n                if (settings == null) {\n                    return error(SettingsEdit.UNSUPPORTED,\n                            \"本档没有接管配置文件（Settings=null）⇒ 没有可落盘的东西；\"\n                                    + \"/status 的 actionsUnavailable 里如实列着它\");\n                }\n                // changedKeys = 这次保存**真正会变动**的键（内存 vs 文件里现存的 state 段）。\n                // 幂等判据落在它上面：连存两次，第二次必须是**空表**、sha256 也不变。\n                List<String> changed = settings.changedKeysVsFile();\n                boolean saved = settings.save();\n                String file = settings.file() == null ? null : settings.file().toString();\n                if (!saved) {\n                    Map<String, Object> e = error(SettingsEdit.SAVE_FAILED,\n                            \"写盘失败：\" + settings.lastError());\n                    e.put(\"file\", file);\n                    e.put(\"changedKeys\", changed);\n                    return e;\n                }\n                Map<String, Object> data = new LinkedHashMap<String, Object>();\n                data.put(\"saved\", Boolean.TRUE);\n                data.put(\"file\", file);\n                data.put(\"changedKeys\", changed);\n                data.put(\"bytes\", Long.valueOf(settings.sizeBytes()));\n                data.put(\"sha256\", settings.sha256());\n                evidence.log(\"[QA] settings_save: file=\" + file + \" changedKeys=\" + changed\n                        + \" sha256=\" + data.get(\"sha256\"));\n                return ok(data);\n            }\n            case \"open_settings\": {\n                // **客户端动作**：打开游戏内设置屏（Cloth）。逐档差异全在适配层的\n                // GameBridge#openSettingsScreen；core 只负责「如实报有没有开出来」。\n                String beforeScreen = bridge.screenName();\n                if (!bridge.configGuiAvailable()) {\n                    boolean upstream = Settings.clothUpstreamMissing(bridge.platform(), bridge.mcVersion());\n                    Map<String, Object> e = error(SettingsEdit.GUI_UNSUPPORTED,\n                            upstream\n                                    ? \"Cloth Config 上游没有 \" + bridge.platform() + \" \" + bridge.mcVersion()\n                                            + \" 的件 ⇒ 本档没有图形设置页（不假装打开）\"\n                                    : \"本档未接入图形设置页（Cloth 件存在但本档没接线）⇒ 不假装打开\");\n                    e.put(\"guiAvailable\", Boolean.FALSE);\n                    e.put(\"clothUpstreamMissing\", Boolean.valueOf(upstream));\n                    e.put(\"screenBefore\", beforeScreen);\n                    e.put(\"screen\", beforeScreen);\n                    e.put(\"hint\", \"手改配置文件：\" + settingsFilePath());\n                    evidence.log(\"[QA] open_settings: SETTINGS_GUI_UNSUPPORTED (guiAvailable=false; \"\n                            + \"clothUpstreamMissing=\" + upstream + \")\");\n                    return e;\n                }\n                String returned = bridge.openSettingsScreen();\n                String afterScreen = bridge.screenName();\n                if (returned == null && afterScreen == null) {\n                    Map<String, Object> e = error(SettingsEdit.GUI_UNSUPPORTED,\n                            \"适配层自报有设置页，但没能打开（openSettingsScreen 返回 null）\"\n                                    + \" ⇒ 如实报失败，不假装打开\");\n                    e.put(\"guiAvailable\", Boolean.TRUE);\n                    e.put(\"screenBefore\", beforeScreen);\n                    e.put(\"screen\", afterScreen);\n                    return e;\n                }\n                Map<String, Object> data = new LinkedHashMap<String, Object>();\n                data.put(\"opened\", Boolean.TRUE);\n                // 屏的类名**以此刻实际打开的 Screen 为准**（调用方拿它去 query_widgets 交叉验证）。\n                data.put(\"screen\", afterScreen == null ? returned : afterScreen);\n                data.put(\"returnedScreen\", returned);\n                data.put(\"screenBefore\", beforeScreen);\n                data.put(\"provider\", bridge.configGuiProvider());\n                evidence.log(\"[QA] open_settings: -> \" + data.get(\"screen\") + \" (before=\" + beforeScreen + \")\");\n                return ok(data);\n            }\n            // ================= [T19] 点屏幕 / 操作容器 五条 =================\n            // 为什么进 DRIVER：它们都是**客户端界面动作**（与 query_widgets / close_screen /\n            // open_settings 同一面）。core 只做「参数解析 + 没界面 / 越界 的 fail-loud + 如实透出」，\n            // 真正的 MC 调用全在适配层（GameBridge#slotsJson / clickSlot / clickWidget / useOn / placeBlock）。\n            // 两档共用这一份校验 ⇒ 「越界」「没开界面」的判据逐字一致（这是 core 单测钉得住的那半边）。\n            case \"query_slots\": {\n                if (!bridge.guiActionCapable()) {\n                    return error(GuiResult.UNSUPPORTED,\n                            \"本档未实现「点屏幕 / 操作容器」一族（GameBridge#guiActionCapable=false）\"\n                                    + \" ⇒ 不假装能读容器槽位；/status 的 actionsUnavailable 里如实列着这五条\");\n                }\n                String json = bridge.slotsJson();\n                if (json == null) {\n                    // **fail-loud**：没有界面 ⇒ 明确错误码，**绝不**假装空列表 ——\n                    // 「容器里的东西读不到」与「容器是空的」是两件完全不同的事。\n                    Map<String, Object> e = error(GuiResult.NO_SCREEN_OPEN,\n                            \"当前没有打开任何容器界面（隐藏的玩家背包也没开）⇒ 读不到槽位；\"\n                                    + \"先用 use_on 右键工作台/熔炉/箱子，或 press inventory 打开背包\");\n                    e.put(\"screen\", bridge.screenName());\n                    evidence.log(\"[QA] query_slots: \" + GuiResult.NO_SCREEN_OPEN\n                            + \"（screen=\" + bridge.screenName() + \"）\");\n                    return e;\n                }\n                Map<String, Object> data;\n                try {\n                    data = SlotRoles.decorate(Json.parseObject(json));\n                } catch (RuntimeException ex) {\n                    return error(\"SLOTS_PARSE_FAILED\", \"适配层给的槽位 JSON 解析失败：\" + ex);\n                }\n                Map<String, Object> pr = mapAtOf(data, \"playerRange\");\n                evidence.log(\"[QA] query_slots: screen=\" + data.get(\"screen\") + \" menuType=\" + data.get(\"menuType\")\n                        + \" containerId=\" + data.get(\"containerId\") + \" slotCount=\" + data.get(\"slotCount\")\n                        + \" playerRange=\" + (pr.isEmpty() ? \"null\" : (pr.get(\"from\") + \"..\" + pr.get(\"to\")))\n                        + \" roleKnown=\" + data.get(\"roleKnown\"));\n                return ok(data);\n            }\n            case \"click_slot\": {\n                if (!bridge.guiActionCapable()) {\n                    return error(GuiResult.UNSUPPORTED,\n                            \"本档未实现 click_slot（GameBridge#guiActionCapable=false）\");\n                }\n                if (!has(p, \"slot\")) {\n                    return error(\"MISSING_REQUIRED_PARAM\", \"缺少 slot（整数下标，0..slotCount-1）\");\n                }\n                Long sv = longOrNull(p, \"slot\");\n                if (sv == null) {\n                    return error(\"BAD_REQUEST\", \"slot 必须是**整值**，收到：\" + Json.of(p.get(\"slot\")));\n                }\n                int button = 0;\n                if (has(p, \"button\")) {\n                    Long bv = longOrNull(p, \"button\");\n                    if (bv == null) return error(\"BAD_REQUEST\", \"button 必须是整值，收到：\" + Json.of(p.get(\"button\")));\n                    button = bv.intValue();\n                }\n                if (button != 0 && button != 1) {\n                    return error(\"BAD_REQUEST\", \"button 只支持 0（左键）与 1（右键）—— 照原版点击语义；收到 \" + button);\n                }\n                boolean shift = Json.bool(p, \"shift\", false);\n                String json = bridge.slotsJson();\n                if (json == null) {\n                    Map<String, Object> e = error(GuiResult.NO_SCREEN_OPEN,\n                            \"当前没有打开容器界面 ⇒ 没有槽位可点；先 use_on 开容器 / press inventory\");\n                    e.put(\"screen\", bridge.screenName());\n                    evidence.log(\"[QA] click_slot: \" + GuiResult.NO_SCREEN_OPEN + \"（screen=\" + bridge.screenName() + \"）\");\n                    return e;\n                }\n                int slotCount = slotCountOf(json);\n                int slot = sv.intValue();\n                if (slot < 0 || (slotCount >= 0 && slot >= slotCount)) {\n                    Map<String, Object> e = error(GuiResult.SLOT_OUT_OF_RANGE,\n                            \"slot=\" + slot + \" 越界（本菜单 slotCount=\"\n                                    + (slotCount < 0 ? \"读不到\" : String.valueOf(slotCount)) + \"；合法区间 0..\"\n                                    + (slotCount - 1) + \"）—— 越界**不静默**当成点击了 0 号格\");\n                    e.put(\"slot\", Integer.valueOf(slot));\n                    e.put(\"slotCount\", slotCount < 0 ? null : Integer.valueOf(slotCount));\n                    evidence.log(\"[QA] click_slot: \" + GuiResult.SLOT_OUT_OF_RANGE\n                            + \" slot=\" + slot + \" slotCount=\" + slotCount);\n                    return e;\n                }\n                GuiResult r = bridge.clickSlot(slot, button, shift);\n                if (!r.ok) {\n                    Map<String, Object> extra = new LinkedHashMap<String, Object>();\n                    extra.put(\"slot\", Integer.valueOf(slot));\n                    extra.put(\"button\", Integer.valueOf(button));\n                    extra.put(\"shift\", Boolean.valueOf(shift));\n                    return guiFail(\"click_slot\", r, extra);\n                }\n                Map<String, Object> data = new LinkedHashMap<String, Object>(r.data);\n                data.put(\"slot\", Integer.valueOf(slot));\n                data.put(\"button\", Integer.valueOf(button));\n                data.put(\"shift\", Boolean.valueOf(shift));\n                // 原版点击类型的落点（如实写清我们按 shift/button 映射到哪个枚举常量）\n                data.put(\"actionType\", shift ? \"QUICK_MOVE\" : \"PICKUP\");\n                data.put(\"actionTypeNote\", shift\n                        ? \"shift=true ⇒ QUICK_MOVE（快速移动，原版 shift 左键）\"\n                        : (button == 1\n                                ? \"button=1 ⇒ PICKUP（原版右键：拿一半 / 放一个）\"\n                                : \"button=0 ⇒ PICKUP（原版左键：拿/放整叠）\"));\n                data.put(\"slotCount\", slotCount < 0 ? null : Integer.valueOf(slotCount));\n                evidence.log(\"[QA] click_slot: slot=\" + slot + \" button=\" + button + \" shift=\" + shift\n                        + \" actionType=\" + data.get(\"actionType\") + \" containerId=\" + data.get(\"containerId\")\n                        + \" slotCount=\" + slotCount);\n                return ok(data);\n            }\n            case \"click_widget\": {\n                if (!bridge.guiActionCapable()) {\n                    return error(GuiResult.UNSUPPORTED,\n                            \"本档未实现 click_widget（GameBridge#guiActionCapable=false）\");\n                }\n                if (!has(p, \"index\")) {\n                    return error(\"MISSING_REQUIRED_PARAM\", \"缺少 index（对应 query_widgets 列表里的下标）\");\n                }\n                Long iv = longOrNull(p, \"index\");\n                if (iv == null) {\n                    return error(\"BAD_REQUEST\", \"index 必须是整值，收到：\" + Json.of(p.get(\"index\")));\n                }\n                String screen = bridge.screenName();\n                if (screen == null) {\n                    Map<String, Object> e = error(GuiResult.NO_SCREEN_OPEN,\n                            \"当前没有打开任何界面 ⇒ 没有控件可点（先 open_settings / use_on 打开一个界面）\");\n                    e.put(\"screen\", null);\n                    evidence.log(\"[QA] click_widget: \" + GuiResult.NO_SCREEN_OPEN + \"（screen=null）\");\n                    return e;\n                }\n                String wj = bridge.widgetsJson();\n                Object wl = Json.parse(wj == null ? \"[]\" : wj);\n                int count = (wl instanceof List) ? ((List<?>) wl).size() : 0;\n                int index = iv.intValue();\n                if (index < 0 || index >= count) {\n                    Map<String, Object> e = error(GuiResult.WIDGET_OUT_OF_RANGE,\n                            \"index=\" + index + \" 越界（当前界面 \" + screen + \" 的控件数=\" + count\n                                    + \"；合法区间 0..\" + (count - 1) + \"）—— 先 query_widgets 取清单\");\n                    e.put(\"index\", Integer.valueOf(index));\n                    e.put(\"widgetCount\", Integer.valueOf(count));\n                    e.put(\"screen\", screen);\n                    evidence.log(\"[QA] click_widget: \" + GuiResult.WIDGET_OUT_OF_RANGE\n                            + \" index=\" + index + \" count=\" + count);\n                    return e;\n                }\n                GuiResult r = bridge.clickWidget(index);\n                if (!r.ok) {\n                    Map<String, Object> extra = new LinkedHashMap<String, Object>();\n                    extra.put(\"index\", Integer.valueOf(index));\n                    extra.put(\"screen\", screen);\n                    extra.put(\"widgetCount\", Integer.valueOf(count));\n                    return guiFail(\"click_widget\", r, extra);\n                }\n                Map<String, Object> data = new LinkedHashMap<String, Object>(r.data);\n                data.put(\"index\", Integer.valueOf(index));\n                data.put(\"screen\", screen);\n                data.put(\"widgetCount\", Integer.valueOf(count));\n                data.put(\"clickPath\", \"界面鼠标点击入口（Screen.mouseClicked）敲控件中心 —— \"\n                        + \"**不是** OS 级按键/鼠标注入\");\n                evidence.log(\"[QA] click_widget: index=\" + index + \" screen=\" + screen\n                        + \" type=\" + data.get(\"type\") + \" at=\" + data.get(\"x\") + \",\" + data.get(\"y\")\n                        + \" accepted=\" + data.get(\"accepted\"));\n                return ok(data);\n            }\n            case \"use_on\": {\n                if (!bridge.guiActionCapable()) {\n                    return error(GuiResult.UNSUPPORTED, \"本档未实现 use_on（GameBridge#guiActionCapable=false）\");\n                }\n                if (!has(p, \"x\") || !has(p, \"y\") || !has(p, \"z\")) {\n                    return error(\"MISSING_REQUIRED_PARAM\", \"需要 x/y/z（整数方块坐标）\");\n                }\n                Long xv = longOrNull(p, \"x\"), yv = longOrNull(p, \"y\"), zv = longOrNull(p, \"z\");\n                if (xv == null || yv == null || zv == null) {\n                    return error(\"BAD_REQUEST\", \"x/y/z 必须是**整值**（8 / 8.0 / \\\"8\\\" 都行；8.7 一律拒，\"\n                            + \"不静默 floor）收到 x=\" + Json.of(p.get(\"x\")) + \" y=\" + Json.of(p.get(\"y\"))\n                            + \" z=\" + Json.of(p.get(\"z\")));\n                }\n                GuiResult r = bridge.useOn(xv.doubleValue(), yv.doubleValue(), zv.doubleValue());\n                if (!r.ok) {\n                    Map<String, Object> extra = new LinkedHashMap<String, Object>();\n                    extra.put(\"x\", xv);\n                    extra.put(\"y\", yv);\n                    extra.put(\"z\", zv);\n                    return guiFail(\"use_on\", r, extra);\n                }\n                Map<String, Object> data = new LinkedHashMap<String, Object>(r.data);\n                data.put(\"x\", xv);\n                data.put(\"y\", yv);\n                data.put(\"z\", zv);\n                evidence.log(\"[QA] use_on: (\" + xv + \",\" + yv + \",\" + zv + \") result=\" + data.get(\"result\")\n                        + \" screen=\" + data.get(\"screen\"));\n                return ok(data);\n            }\n            case \"place_block\": {\n                if (!bridge.guiActionCapable()) {\n                    return error(GuiResult.UNSUPPORTED, \"本档未实现 place_block（GameBridge#guiActionCapable=false）\");\n                }\n                if (!has(p, \"x\") || !has(p, \"y\") || !has(p, \"z\")) {\n                    return error(\"MISSING_REQUIRED_PARAM\", \"需要 x/y/z（整数方块坐标）\");\n                }\n                Long xv = longOrNull(p, \"x\"), yv = longOrNull(p, \"y\"), zv = longOrNull(p, \"z\");\n                if (xv == null || yv == null || zv == null) {\n                    return error(\"BAD_REQUEST\", \"x/y/z 必须是**整值**（8 / 8.0 / \\\"8\\\" 都行；8.7 一律拒，\"\n                            + \"不静默 floor）收到 x=\" + Json.of(p.get(\"x\")) + \" y=\" + Json.of(p.get(\"y\"))\n                            + \" z=\" + Json.of(p.get(\"z\")));\n                }\n                GuiResult r = bridge.placeBlock(xv.doubleValue(), yv.doubleValue(), zv.doubleValue());\n                if (!r.ok) {\n                    Map<String, Object> extra = new LinkedHashMap<String, Object>();\n                    extra.put(\"x\", xv);\n                    extra.put(\"y\", yv);\n                    extra.put(\"z\", zv);\n                    return guiFail(\"place_block\", r, extra);\n                }\n                Map<String, Object> data = new LinkedHashMap<String, Object>(r.data);\n                data.put(\"x\", xv);\n                data.put(\"y\", yv);\n                data.put(\"z\", zv);\n                evidence.log(\"[QA] place_block: (\" + xv + \",\" + yv + \",\" + zv + \") placed=\" + data.get(\"placed\")\n                        + \" held=\" + data.get(\"held\") + \" support=\" + data.get(\"support\"));\n                return ok(data);\n            }\n            // ================= [T22] select_slot / drop_item（与上面一族**同一面**）=================\n            // 为什么进 DRIVER：两条都是**玩家级**动作（切本档的选中槽 / 走客户端交互管理器丢格子）——\n            // 与 click_slot 同一面。core 只做「参数解析 + 越界 / 缺省 的 fail-loud + 如实透出」，\n            // 真正的 MC 调用全在适配层（GameBridge#selectSlot / dropItem）。\n            case \"select_slot\": {\n                if (!bridge.guiActionCapable()) {\n                    return error(GuiResult.UNSUPPORTED,\n                            \"本档未实现 select_slot（GameBridge#guiActionCapable=false）\"\n                                    + \" ⇒ /status 的 actionsUnavailable 里如实列着它\");\n                }\n                if (!has(p, \"slot\")) {\n                    return error(\"MISSING_REQUIRED_PARAM\", \"缺少 slot（整数，快捷栏 0..8）\");\n                }\n                Long sv = longOrNull(p, \"slot\");\n                if (sv == null) {\n                    return error(\"BAD_REQUEST\", \"slot 必须是**整值**（8 / 8.0 / \\\"8\\\" 都行；8.7 一律拒，\"\n                            + \"不静默 floor）收到：\" + Json.of(p.get(\"slot\")));\n                }\n                int slot = sv.intValue();\n                if (slot < 0 || slot > 8) {\n                    Map<String, Object> e = error(GuiResult.SLOT_OUT_OF_RANGE,\n                            \"slot=\" + slot + \" 越界（快捷栏合法区间 0..8）—— 越界**不静默**当成切到 0 号槽\");\n                    e.put(\"slot\", Integer.valueOf(slot));\n                    e.put(\"slotMin\", Integer.valueOf(0));\n                    e.put(\"slotMax\", Integer.valueOf(8));\n                    evidence.log(\"[QA] select_slot: \" + GuiResult.SLOT_OUT_OF_RANGE + \" slot=\" + slot);\n                    return e;\n                }\n                GuiResult r = bridge.selectSlot(slot);\n                if (!r.ok) {\n                    Map<String, Object> extra = new LinkedHashMap<String, Object>();\n                    extra.put(\"slot\", Integer.valueOf(slot));\n                    return guiFail(\"select_slot\", r, extra);\n                }\n                Map<String, Object> data = new LinkedHashMap<String, Object>(r.data);\n                data.put(\"slot\", Integer.valueOf(slot));\n                // 与 query_inventory 的**交叉验证**：能读背包才给这两项（读不到就**不给**，不编）。\n                String invJson = bridge.inventoryJson();\n                if (invJson != null) {\n                    Map<String, Object> inv = parseInventory(invJson);\n                    Object isel = inv.get(\"selectedSlot\");\n                    Object asel = data.get(\"selectedSlot\");\n                    data.put(\"inventorySelectedSlot\", isel);\n                    data.put(\"inventoryMainHand\", inv.get(\"mainHand\"));\n                    Boolean consistent = null;\n                    if (asel instanceof Number && isel instanceof Number) {\n                        consistent = Boolean.valueOf(((Number) asel).intValue() == ((Number) isel).intValue()\n                                && ((Number) isel).intValue() == slot);\n                    }\n                    data.put(\"consistent\", consistent);\n                }\n                evidence.log(\"[QA] select_slot: slot=\" + slot + \" previous=\" + data.get(\"previousSlot\")\n                        + \" selected=\" + data.get(\"selectedSlot\") + \" mainHand=\" + data.get(\"mainHand\")\n                        + \" inventorySelected=\" + data.get(\"inventorySelectedSlot\"));\n                return ok(data);\n            }\n            case \"drop_item\": {\n                if (!bridge.guiActionCapable()) {\n                    return error(GuiResult.UNSUPPORTED,\n                            \"本档未实现 drop_item（GameBridge#guiActionCapable=false）\"\n                                    + \" ⇒ /status 的 actionsUnavailable 里如实列着它\");\n                }\n                int slot = -1;                     // -1 = 未给 ⇒ 用当前选中槽\n                if (has(p, \"slot\")) {\n                    Long sv = longOrNull(p, \"slot\");\n                    if (sv == null) {\n                        return error(\"BAD_REQUEST\", \"slot 必须是**整值**，收到：\" + Json.of(p.get(\"slot\")));\n                    }\n                    slot = sv.intValue();\n                }\n                boolean all = Json.bool(p, \"all\", false);\n                int count = -1;                    // -1 = 未给 ⇒ 整叠\n                boolean countGiven = false;\n                if (has(p, \"count\")) {\n                    Long cv = longOrNull(p, \"count\");\n                    if (cv == null) {\n                        return error(\"BAD_REQUEST\", \"count 必须是**整值**，收到：\" + Json.of(p.get(\"count\")));\n                    }\n                    if (cv.intValue() <= 0) {\n                        return error(\"BAD_REQUEST\",\n                                \"count 必须 ≥ 1（要丢整叠请用 all=true 或省略 count）；收到 \" + cv);\n                    }\n                    count = cv.intValue();\n                    countGiven = true;\n                    all = false;                   // 显式 count 优先于 all（回执里 all/requestedCount 写清）\n                }\n                // 缺省槽与上界：能读背包就先拦一道（读不到就让适配层拦，**绝不编** size/selectedSlot）。\n                String invJson = bridge.inventoryJson();\n                Map<String, Object> inv = invJson == null ? null : parseInventory(invJson);\n                if (slot < 0 && inv != null) {\n                    Object sel = inv.get(\"selectedSlot\");\n                    if (sel instanceof Number) slot = ((Number) sel).intValue();\n                }\n                if (inv != null && slot >= 0) {\n                    Object sz = inv.get(\"size\");\n                    int size = sz instanceof Number ? ((Number) sz).intValue() : -1;\n                    if (size >= 0 && slot >= size) {\n                        Map<String, Object> e = error(GuiResult.SLOT_OUT_OF_RANGE,\n                                \"slot=\" + slot + \" 越界（本档物品栏 size=\" + size + \"；合法区间 0..\" + (size - 1) + \"）\");\n                        e.put(\"slot\", Integer.valueOf(slot));\n                        e.put(\"size\", Integer.valueOf(size));\n                        evidence.log(\"[QA] drop_item: \" + GuiResult.SLOT_OUT_OF_RANGE\n                                + \" slot=\" + slot + \" size=\" + size);\n                        return e;\n                    }\n                }\n                GuiResult r = bridge.dropItem(slot, count, all);\n                if (!r.ok) {\n                    Map<String, Object> extra = new LinkedHashMap<String, Object>();\n                    extra.put(\"slot\", slot < 0 ? null : Integer.valueOf(slot));\n                    extra.put(\"requestedCount\", countGiven ? Integer.valueOf(count) : null);\n                    extra.put(\"all\", Boolean.valueOf(all));\n                    return guiFail(\"drop_item\", r, extra);\n                }\n                Map<String, Object> data = new LinkedHashMap<String, Object>(r.data);\n                if (!data.containsKey(\"slot\")) {\n                    data.put(\"slot\", slot < 0 ? null : Integer.valueOf(slot));\n                }\n                data.put(\"requestedCount\", countGiven ? Integer.valueOf(count) : null);\n                data.put(\"all\", Boolean.valueOf(all));\n                evidence.log(\"[QA] drop_item: slot=\" + data.get(\"slot\") + \" dropped=\" + data.get(\"count\")\n                        + \" remaining=\" + data.get(\"remaining\") + \" empty=\" + data.get(\"empty\")\n                        + \" id=\" + data.get(\"id\"));\n                return ok(data);\n            }\n            case \"screenshot\": {\n                String path = bridge.screenshotPath();\n                evidence.log(\"[QA] screenshot -> \" + path);\n                return path == null ? error(\"SCREENSHOT_FAILED\", \"适配层返回 null\") : ok(single(\"path\", path));\n            }\n            case \"chat_command\": {\n                String cmd = Json.str(p, \"command\", \"\");\n                if (cmd.isEmpty()) return error(\"MISSING_REQUIRED_PARAM\", \"缺少 command\");\n                String head = cmd.startsWith(\"/\") ? cmd.substring(1) : cmd;\n                // 禁列（kill/tnt/fill）默认全禁；**唯一例外**是本模组自己化身的收回，\n                // 且要求**逐字精确匹配**（不是前缀放宽）—— 见 bot_despawn。\n                // **过滤逻辑不许放松**：被过滤的命令仍回 COMMAND_FORBIDDEN，另加 parsed:false 明说没解析。\n                if (!BOT_KILL.equals(head)) {\n                    for (String bad : FORBIDDEN_PREFIX) {\n                        if (head.startsWith(bad)) {\n                            // 禁列仍在**本地解析之前**拦截 ⇒ 未下发（sent:false 如实报）。\n                            Map<String, Object> e = error(\"COMMAND_FORBIDDEN\", \"禁列命令：\" + bad);\n                            e.put(\"parsed\", Boolean.FALSE);\n                            e.put(\"sent\", Boolean.FALSE);   // 未下发（禁列在本地解析之前拦截）\n                            return e;\n                        }\n                    }\n                }\n                // **诚实回执 + 有界回落**（[T16]）：\n                //   适配层走客户端命令派发器 parse/execute 拿 parsed/result/error/cursor。\n                //   **别名（/tp）是在服务端注册的**，本地客户端命令树里没有它 ⇒ 本地解析失败。\n                //   旧行为是「本地解析失败就不发」，别名命令**根本没出去**（真机：tp 玩家纹丝不动）。\n                //   新行为：本地解析失败时**仍然把命令原样发给服务端**（走与成功路径相同的下发通道\n                //   = GameBridge#chatCommand），并如实把三件事分开报：\n                //     sent       本次**有没有真的下发**（bool；与旧实现的同名串字段**语义已改**，见回执说明）\n                //     localParse 本地是否解析成功（本档没有本地派发器 ⇒ null，**不编**）\n                //     localError 本地解析错误原文（没有错 / 没有派发器 ⇒ null）\n                //   此情形下 parsed 保持 false、result 保持 null（**不许编本地结果**）。\n                CommandResult cr = bridge.runCommand(cmd);\n                Map<String, Object> data = new LinkedHashMap<>();\n                data.put(\"sentCommand\", cmd);   // 回显原命令（旧 sent 串字段的落点，改名以腾出 sent 给 bool）\n                if (cr == null) {\n                    // 本档没有本地派发器（老档）：只能原样下发，本地解析结果**如实留 null**。\n                    bridge.chatCommand(cmd);\n                    data.put(\"sent\", Boolean.TRUE);\n                    data.put(\"localParse\", null);\n                    data.put(\"localError\", null);\n                } else if (cr.parsed) {\n                    // 本地解析成功：走既有成功路径（适配层已执行 / 已下发）⇒ result 照旧给。\n                    data.put(\"sent\", Boolean.TRUE);\n                    data.put(\"parsed\", Boolean.TRUE);\n                    data.put(\"result\", cr.result);\n                    data.put(\"error\", cr.error);\n                    data.put(\"cursor\", cr.cursor);\n                    data.put(\"localParse\", Boolean.TRUE);\n                    data.put(\"localError\", null);\n                } else {\n                    // **回落**：本地不认（多半是服务端别名）⇒ 原样下发；parsed=false、result=null（不编）。\n                    bridge.chatCommand(cmd);\n                    data.put(\"sent\", Boolean.TRUE);\n                    data.put(\"parsed\", Boolean.FALSE);\n                    data.put(\"result\", null);\n                    data.put(\"error\", cr.error);\n                    data.put(\"cursor\", cr.cursor);\n                    data.put(\"localParse\", Boolean.FALSE);\n                    data.put(\"localError\", cr.error);\n                    data.put(\"fallback\", Boolean.TRUE);\n                    data.put(\"fallbackNote\", \"本地命令树没有这条命令（别名多在**服务端**注册）⇒ \"\n                            + \"已按**原命令**下发到服务端；parsed=false / result=null 是**本地**读数，\"\n                            + \"命令到底成没成要看服务端效果（位置 / 物品 / 聊天栏），别只看 parsed\");\n                }\n                evidence.log(\"[QA] chat_command: \" + cmd + \" sent=\" + data.get(\"sent\")\n                        + \" localParse=\" + data.get(\"localParse\")\n                        + (data.get(\"localError\") == null ? \"\" : \" localError=\" + data.get(\"localError\")));\n                return ok(data);\n            }\n            case \"query_chat\": {\n                List<String> fresh = bridge.drainChat();\n                chatHistory.addAll(fresh);\n                while (chatHistory.size() > 200) chatHistory.remove(0);\n                return ok(single(\"messages\", fresh));\n            }\n            case \"chat_say\": {\n                String text = Json.str(p, \"text\", \"\");\n                if (text.isEmpty()) return error(\"MISSING_REQUIRED_PARAM\", \"缺少 text\");\n                // 用 tellraw 让回复带 [AI] 前缀与颜色（不冒充玩家发言）\n                bridge.chatCommand(\"tellraw @a {\\\"text\\\":\\\"[AI] \" + escJson(text) + \"\\\",\\\"color\\\":\\\"aqua\\\"}\");\n                // 真机发现（2026-11-01）：ClientChatReceivedEvent **只对玩家聊天触发**，tellraw 走系统消息\n                // ⇒ 自己的回话不会回灌进收件箱。这里本地记账，保证对话记录两半边都全（且不产生回声循环）。\n                chatHistory.add(\"ai: \" + text);\n                while (chatHistory.size() > 200) chatHistory.remove(0);\n                evidence.log(\"[QA] chat_say: \" + text);\n                return ok(single(\"said\", text));\n            }\n            case \"press\": {\n                String key = Json.str(p, \"key\", \"\");\n                boolean down = Json.bool(p, \"down\", true);\n                if (!bridge.supportedKeys().contains(key)) {\n                    return error(\"KEY_NOT_SUPPORTED\", \"本档不支持该键：\" + key);\n                }\n                if (arb.mode() == Arbitration.Mode.DUAL) {\n                    return error(\"DRIVER_DISABLED\", \"仲裁模式 DUAL：AI 不碰按键\");\n                }\n                if (down && !arb.aiOwns()) {\n                    return error(\"NOT_OWNING\", \"当前持权方是真人（\" + arb.lastReason() + \"）\");\n                }\n                bridge.setPressed(key, down);\n                arb.noteOwned(key, down);\n                Map<String, Object> data = new LinkedHashMap<String, Object>();\n                data.put(\"key\", key + (down ? \" down\" : \" up\"));\n                // [T20-③] 诚实回执：窗口失焦时 **MC 不处理输入**（单人世界 pauseOnLostFocus 默认 true\n                //   还会弹暂停屏）⇒ 真机实测 attack / use 不生效，而旧回执照样只报 \"down\"（假回执）。\n                //   这里如实带上窗口聚焦位 + 「本次按键是否真的可能生效」；拿不到就留 null（未知），不假装。\n                Boolean focused = bridge.windowFocused();\n                data.put(\"windowFocused\", focused);\n                if (!down) {\n                    data.put(\"mayTakeEffect\", Boolean.TRUE);\n                    data.put(\"mayTakeEffectNote\", \"这是**释放**（down=false）：只是把键位复位，失焦时也照做。\");\n                } else if (Boolean.TRUE.equals(focused)) {\n                    data.put(\"mayTakeEffect\", Boolean.TRUE);\n                } else if (Boolean.FALSE.equals(focused)) {\n                    data.put(\"mayTakeEffect\", Boolean.FALSE);\n                    data.put(\"pressNote\", \"窗口**失焦**（windowFocused=false）⇒ MC 不处理按键输入\"\n                            + \"（单人世界里 pauseOnLostFocus 默认 true，还会自己弹暂停屏）\"\n                            + \" ⇒ **本次 press 不会生效**（回执不再假装已按下）。\"\n                            + \"处置：把该客户端窗口置前/聚焦后重发；或先 close_screen。\"\n                            + \"**本模组不做任何宿主级窗口置前 / 鼠标键盘注入**（那会抢用户焦点）。\");\n                } else {\n                    data.put(\"mayTakeEffect\", null);\n                    data.put(\"pressNote\", \"本档不报窗口聚焦位（windowFocused=null）⇒ 本次按键**是否真的生效未知**\"\n                            + \"（不假装已生效）。判据请用后续动作 / 读数，或让适配层实现 GameBridge#windowFocused。\");\n                }\n                evidence.log(\"[QA] press: \" + key + \" down=\" + down + \" windowFocused=\" + focused\n                        + \" mayTakeEffect=\" + data.get(\"mayTakeEffect\"));\n                return ok(data);\n            }\n            case \"open_world\": {\n                String world = Json.str(p, \"world\", \"\");\n                if (world.isEmpty()) return error(\"MISSING_REQUIRED_PARAM\", \"缺少 world（存档名）\");\n                bridge.openWorld(world);\n                // 换世界 ⇒ 会话码表必须换世代（**同一维度名下的另一个存档也是另一个世界**，\n                // 维度判据抓不到 ⇒ 这里显式重置）。见 GameStateService 类注释的「重置边界」。\n                state.resetPalette(\"open_world:\" + world);\n                evidence.log(\"[QA] open_world: \" + world);\n                return ok(single(\"world\", world));\n            }\n            case \"spawn_bot\": {\n                String name = Json.str(p, \"name\", \"AI\");\n                double dist = 3.0;\n                try { dist = Double.parseDouble(Json.num(p, \"distance\", \"3\")); } catch (NumberFormatException ignored) { }\n                String kind = bridge.spawnBot(name, dist);\n                if (kind == null) return error(\"BOT_UNSUPPORTED\", \"本档或当前环境不支持召唤化身\");\n                botSpawned = true;\n                botName = name;\n                botKind = kind;\n                evidence.log(\"[QA] spawn_bot: \" + name + \" @ \" + kind + \"（前方 \" + dist + \" 格）\");\n                return ok(single(\"bot\", name + \" @ \" + kind));\n            }\n            case \"bot_move\": {\n                if (!botSpawned) return error(\"NO_BOT\", \"还没有化身，先 spawn_bot\");\n                String mode = Json.str(p, \"mode\", \"absolute\");\n                if (\"front\".equals(mode)) {\n                    // core 拿不到玩家朝向 ⇒ 只能\"放到玩家旁\"（近似）；要真正\"正前方\"用 spawn_bot。\n                    Map<String, Object> st = Json.parseObject(bridge.playerStateJson());\n                    Object px = st.get(\"x\"), py = st.get(\"y\"), pz = st.get(\"z\");\n                    if (!(px instanceof Number) || !(py instanceof Number) || !(pz instanceof Number)) {\n                        return error(\"NO_PLAYER\", \"读不到玩家坐标\");\n                    }\n                    bridge.moveBotTo(((Number) px).doubleValue() + 1.5, ((Number) py).doubleValue(),\n                            ((Number) pz).doubleValue() + 1.5);\n                } else {\n                    String x = Json.num(p, \"x\", \"\"), y = Json.num(p, \"y\", \"\"), z = Json.num(p, \"z\", \"\");\n                    if (x.isEmpty() || y.isEmpty() || z.isEmpty()) {\n                        return error(\"MISSING_REQUIRED_PARAM\", \"需要 x/y/z，或用 mode=front\");\n                    }\n                    try {\n                        bridge.moveBotTo(Double.parseDouble(x), Double.parseDouble(y), Double.parseDouble(z));\n                    } catch (NumberFormatException e) {\n                        return error(\"BAD_REQUEST\", \"x/y/z 必须是数字\");\n                    }\n                }\n                evidence.log(\"[QA] bot_move: \" + mode);\n                return ok(single(\"moved\", mode));\n            }\n            case \"bot_follow\": {\n                if (!botSpawned) return error(\"NO_BOT\", \"还没有化身，先 spawn_bot\");\n                botFollow = Json.bool(p, \"on\", true);\n                evidence.log(\"[QA] bot_follow: \" + botFollow);\n                return ok(single(\"follow\", botFollow));\n            }\n            case \"bot_give\": {\n                if (!botSpawned) return error(\"NO_BOT\", \"还没有化身，先 spawn_bot\");\n                String item = Json.str(p, \"item\", \"\");\n                if (item.isEmpty()) return error(\"MISSING_REQUIRED_PARAM\", \"缺少 item（如 minecraft:diamond）\");\n                int count = 1;\n                try { count = Integer.parseInt(Json.num(p, \"count\", \"1\")); } catch (NumberFormatException ignored) { }\n                String r = bridge.giveBot(item, count);\n                if (r == null) return error(\"GIVE_FAILED\", \"物品 id 不存在或载体不支持：\" + item);\n                evidence.log(\"[QA] bot_give: \" + r);\n                return ok(single(\"gave\", r));\n            }\n            case \"look\": {\n                // 本机玩家转视角（bot_look 是给化身的；真客户端的身体 = mc.player 自己）\n                double ly, lp;\n                try {\n                    ly = Double.parseDouble(Json.num(p, \"yaw\", \"0\"));\n                    lp = Double.parseDouble(Json.num(p, \"pitch\", \"0\"));\n                } catch (NumberFormatException e) {\n                    return error(\"BAD_REQUEST\", \"yaw/pitch 必须是数字\");\n                }\n                if (lp > 90) lp = 90;\n                if (lp < -90) lp = -90;\n                if (!bridge.look(ly, lp)) return error(\"LOOK_UNSUPPORTED\", \"本档未实现本机玩家转视角\");\n                return ok(single(\"look\", ly + \"/\" + lp));\n            }\n            case \"mine\": {\n                // 破坏准星所指方块（先用 look 瞄准）。\n                // **跨 tick**：本发只 START（走正常破坏进度），实际挖穿在后续 client tick 里完成；\n                // 适配层还把「破坏进度」自报回来（[T20-①]），这里如实合并进回执 —— mine 不再是个黑盒。\n                String hit = bridge.mineLookingAt();\n                Map<String, Object> progress = bridge.mineStatus();\n                if (hit == null) {\n                    Map<String, Object> e = error(\"MINE_FAILED\", \"准星没落在可破坏方块上（先用 look 瞄准）；\"\n                            + \"或游戏不受理这次破坏（适配层已收工）—— 见 progress 的 lastStopReason / \"\n                            + \"continueReturnedTrueCount\");\n                    e.put(\"progress\", progress);\n                    e.put(\"progressNote\", \"progress 为 null = 本档不报破坏进度（不编）。\");\n                    evidence.log(\"[QA] mine: MINE_FAILED progress=\" + (progress == null ? \"null\" : progress.get(\"lastStopReason\")));\n                    return e;\n                }\n                Map<String, Object> data = new LinkedHashMap<String, Object>();\n                data.put(\"mined\", hit);          // 兼容旧字段：语义 = 「目标已锁定并开始破坏」（不是「已挖穿」）\n                data.put(\"target\", hit);\n                data.put(\"started\", Boolean.TRUE);\n                data.put(\"progress\", progress);\n                data.put(\"progressNote\", progress == null\n                        ? \"本档不报破坏进度（GameBridge#mineStatus 回 null）⇒ progress 留 null（**不编**）。\"\n                                + \"注意 mine 是**跨 tick** 的：\" + hit + \" 只代表「已锁定并开始破坏」，\"\n                                + \"不代表已经挖穿 —— 真值请用 query_column / query_blocks 读该格。\"\n                        : \"mine 是**跨 tick** 的：本发只代表「已锁定并开始破坏」，**不代表已经挖穿**。\"\n                                + \"是否真挖穿看 progress.targetStillThere（false = 已不在）/ \"\n                                + \"progress.lastStopReason（\" + com.bandd.playtest.core.MiningTracker.STOP_BROKEN\n                                + \" = 挖穿，\" + com.bandd.playtest.core.MiningTracker.STOP_TIMEOUT\n                                + \" = 超时收工、没挖穿）/ progress.minedCount（本会话挖穿计数）；\"\n                                + \"progress.miningTicks = 该目标已累计的 tick 数。\"\n                                + \"continueReturnedTrueCount > 0 且 targetStillThere 仍为 true 是**正常的**：\"\n                                + \"vanilla 在延迟 / 冷却未到的分支里也回 true。\");\n                evidence.log(\"[QA] mine: \" + hit\n                        + (progress == null ? \"\" : \" ticks=\" + progress.get(\"miningTicks\")\n                                + \" minedCount=\" + progress.get(\"minedCount\")\n                                + \" stillThere=\" + progress.get(\"targetStillThere\")\n                                + \" lastStop=\" + progress.get(\"lastStopReason\")\n                                + \" continueTrue=\" + progress.get(\"continueReturnedTrueCount\")));\n                return ok(data);\n            }\n            case \"close_screen\": {\n                // 界面开着时 MC 不处理输入（press 静默失效）⇒ 驱动前先关掉\n                if (!bridge.closeScreen()) return error(\"CLOSE_UNSUPPORTED\", \"本档未实现关界面\");\n                return ok(single(\"closed\", Boolean.TRUE));\n            }\n            case \"bot_look\": {\n                if (!botSpawned) return error(\"NO_BOT\", \"还没有化身，先 spawn_bot\");\n                double yaw, pitch;\n                try {\n                    yaw = Double.parseDouble(Json.num(p, \"yaw\", \"0\"));\n                    pitch = Double.parseDouble(Json.num(p, \"pitch\", \"0\"));\n                } catch (NumberFormatException e) {\n                    return error(\"BAD_REQUEST\", \"yaw/pitch 必须是数字\");\n                }\n                if (!bridge.lookBot(yaw, pitch)) return error(\"BOT_UNSUPPORTED\", \"载体不支持转向\");\n                return ok(single(\"look\", yaw + \"/\" + pitch));\n            }\n            case \"bot_break\": {\n                if (!botSpawned) return error(\"NO_BOT\", \"还没有化身，先 spawn_bot\");\n                double[] c = xyz(p);\n                if (c == null) return error(\"MISSING_REQUIRED_PARAM\", \"需要 x/y/z\");\n                String r = bridge.breakBotBlock(c[0], c[1], c[2]);\n                if (r == null) return error(\"BREAK_FAILED\", \"没挖动（方块不可破坏 / 距离太远 / 载体不支持）\");\n                evidence.log(\"[QA] bot_break: \" + r);\n                return ok(single(\"broke\", r));\n            }\n            case \"bot_place\": {\n                if (!botSpawned) return error(\"NO_BOT\", \"还没有化身，先 spawn_bot\");\n                double[] c = xyz(p);\n                if (c == null) return error(\"MISSING_REQUIRED_PARAM\", \"需要 x/y/z\");\n                String r = bridge.placeBotBlock(c[0], c[1], c[2]);\n                if (r == null) return error(\"PLACE_FAILED\", \"没放上（手上没有方块 / 目标不可放置 / 载体不支持）\");\n                evidence.log(\"[QA] bot_place: \" + r);\n                return ok(single(\"placed\", r));\n            }\n            case \"set_auth\": {\n                boolean online = Json.bool(p, \"online\", false);\n                if (!bridge.setServerAuth(online)) return error(\"NO_SERVER\", \"本机没有服务端（不在单人/局域网世界里？）\");\n                evidence.log(\"[QA] set_auth: online=\" + online);\n                return ok(single(\"usesAuthentication\", online));\n            }\n            case \"join_server\": {\n                String addr = Json.str(p, \"address\", \"\");\n                if (addr.isEmpty()) return error(\"MISSING_REQUIRED_PARAM\", \"缺少 address（如 127.0.0.1:54321）\");\n                bridge.joinServer(addr);\n                // 连别人的服务器 = 换世界 ⇒ 同上，会话码表换世代（否则旧世界的码张冠李戴）。\n                state.resetPalette(\"join_server:\" + addr);\n                evidence.log(\"[QA] join_server: \" + addr);\n                return ok(single(\"connecting\", addr));\n            }\n            case \"open_bot_inventory\": {\n                String how = bridge.openBotInventory();\n                if (how == null) return error(\"BOT_UNSUPPORTED\", \"本档/当前载体不支持把物品栏开到真人屏幕\");\n                evidence.log(\"[QA] open_bot_inventory: \" + how);\n                return ok(single(\"opened\", how));\n            }\n            case \"bot_despawn\": {\n                bridge.despawnBot();\n                botSpawned = false;\n                botFollow = false;\n                evidence.log(\"[QA] bot_despawn（收回化身）\");\n                return ok(single(\"despawned\", Boolean.TRUE));\n            }\n            case \"release_all\":\n                arb.releaseOwned(bridge);\n                return ok(single(\"released\", Boolean.TRUE));\n            case \"take_over\":\n                arb.takeOver();\n                return ok(single(\"aiOwns\", Boolean.TRUE));\n            case \"set_arbitration\": {\n                String mode = Json.str(p, \"mode\", \"\").toUpperCase();\n                try {\n                    arb.setMode(Arbitration.Mode.valueOf(mode));\n                } catch (IllegalArgumentException e) {\n                    return error(\"INVALID_MODE\", \"mode 必须是 AUTO | HOTKEY | DUAL\");\n                }\n                return ok(single(\"mode\", arb.mode().name()));\n            }\n            default:\n                return error(\"UNKNOWN_ACTION\", \"未知动作：\" + action);\n        }\n    }\n\n    // ---- 小工具（core 内部） ----\n\n    /**\n     * 把适配层的背包 JSON 规范化成回执形状。\n     *\n     * <p>为什么必须**过一道规范化**而不是原样透出：{@link Json#parseObject} 把 JSON 数字一律读成\n     * {@code Double} ⇒ 原样透出会让 {@code count:64} 变成 {@code 64.0}（调用方按整数比对就\"对不上\"）。\n     * 这里把 size/slot/count/selectedSlot 统一成整型；缺字段**如实留 null**，不编 0。\n     */\n    @SuppressWarnings(\"unchecked\")\n    static Map<String, Object> parseInventory(String json) {\n        Map<String, Object> src;\n        try {\n            src = Json.parseObject(json);\n        } catch (RuntimeException e) {\n            src = new LinkedHashMap<String, Object>();\n        }\n        Map<String, Object> out = new LinkedHashMap<String, Object>();\n        Object size = src.get(\"size\");\n        out.put(\"size\", size instanceof Number ? (Object) Integer.valueOf(((Number) size).intValue()) : null);\n        List<Object> slots = new ArrayList<Object>();\n        Object sl = src.get(\"slots\");\n        if (sl instanceof List) {\n            for (Object o : (List<?>) sl) {\n                if (!(o instanceof Map)) continue;\n                Map<String, Object> s = stackJson((Map<String, Object>) o, -1);\n                if (s.get(\"slot\") == null) continue;     // 没有槽位的条目无法定位 ⇒ 不收（不编槽号）\n                slots.add(s);\n            }\n        }\n        out.put(\"slots\", slots);\n        out.put(\"slotCount\", Integer.valueOf(slots.size()));\n        Object sel = src.get(\"selectedSlot\");\n        out.put(\"selectedSlot\", sel instanceof Number ? (Object) Integer.valueOf(((Number) sel).intValue()) : null);\n        Object mh = src.get(\"mainHand\");\n        out.put(\"mainHand\", (mh instanceof Map) ? stackJson((Map<String, Object>) mh, -1) : null);\n        List<Object> hotbar = new ArrayList<Object>();\n        Object hb = src.get(\"hotbar\");\n        if (hb instanceof List) {\n            for (Object o : (List<?>) hb) {\n                if (o instanceof Map) hotbar.add(stackJson((Map<String, Object>) o, -1));\n            }\n        }\n        if (hotbar.isEmpty()) {\n            out.put(\"hotbar\", null);\n            out.put(\"hotbarNote\", \"适配层没给 hotbar 摘要 ⇒ 如实留 null（不编 9 格）\");\n        } else {\n            out.put(\"hotbar\", hotbar);\n            out.put(\"hotbarCount\", Integer.valueOf(hotbar.size()));\n        }\n        Object ik = src.get(\"idKind\");\n        if (ik != null) out.put(\"adapterIdKind\", String.valueOf(ik));\n        return out;\n    }\n\n    // ================= [T13] query_column / query_blocks 的参数小工具 =================\n\n    private static boolean has(Map<String, Object> p, String k) {\n        return p != null && p.containsKey(k) && p.get(k) != null;\n    }\n\n    /** 整值解析：Number 必须**整值**（8 / 8.0 行；8.7 拒）、字符串必须能整解析。取不到 ⇒ null。 */\n    private static Long longOrNull(Map<String, Object> p, String k) {\n        if (!has(p, k)) return null;\n        Object v = p.get(k);\n        if (v instanceof Number) {\n            double d = ((Number) v).doubleValue();\n            if (Double.isNaN(d) || Double.isInfinite(d)) return null;\n            if (d != Math.rint(d)) return null;\n            return Long.valueOf((long) d);\n        }\n        if (v instanceof String) {\n            String s = ((String) v).trim();\n            if (s.isEmpty()) return null;\n            try {\n                return Long.valueOf(Long.parseLong(s));\n            } catch (NumberFormatException e) {\n                return null;\n            }\n        }\n        return null;\n    }\n\n    /** filter 的**形状**解析：数组（或单个字符串）⇒ 列表；形状不对回 null（调用方回 BAD_REQUEST）。 */\n    private static List<String> filterList(Map<String, Object> p) {\n        if (!has(p, \"filter\")) return null;\n        Object v = p.get(\"filter\");\n        List<String> out = new ArrayList<String>();\n        if (v instanceof List) {\n            for (Object o : (List<?>) v) {\n                if (!(o instanceof String)) return null;   // 形状不对 ⇒ 不猜、不 toString\n                out.add((String) o);\n            }\n            return out;\n        }\n        if (v instanceof String) {\n            out.add((String) v);\n            return out;\n        }\n        return null;\n    }\n\n    /** 玩家脚所在方块 Y；读不到 ⇒ null（**不编 0**）。 */\n    private Double playerBlockY() {\n        Map<String, Object> st;\n        try {\n            st = Json.parseObject(bridge.playerStateJson());\n        } catch (RuntimeException e) {\n            return null;\n        }\n        Object v = st.get(\"y\");\n        if (v instanceof Number) return Double.valueOf(((Number) v).doubleValue());\n        if (v instanceof String) {\n            try {\n                return Double.valueOf(Double.parseDouble(((String) v).trim()));\n            } catch (NumberFormatException e) {\n                return null;\n            }\n        }\n        return null;\n    }\n\n    /** y 窗口的解析结果（三种情形 + 补法说明一次算清）。 */\n    private static final class YRange {\n        int y1;\n        int y2;\n        boolean usedDefault;\n        boolean partial;\n        boolean noteIsDefault;\n        String note;\n    }\n\n    /**\n     * 解析 y1/y2（可选）：\n     * <ul>\n     *   <li>都没给 ⇒ 有界默认窗口 [floor(玩家Y) - down, floor(玩家Y) + up]；</li>\n     *   <li>只给一个 ⇒ 另一个按默认窗口**补**，并回 {@code yPartial:true} + 人话（不静默、也不编中点）；</li>\n     *   <li>都给了 ⇒ 原样用（顺序错由下游按 [yLow..yHigh] 规范化并说明）。</li>\n     * </ul>\n     * 需要玩家 Y 却读不到 ⇒ 回 {@code null}（调用方回 {@code NO_PLAYER}，**不猜世界高度**）。\n     */\n    private YRange resolveY(Map<String, Object> p, int up, int down) {\n        Long a = has(p, \"y1\") ? longOrNull(p, \"y1\") : null;\n        Long b = has(p, \"y2\") ? longOrNull(p, \"y2\") : null;\n        YRange r = new YRange();\n        if (a != null && b != null) {\n            r.y1 = a.intValue();\n            r.y2 = b.intValue();\n            return r;\n        }\n        Double py = playerBlockY();\n        if (py == null) return null;\n        int d2 = (int) Math.floor(py.doubleValue()) + up;\n        int d1 = d2 - up - down;\n        if (a == null && b == null) {\n            r.y1 = d1;\n            r.y2 = d2;\n            r.usedDefault = true;\n            r.noteIsDefault = true;\n            r.note = \"未给 y1/y2 ⇒ 用**有界**默认窗口 [floor(玩家Y) - \" + down + \", floor(玩家Y) + \" + up\n                    + \"]（玩家 Y=\" + py + \" ⇒ [\" + d1 + \", \" + d2 + \"]）\";\n            return r;\n        }\n        r.y1 = a == null ? d1 : a.intValue();\n        r.y2 = b == null ? d2 : b.intValue();\n        r.partial = true;\n        r.note = \"只给了 y1/y2 中的一个 ⇒ 另一个按**默认窗口**补（默认 = [floor(玩家Y) - \" + down\n                + \", floor(玩家Y) + \" + up + \"]，玩家 Y=\" + py + \"）—— **不**编中点、不静默\";\n        return r;\n    }\n\n    /** 从回执里取一个子对象（取不到回空表）。 */\n    @SuppressWarnings(\"unchecked\")\n    private static Map<String, Object> mapAtOf(Map<String, Object> m, String k) {\n        Object v = m == null ? null : m.get(k);\n        return (v instanceof Map) ? (Map<String, Object>) v : new LinkedHashMap<String, Object>();\n    }\n\n    // ================= [T19] 界面动作的小工具 =================\n\n    /**\n     * 从适配层给的槽位 JSON 里取 {@code slotCount}（= slots 列表长度）；取不到 / 解析失败回 -1。\n     *\n     * <p>为什么 core 要自己数一遍：{@code click_slot} 的**越界判据**必须落在 core ——\n     * 这样它才**能被纯 JDK 单测钉死**（适配层那半边要真机）。适配层仍会**再拦一道**\n     * （它知道本档 slotCount），两道都在 ⇒ 越界不可能静默落成「点了 0 号格」。\n     */\n    static int slotCountOf(String json) {\n        if (json == null) return -1;\n        try {\n            Map<String, Object> m = Json.parseObject(json);\n            Object sl = m.get(\"slots\");\n            return (sl instanceof List) ? ((List<?>) sl).size() : -1;\n        } catch (RuntimeException e) {\n            return -1;\n        }\n    }\n\n    /** 把适配层的失败 {@link GuiResult} 转成 core 的失败回执（码 + 人话 + 诊断读数），并写 [QA] 行。 */\n    private Map<String, Object> guiFail(String action, GuiResult r, Map<String, Object> extra) {\n        Map<String, Object> e = error(r.code == null ? \"GUI_ACTION_FAILED\" : r.code,\n                r.message == null ? \"适配层未给失败说明\" : r.message);\n        e.putAll(r.data);\n        if (extra != null) e.putAll(extra);\n        evidence.log(\"[QA] \" + action + \": \" + e.get(\"code\") + \" -- \" + e.get(\"message\"));\n        return e;\n    }\n\n    /** 单格规范化：{@code {slot, empty, itemId?, idKind?, count?}}。**空格子也要有 empty:true**。 */\n    static Map<String, Object> stackJson(Map<String, Object> src, int dfltSlot) {\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        Object slot = src.get(\"slot\");\n        if (slot instanceof Number) m.put(\"slot\", Integer.valueOf(((Number) slot).intValue()));\n        else if (dfltSlot >= 0) m.put(\"slot\", Integer.valueOf(dfltSlot));\n        else m.put(\"slot\", null);\n        boolean empty = Boolean.TRUE.equals(src.get(\"empty\")) || src.get(\"itemId\") == null;\n        m.put(\"empty\", Boolean.valueOf(empty));\n        if (!empty) {\n            m.put(\"itemId\", String.valueOf(src.get(\"itemId\")));\n            Object kind = src.get(\"idKind\");\n            m.put(\"idKind\", kind == null ? \"registryName\" : String.valueOf(kind));\n            Object c = src.get(\"count\");\n            m.put(\"count\", c instanceof Number ? (Object) Integer.valueOf(((Number) c).intValue()) : null);\n        }\n        return m;\n    }\n\n    /** 在规范化后的 slots 里找某槽位；没有（空格 / 越界）回 null。 */\n    static Map<String, Object> findSlot(Map<String, Object> inv, int slot) {\n        Object sl = inv.get(\"slots\");\n        if (!(sl instanceof List)) return null;\n        for (Object o : (List<?>) sl) {\n            if (!(o instanceof Map)) continue;\n            Map<?, ?> e = (Map<?, ?>) o;\n            Object s = e.get(\"slot\");\n            if (s instanceof Number && ((Number) s).intValue() == slot) {\n                @SuppressWarnings(\"unchecked\")\n                Map<String, Object> me = (Map<String, Object>) e;\n                return me;\n            }\n        }\n        return null;\n    }\n\n    public static Map<String, Object> ok(Map<String, Object> data) {\n        Map<String, Object> m = new LinkedHashMap<>();\n        m.put(\"status\", \"ok\");\n        m.put(\"data\", data);\n        return m;\n    }\n\n    public static Map<String, Object> error(String code, String message) {\n        Map<String, Object> m = new LinkedHashMap<>();\n        m.put(\"status\", \"failed\");\n        m.put(\"code\", code);\n        m.put(\"message\", message);\n        return m;\n    }\n\n    public static Map<String, Object> single(String k, Object v) {\n        Map<String, Object> m = new LinkedHashMap<>();\n        m.put(k, v);\n        return m;\n    }\n\n    public static List<String> listOf(String... v) {\n        return new ArrayList<>(Arrays.asList(v));\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/Settings.java": "package com.bandd.playtest.core;\n\nimport java.io.IOException;\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.AtomicMoveNotSupportedException;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.nio.file.StandardCopyOption;\nimport java.nio.file.StandardOpenOption;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/**\n * **那一个可手改的配置文件**（全 56 档统一 {@code <gameDir>/config/bandd_playtest.json}）。\n *\n * <h3>为什么单独一个类</h3>\n * 设置页面（Cloth Config）只负责画控件；**读写文件**这件事与任何一个加载器无关，所以放在 core：\n *\n * <ul>\n *   <li>**读-改-写**：{@link #save()} 只覆盖自己认识的两块（顶层 {@code token/port/arbitration/evidenceDir}\n *       与 {@code state} 里的 {@link StateConfig} 旋钮），**其余键一个不动** ——\n *       尤其 <b>绝不覆盖 {@code port} 与 {@code token}</b>（它们是本模组与外部驱动的握手凭据，\n *       设置页面没有、也不该有它们的控件）。</li>\n *   <li>**未知键保住两层**：顶层未知键（如别人手加的 {@code \"future\":{...}}）与\n *       {@code state} 内的未知键（如手加的 {@code \"myKnob\":7}）都原样留在文件里。</li>\n *   <li>{@link StateConfig#toJson()} 里的派生键 {@code mapSideBlocks}（= (2×chunkRadius+1)×16）\n *       **不落盘** —— {@link StateConfig#applyJson} 不认它，写进去只会让人以为可改。</li>\n *   <li>数值规范化：{@link Json#parseObject} 把裸数字读成 {@code Double} ⇒ 直接回写会出现\n *       {@code \"port\":38081.0}。{@link #save()} 在写之前把**整数值的 Double 收成 Long**\n *       （{@code 38081.0 → 38081}），非整数值与字符串原样保留。</li>\n * </ul>\n *\n * <h3>谁在用它</h3>\n * fabric-1.21.11 / neoforge-1.20.1 的入口构造一个本类实例并交给 {@link PlaytestCore}；\n * 其余档（含 11 个 Cloth 不可能有件的档）**不改一行**，{@code /status} 里如实报\n * {@code settings.guiAvailable=false} + 文件绝对路径 + 全部键名与默认值 + 「请手改该文件」。\n *\n * <p>Java 8 兼容（core 与 54 个老档共用同一份源码）。\n */\npublic final class Settings {\n\n    /** 派生键：只出现在 {@link StateConfig#toJson()}，{@link StateConfig#applyJson} 不认它 ⇒ 永不落盘。 */\n    public static final String DERIVED_KEY = \"mapSideBlocks\";\n\n    /** 配置文件名（各档同值；路径 = {@code <gameDir>/config/<本值>}）。 */\n    public static final String FILE_NAME = \"bandd_playtest.json\";\n\n    private final Path file;\n    /** 整份配置的**原始** JSON（含未知键）；读写都围着它做读-改-写。 */\n    private final Map<String, Object> raw;\n    private final StateConfig state;\n    private boolean writable = true;\n    private String lastError;\n\n    private Settings(Path file, Map<String, Object> raw, StateConfig state) {\n        this.file = file;\n        this.raw = raw;\n        this.state = state;\n    }\n\n    // ==================================================================\n    // 构造\n    // ==================================================================\n\n    /**\n     * 读一个配置文件；**文件不存在或读不动也返回实例**（用默认值），只是 {@link #writable()} 为 false\n     * 或文件不存在 —— 调用方照常能读旋钮，{@link #save()} 会尝试创建它。\n     */\n    public static Settings load(Path file) {\n        Map<String, Object> raw = new LinkedHashMap<String, Object>();\n        String err = null;\n        try {\n            if (file != null && Files.exists(file)) {\n                String text = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);\n                raw = Json.parseObject(text);\n            }\n        } catch (IOException e) {\n            err = \"读失败：\" + e;\n        } catch (RuntimeException e) {\n            err = \"解析失败（JSON 坏了？）：\" + e;\n        }\n        Settings s = of(file, raw);\n        if (err != null) { s.writable = false; s.lastError = err; }\n        return s;\n    }\n\n    /**\n     * 用**已经读出来的**整份配置构造（入口里的 {@code loadOrCreateConfig} 就是这条路）。\n     * {@code raw} 被本实例接管：{@link #save()} 会就地改它再整份写回。\n     */\n    public static Settings of(Path file, Map<String, Object> raw) {\n        Map<String, Object> m = raw == null ? new LinkedHashMap<String, Object>() : raw;\n        StateConfig cfg = new StateConfig();\n        Object s = m.get(\"state\");\n        if (s instanceof Map) {\n            @SuppressWarnings(\"unchecked\")\n            Map<String, Object> sm = (Map<String, Object>) s;\n            cfg.applyJson(sm);      // applyJson 末尾自己 sanitize（缺键保持默认）\n        }\n        return new Settings(file, m, cfg);\n    }\n\n    // ==================================================================\n    // 读\n    // ==================================================================\n\n    /** 设置的**唯一**读写口（设置页面直接改这个对象；{@link GameStateService} 也持有同一个引用）。 */\n    public StateConfig config() { return state; }\n\n    /** 配置文件绝对路径；构造时给了 null 就回 null。 */\n    public Path file() { return file; }\n\n    /** 文件此刻在不在。 */\n    public boolean exists() { return file != null && Files.exists(file); }\n\n    /** 上一次读/写是否成功（false ⇒ {@link #lastError()} 有原因）。 */\n    public boolean writable() { return writable; }\n\n    /**\n     * 当前**内存里的旋钮** 与 **文件里现存的 {@code state} 段** 逐键比较\n     * ⇒ 这次 {@link #save()} 真正会改动的键（顺序 = {@link SettingsEdit#KEYS}）。\n     *\n     * <p>为什么需要它：{@code settings_save} 的回执要求 {@code changedKeys} **如实**\n     * （用户拍板）。文件里**缺**这个键 = 保存会**新增**它 ⇒ 也算 changed；\n     * 两边值等价（{@code 38081.0 ≡ 38081}，见 {@link SettingsEdit#same}）⇒ 不算。\n     *\n     * <p>幂等的判据就落在它上面：连存两次，第二次必须回**空表**（而且文件字节也不变）。\n     */\n    public List<String> changedKeysVsFile() {\n        Map<String, Object> mem = SettingsEdit.snapshot(state);\n        Map<String, Object> cur = new LinkedHashMap<String, Object>();\n        Object s = raw.get(\"state\");\n        if (s instanceof Map) {\n            @SuppressWarnings(\"unchecked\")\n            Map<String, Object> sm = (Map<String, Object>) s;\n            cur.putAll(sm);\n        }\n        List<String> out = new java.util.ArrayList<String>();\n        for (String k : SettingsEdit.KEYS) {\n            if (!cur.containsKey(k)) { out.add(k); continue; }\n            if (!SettingsEdit.same(mem.get(k), cur.get(k))) out.add(k);\n        }\n        return out;\n    }\n\n    /** 文件当前字节数；文件不在 / 读不到回 -1（{@code settings_save} 的回执用）。 */\n    public long sizeBytes() {\n        try {\n            return file != null && Files.exists(file) ? Files.size(file) : -1L;\n        } catch (IOException e) {\n            return -1L;\n        }\n    }\n\n    /**\n     * 文件当前的 sha256（小写十六进制）；失败回 {@code null}。\n     * 为什么放这里：幂等判据「连存两次 sha256 一样」最省事的取证口就在文件自己身上，\n     * 免得调用方还要去 shell 里再算一次（core 只用 JDK 自带的 {@link java.security.MessageDigest}）。\n     */\n    public String sha256() {\n        if (file == null) return null;\n        try {\n            byte[] bytes = Files.readAllBytes(file);\n            java.security.MessageDigest md = java.security.MessageDigest.getInstance(\"SHA-256\");\n            byte[] d = md.digest(bytes);\n            StringBuilder b = new StringBuilder();\n            for (byte x : d) b.append(String.format(\"%02x\", Integer.valueOf(x & 0xff)));\n            return b.toString();\n        } catch (IOException e) {\n            return null;\n        } catch (java.security.NoSuchAlgorithmException e) {\n            return null;\n        }\n    }\n\n    public String lastError() { return lastError; }\n\n    // ==================================================================\n    // 写（读-改-写）\n    // ==================================================================\n\n    /**\n     * 本次要落盘的 {@code state} 段：\n     * **先拿文件里原有的那段**（保住未知键与键序），再只用 {@link StateConfig#toJson()} 的\n     * **已知键**覆盖之，最后剔掉派生键 {@link #DERIVED_KEY}。\n     */\n    public Map<String, Object> stateMapForFile() {\n        Map<String, Object> out = new LinkedHashMap<String, Object>();\n        Object cur = raw.get(\"state\");\n        if (cur instanceof Map) {\n            @SuppressWarnings(\"unchecked\")\n            Map<String, Object> cm = (Map<String, Object>) cur;\n            out.putAll(cm);\n        }\n        for (Map.Entry<String, Object> e : state.toJson().entrySet()) {\n            if (!DERIVED_KEY.equals(e.getKey())) out.put(e.getKey(), e.getValue());\n        }\n        return out;\n    }\n\n    /**\n     * 写回**同一个文件**：{@code state} 段用当前旋钮覆盖，其余顶层键（含 {@code token} / {@code port} /\n     * {@code arbitration} / {@code evidenceDir} / {@code _comment} 与一切未知键）**原样保留**。\n     * 写失败不抛（返回 false 并记 {@link #lastError()}）—— 设置页面按钮不该因为盘满而崩。\n     */\n    public boolean save() {\n        if (file == null) { writable = false; lastError = \"没有配置文件路径\"; return false; }\n        try {\n            state.sanitize();\n            raw.put(\"state\", stateMapForFile());\n            normalizeNumbersInPlace(raw);\n            writeAtomic(pretty(raw));\n            writable = true;\n            lastError = null;\n            return true;\n        } catch (IOException e) {\n            writable = false;\n            lastError = \"写失败：\" + e;\n            return false;\n        } catch (RuntimeException e) {\n            writable = false;\n            lastError = \"写失败：\" + e;\n            return false;\n        }\n    }\n\n    private void writeAtomic(String text) throws IOException {\n        byte[] bytes = text.getBytes(StandardCharsets.UTF_8);\n        Path parent = file.toAbsolutePath().getParent();\n        if (parent != null) Files.createDirectories(parent);\n        Path tmp = file.resolveSibling(file.getFileName().toString() + \".tmp\");\n        Files.write(tmp, bytes, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING,\n                StandardOpenOption.WRITE);\n        try {\n            Files.move(tmp, file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);\n        } catch (AtomicMoveNotSupportedException e) {\n            Files.move(tmp, file, StandardCopyOption.REPLACE_EXISTING);\n        }\n    }\n\n    // ==================================================================\n    // /status 用：文件路径 + 全部键名与默认值 + 「本档能不能图形化」的文案\n    // ==================================================================\n\n    /**\n     * **全部键名与默认值**（给 {@code /status} 与日志；值与 {@link StateConfig} 源码默认一一对应）。\n     * 形状：{@code {top:{...}, state:{...}, stateDerived:\"...\"}}。\n     */\n    public static Map<String, Object> defaultsDoc() {\n        Map<String, Object> top = new LinkedHashMap<String, Object>();\n        top.put(\"token\", \"<首次启动随机生成的 32 位十六进制串；外部驱动请求要带上>\");\n        top.put(\"port\", Integer.valueOf(38081));\n        top.put(\"arbitration\", \"AUTO\");\n        top.put(\"evidenceDir\", \"<gameDir>/bandd-playtest-evidence\");\n        top.put(\"_comment\", \"自由文本，本模组不读；写什么都没关系\");\n        Map<String, Object> st = new LinkedHashMap<String, Object>(new StateConfig().toJson());\n        st.remove(DERIVED_KEY);\n        Map<String, Object> m = new LinkedHashMap<String, Object>();\n        m.put(\"top\", top);\n        m.put(\"state\", st);\n        m.put(\"stateDerived\", DERIVED_KEY + \" 是派生值（(2×chunkRadius+1)×16），不可改 ⇒ 不落盘\");\n        return m;\n    }\n\n    /**\n     * 本档**上游有没有 Cloth Config 件**。\n     *\n     * <p>数据出处 = {@code F:\\B AND D MOD\\artifacts\\cloth-config-调研.md}（2026-11-10，Modrinth +\n     * maven 双源）：Cloth 的 loader 面只有 fabric / forge / neoforge；liteloader / rift / modloader\n     * 三族**不可能有**，forge 1.12.2 / 1.13.2 也是 0 条。共 11 档。\n     *\n     * <p>返回 true **只表示上游没有件**（这类档永远只能手改文件）；返回 false 不等于本档已经接线，\n     * 那只由适配层自报的 {@link GameBridge#configGuiAvailable()} 决定。\n     */\n    public static boolean clothUpstreamMissing(String platform, String mcVersion) {\n        String p = platform == null ? \"\" : platform.toLowerCase(java.util.Locale.ROOT);\n        String v = mcVersion == null ? \"\" : mcVersion;\n        if (\"liteloader\".equals(p) || \"rift\".equals(p) || \"modloader\".equals(p)) return true;\n        if (\"forge\".equals(p) && (\"1.12.2\".equals(v) || \"1.13.2\".equals(v))) return true;\n        return false;\n    }\n\n    /** 上面那张表的人话版本（写进 {@code /status} 的 {@code note}）。 */\n    public static String clothUpstreamNote() {\n        return \"Cloth Config 上游只有 fabric/forge/neoforge 三个 loader 面；\"\n                + \"liteloader / rift / modloader 三族与 forge 1.12.2 / 1.13.2 共 11 档没有件 \"\n                + \"⇒ 这些档没有图形设置，只能手改本文件（出处 artifacts/cloth-config-调研.md）\";\n    }\n\n    // ==================================================================\n    // 小工具\n    // ==================================================================\n\n    /**\n     * 把「整数值的 Double」就地收成 Long（{@code 38081.0 → 38081}），Map/List 递归。\n     * 为什么必须：{@link Json#parseObject} 用 {@code Double} 存裸数字，回写会变 {@code 38081.0}。\n     */\n    static void normalizeNumbersInPlace(Object o) {\n        if (o instanceof Map) {\n            @SuppressWarnings(\"unchecked\")\n            Map<String, Object> m = (Map<String, Object>) o;\n            for (Map.Entry<String, Object> e : m.entrySet()) {\n                Object nv = normalizeValue(e.getValue());\n                e.setValue(nv);\n                normalizeNumbersInPlace(nv);\n            }\n        } else if (o instanceof List) {\n            List<?> l = (List<?>) o;\n            for (int i = 0; i < l.size(); i++) {\n                @SuppressWarnings(\"unchecked\")\n                List<Object> ml = (List<Object>) l;\n                Object nv = normalizeValue(ml.get(i));\n                ml.set(i, nv);\n                normalizeNumbersInPlace(nv);\n            }\n        }\n    }\n\n    private static Object normalizeValue(Object v) {\n        if (v instanceof Double) {\n            double d = ((Double) v).doubleValue();\n            if (!Double.isNaN(d) && !Double.isInfinite(d) && d == Math.rint(d)\n                    && Math.abs(d) < 9007199254740992.0) {\n                return Long.valueOf((long) d);\n            }\n        }\n        return v;\n    }\n\n    /** 两空格缩进的 JSON（手改友好；{@link Json#of} 只有紧凑形）。 */\n    static String pretty(Object o) {\n        StringBuilder b = new StringBuilder();\n        prettyWrite(b, o, 0);\n        b.append('\\n');\n        return b.toString();\n    }\n\n    private static void prettyWrite(StringBuilder b, Object o, int ind) {\n        if (o == null) { b.append(\"null\"); return; }\n        if (o instanceof Map) {\n            @SuppressWarnings(\"unchecked\")\n            Map<String, Object> m = (Map<String, Object>) o;\n            if (m.isEmpty()) { b.append(\"{}\"); return; }\n            b.append(\"{\\n\");\n            int i = 0;\n            for (Map.Entry<String, Object> e : m.entrySet()) {\n                indent(b, ind + 1);\n                b.append('\"').append(Json.esc(e.getKey())).append(\"\\\": \");\n                prettyWrite(b, e.getValue(), ind + 1);\n                if (++i < m.size()) b.append(',');\n                b.append('\\n');\n            }\n            indent(b, ind);\n            b.append('}');\n            return;\n        }\n        if (o instanceof List) {\n            List<?> l = (List<?>) o;\n            if (l.isEmpty()) { b.append(\"[]\"); return; }\n            b.append(\"[\\n\");\n            for (int i = 0; i < l.size(); i++) {\n                indent(b, ind + 1);\n                prettyWrite(b, l.get(i), ind + 1);\n                if (i + 1 < l.size()) b.append(',');\n                b.append('\\n');\n            }\n            indent(b, ind);\n            b.append(']');\n            return;\n        }\n        b.append(Json.of(o));\n    }\n\n    private static void indent(StringBuilder b, int n) {\n        for (int i = 0; i < n; i++) b.append(\"  \");\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/SettingsEdit.java": "package com.bandd.playtest.core;\n\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\n\n/**\n * **桥面（settings_set）能改哪些键、每个键接受什么值** —— 唯一白名单与取值规则。\n *\n * <h3>为什么单独一个类</h3>\n * 白名单是这条动作的**安全边界**（用户拍板：禁止任意 JSON 写入）。边界必须是一处\n * 可读、可测、可被负控实验整体拆掉的实体；散在 {@link PlaytestCore#dispatch} 的 switch 里\n * 既读不全也测不到。见 {@code tests/.../SettingsActionsTest.java} 的负控实验。\n *\n * <h3>白名单 = {@link StateConfig} 的 17 个旋钮</h3>\n * 派生键 {@code mapSideBlocks} **不是旋钮**；顶层 {@code token} / {@code port} /\n * {@code arbitration} / {@code evidenceDir} / {@code _comment} 更不在内。\n * 不在白名单里的一律 **fail-loud**，且三类各有自己的错误码：\n * <pre>\n *   SETTINGS_PROTECTED_KEY  顶层握手/装配键（port/token 就在这——绝不允许被这条动作碰）\n *   SETTINGS_DERIVED_KEY    mapSideBlocks（派生值，(2×chunkRadius+1)×16）\n *   SETTINGS_UNKNOWN_KEY    其余任何键\n *   SETTINGS_BAD_VALUE      键对了但值不对（类型不符 / 越界 / 空串）\n *   SETTINGS_UNSUPPORTED    本档压根没接管配置文件（settings == null）\n *   SETTINGS_SAVE_FAILED    落盘失败\n *   SETTINGS_GUI_UNSUPPORTED 本档没有图形设置页（open_settings）\n * </pre>\n *\n * <h3>值也**不静默**</h3>\n * 类型不符 / 越界 / 空串 ⇒ {@link #BAD_VALUE}，并把**人话区间**写进回执。\n * 这里**故意比文件那条路更严**：手改文件时 {@link StateConfig#sanitize()} 会把越界值**夹回去**\n * （有出处、有单测）；桥面是**程序调用**，夹回去等于把调用方的错误咽掉 ⇒ 直接拒。\n * 唯一的例外是 {@code palette}（写完后 sanitize 会剔除与三个标记码重复的字符 / 去重），\n * 那种连带调整由 {@link PlaytestCore} 用 {@code adjusted} 与 {@code changedKeys} **如实报出**。\n *\n * <p>Java 8 兼容（core 与 54 个老档共用同一份源码）。\n */\npublic final class SettingsEdit {\n\n    // ==================================================================\n    // 错误码（回执里的 code，一字不改）\n    // ==================================================================\n    public static final String BAD_VALUE = \"SETTINGS_BAD_VALUE\";\n    public static final String UNKNOWN_KEY = \"SETTINGS_UNKNOWN_KEY\";\n    public static final String PROTECTED_KEY = \"SETTINGS_PROTECTED_KEY\";\n    public static final String DERIVED_KEY_CODE = \"SETTINGS_DERIVED_KEY\";\n    public static final String UNSUPPORTED = \"SETTINGS_UNSUPPORTED\";\n    public static final String SAVE_FAILED = \"SETTINGS_SAVE_FAILED\";\n    public static final String GUI_UNSUPPORTED = \"SETTINGS_GUI_UNSUPPORTED\";\n\n    /**\n     * 顶层**握手/装配**键：永远不在白名单里。\n     * 为什么单独列：{@code port}/{@code token} 是本模组与外部驱动的握手凭据\n     * （HTTP 端口与鉴权），{@code arbitration}/{@code evidenceDir} 是启动装配；\n     * 给它们一个**独立错误码**，调用方一眼能看出「不是拼错了键名，是这条动作不许碰」。\n     */\n    public static final List<String> PROTECTED_TOP = Arrays.asList(\n            \"port\", \"token\", \"arbitration\", \"evidenceDir\", \"_comment\");\n\n    /** 白名单：顺序 = 设置页面上的顺序；17 个 = {@link StateConfig} 的全部旋钮。 */\n    public static final List<String> KEYS = Arrays.asList(\n            \"refreshIntervalTicks\", \"chunkRadius\", \"step\", \"columnsPerTick\", \"maxChars\",\n            \"maxAutoStep\", \"includeHeight\", \"includeEntities\", \"playerMark\", \"unknownCode\",\n            \"overflowCode\", \"palette\", \"minHeightWidth\",\n            // [T16] 纵层四个旋钮（设置页「纵层（yMode）」分组；yLayerMax 硬上限 16）\n            \"yModeAuto\", \"yModeAutoDepth\", \"yLayerMax\", \"yAutoRange\");\n\n    private SettingsEdit() {\n    }\n\n    /** 白名单判定（**负控实验拆的就是这一行**：改成 return true 必须让新单测真红）。 */\n    public static boolean known(String key) {\n        return key != null && KEYS.contains(key);\n    }\n\n    public static boolean protectedTop(String key) {\n        return key != null && PROTECTED_TOP.contains(key);\n    }\n\n    // ==================================================================\n    // 规格说明（进回执的人话）\n    // ==================================================================\n\n    /** 该键接受什么（类型 + 区间）。回执里的 {@code spec} 与错误 message 都用它。 */\n    public static String specOf(String key) {\n        long[] r = intRange(key);\n        if (r != null) return \"整数 \" + r[0] + \"..\" + r[1];\n        if (isBoolKey(key)) return \"布尔 true|false\";\n        if (isCharKey(key)) return \"恰 1 个字符的字符串\";\n        if (\"palette\".equals(key)) return \"非空字符串（每个码恰 1 字符；与三个标记码重复的字符会被 sanitize 剔除）\";\n        return \"（未知键）\";\n    }\n\n    public static String keysLine() {\n        return join(KEYS, \",\");\n    }\n\n    private static String join(List<String> l, String sep) {\n        StringBuilder b = new StringBuilder();\n        for (int i = 0; i < l.size(); i++) {\n            if (i > 0) b.append(sep);\n            b.append(l.get(i));\n        }\n        return b.toString();\n    }\n\n    private static long[] intRange(String key) {\n        if (\"refreshIntervalTicks\".equals(key)) return new long[] { 1, 1200 };\n        if (\"chunkRadius\".equals(key)) return new long[] { 0, 8 };\n        if (\"step\".equals(key)) return new long[] { 1, 16 };\n        if (\"columnsPerTick\".equals(key)) return new long[] { 1, 4096 };\n        if (\"maxChars\".equals(key)) return new long[] { 64, 200000 };\n        if (\"maxAutoStep\".equals(key)) return new long[] { 1, 64 };\n        if (\"minHeightWidth\".equals(key)) return new long[] { 1, 4 };\n        // [T16] 纵层四旋钮的**设置面**区间（越界一律拒，人话见 specOf）。\n        if (\"yModeAutoDepth\".equals(key)) return new long[] { 1, 256 };\n        if (\"yLayerMax\".equals(key)) return new long[] { 1, 16 };     // 硬上限 16（GameStateService.Y_LAYER_HARD_MAX）\n        if (\"yAutoRange\".equals(key)) return new long[] { 0, 64 };\n        return null;\n    }\n\n    private static boolean isIntKey(String key) {\n        return intRange(key) != null;\n    }\n\n    private static boolean isBoolKey(String key) {\n        return \"includeHeight\".equals(key) || \"includeEntities\".equals(key)\n                || \"yModeAuto\".equals(key);\n    }\n\n    private static boolean isCharKey(String key) {\n        return \"playerMark\".equals(key) || \"unknownCode\".equals(key) || \"overflowCode\".equals(key);\n    }\n\n    // ==================================================================\n    // 校验 + 规范化\n    // ==================================================================\n\n    /** 校验结果：ok=false ⇒ {@link #message} 是人话原因，调用方据此回 {@link #BAD_VALUE}。 */\n    public static final class Verdict {\n        public final boolean ok;\n        public final Object value;\n        public final String message;\n\n        private Verdict(boolean ok, Object value, String message) {\n            this.ok = ok;\n            this.value = value;\n            this.message = message;\n        }\n\n        static Verdict good(Object v) {\n            return new Verdict(true, v, null);\n        }\n\n        static Verdict bad(String m) {\n            return new Verdict(false, null, m);\n        }\n    }\n\n    /**\n     * 把一个 JSON 值（{@code Json.parseObject} 会给 Double / Boolean / String / List / Map / null）\n     * 规范化成该键的**存储形状**（Integer / Boolean / String）。不合法回 {@code Verdict.bad}。\n     */\n    public static Verdict coerce(String key, Object raw) {\n        if (!known(key)) return Verdict.bad(\"不是可改的键\");\n        if (raw == null) return Verdict.bad(\"value 不能是 null；本键接受：\" + specOf(key));\n        if (isIntKey(key)) {\n            Long l = longOf(raw);\n            if (l == null) {\n                return Verdict.bad(\"本键要整数（\" + specOf(key) + \"），收到 \" + kindOf(raw) + \"：\" + show(raw));\n            }\n            long[] r = intRange(key);\n            if (l.longValue() < r[0] || l.longValue() > r[1]) {\n                return Verdict.bad(\"越界：本键范围 \" + specOf(key) + \"，收到 \" + l);\n            }\n            return Verdict.good(Integer.valueOf(l.intValue()));\n        }\n        if (isBoolKey(key)) {\n            Boolean b = boolOf(raw);\n            if (b == null) {\n                return Verdict.bad(\"本键要布尔（\" + specOf(key) + \"），收到 \" + kindOf(raw) + \"：\" + show(raw));\n            }\n            return Verdict.good(b);\n        }\n        if (isCharKey(key)) {\n            if (!(raw instanceof String)) {\n                return Verdict.bad(\"本键要\" + specOf(key) + \"，收到 \" + kindOf(raw) + \"：\" + show(raw));\n            }\n            String s = (String) raw;\n            if (s.length() != 1) {\n                return Verdict.bad(\"本键要恰 1 个字符，收到长度 \" + s.length() + \" 的字符串：\" + show(raw));\n            }\n            return Verdict.good(s);\n        }\n        if (\"palette\".equals(key)) {\n            if (!(raw instanceof String)) {\n                return Verdict.bad(\"本键要\" + specOf(key) + \"，收到 \" + kindOf(raw) + \"：\" + show(raw));\n            }\n            String s = (String) raw;\n            if (s.isEmpty()) return Verdict.bad(\"palette 不能是空串（空 palette 没有方块码可用）\");\n            return Verdict.good(s);\n        }\n        return Verdict.bad(\"不是可改的键\");\n    }\n\n    /** 整数：Number 必须**整值**；字符串必须能整解析（\"8\" 可以，\"8.5\" 不行）。 */\n    private static Long longOf(Object v) {\n        if (v instanceof Number) {\n            double d = ((Number) v).doubleValue();\n            if (Double.isNaN(d) || Double.isInfinite(d)) return null;\n            if (d != Math.rint(d)) return null;\n            if (d < -9007199254740992.0 || d > 9007199254740992.0) return null;\n            return Long.valueOf((long) d);\n        }\n        if (v instanceof String) {\n            String s = ((String) v).trim();\n            if (s.isEmpty()) return null;\n            try {\n                return Long.valueOf(Long.parseLong(s));\n            } catch (NumberFormatException e) {\n                return null;\n            }\n        }\n        return null;\n    }\n\n    private static Boolean boolOf(Object v) {\n        if (v instanceof Boolean) return (Boolean) v;\n        if (v instanceof String) {\n            String s = ((String) v).trim();\n            if (\"true\".equalsIgnoreCase(s)) return Boolean.TRUE;\n            if (\"false\".equalsIgnoreCase(s)) return Boolean.FALSE;\n        }\n        return null;\n    }\n\n    private static String kindOf(Object v) {\n        if (v == null) return \"null\";\n        if (v instanceof Number) return \"number\";\n        if (v instanceof Boolean) return \"boolean\";\n        if (v instanceof String) return \"string\";\n        if (v instanceof Map) return \"object\";\n        if (v instanceof List) return \"array\";\n        return v.getClass().getSimpleName();\n    }\n\n    private static String show(Object v) {\n        String s = Json.of(v);\n        return s.length() > 80 ? s.substring(0, 80) + \"...\" : s;\n    }\n\n    // ==================================================================\n    // 写入内存中的配置 + 前后对比\n    // ==================================================================\n\n    /**\n     * 当前旋钮的快照（与落盘形状一致：int / bool / String；**不含派生键**）。\n     * 用它做前后对比与「将要落盘的键」比较 —— 与 {@link StateConfig#toJson()} 同源，不另编口径。\n     */\n    public static Map<String, Object> snapshot(StateConfig cfg) {\n        Map<String, Object> m = new LinkedHashMap<String, Object>(cfg.toJson());\n        m.remove(Settings.DERIVED_KEY);\n        return m;\n    }\n\n    /** 把规范化后的值写进**内存中的**配置（调用方已过白名单 + {@link #coerce}）。 */\n    public static void apply(StateConfig cfg, String key, Object v) {\n        switch (key) {\n            case \"refreshIntervalTicks\": cfg.refreshIntervalTicks = ((Number) v).intValue(); break;\n            case \"chunkRadius\":          cfg.chunkRadius = ((Number) v).intValue(); break;\n            case \"step\":                 cfg.step = ((Number) v).intValue(); break;\n            case \"columnsPerTick\":       cfg.columnsPerTick = ((Number) v).intValue(); break;\n            case \"maxChars\":             cfg.maxChars = ((Number) v).intValue(); break;\n            case \"maxAutoStep\":          cfg.maxAutoStep = ((Number) v).intValue(); break;\n            case \"minHeightWidth\":       cfg.minHeightWidth = ((Number) v).intValue(); break;\n            case \"yModeAutoDepth\":       cfg.yModeAutoDepth = ((Number) v).intValue(); break;\n            case \"yLayerMax\":            cfg.yLayerMax = ((Number) v).intValue(); break;\n            case \"yAutoRange\":           cfg.yAutoRange = ((Number) v).intValue(); break;\n            case \"includeHeight\":        cfg.includeHeight = ((Boolean) v).booleanValue(); break;\n            case \"includeEntities\":      cfg.includeEntities = ((Boolean) v).booleanValue(); break;\n            case \"yModeAuto\":            cfg.yModeAuto = ((Boolean) v).booleanValue(); break;\n            case \"playerMark\":           cfg.playerMark = ((String) v).charAt(0); break;\n            case \"unknownCode\":          cfg.unknownCode = ((String) v).charAt(0); break;\n            case \"overflowCode\":         cfg.overflowCode = ((String) v).charAt(0); break;\n            case \"palette\":              cfg.palette = (String) v; break;\n            default: break;\n        }\n    }\n\n    /** 两快照的**差异键**（保白名单顺序；只报真变了的）。 */\n    public static List<String> diff(Map<String, Object> before, Map<String, Object> after) {\n        List<String> out = new ArrayList<String>();\n        for (String k : KEYS) {\n            if (!same(before.get(k), after.get(k))) out.add(k);\n        }\n        return out;\n    }\n\n    /**\n     * 值等价（跨形状）：{@code 38081.0 ≡ 38081}（{@link Json#parseObject} 存 Double、\n     * 回写存 Integer），字符与字符串同形（shot 存 String），其余按字符串比。\n     */\n    public static boolean same(Object a, Object b) {\n        if (a == null || b == null) return a == b;\n        if (a instanceof Number && b instanceof Number) {\n            return ((Number) a).doubleValue() == ((Number) b).doubleValue();\n        }\n        return String.valueOf(a).equals(String.valueOf(b));\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/SlotRoles.java": "package com.bandd.playtest.core;\n\nimport java.util.ArrayList;\nimport java.util.LinkedHashMap;\nimport java.util.LinkedHashSet;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\n\n/**\n * **槽位角色表**：由「容器菜单的注册名（menuType）+ 槽位下标」推出该格的 {@code role}\n * 与**玩家槽区间**（{@code playerRange}）。\n *\n * <p>为什么这一段在 **core**（而不是逐档适配层）：角色只取决于**原版菜单的版式**\n * （哪个下标是合成输入格 / 结果格 / 燃料格），与「是 Fabric 还是 NeoForge」无关；\n * 放进 core 有两条直接好处：\n * <ol>\n *   <li>两档**逐字同表**，不会各写一份慢慢漂移；</li>\n *   <li>这份映射能用**纯 JDK 单测**钉死（见 {@code tests/.../GuiActionsTest.java}）——\n *       适配层那半边（Slot.x / Slot.y / 物品）才需要真机。</li>\n * </ol>\n *\n * <p>版式出处 = **逐档 javap -c 实证**（不是记忆；命令与读数见交付报告「② 新 API 的 javap 取证」）：\n * <pre>\n *   fabric 1.21.11（yarn 映射件）：\n *     PlayerScreenHandler    ：addResultSlot(154,28) / addInputSlots(98,18) / 4x ArmorSlot / addPlayerSlots(8,84) / 副手 (40,77)\n *     CraftingScreenHandler  ：getOutputSlot()=slots.get(0)；getInputSlots()=slots.subList(1,10)；insertItem(...,10,46,..)\n *     AbstractFurnaceScreenHandler：Slot(56,17)=料 / FurnaceFuelSlot(56,53)=燃料 / FurnaceOutputSlot(116,35)=成品 / addPlayerSlots(8,84)\n *     GenericContainerScreenHandler：N*9 容器格 + addPlayerSlots(...)\n *     HopperScreenHandler    ：5 容器格 + addPlayerSlots(8,51)\n *     CrafterScreenHandler   ：9x CrafterInputSlot + addPlayerSlots(8,84) + CrafterOutputSlot(134,35)\n *   neoforge 1.20.1（parchment 映射件）：同一批菜单类，id 串与版式逐项一致（见 MenuType 静态块 ldc 常量）\n *   id 串：inventory/crafting/furnace/blast_furnace/smoker/generic_9x1..9x6/generic_3x3/crafter_3x3/\n *          shulker_box/hopper/brewing_stand/anvil/smithing/stonecutter/grindstone/loom/\n *          cartography_table/merchant/beacon/enchantment/lectern\n * </pre>\n *\n * <p><b>诚实边界</b>：表外的 menuType 走**兜底规则**（「末 36 格 = 玩家主背包 27 + 快捷栏 9，\n * 其余 = 容器格」）并在回执里写 {@code roleKnown:false} + {@code roleNote} —— **不假装**认得版式。\n *\n * <p>Java 8 可用（本类无任何 MC / 加载器类型）。\n */\npublic final class SlotRoles {\n\n    public static final String CRAFT_INPUT = \"craft_input\";\n    public static final String CRAFT_RESULT = \"craft_result\";\n    public static final String FUEL = \"fuel\";\n    public static final String INPUT = \"input\";\n    public static final String OUTPUT = \"output\";\n    public static final String ARMOR = \"armor\";\n    public static final String OFFHAND = \"offhand\";\n    public static final String CONTAINER = \"container\";\n    public static final String PLAYER_MAIN = \"player_main\";\n    public static final String PLAYER_HOTBAR = \"player_hotbar\";\n    public static final String UNKNOWN = \"unknown\";\n\n    /** 全部 role 取值（供调用方与自己人核对；顺序 = 文档顺序）。 */\n    public static final List<String> ALL_ROLES;\n    static {\n        List<String> l = new ArrayList<String>();\n        l.add(CRAFT_INPUT);\n        l.add(CRAFT_RESULT);\n        l.add(FUEL);\n        l.add(INPUT);\n        l.add(OUTPUT);\n        l.add(ARMOR);\n        l.add(OFFHAND);\n        l.add(CONTAINER);\n        l.add(PLAYER_MAIN);\n        l.add(PLAYER_HOTBAR);\n        l.add(UNKNOWN);\n        ALL_ROLES = java.util.Collections.unmodifiableList(l);\n    }\n\n    private SlotRoles() {}\n\n    /** 玩家主背包格数（27 = 3x9），后接快捷栏 9 格。 */\n    private static final int PLAYER_MAIN_COUNT = 27;\n    private static final int PLAYER_HOTBAR_COUNT = 9;\n    private static final int PLAYER_TOTAL = PLAYER_MAIN_COUNT + PLAYER_HOTBAR_COUNT;\n\n    /**\n     * 由 menuType + 下标推 role（表外走兜底）。\n     *\n     * @param menuType  容器菜单注册名（如 {@code minecraft:crafting}）；null / 未知 ⇒ 兜底\n     * @param index     槽位下标（0 起）\n     * @param slotCount 本菜单总槽位数（兜底规则要用）\n     */\n    public static String roleOf(String menuType, int index, int slotCount) {\n        List<String> roles = rolesFor(menuType, slotCount);\n        if (index < 0 || index >= roles.size()) return UNKNOWN;\n        return roles.get(index);\n    }\n\n    /** 该菜单类型是否命中**精确表**（false = 走兜底）。 */\n    public static boolean knownMenu(String menuType) {\n        if (menuType == null) return false;\n        // 特殊版式（背包屏带结果/合成/护甲/副手；熔炉一族；合成器）也各有独立分支 ⇒ 同属精确表。\n        if (\"minecraft:inventory\".equals(menuType) || \"minecraft:crafting\".equals(menuType)\n                || \"minecraft:furnace\".equals(menuType) || \"minecraft:blast_furnace\".equals(menuType)\n                || \"minecraft:smoker\".equals(menuType) || \"minecraft:crafter_3x3\".equals(menuType)) {\n            return true;\n        }\n        return fixedSpecOf(menuType) != null;\n    }\n\n    /**\n     * 完整角色列表（长度 = 表定义的长度，可能短于 / 长于 slotCount；{@link #decorate} 负责对齐）。\n     */\n    public static List<String> rolesFor(String menuType, int slotCount) {\n        List<String> r = new ArrayList<String>();\n        // ---- 1) 玩家自己的背包屏（0 结果 / 1-4 合成 / 5-8 护甲 / 9-44 主+快捷 / 45 副手）----\n        if (\"minecraft:inventory\".equals(menuType)) {\n            r.add(CRAFT_RESULT);\n            for (int i = 0; i < 4; i++) r.add(CRAFT_INPUT);\n            for (int i = 0; i < 4; i++) r.add(ARMOR);\n            addPlayerSlots(r);\n            r.add(OFFHAND);\n            return pad(r, slotCount, UNKNOWN);\n        }\n        // ---- 2) 工作台（0 结果 / 1-9 合成 3x3 / 10-45 玩家）----\n        if (\"minecraft:crafting\".equals(menuType)) {\n            r.add(CRAFT_RESULT);\n            for (int i = 0; i < 9; i++) r.add(CRAFT_INPUT);\n            addPlayerSlots(r);\n            return pad(r, slotCount, UNKNOWN);\n        }\n        // ---- 3) 熔炉一族（0 料 / 1 燃料 / 2 成品 / 3-38 玩家）----\n        if (\"minecraft:furnace\".equals(menuType)\n                || \"minecraft:blast_furnace\".equals(menuType)\n                || \"minecraft:smoker\".equals(menuType)) {\n            r.add(INPUT);\n            r.add(FUEL);\n            r.add(OUTPUT);\n            addPlayerSlots(r);\n            return pad(r, slotCount, UNKNOWN);\n        }\n        // ---- 4) 合成器（0-8 合成输入 / 9-44 玩家 / 45 产出）----\n        if (\"minecraft:crafter_3x3\".equals(menuType)) {\n            for (int i = 0; i < 9; i++) r.add(CRAFT_INPUT);\n            addPlayerSlots(r);\n            r.add(CRAFT_RESULT);\n            return pad(r, slotCount, UNKNOWN);\n        }\n        // ---- 5) 精确表里「N 个容器格 + 玩家」的机器 ----\n        List<String> fixed = fixedSpecOf(menuType);\n        if (fixed != null) {\n            r.addAll(fixed);\n            addPlayerSlots(r);\n            return pad(r, slotCount, UNKNOWN);\n        }\n        // ---- 6) 兜底：末 36 格当玩家背包，其余当容器格（**不假装认得版式**）----\n        int playerFrom = Math.max(0, slotCount - PLAYER_TOTAL);\n        for (int i = 0; i < slotCount; i++) {\n            r.add(i < playerFrom ? CONTAINER : playerRole(i - playerFrom));\n        }\n        return r;\n    }\n\n    /** 精确表里「固定容器格」那一截（不含玩家槽）；不在表里回 null。 */\n    private static List<String> fixedSpecOf(String menuType) {\n        if (menuType == null) return null;\n        if (\"minecraft:generic_9x1\".equals(menuType)) return n(CONTAINER, 9);\n        if (\"minecraft:generic_9x2\".equals(menuType)) return n(CONTAINER, 18);\n        if (\"minecraft:generic_9x3\".equals(menuType)) return n(CONTAINER, 27);\n        if (\"minecraft:generic_9x4\".equals(menuType)) return n(CONTAINER, 36);\n        if (\"minecraft:generic_9x5\".equals(menuType)) return n(CONTAINER, 45);\n        if (\"minecraft:generic_9x6\".equals(menuType)) return n(CONTAINER, 54);\n        if (\"minecraft:generic_3x3\".equals(menuType)) return n(CONTAINER, 9);\n        if (\"minecraft:shulker_box\".equals(menuType)) return n(CONTAINER, 27);\n        if (\"minecraft:hopper\".equals(menuType)) return n(CONTAINER, 5);\n        if (\"minecraft:lectern\".equals(menuType)) return n(CONTAINER, 1);\n        if (\"minecraft:brewing_stand\".equals(menuType)) {\n            // 3 个药水格（PotionSlot）+ 1 个原料格（IngredientSlot）+ 1 个燃料格（FuelSlot）\n            List<String> l = n(INPUT, 4);\n            l.add(FUEL);\n            return l;\n        }\n        if (\"minecraft:anvil\".equals(menuType)) return roles(INPUT, INPUT, OUTPUT);\n        if (\"minecraft:smithing\".equals(menuType)) return roles(INPUT, INPUT, INPUT, OUTPUT);\n        if (\"minecraft:stonecutter\".equals(menuType)) return roles(INPUT, OUTPUT);\n        if (\"minecraft:grindstone\".equals(menuType)) return roles(INPUT, INPUT, OUTPUT);\n        if (\"minecraft:loom\".equals(menuType)) return roles(INPUT, INPUT, INPUT, OUTPUT);\n        if (\"minecraft:cartography_table\".equals(menuType)) return roles(INPUT, INPUT, OUTPUT);\n        if (\"minecraft:merchant\".equals(menuType)) return roles(INPUT, INPUT, OUTPUT);\n        if (\"minecraft:beacon\".equals(menuType)) return roles(INPUT);\n        if (\"minecraft:enchantment\".equals(menuType)) return roles(INPUT, INPUT);\n        return null;\n    }\n\n    private static void addPlayerSlots(List<String> r) {\n        for (int i = 0; i < PLAYER_MAIN_COUNT; i++) r.add(PLAYER_MAIN);\n        for (int i = 0; i < PLAYER_HOTBAR_COUNT; i++) r.add(PLAYER_HOTBAR);\n    }\n\n    private static String playerRole(int i) {\n        return i < PLAYER_MAIN_COUNT ? PLAYER_MAIN : PLAYER_HOTBAR;\n    }\n\n    private static List<String> n(String role, int count) {\n        List<String> l = new ArrayList<String>();\n        for (int i = 0; i < count; i++) l.add(role);\n        return l;\n    }\n\n    private static List<String> roles(String... rs) {\n        List<String> l = new ArrayList<String>();\n        for (String s : rs) l.add(s);\n        return l;\n    }\n\n    /** 把固定表对齐到 slotCount（短了补 UNKNOWN，长了截断）—— **如实**，不硬塞。 */\n    private static List<String> pad(List<String> r, int slotCount, String filler) {\n        while (r.size() < slotCount) r.add(filler);\n        while (r.size() > slotCount) r.remove(r.size() - 1);\n        return r;\n    }\n\n    /**\n     * 把适配层给的**原始槽位 JSON**（{@code {screen,menuType,containerId,slots:[{index,x,y,empty,itemId?,count?}]}}）\n     * 规范化成回执：补 {@code role} / {@code playerRange} / {@code slotCount} / 角色计数 / 口径说明。\n     *\n     * <p>为什么不直接原样透出：{@link Json#parseObject} 把 JSON 数字一律读成 {@code Double}\n     * ⇒ 原样透出会让 {@code count:64} 变成 {@code 64.0}（调用方按整数比对就\"对不上\"）。\n     * 与 {@code query_inventory} 的 {@code parseInventory} 同一套口径。\n     */\n    @SuppressWarnings(\"unchecked\")\n    public static Map<String, Object> decorate(Map<String, Object> raw) {\n        Map<String, Object> src = raw == null ? new LinkedHashMap<String, Object>() : raw;\n        String screen = src.get(\"screen\") == null ? null : String.valueOf(src.get(\"screen\"));\n        String menuType = src.get(\"menuType\") == null ? null : String.valueOf(src.get(\"menuType\"));\n        Object rawSlots = src.get(\"slots\");\n        List<Object> in = (rawSlots instanceof List) ? (List<Object>) rawSlots : new ArrayList<Object>();\n        int slotCount = in.size();\n        List<String> roles = rolesFor(menuType, slotCount);\n\n        List<Object> out = new ArrayList<Object>();\n        Map<String, Object> counts = new LinkedHashMap<String, Object>();\n        Set<String> seenRoles = new LinkedHashSet<String>();\n        int playerFrom = -1;\n        int playerTo = -1;\n        for (int i = 0; i < slotCount; i++) {\n            Map<String, Object> e = (in.get(i) instanceof Map)\n                    ? new LinkedHashMap<String, Object>((Map<String, Object>) in.get(i))\n                    : new LinkedHashMap<String, Object>();\n            // index 以**列表位置**为准（适配层给了也以位置对齐，防止两者漂移而不报）\n            Object statedIndex = e.get(\"index\");\n            int idx = (statedIndex instanceof Number) ? ((Number) statedIndex).intValue() : i;\n            if (idx != i) {\n                e.put(\"indexStatedByAdapter\", Integer.valueOf(idx));\n            }\n            e.put(\"index\", Integer.valueOf(i));\n            String role = (i < roles.size()) ? roles.get(i) : UNKNOWN;\n            e.put(\"role\", role);\n            boolean empty = Boolean.TRUE.equals(e.get(\"empty\")) || e.get(\"itemId\") == null;\n            e.put(\"empty\", Boolean.valueOf(empty));\n            if (empty) {\n                e.put(\"itemId\", null);\n                e.put(\"count\", Integer.valueOf(0));\n            } else {\n                e.put(\"itemId\", String.valueOf(e.get(\"itemId\")));\n                Object c = e.get(\"count\");\n                e.put(\"count\", c instanceof Number ? (Object) Integer.valueOf(((Number) c).intValue()) : null);\n                e.put(\"idKind\", \"registryName\");\n            }\n            Object xv = e.get(\"x\");\n            e.put(\"x\", xv instanceof Number ? (Object) Integer.valueOf(((Number) xv).intValue()) : null);\n            Object yv = e.get(\"y\");\n            e.put(\"y\", yv instanceof Number ? (Object) Integer.valueOf(((Number) yv).intValue()) : null);\n            e.put(\"playerSlot\", Boolean.valueOf(\n                    PLAYER_MAIN.equals(role) || PLAYER_HOTBAR.equals(role)));\n            if (PLAYER_MAIN.equals(role) || PLAYER_HOTBAR.equals(role)) {\n                if (playerFrom < 0) playerFrom = i;\n                playerTo = i;\n            }\n            counts.put(role, Integer.valueOf(((Number) counts.getOrDefault(role, Integer.valueOf(0))).intValue() + 1));\n            seenRoles.add(role);\n            out.add(e);\n        }\n\n        boolean known = knownMenu(menuType);\n        Map<String, Object> data = new LinkedHashMap<String, Object>();\n        data.put(\"screen\", screen);\n        data.put(\"menuType\", menuType);\n        Object cid = src.get(\"containerId\");\n        data.put(\"containerId\", cid instanceof Number ? (Object) Integer.valueOf(((Number) cid).intValue()) : null);\n        data.put(\"slotCount\", Integer.valueOf(slotCount));\n        if (playerFrom >= 0) {\n            Map<String, Object> pr = new LinkedHashMap<String, Object>();\n            pr.put(\"from\", Integer.valueOf(playerFrom));\n            pr.put(\"to\", Integer.valueOf(playerTo));\n            pr.put(\"note\", \"主背包 27 格后接快捷栏 9 格（共 36 格）\");\n            data.put(\"playerRange\", pr);\n        } else {\n            data.put(\"playerRange\", null);\n            data.put(\"playerRangeNote\", \"本菜单里没识别出玩家槽（角色表未命中该 menuType）\");\n        }\n        data.put(\"roles\", counts);\n        data.put(\"roleKnown\", Boolean.valueOf(known));\n        data.put(\"roleNote\", known\n                ? \"role 由「menuType + 下标」的**原版版式精确表**推出（javap -c 实证，见 SlotRoles 类注释）\"\n                : \"该 menuType 不在精确表里 ⇒ 走**兜底规则**（末 36 格当玩家主背包 27 + 快捷栏 9，\"\n                        + \"其余当容器格）—— **不假装**认得这一档的版式；roleKnown:false\");\n        data.put(\"rolesAll\", new ArrayList<Object>(seenRoles));\n        data.put(\"slotCountNote\", \"slotCount = 本菜单的槽位总数（含玩家 36 格）\");\n        data.put(\"idKind\", \"registryName\");\n        data.put(\"idKindNote\", \"itemId 走现代注册名（如 minecraft:stone）；\"\n                + \"桥路线（forge 1.7.10-1.12.2）同类字段给的是 unlocalizedName（如 item.stone）\");\n        data.put(\"slots\", out);\n        return data;\n    }\n}\n",
  "playtest/core/com/bandd/playtest/core/StateConfig.java": "package com.bandd.playtest.core;\n\nimport java.util.LinkedHashMap;\nimport java.util.Map;\n\n/**\n * 「游戏状态器」的**全部可调项集中在这一个类里**（T3 的设置页面只需要接这一个类）。\n *\n * <p>为什么单独一个类：状态器的行为全是旋钮（多久重采一次 / 半径多大 / 采样多密 /\n * 一张图最多多少字符 / 要不要高度 / 玩家怎么标），散落在 {@link GameStateService} 里就没法\n * 让设置界面「一处读、一处写」。本类只放**纯数据**，不含任何逻辑与时序 —— 逻辑在\n * {@link GameStateService}，本轮**不做**界面。\n *\n * <p>**默认值即用户拍板口径**：{@code chunkRadius = 1} ⇒ 玩家所在区块 ±1 ⇒ **3×3 区块 = 48×48 格**。\n *\n * <p>本类 **Java 8 兼容**（core 与 54 个老档共用同一份源码 ⇒ 不许用 record / var / List.of）。\n */\npublic final class StateConfig {\n\n    // ---- 刷新与范围 ----\n    /** 主动重采间隔（客户端 tick 数）。默认 40 = 2s。 */\n    public int refreshIntervalTicks = 40;\n    /** 地图半径（**区块**数）。1 = 3×3 区块 = 48×48 格（默认，= 用户拍板口径）。 */\n    public int chunkRadius = 1;\n\n    // ---- 采样与容量 ----\n    /** 采样步长（格）：1 = 逐格；2 = 隔一格采一格。会**逐字写进地图头**的 {@code step}。 */\n    public int step = 1;\n    /** 分帧预算：每个客户端 tick 最多扫多少**格**。绝不一次全扫（会卡 tick 线程）。 */\n    public int columnsPerTick = 128;\n    /** 单次回执里**地图网格正文**的字符上限（不含头/图例；头里逐字写 {@code maxChars}）。 */\n    public int maxChars = 12000;\n    /** 自动降采样的最大步长；到这个步长还超 {@code maxChars} ⇒ 按行截断并写 {@code truncated:true}。 */\n    public int maxAutoStep = 4;\n\n    // ---- 内容开关 ----\n    /** 每格是否带高度数字（关掉 ⇒ 每格只有 1 个方块码字符）。 */\n    public boolean includeHeight = true;\n    /**\n     * 是否在地图上**叠加实体层**（{@code entityGrid} + {@code entityLegend} + {@code entities[]}）。\n     *\n     * <p>**已实现**（2026-11-11）：默认 false = 不叠加；打开后地图头里多一层**独立**的\n     * 定宽字符网格（与 {@code grid} 同几何），**方块层一个字符都不受影响**（方格码只出现在\n     * {@code grid} 里）。每个调用还可以用参数 {@code entities=true|false} **只覆盖本次**\n     * （见 {@code query_map}/{@code query_state}）。本档没实现实体扫描面\n     * （{@code GameBridge#nearbyEntitiesJson} 回 null）⇒ 地图头如实写 {@code entitiesIncluded:false}\n     * 与 {@code entitiesNote}，**不假装有实体层**。\n     */\n    public boolean includeEntities = false;\n\n    // ---- [T16] 纵层 yMode 的配置默认（四个旋钮进设置页；每次调用仍可用同名参数**只覆盖本次**）----\n    /** 地下自动切层总开关（默认 true）。关掉 ⇒ 不给 yMode 时一律 surface（不再自动切层）。 */\n    public boolean yModeAuto = true;\n    /** 自动切层的地下判据：playerDepthBelowSurface ≥ 此值 ⇒ 默认改用 player 纵层（默认 3）。 */\n    public int yModeAutoDepth = 3;\n    /** 一次请求采样的层数上限（默认 8；**硬上限 16** —— 超过一律拒，设置面不静默夹回）。 */\n    public int yLayerMax = 8;\n    /** 自动切层 / player 模式省略 yRange 时的 dy 半径（±N ⇒ 2N+1 层；默认 2）。 */\n    public int yAutoRange = 2;\n\n    // ---- 渲染字符 ----\n    /** 玩家所在格的标记字符（画在玩家那格，代替方块码）。 */\n    public char playerMark = '+';\n    /** 未知格（{@code blockAt} 回 null：越界 / 未加载 / 本档不支持）的方块码。 */\n    public char unknownCode = '?';\n    /** 码位用完后的「其它」码（图例里另附 {@code legendOverflow} 列出真实 id）。 */\n    public char overflowCode = '#';\n    /** 方块码候选字符表（每个码**恰好 1 字符** ⇒ 网格固定宽度不靠空格对齐）。 */\n    public String palette = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz\";\n    /** 高度字段最小宽度（实际宽度由本图 yMin/yMax 决定，只增不减）。 */\n    public int minHeightWidth = 1;\n\n    public StateConfig() {\n    }\n\n    public StateConfig(StateConfig other) {\n        this.refreshIntervalTicks = other.refreshIntervalTicks;\n        this.chunkRadius = other.chunkRadius;\n        this.step = other.step;\n        this.columnsPerTick = other.columnsPerTick;\n        this.maxChars = other.maxChars;\n        this.maxAutoStep = other.maxAutoStep;\n        this.includeHeight = other.includeHeight;\n        this.includeEntities = other.includeEntities;\n        this.yModeAuto = other.yModeAuto;\n        this.yModeAutoDepth = other.yModeAutoDepth;\n        this.yLayerMax = other.yLayerMax;\n        this.yAutoRange = other.yAutoRange;\n        this.playerMark = other.playerMark;\n        this.unknownCode = other.unknownCode;\n        this.overflowCode = other.overflowCode;\n        this.palette = other.palette;\n        this.minHeightWidth = other.minHeightWidth;\n    }\n\n    /** 地图边长（格）= (2×半径区块 + 1) × 16。默认 = 48。 */\n    public int mapSideBlocks() {\n        return (2 * chunkRadius + 1) * 16;\n    }\n\n    /**\n     * 把外部（配置文件 / 设置界面）塞进来的值夹到安全范围。\n     * 为什么必须夹：这些值直接决定「每 tick 扫多少格」与「回执多大」，\n     * 一个 0 或负数会让扫描永不推进或死循环。\n     */\n    public void sanitize() {\n        if (refreshIntervalTicks < 1) refreshIntervalTicks = 1;\n        if (chunkRadius < 0) chunkRadius = 0;\n        if (chunkRadius > 8) chunkRadius = 8;\n        if (step < 1) step = 1;\n        if (step > 16) step = 16;\n        if (columnsPerTick < 1) columnsPerTick = 1;\n        if (columnsPerTick > 4096) columnsPerTick = 4096;\n        if (maxChars < 64) maxChars = 64;\n        if (maxChars > 200000) maxChars = 200000;\n        if (maxAutoStep < step) maxAutoStep = step;\n        if (maxAutoStep > 64) maxAutoStep = 64;\n        if (minHeightWidth < 1) minHeightWidth = 1;\n        if (minHeightWidth > 4) minHeightWidth = 4;\n        // [T16] 纵层四个旋钮的文件面夹取（设置面 settings_set 更严：越界直接拒，见 SettingsEdit）。\n        if (yModeAutoDepth < 1) yModeAutoDepth = 1;\n        if (yModeAutoDepth > 256) yModeAutoDepth = 256;\n        if (yLayerMax < 1) yLayerMax = 1;\n        if (yLayerMax > 16) yLayerMax = 16;          // 硬上限：与 GameStateService.Y_LAYER_HARD_MAX 同值\n        if (yAutoRange < 0) yAutoRange = 0;\n        if (yAutoRange > 64) yAutoRange = 64;\n        if (palette == null || palette.isEmpty()) palette = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ\";\n        StringBuilder b = new StringBuilder();\n        for (int i = 0; i < palette.length(); i++) {\n            char c = palette.charAt(i);\n            if (c != playerMark && c != unknownCode && c != overflowCode\n                    && b.indexOf(String.valueOf(c)) < 0) {\n                b.append(c);\n            }\n        }\n        if (b.length() == 0) b.append(\"ABCDEFGHIJKLMNOPQRSTUVWXYZ\");\n        palette = b.toString();\n    }\n\n    /** 供设置界面 / 状态自报读出的形状（字段名即旋钮名）。 */\n    public Map<String, Object> toJson() {\n        Map<String, Object> m = new LinkedHashMap<>();\n        m.put(\"refreshIntervalTicks\", refreshIntervalTicks);\n        m.put(\"chunkRadius\", chunkRadius);\n        m.put(\"mapSideBlocks\", mapSideBlocks());\n        m.put(\"step\", step);\n        m.put(\"columnsPerTick\", columnsPerTick);\n        m.put(\"maxChars\", maxChars);\n        m.put(\"maxAutoStep\", maxAutoStep);\n        m.put(\"includeHeight\", includeHeight);\n        m.put(\"includeEntities\", includeEntities);\n        m.put(\"yModeAuto\", Boolean.valueOf(yModeAuto));\n        m.put(\"yModeAutoDepth\", Integer.valueOf(yModeAutoDepth));\n        m.put(\"yLayerMax\", Integer.valueOf(yLayerMax));\n        m.put(\"yAutoRange\", Integer.valueOf(yAutoRange));\n        m.put(\"playerMark\", String.valueOf(playerMark));\n        m.put(\"unknownCode\", String.valueOf(unknownCode));\n        m.put(\"overflowCode\", String.valueOf(overflowCode));\n        m.put(\"palette\", palette);\n        m.put(\"minHeightWidth\", minHeightWidth);\n        return m;\n    }\n\n    /** 设置界面回写用：只认已知键，缺键保持原值，最后自动 {@link #sanitize()}。 */\n    public void applyJson(Map<String, Object> m) {\n        if (m == null) return;\n        if (m.containsKey(\"refreshIntervalTicks\")) refreshIntervalTicks = intOf(m.get(\"refreshIntervalTicks\"), refreshIntervalTicks);\n        if (m.containsKey(\"chunkRadius\")) chunkRadius = intOf(m.get(\"chunkRadius\"), chunkRadius);\n        if (m.containsKey(\"step\")) step = intOf(m.get(\"step\"), step);\n        if (m.containsKey(\"columnsPerTick\")) columnsPerTick = intOf(m.get(\"columnsPerTick\"), columnsPerTick);\n        if (m.containsKey(\"maxChars\")) maxChars = intOf(m.get(\"maxChars\"), maxChars);\n        if (m.containsKey(\"maxAutoStep\")) maxAutoStep = intOf(m.get(\"maxAutoStep\"), maxAutoStep);\n        if (m.containsKey(\"includeHeight\")) includeHeight = boolOf(m.get(\"includeHeight\"), includeHeight);\n        if (m.containsKey(\"includeEntities\")) includeEntities = boolOf(m.get(\"includeEntities\"), includeEntities);\n        if (m.containsKey(\"yModeAuto\")) yModeAuto = boolOf(m.get(\"yModeAuto\"), yModeAuto);\n        if (m.containsKey(\"yModeAutoDepth\")) yModeAutoDepth = intOf(m.get(\"yModeAutoDepth\"), yModeAutoDepth);\n        if (m.containsKey(\"yLayerMax\")) yLayerMax = intOf(m.get(\"yLayerMax\"), yLayerMax);\n        if (m.containsKey(\"yAutoRange\")) yAutoRange = intOf(m.get(\"yAutoRange\"), yAutoRange);\n        if (m.containsKey(\"minHeightWidth\")) minHeightWidth = intOf(m.get(\"minHeightWidth\"), minHeightWidth);\n        if (m.containsKey(\"palette\")) {\n            Object v = m.get(\"palette\");\n            if (v != null) palette = String.valueOf(v);\n        }\n        Character pc = charOf(m.get(\"playerMark\"));\n        if (pc != null) playerMark = pc.charValue();\n        Character uc = charOf(m.get(\"unknownCode\"));\n        if (uc != null) unknownCode = uc.charValue();\n        Character oc = charOf(m.get(\"overflowCode\"));\n        if (oc != null) overflowCode = oc.charValue();\n        sanitize();\n    }\n\n    private static int intOf(Object v, int dflt) {\n        if (v instanceof Number) return ((Number) v).intValue();\n        if (v instanceof String) {\n            try {\n                return (int) Double.parseDouble(((String) v).trim());\n            } catch (NumberFormatException e) {\n                return dflt;\n            }\n        }\n        return dflt;\n    }\n\n    private static boolean boolOf(Object v, boolean dflt) {\n        if (v instanceof Boolean) return ((Boolean) v).booleanValue();\n        if (v instanceof String) return Boolean.parseBoolean((String) v);\n        return dflt;\n    }\n\n    private static Character charOf(Object v) {\n        if (v == null) return null;\n        String s = String.valueOf(v);\n        return s.isEmpty() ? null : Character.valueOf(s.charAt(0));\n    }\n}\n",
};

export const PLAYTEST_MOD_CORE_CLASSES: readonly string[] = ["ActionQueue.java","Arbitration.java","Capabilities.java","CommandResult.java","EvidenceWriter.java","GameBridge.java","GameStateService.java","GuiResult.java","HttpApi.java","Json.java","LogTail.java","MiningTracker.java","PlanInterpreter.java","PlaytestCore.java","Settings.java","SettingsEdit.java","SlotRoles.java","StateConfig.java"];
